  }

  rep(i,N) {
    rep(j,N) {
      if(r[i].x < b[j].x && r[i].y < b[j].y) {
        addEdge(i+1, j+N+1, INF);
      }
    }
  }

  cout << maxFlow(0, 2*N + 1) << endl;
  return 0;
}

