int main(void) {
    // 2部グラフの最大マッチング O(f(N+M)) f:=最大マッチング数で高々N
    class bipartite_matching {
    public:
        int n;
        vector<vector<int>> g;
        vector<int> match;

        bipartite_matching(int n_) : n(n_), g(n_), match(n_), used(n_) {}

        void add_edge(int u, int v) {
            g[u].push_back(v);
            g[v].push_back(u);
        }

        int maximum_matching(void) {
            int res = 0;
            fill(begin(match), end(match), -1);
            for (int v = 0; v < n; ++v) {
                if (match[v] == -1) {
                    fill(begin(used), end(used), false);
                    if (dfs(v)) res++;
                }
            }
            return res;
        }

    private:
        vector<int> used;
        bool dfs(int v) {
            used[v] = true;
            for (int u : g[v]) {
                int w = match[u];
                if (w == -1 || (!used[w] && dfs(w))) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
            return false;
        }
    };

    int n;
    cin >> n;
    vector<pair<int, int>> red;
    vector<pair<int, int>> blue;
    rep (n) {
        int x, y;
        cin >> x >> y;
        red.emplace_back( pair<int, int> {x, y} );
    }
    rep (n) {
        int x, y;
        cin >> x >> y;
        blue.emplace_back( pair<int, int> {x, y} );
    }

    auto isgood = [](pair<int, int> r, pair<int, int> b) -> bool {
        return (r.fst < b.fst) and (r.snd < b.snd);
    };

    bipartite_matching bm(2*n);

    repeat (i, n) {
        repeat (j, n) {
            if (isgood(red[i], blue[j])) {
                bm.add_edge(i, j+n);
            }
        }
    }
    cout << bm.maximum_matching() << endl;

}

