// 二次元平面に，赤い点と青い点が N個ずつあります。
// i個目の赤い点の座標は (ai,bi) で，i個目の青い点の座標は (ci,di) です。
// 赤い点と青い点は，赤い点の x座標が青い点の x座標より小さく， また赤い点の
// y座標も青い点の y座標より小さいとき，仲良しペアになれます。
// あなたは最大で何個の仲良しペアを作ることができますか？ ただし，1つの点が複数のペアに所属することはできません。
//
// 入力例：
// 3
// 2 0
// 3 1
// 1 3
// 4 2
// 0 4
// 5 5
//
// 出力例：
// 2
// 例えば,(2,0)と(4,2)をペアにし,(3,1)と(5,5)をペアにすればよいです。

#include <iostream>
#include <string>
#include <vector>
#include <algorithm> // sort
#include <map> // pair
using namespace std;

int main(){
  int count = 0;
  int N;
  cin >> N;
  vector<pair<int, int> > red(N);
  vector<pair<int, int> > usedred(N);
  for(int i=0; i<N; i++){
    cin >> red[i].first >> red[i].second;
    usedred[i].first = -1;
    usedred[i].second = -1;
  }
  vector<pair<int, int> > blue(N);
  vector<pair<int, int> > usedblue(N);
  for(int i=0; i<N; i++){
    cin >> blue[i].first >> blue[i].second;
    usedblue[i].first = -1;
    usedblue[i].second = -1;
  }
  sort(red.begin(), red.end());
  sort(blue.begin(), blue.end());

  int ii = 0;
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      if(usedred[i].first!=0 && usedred[i].second!=0 && usedblue[j].first!=0 && usedblue[j].second!=0){
        if(red[i].first < blue[j].first){
          if(red[i].second < blue[j].second){
            ii=i;
            while(red[ii].second < blue[j].second){
                ii++;
            }
            usedred[i].first = 0;
            usedred[i].second = 0;
            usedblue[j].first = 0;
            usedblue[j].second = 0;
            count++;
          }
        }
      }

    }
  }
  cout << count << endl;

}

