int main(){
	int n;
	cin >> n;
	vector<pair<int, int>> a;
	vector<pair<int, int>> b;
	for(int i = 0; i < n; i++){
		int x, y;
		cin >> x >> y;
		a.push_back({x, y});
	}
	for(int i = 0; i < n; i++){
		int x, y;
		cin >> x >> y;
		b.push_back({x, y});
	}
	int ans = 0;
	auto x_sorter = [](pair<int, int> a, pair<int, int> b) -> bool {
		return a.first < b.first;
	};
//	auto y_sorter = [](pair<int, int> a, pair<int, int> b) -> bool {
//		return a.second < b.second;
//	};
	// a, b を x座標で昇順にソート
	sort(a.begin(), a.end(), x_sorter);
	sort(b.begin(), b.end(), x_sorter);

	// b の要素をループ
	for(auto p: b){
		int target = -1;
		int max_y = -1;
		// b の x座標も、かつ y座標も小さい a の点を見つけて vector から削除
		for(int i = 0; i < a.size(); i++){
			// x 座標が逆転したら もう a は調べない(ソート済みなので)
			if(a[i].first >= p.first) break;
			// y 座標が逆転していればこいつとはペアを組めないので次の周回へ
			if(a[i].second >= p.second) continue;
			// 最大の y 座標を保存
			int before = max_y;
			// y 座標を更新
			max_y = max(max_y, a[i].second);
			// y 座標が更新されれば、こいつがペアの相手(削除対象)
			if(before != max_y) target = i;
		}
		// パートナーが見つからなかったら次の周回に期待
		if(target == -1) continue;
		// ペアが決まったので a から削除
		a.erase(a.begin() + target);
		// ペアの数を更新
		++ans;
	}
	cout << ans << endl;
	return 0;
}

