using namespace std;

//#define errOut(s) { std::cerr << "LINE:" << __LINE__ << " " << #s << " = " << s << std::endl; }
#define errOut(s)

struct Point {
    int x;
    int y;
    int numberOfPairable;
    std::array<int, 100> pairableIdxes;
    bool fixed;

    const bool operator<(const Point &another) const {
        return x + y < another.x + another.y;
    }
};

std::array<Point, 100> reds;
std::array<Point, 100> blues;

int numberOfSoloReds = 0;
std::array<int, 100> soloRedIdxes;

int optimizePair(int begin) {
    if (begin == numberOfSoloReds) {
        return 0;
    }
    int ret = optimizePair(begin + 1) + 0;
    auto &red =  reds[soloRedIdxes[begin]];
    for (int i = 0; i < red.numberOfPairable; ++i) {
        auto &blue = blues[red.pairableIdxes[i]];
        if (blue.fixed) {
            continue;
        }
        blue.fixed = true;
        int candidate = optimizePair(begin + 1) + 1;
        ret = std::max(ret, candidate);
        blue.fixed = false;
        if (ret == numberOfSoloReds - begin) {
            break;
        }
    }
    return ret;
}

bool canPair(const Point &red, const Point &blue) {
    return red.x < blue.x && red.y < blue.y;
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        std::cin >> red.x >> red.y;
        red.numberOfPairable = 0;
        red.fixed = false;
    }
    for (int i = 0; i < n; ++i) {
        auto &blue = blues[i];
        std::cin >> blue.x >> blue.y;
        blue.numberOfPairable = 0;
        blue.fixed = false;
    }

    std::sort(reds.begin(), reds.begin() + n);
    std::sort(blues.begin(), blues.begin() + n);

    int ret = 0;
    int bound = 0;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        bound = (int) (std::lower_bound(blues.begin() + bound, blues.begin() + n, red) - blues.begin());
        for (int j = bound; j < n; ++j) {
            auto &blue = blues[j];
            if (!canPair(red, blue)) {
                continue;
            }
            red.pairableIdxes[red.numberOfPairable++] = j;
            blue.pairableIdxes[blue.numberOfPairable++] = i;
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed) {
            continue;
        }
        if (red.numberOfPairable == 0) {
            red.fixed = true;
            continue;
        }
        if (red.numberOfPairable == 1) {
            auto &blue = blues[red.pairableIdxes[0]];
            if (blue.numberOfPairable == 1) {
                red.fixed = true;
                blue.fixed = true;
                ++ret;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        const auto &red = reds[i];
        if (red.fixed) {
            continue;
        }
        soloRedIdxes[numberOfSoloReds++] = i;
    }
    if (numberOfSoloReds == 0) {
        std::cout << ret << std::endl;
        errOut(ret);
        return 0;
    }
    std::sort(soloRedIdxes.begin(), soloRedIdxes.begin() + numberOfSoloReds, [&](const int &a, const int &b) {
        return reds[a].numberOfPairable < reds[b].numberOfPairable;
    });
    errOut(ret);
    ret += optimizePair(0);
    errOut(ret);
    std::cout << ret << std::endl;
    return 0;
}

