#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define all(x) (x).begin(),(x).end()
const int mod=1000000007,MAX=600005,INF=1<<30;

int n;
ll dat[2*MAX-1];

void init(int n_){
    n=1;
    while(n<n_) n*=2;
    for(int i=0;i<2*n-1;i++){
        dat[i]=-INF;
    }
}

void update(int k,ll a){
    k+=n-1;
    dat[k]=a;

    while(k>0){
        k=(k-1)/2;
        dat[k]=max(dat[k*2+1],dat[k*2+2]);
    }
}

ll query(int a,int b,int k,int l,int r){

    if(r<=a||b<=l) return -INF;
    if(a<=l&&r<=b) return dat[k];
    else{
        ll vl=query(a,b,2*k+1,l,(l+r)/2);
        ll vr=query(a,b,2*k+2,(l+r)/2,r);
        return max(vl,vr);
    }
}

bool compare(pair<int,int> a,pair<int,int> b){
    if(a.second==b.second) return a.first>b.first;
    return a.second>b.second;
}

int main(){

    int N,M;cin>>N;M=N;
    vector<pair<int,int>> X(N),Y(M),asort(N+M),bsort(N+M);
    for(int i=0;i<N;i++){
        cin>>X[i].first>>X[i].second;
        asort[i]={X[i].first,i};
        bsort[i]={X[i].second,i};
    }

    for(int i=0;i<M;i++){
        cin>>Y[i].first>>Y[i].second;
        asort[i+N]={Y[i].first,i+N};
        bsort[i+N]={Y[i].second,i+N};
    }

    sort(all(asort));
    sort(all(bsort));

    for(int i=0;i<N+M;i++){
        asort[i].first=i+1;
        bsort[i].first=i+1;

        if(asort[i].second<N) X[asort[i].second].first=asort[i].first;
        else Y[asort[i].second-N].first=asort[i].first;

        if(bsort[i].second<N) X[bsort[i].second].second=bsort[i].first;
        else Y[bsort[i].second-N].second=bsort[i].first;
    }

    sort(all(X),compare);

    init(N+M);

    for(int i=0;i<M;i++){
        update(Y[i].first,Y[i].second);
    }

    int ans=0;

    for(int q=0;q<N;q++){
        if(query(X[q].first,n+1,0,0,n)<X[q].second) continue;
        int left=X[q].first,right=N+M;
        while(right-left>1){
            int mid=(left+right)/2;
            if(query(X[q].first,mid+1,0,0,n)<X[q].second) left=mid;
            else right=mid;
        }
        ans++;
        update(right,-INF);
    }

    cout<<ans<<endl;
}

