using namespace std;

class Point{
  public:
    int x;
    int y;
    vector<Point> relations;

    Point() {
      x = 0;
      y = 0;
      relations = vector<Point>();
    }

    Point(int x0, int y0) {
      x = x0;
      y = y0;
      relations = vector<Point>();
    }

    bool is_inner(Point& p) {
      return x < p.x && y < p.y;
    }

    bool operator==(Point p) {
        return x == p.x && y == p.y;
    }

    int dist() const {
      return x*x + y*y;
    }
};

bool dist(const Point &left, const Point &right) {
  return left.dist() > right.dist();
}

bool num_relations_asc(const Point left, const Point right) {
  return left.relations.size() < right.relations.size();
}

std::ostream &operator<<(std::ostream &os, Point const &p) {
    return os << "(" << p.x << ", " << p.y << ")";
}

