int find1(int l,int r,point *a,point b)  
{  
    //int l=0;  
    //int r=n-1;  
    if(l==r)  
        return l;  
    int mid=(l+r)/2;  
    if(a[mid].x<b.x||(a[mid].x==b.x&&a[mid].y<=b.y))  
        return find1(mid+1,r,a,b);  
    else  
        return find1(l,mid,a,b);  
}  
int find2(int l,int r,point *a,point b)  
{  
    //int l=0;  
    //int r=n-1;  
    if(l==r)  
        return l;  
    int mid=(l+r)/2;  
    if(a[mid].y<b.y||(a[mid].y==b.y&&a[mid].x<=b.x))  
        return find1(mid+1,r,a,b);  
    else  
        return find1(l,mid,a,b);  
}  

