struct edge {
	int x, f, t;
};
vector<edge> G[205];
int s, t, level[205], iter[205];
void addedge(int x,int y,int value){
	G[x].push_back(edge{y,value,(int)G[y].size()});
	G[y].push_back(edge{ x,0,(int)G[x].size() - 1 });
}
void bfs() {
	queue<int> q;
	q.push(s);
	level[s] = 0;
	while (!q.empty()) {
		int t = q.front();
		q.pop();
		int siz = G[t].size();
		for (int i = 0; i < siz; ++i) {
			edge &p = G[t][i];
			if (p.f && level[p.x] < 0) {
				level[p.x] = level[t] + 1;
				q.push(p.x);
			}
		}
	}
}
int dfs(int v, int f) {
	if (v == t) {
		return f;
	}
	int s = G[v].size();
	for (int &i = iter[v]; i < s; ++i) {
		edge &p = G[v][i];
		if (p.f && level[v] < level[p.x]) {
			int d = dfs(p.x, min(p.f, f));
			if (d) {
				p.f -= d;
				G[p.x][p.t].f += d;
				return d;
			}
		}
	}
	return 0;
}
int maxflow() {
	int flow = 0;
	while (1) {
		memset(level, -1, sizeof(level));
		bfs();
		if (level[t] == -1) {
			return flow;
		}
		memset(iter, 0, sizeof(iter));
		int f;
		while ((f = dfs(s, INF)) > 0) {
			flow += f;
		}
	}
}
