		for (int i = 1; i <= n; ++i) {
			for (int j = 1; j <= n; ++j) {
				if (r[i].a < b[j].a && r[i].b < b[j].b) {
					addedge(i, j + n, 1);
				}
			}
		}
		for (int i = 1; i <= n; ++i) {
			addedge(s, i, 1);
			addedge(i + n, t, 1);
		}
		printf("%d\n", maxflow());
		for (int i = 0; i <= 2 * n + 1; ++i) {
			G[i].clear();
		}
	}
