	std::vector<std::pair<int, int>> blue(N);
	for(int i = 0; i < N; i++) {
		std::cin >> red[i].first >> red[i].second;
	}
	for(int i = 0; i < N; i++) {
		std::cin >> blue[i].first >> blue[i].second;
	}

	std::sort(red.begin(), red.end());
	std::sort(blue.begin(), blue.end());

	int ans = 0;

	for(int bi = 0; bi < N; bi++) {
		// <y, index>
		std::vector<std::pair<int, int>> ok;
		for(int ri = 0; ri < red.size(); ri++) {
			if(red[ri].first < blue[bi].first && red[ri].second < blue[bi].second) {
				ok.emplace_back(red[ri].second, ri);
