        red[i]=make_pair(x,y);
    }
    for(i=0; i<N; i++){
        cin >> x >> y;
        blue[i]=make_pair(x,y);
    }

    //calc
    max_flow mf(2*N+2);//sink:2*N, tank:2*N+1
    for(i=0; i<N; i++){
        mf.add_edge(2*N,i,1);
    }
    for(i=0; i<N; i++){
        mf.add_edge(N+i,2*N+1,1);
    }
    for(i=0; i<N; i++){
        for(j=0; j<N; j++){
            if(red[i].first<blue[j].first&&red[i].second<blue[j].second){
                mf.add_edge(i,N+j,1);
            }
        }
    }

    //output
    cout << mf.run(2*N,2*N+1) << endl;
    system("pause");
    return 0;
}

