                    }
                }
            }
        }
        if (target_bi >= 0) {
            // printf("ri: %d, target_bi: %d\n", ri, target_bi);
            ans++;
            bs[target_bi] = true;
        }
    }

    cout << ans << endl;

    return 0;
}

