using namespace std;

const int INF = 1000000000;
struct NEdge {
    int to;
    int cap;
    int rev;
};

struct FlowNetwork {
    int N;
    vector<vector<NEdge>> edges;
    vector<int> level;
    vector<int> iter;

    FlowNetwork(int n) {
        N = n;
        edges.resize(N);
        level.resize(N);
        iter.resize(N);
    }
    void addEdge(int from, int to, int cap) {
        edges[from].push_back({ to, cap, (int)edges[to].size() });
        edges[to].push_back({ from, 0, (int)edges[from].size() - 1 });
    }

    int maxflow(int s, int t) {
        int flow = 0;
        while (1) {
            bfs(s);
            if (level[t] < 0)
                return flow;
            fill(iter.begin(), iter.end(), 0);
            int f;
            while ((f = dfs(s, t, INF)) > 0)
                flow += f;

        }
        return flow;
    }

    void bfs(int s) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int i = 0; i < edges[v].size(); i++) {
                NEdge &e = edges[v][i];
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }
    int dfs(int v, int t, int f) {
        if (v == t)
            return f;
        for (int &i = iter[v]; i < edges[v].size(); i++) {
            NEdge &e = edges[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    edges[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
};


int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> red(n), blue(n);
    for (int i = 0; i < n; i++) {
        cin >> red[i].first >> red[i].second;
    }
    for (int i = 0; i < n; i++) {
        cin >> blue[i].first >> blue[i].second;
    }

    FlowNetwork fn(2 * n + 2);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (red[i].first < blue[j].first && red[i].second < blue[j].second)
                fn.addEdge(i, n + j, 1);
        }
    }
    for (int i = 0; i < n; i++) {
        fn.addEdge(2 * n, i, 1);
        fn.addEdge(n + i, 2 * n + 1, 1);
    }
    int ans = fn.maxflow(2 * n, 2 * n + 1);
    cout << ans << endl;
    return 0;
}

