struct Biparite_Matching {

    int n;
    vector<vector<int>> g;
    vector<int> match;
    vector<bool> seen;

    Biparite_Matching(int _n) {
        n = _n;
        g.assign(n, vector<int>());
        match.resize(n);
        seen.resize(n);
    }

    // 辺の追加
    void add_edge(int u, int v) {
        g[u].push_back(v);
        g[v].push_back(u);
    }

    bool dfs(int v) {
        seen[v] = true;
        for(int i = 0; i < (int)g[v].size(); i++) {
            int u = g[v][i];
            int w = match[u];
            if(w < 0 || (!seen[w] && dfs(w))) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }

    // 最大マッチング
    int count() {
        int res = 0;
        match.assign(n, -1);
        for(int v = 0; v < n; v++) {
            if(match[v] < 0) {
                seen.assign(n, false);
                if(dfs(v)) res++;
            }
        }
        return res;
    }

};


