    REP(i, N) {
        LCIN(a, b);
        r.emplace_back(a, b);
    }
    REP(i, N) {
        LCIN(a, b);
        bl.emplace_back(a, b);
    }
    REP(i, N) REP(j, N) {
        if(r[i].fi < bl[j].fi && r[i].se < bl[j].se) {
            mf.add_edge(i, j + N, 1);
        }
    }
    REP(i, N) {
        mf.add_edge(s, i, 1);
        mf.add_edge(i + N, t, 1);
    }
    cout << mf.max_flow(s, t) << "\n";
}

