static constexpr uint32_t N = 200;
static constexpr uint32_t R = 1;
static constexpr uint32_t B = 2;

uint32_t matrix[N][N] = {0};

bool find(uint32_t src_x, uint32_t src_y)
{
    for (uint32_t y=0; y < N; ++y) {
        for (uint32_t x=0; x < N; ++x) {
            if (x <= src_x || y <= src_y) continue;
            if (matrix[y][x] == B) {
                matrix[y][x] = 0;
                return true;
            }
        }
    }
    return false;
}

int main(void)
{
    uint32_t n;
    std::cin >> n; 

    for (uint32_t i=0; i < n; ++i) {
        uint32_t x, y;
        std:: cin >> x >> y;
        matrix[y][x] = R;
    }

    for (uint32_t i=0; i < n; ++i) {
        uint32_t x, y;
        std:: cin >> x >> y;
        matrix[y][x] = B;
    }

    uint32_t count = 0;
    for (uint32_t i=0; i < N; ++i) {
        for (uint32_t y=0; y < N; ++y) {
            if (y > i) continue;
            for (uint32_t x=0; x < N; ++x) {
                if (x > i) continue;
                if (matrix[y][x] == R && find(x, y)) count++;
            }
        }
    }

    std::cout << count << std::endl;

    return 0;
}

