int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<P> s1;
    set<P> s2;
    REP(i, 2 * n) {
        int a, b;
        cin >> a >> b;
        if (i < n) {
            s1.push_back({a, b});
        } else {
            s2.insert({a, b});
        }
    }
    // 降順ソート
    sort(ALLR(s1));

