        int x;
        int y;
    };

    vector<pos> red;
    for (int i = 0; i < N; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);
        red.push_back({x, y});
    }

    vector<pos> blue;
    for (int i = 0; i < N; ++i) {
        int x, y;
        scanf("%d%d", &x, &y);
        blue.push_back({x, y});
    }

    auto red2 = red;
    auto blue2 = blue;

    sort(red.begin(), red.end(), [](pos& a, pos& b){ return (a.x == b.x) ? (a.y < b.y) : (a.x < b.x);});
    sort(blue.begin(), blue.end(), [](pos& a, pos& b){ return (a.x == b.x) ? (a.y < b.y) : (a.x < b.x);});

    sort(red2.begin(), red2.end(), [](pos& a, pos& b){ return (a.y == b.y) ? (a.x < b.x) : (a.y < b.y);});
    sort(blue2.begin(), blue2.end(), [](pos& a, pos& b){ return (a.y == b.y) ? (a.x < b.x) : (a.y < b.y);});

    int c = 0;
    for (auto r = red.begin(); r != red.end(); ++r) {
        for (auto b = blue.begin(); b != blue.end(); ++b) {
            if (r->x < b->x && r->y < b->y) {
                blue.erase(b);
                c++;
                break;
            }
        }
    }

    int cc = 0;
    for (auto r = red2.begin(); r != red2.end(); ++r) {
        for (auto b = blue2.begin(); b != blue2.end(); ++b) {
            if (r->x < b->x && r->y < b->y) {
                blue2.erase(b);
                cc++;
                break;
            }
        }
    }

    c = c < cc ? cc : c;

    cout << c << endl;
    return 0;
}

