#include <bits/stdc++.h>
using namespace std;

const int inf = 1e9 + 7;
int x[207];
int y[207];
int N;

bool vis[207][207];

int fnc_pre()
{
    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        int sumx = inf, sumy = inf;
        for (int j = N+1; j <= 2*N; j++) {
            if (x[j] > x[i] && y[j] > y[i] && !vis[x[j]][y[j]]) {
                if (x[j] < sumx) sumx = x[j], sumy = y[j];
            }
        }
        if (sumx != inf) cnt++, vis[sumx][sumy] = 1; //cout << sumx << ' ' << sumy << endl;
    }

    return cnt;
}

int fnc_post()
{
    for (int i = 0; i <= 200; i++) for (int j = 0; j <= 200; j++) vis[i][j] = 0;

    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        int sumx = inf, sumy = inf;
        for (int j = N+1; j <= 2*N; j++) {
            if (x[j] > x[i] && y[j] > y[i] && !vis[x[j]][y[j]]) {
                if (y[j] < sumy) sumx = x[j], sumy = y[j];
            }
        }
        if (sumx != inf) cnt++, vis[sumx][sumy] = 1; //cout << sumx << ' ' << sumy << endl;
    }

    return cnt;
}

int fnc_pre_and_post()
{
    for (int i = 0; i <= 200; i++) for (int j = 0; j <= 200; j++) vis[i][j] = 0;

    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        int sumx = inf, sumy = inf;
        for (int j = N+1; j <= 2*N; j++) {
            if (x[j] > x[i] && y[j] > y[i] && !vis[x[j]][y[j]]) {
                if (x[j] < sumx && y[j] < sumy) sumx = x[j], sumy = y[j];
            }
        }
        if (sumx != inf) cnt++, vis[sumx][sumy] = 1; //cout << sumx << ' ' << sumy << endl;
    }

    return cnt;
}

int main()
{
    cin >> N;
    for (int i = 1; i <= 2*N; i++) cin >> x[i] >> y[i];

    int ans = 0;

    ans = max(ans, fnc_pre());
    ans = max(ans, fnc_post());
    ans = max(ans, fnc_pre_and_post());

    cout << ans << endl;
}

