    REP(i, N) blue.emplace_back(IN(), IN());
    REP(i, N) REP(j, N) {
        if(red[i].first < blue[j].first && red[i].second < blue[j].second) {
            add_edge(i + 1, N + j + 1, 1);
        }
    }
    REP(i, N) add_edge(0, i + 1, 1);
    REP(i, N) add_edge(N + i + 1, 2 * N + 1, 1);
    cout << max_flow(0, 2 * N + 1) << "\n";
}

