using namespace std;

const int INF = 1e9 + 10;

class MaxFlow {
private:

#define MAX_V 301
  struct Edge {
    int to, cap, rev;
    Edge(int to, int cap, int rev) : to(to), cap(cap), rev(rev) { }
  };

  vector<Edge> G[MAX_V];
  bool used[MAX_V];

  int Dfs(int v, int t, int f) {
    if (v == t) {
      return f;
    }
    used[v] = true;
    for (int i = 0; i < G[v].size(); i++) {
      Edge& e = G[v][i];
      if (!used[e.to] && e.cap > 0) {
        int d = Dfs(e.to, t, min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          G[e.to][e.rev].cap += d;

          return d;
        }
      }
    }

    return 0;
  }

public:

  void AddEdge(int from, int to, int cap) {
    G[from].push_back(Edge(to, cap, G[to].size()));
    G[to].push_back(Edge(from, 0, G[from].size() - 1));
  }

  int Solve(int s, int t) {
    int flow = 0;

    while (true) {
      memset(used, 0, MAX_V);
      int f = Dfs(s, t, INF);
      if (f == 0) {
        break;
      }
      flow += f;
    }

    return flow;
  }
};

int main() {
  int n;
  Read(n);

  vector<P> ab(n);
  vector<P> cd(n);

  for (int i = 0; i < n; i++) {
    Read(ab[i].first, ab[i].second);
  }

  for (int i = 0; i < n; i++) {
    Read(cd[i].first, cd[i].second);
  }

  int s = 2 * n + 1;
  int t = s + 1;

  MaxFlow mf;

  for (int i = 0; i < n; i++) {
    mf.AddEdge(s, i, 1);
  }

  for (int i = n; i < 2 * n; i++) {
    mf.AddEdge(i, t, 1);
  }

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (ab[i].first < cd[j].first && ab[i].second < cd[j].second) {
        mf.AddEdge(i, n + j, 1);
      }
    }
  }

  int f = mf.Solve(s, t);

  Print(f);

  return 0;
}
