bool dfs(vector<vector<int>>& edge, vector<int>& used, int now) {
	used[now] = true;
	if (now == edge.size() - 1) {
		used[now] = false;
	   return true;	
	}

	for (int i = 0; i < edge.size(); i++) {
		if (!used[i] && edge[now][i]) {
			bool result = dfs(edge, used, i);
			if (result) {
				edge[now][i] = false;
				edge[i][now] = true;
				used[now] = false;

				return true;
			}
		}
	}

	used[now] = false;

	return false;
}

