  g[from].push_back((edge){to, cap, (int)g[to].size()});
  g[to].push_back((edge){from, 0, (int)g[from].size() - 1});
}

void bfs(V2<edge> &g, V<int> &level, int s){
  FOR(i,0,(int)level.size()) level[i] = -1;
  queue<int> q;
  level[s] = 0;
  q.push(s);
  while( !q.empty() ){
    int v = q.front(); q.pop();
    FOR(i,0,(int)g[v].size()){
      edge &e = g[v][i];
      if( e.cap > 0 && level[e.to] < 0 ){
        level[e.to] = level[v] + 1;
        q.push(e.to);
      }
    }
  }
}

