  for(int &i=iter[v]; i<g[v].size(); ++i){
    edge &e = g[v][i];
    if(e.cap > 0 && level[v] < level[e.to]){
      int d = dfs(g, level, iter, e.to, t, min(f, e.cap));
      if(d > 0){
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}


int max_flow(V2<edge> &g, V<int> &level, V<int> &iter, int s, int t){
  int flow = 0;
  for(;;){
    bfs(g, level, s);
    if(level[t] < 0) return flow;
    FOR(i,0, (int)iter.size() ) iter[i] = 0;
    int f;;
    while( (f=dfs(g,level,iter,s,t,INF)) > 0 ){
      flow += f;
    }
  }
  return 0;
}

