#define errOut(s)

struct Point {
    int x;
    int y;
    std::vector<int> connectableIdxes;
    int connectedIdx;
    bool fixed;

    const bool operator<(const Point &another) const {
        return x + y < another.x + another.y;
    }
};

class PointFixer {
public:
    PointFixer(Point &p) : p_(p) {
        assert(!p.fixed);
        p_.fixed = true;
    }

    ~PointFixer() {
        p_.fixed = false;
    }

private:
    Point &p_;
};

std::array<Point, 100> reds;
std::array<Point, 100> blues;

bool searchOddCycleTransversal(int redIdx, std::stack<int> &result) {
    auto &red = reds[redIdx];
    if (red.fixed) {
        return false;
    }

    PointFixer redFixer(red);
    result.push(redIdx);
    for (auto &&blueIdx : red.connectableIdxes) {
        auto &blue = blues[blueIdx];
        if (blue.fixed) {
            continue;
        }

        PointFixer blueFixer(blue);
        result.push(blueIdx);
        if (blue.connectedIdx < 0) {
            return true;
        }

        auto nextRedIdx = blue.connectedIdx;
        auto &nextRed = reds[nextRedIdx];
        if (searchOddCycleTransversal(nextRedIdx, result)) {
            return true;
        }
        result.pop();
    }
    result.pop();
    return false;
}

bool maximizeMatchings(int redIdx) {
    std::stack<int> result;
    if (!searchOddCycleTransversal(redIdx, result)) {
        return false;
    }
    int currentIdx = result.top();
    result.pop();
    bool fromRed = false;
    while (!result.empty()) {
        auto nextIdx = result.top();
        if (fromRed) {
            auto &red = reds[currentIdx];
            red.connectedIdx = nextIdx;
            auto &blue = blues[nextIdx];
            blue.connectedIdx = currentIdx;
        } else {
            auto &blue = blues[currentIdx];
            blue.connectedIdx = nextIdx;
            auto &red = reds[nextIdx];
            red.connectedIdx = currentIdx;
        }
        fromRed = !fromRed;
        currentIdx = nextIdx;
        result.pop();
    }
    return true;
}

bool canPair(const Point &red, const Point &blue) {
    return red.x < blue.x && red.y < blue.y;
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        std::cin >> red.x >> red.y;
        red.fixed = false;
        red.connectableIdxes.reserve(100);
        red.connectedIdx = -1;
    }
    for (int i = 0; i < n; ++i) {
        auto &blue = blues[i];
        std::cin >> blue.x >> blue.y;
        blue.fixed = false;
        blue.connectableIdxes.reserve(100);
        blue.connectedIdx = -1;
    }

    std::sort(reds.begin(), reds.begin() + n);
    std::sort(blues.begin(), blues.begin() + n);

    int ret = 0;
    int bound = 0;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        bound = (int) (std::lower_bound(blues.begin() + bound, blues.begin() + n, red) - blues.begin());
        for (int j = bound; j < n; ++j) {
            auto &blue = blues[j];
            if (!canPair(red, blue)) {
                continue;
            }
            red.connectableIdxes.push_back(j);
            blue.connectableIdxes.push_back(i);
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.connectableIdxes.size() == 0) {
            red.fixed = true;
        }
        auto &blue = blues[i];
        if (blue.connectableIdxes.size() == 0) {
            blue.fixed = true;
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectableIdxes.size() > 1) {
            continue;
        }
        auto &blue = blues[red.connectableIdxes[0]];
        if (blue.fixed || blue.connectableIdxes.size() > 1) {
            continue;
        }
        red.fixed = true;
        blue.fixed = true;
        red.connectedIdx = red.connectableIdxes[0];
        blue.connectedIdx = i;
        ++ret;
    }

    errOut(ret);
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed) {
            continue;
        }
        if (maximizeMatchings(i)) {
            ++ret;
        }
    }

    errOut(ret);
    std::cout << ret << std::endl;
    return 0;
}

