vector<__uint128_t> dp;

int solve(__uint128_t used, vector<set<int>> inside, int idx) {
  int ret = 0;
  if (idx >= inside.size()) return 0;
  if (dp[idx] > -1) return dp[idx];
  // cerr << bitset<10>(used)  << endl;
  for(auto &r : inside[idx]) {
    if (!(used & (1<<r))) {
      ret = max(ret, solve(used | (1<<r), inside, idx+1)+1);
    }
  }
  ret = max(ret, solve(used, inside, idx+1));
  dp[idx] = ret;
  return ret;
}

