int n;
bool bpGraph[105][105];

bool bpm(bool bpGraph[105][105], int u,
	bool seen[], int matchR[])
{
	for (int v = 0; v < n; v++)
	{
		if (bpGraph[u][v] && !seen[v])
		{
			seen[v] = true;

			if (matchR[v] < 0 || bpm(bpGraph, matchR[v],
				seen, matchR))
			{
				matchR[v] = u;
				return true;
			}
		}
	}
	return false;
}

int maxBPM(bool bpGraph[105][105])
{
	int matchR[105];

	memset(matchR, -1, sizeof(matchR));

	int result = 0;
	for (int u = 0; u < n; u++)
	{
		bool seen[105];
		memset(seen, 0, sizeof(seen));

		if (bpm(bpGraph, u, seen, matchR))
			result++;
	}
	return result;
}

