            if (can == -1 || (r[can].second > r[j].second && b[i].second > r[j].second)) can = j;
        }

        if (can != -1) {
            ans++;
            r.erase(begin(r) + can);
            r.shrink_to_fit();
        }
    }

    cout << ans << endl;
}

