const ll INF = 1'000'000'000'000'000'007;
// const int INF = 1'000'000'007;
const ll MOD = 1'000'000'007; // 998'244'353;

ll flow(int u, int v, ll f, vector<set<int>> &g, map<pii, ll> &cap, vb &r) {	
	if (u == v) return f;
	r[u] = true;
	for (int t : g[u]) {
		if (r[t] or cap[pii(u, t)] == 0) continue;
		ll d = flow(t, v, min(f, cap[pii(u, t)]), g, cap, r);
		if (d > 0) {
			cap[pii(u, t)] -= d;
			cap[pii(t, u)] += d;		
			return d;
		}
	}	
	return 0;
}
ll max_flow(int s, int t, vector<set<int>> &g, map<pii, ll> &cap) {
	ll res = 0;
	while(true) {
		vb r(g.size());
		ll f = flow(s, t, INF, g, cap, r);
		if (f > 0) res += f;
		else return res;
	}
}

set<pii> matches(const vector<set<int>> &g, const map<pii, ll> &cap) {
	int X = g[0].size(), Y = g[g.size() - 1].size();
	dbs(X, Y);
	set<pii> res;
	for (auto pr : cap) {		
		int u, v; ll f; tie(u, v) = pr.first; f = pr.second;
		dbs(u, v, f);
		if (u == 0 or v == X + Y + 1) continue;
		if (u <= X and X < v and f == 0) res.insert(pii(u - 1, v - X - 1));
	}
	return res;
}
