#include <iostream>
using namespace std;
typedef pair<int ,int > pp;


void swap(pp *kr,pp *kl){
    pp t=*kr;
    *kr=*kl;
    *kl=t;
}

void sortF(pp *k, int N)
{   int count=0;
    for(int i=0;i<N-1-count;i++){
        for(int j=1;j<N-count;j++){
            if(k[i].first>k[j].first){
                swap(&k[i],&k[j]);
                count++;
            }
        }
    }
}

void sortS(pp *k, int N)
{   int count=0;
    for(int i=0;i<N-1-count;i++){
        for(int j=1;j<N-count;j++){
            if(k[i].second<k[j].second){
                swap(&k[i],&k[j]);
                count++;
            }
        }
    }
}

