    }

    for(int i=1;i<=N;i++)
        add_edge(0,i,1);
    for(int i=N+1;i<=2*N;i++)
        add_edge(i,2*N+1,1);
    for(int i=1;i<=N;i++){
        for(int j=N+1;j<=2*N;j++){
            if(p[i].first<p[j].first && p[i].second<p[j].second)
                add_edge(i,j,1);
        }
    }

    cout<<max_flow(0,2*N+1)<<endl;
    return 0;
}

