  pair<int, int> a[100], b[100];
  int ac[100]={0};
  int bc[100]={0};
  cin>>n;
  for(int i=0; i<n; i++) {
    int x, y;
    cin>>x>>y;
    a[i]=make_pair(x, y);
  }
  for(int i=0; i<n; i++) {
    int x, y;
    cin>>x>>y;
    b[i]=make_pair(x, y);
  }
  sort(a, a+n, le);
  sort(b, b+n, le);
  int ans=0;
  for(int i=0; i<n; i++) {
    for(int j=0; j<n; j++) {
      if(ac[i]==1 or bc[j]==1) continue;
      if(a[i].first<b[j].first && a[i].second<b[j].second) {
	ans++;
	ac[i]=1;
	bc[j]=1;
      }
    }
  }
  cout<<ans<<endl;
  return 0;
}

