  for (int i = 0; i < sz; i++) {
    for (int j = 0; j < sz; j++) {
      cnt[i + 1][j + 1] = cnt[i][j + 1] + cnt[i + 1][j] - cnt[i][j];
      if (G[i][j] == 1) cnt[i + 1][j + 1]++;
    }
  }
  vector<vector<int>> dp(sz + 1, vector<int>(sz + 1));
