void Ford_add_edge(int from,int end,int cap){
    G[from].push_back((edge){end,cap,(int)G[end].size()});
    G[end].push_back((edge){from,0,(int)G[from].size()-1});
}

int Ford_dfs(int v,int t,int f){
    if(v==t)return f;
    accessed[v]=true;
    for(int i=0;i<G[v].size();i++){
        edge &e = G[v][i];
        if(!accessed[e.end]&&e.cap>0){
            int d = Ford_dfs(e.end,t,min(f,e.cap));
            if(d>0){
                e.cap -= d;
                G[e.end][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

int FordFulkerson(int s,int t){
    int flow=0;
    while(1){
        memset(accessed,0,sizeof(accessed));
        int f = Ford_dfs(s,t,INF);
        if(f==0) return flow;
        flow+=f;
    }
}

