	REP(i, N) {
		REP(j, N) {
			auto redOne = red[i];
			auto blueOne = blue[j];
			if ((redOne.first < blueOne.first) && (redOne.second < blueOne.second)) {
				res.AddEdge(i, j + N, 1);
			}
		}
	}

	// 始点→赤
	int start = 2 * N;
	REP(i, N) {
		res.AddEdge(start, i, 1);
	}

	// 青→終点
	int end = 2 * N + 1;
	REP(i, N) {
		res.AddEdge(i + N, end, 1);
	}

	// 最大流量
	int ans = res.GetMaxFlow(start, end);
	cout << ans << endl;
	return 0;
}

