struct Point {
    int x;
    int y;
    std::vector<int> connectableIdxes;
    int connectedIdx;
    bool fixed;

    const bool operator<(const Point &another) const {
        return x + y < another.x + another.y;
    }
};

std::array<Point, 100> reds;
std::array<Point, 100> blues;

bool searchOddCycleTransversal(int redIdx, std::set<int> &visited) {
    auto &red = reds[redIdx];
    for (auto &&blueIdx : red.connectableIdxes) {
        if (visited.find(blueIdx) != visited.end()) {
            continue;
        }
        auto &blue = blues[blueIdx];
        auto nextRedIdx = blue.connectedIdx;
        if (nextRedIdx < 0) {
            red.connectedIdx = blueIdx;
            blue.connectedIdx = redIdx;
            return true;
        }
        visited.insert(blueIdx);
        if (searchOddCycleTransversal(nextRedIdx, visited)) {
            red.connectedIdx = blueIdx;
            blue.connectedIdx = redIdx;
            return true;
        }
        visited.erase(blueIdx);
    }
    return false;
}

bool maximizeMatchings(int redIdx) {
    std::set<int> visited;
    return searchOddCycleTransversal(redIdx, visited);
}

bool canPair(const Point &red, const Point &blue) {
    return red.x < blue.x && red.y < blue.y;
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        std::cin >> red.x >> red.y;
        red.fixed = false;
        red.connectableIdxes.reserve(100);
        red.connectedIdx = -1;
    }
    for (int i = 0; i < n; ++i) {
        auto &blue = blues[i];
        std::cin >> blue.x >> blue.y;
        blue.fixed = false;
        blue.connectableIdxes.reserve(100);
        blue.connectedIdx = -1;
    }

    std::sort(reds.begin(), reds.begin() + n);
    std::sort(blues.begin(), blues.begin() + n);

    int ret = 0;
    int bound = 0;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        bound = (int) (std::lower_bound(blues.begin() + bound, blues.begin() + n, red) - blues.begin());
        for (int j = bound; j < n; ++j) {
            auto &blue = blues[j];
            if (!canPair(red, blue)) {
                continue;
            }
            red.connectableIdxes.push_back(j);
            blue.connectableIdxes.push_back(i);
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.connectableIdxes.size() == 0) {
            red.fixed = true;
        }
        auto &blue = blues[i];
        if (blue.connectableIdxes.size() == 0) {
            blue.fixed = true;
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectableIdxes.size() > 1) {
            continue;
        }
        auto &blue = blues[red.connectableIdxes[0]];
        if (blue.fixed || blue.connectableIdxes.size() > 1) {
            continue;
        }
        red.fixed = true;
        blue.fixed = true;
        red.connectedIdx = red.connectableIdxes[0];
        blue.connectedIdx = i;
        ++ret;
    }

    bool anyFound = true;
    while(anyFound) {
        anyFound = false;
        for (int i = 0; i < n; ++i) {
            auto &red = reds[i];
            if (red.fixed || red.connectableIdxes.size() > 1 || red.connectedIdx >= 0) {
                continue;
            }
            auto &blue = blues[red.connectableIdxes[0]];
            if (blue.connectedIdx >= 0) {
                continue;
            }
            red.connectedIdx = red.connectableIdxes[0];
            blue.connectedIdx = i;
            ++ret;
            anyFound = true;
        }
        for (int i = 0; i < n; ++i) {
            auto &blue = blues[i];
            if (blue.fixed || blue.connectableIdxes.size() > 1 || blue.connectedIdx >= 0) {
                continue;
            }
            auto &red = reds[blue.connectableIdxes[0]];
            if (red.connectedIdx >= 0) {
                continue;
            }
            blue.connectedIdx = blue.connectableIdxes[0];
            red.connectedIdx = i;
            ++ret;
            anyFound = true;
        }
    }

    std::vector<int> unfixedRedIdxes;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed) {
            continue;
        }
        unfixedRedIdxes.push_back(i);
    }
    std::sort(unfixedRedIdxes.begin(), unfixedRedIdxes.end(), [](int idx1, int idx2) -> int {
        const auto& red1 = reds[idx1];
        const auto& red2 = reds[idx2];
        if (red1.connectedIdx < 0 && red2.connectedIdx >= 0) {
            return true;
        }
        if (red1.connectedIdx >= 0 && red2.connectedIdx < 0) {
            return false;
        }
        return red1.connectableIdxes.size() < red2.connectableIdxes.size();
    } )

    errOut(ret);
    for (auto&& redIdx: unfixedRedIdxes) {
        auto &red = reds[redIdx];
        if (red.fixed || red.connectedIdx >= 0) {
            continue;
        }
        if (maximizeMatchings(redIdx)) {
            ++ret;
        }
    }

    errOut(ret);
    std::cout << ret << std::endl;
    return 0;
}

