#include<iostream>
#include<algorithm>
using namespace std;

struct point {
	int x; int y;
};

// x座標が小さい順になるように並び替えたいので、このような順序を定義。
bool order(point a, point b) {
	return a.x < b.x;
}

point blue[200];
point red[200];
// 配列の宣言のときに = {}をつけると全部の要素が0になる。
// 必要だったら「配列　初期化」とかでググるとよい。
// この配列usedの役割は後で説明する。
int used[200] = {};

int main() {
	int n;
	cin >> n;
	for (int i = 0; i < n; i++) {
		int p, q;
		cin >> p >> q;
		red[i] = { p,q };
	}
	for (int i = 0; i < n; i++) {
		int p, q;
		cin >> p >> q;
		blue[i] = { p,q };
	}
	int ans = 0;	//最終的な答えがこのansである。ペアを見つけるたびに+1されていく。

	sort(blue, blue + n, order);	//青点をx座標の小さい順にソートする。

	for (int i = 0; i < n; i++) {	//i番目の青点から見ていく。以下、i番目の青点をbiと呼ぶ。

		//今、次のa～cの条件を満たす中で、もっともy座標が大きい赤点を探したいのだった（貪欲法）。
		//a. x座標がbiのx座標よりも小さい。
		//b. y座標がbiのy座標よりも小さい。
		//c. まだどの青点ともペアになっていない。

		int bx = blue[i].x;
		int by = blue[i].y;

		int max_red = -1; 
		int max_red_y = -1000000; 

		//上記の2行と以下のfor文が「配列に入っている要素の中で最大の要素は何番目？」という問題の典型的な解き方。
		//jが0からn-1まで動くが、今まで見てきた中での最大値をmax_red_yに、それが何番目かをmax_redに保存する。
		//それをjが動くごとに更新する。
		//なお、max_red_yに最初はとても小さい値をいれておく。
		//今回は「配列に入っている要素の中で○○の条件を満たすもののうち最大の要素は何番目？」という問題なので、
		//更新は○○の条件を満たす場合のみ更新する。
		//この問題の実装のポイントその1。

		for (int j = 0; j < n; j++) {	

			//上記cの条件（各赤点がもうペアになっているかどうかという状態）を管理しているのが配列usedで、
			//used[j] == 0の場合はj番目の赤点はまだペアになっておらず、1の場合はもうペアになっている。
			//一般に「状態を管理するための配列」をわざわざ用意するというのはよくあるテクで、これが実装のポイントその2。

			if (used[j] == 0 && red[j].x < bx && red[j].y < by && red[j].y > max_red_y) {
				//このifの4条件のうち前3つが上の3条件のチェック
				//その3条件を満たしたうえで、最大値を更新する必要があったら（4番目の条件を満たしたら）更新を行う。
				max_red = j;
				max_red_y = red[j].y;
			}
		}
		//max_redが-1のままであったというのは上の3条件を満たす赤点が見つからなかったということ。
		//見つかった場合はansを+1し、その赤点を使われた状態にする(配列usedのmax_red番目の要素を1にする)
		if (max_red != -1) {
			ans++;
			used[max_red] = 1;
		}
	}
	cout << ans << endl;
}

