class Dinic{
    struct edge{
        int to;
        int rev;
        int cap;
    };
    int n;
    vector<int> level,itr;
    vector<vector<edge>> G;

    void bfs(int s){
        level.assign(n,-1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while(!q.empty()){
            int v = q.front();
            q.pop();
            for(auto &e : G[v]){
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v]+1;
                    q.push(e.to);
                }
            }
        }
    }

    int dfs(int v, int t, int f){
        if(v == t){
            return f;
        }
        for(int& i=itr[v]; i<G[v].size(); i++){
            edge& e = G[v][i];
            if(e.cap > 0 && level[v] < level[e.to]){
                int d = dfs(e.to, t, min(f, e.cap));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    public:

    Dinic(int num){
        n = num;
        G.assign(n,vector<edge>());
    }

    void add_edge(int to, int from, int cap){
        G[from].emplace_back((edge){to, G[to].size(), cap});
        G[to].emplace_back((edge){from, G[from].size()-1, 0});
    }

    int run(int s, int t){
        int ret = 0, f;
        while(bfs(s), level[t]>= 0){
            itr.assign(n,0);
            while((f = dfs(s,t,INT_MAX)) > 0){
                ret += f;
            }
        }
        return ret;
    }
};

