            }
        }
    }
    rep(i, 0, N) {
        fl.add_edge(2 * N, i, 1);
        fl.add_edge(i + N, 2 * N + 1, 1);
    }
    cout << fl.flow(2 * N, 2 * N + 1) << "\n";

