#define MAX_V 100005
#define INF (1 << 30)

class Dinic {
    public:

    struct edge {int to, cap, rev;};

    vector<edge> G[MAX_V];
    int level[MAX_V];
    int iter[MAX_V];

    void add_edge(int from, int to, int cap) {
        G[from].push_back((edge){to, cap, (int)G[to].size()});
        G[to].push_back((edge){to, cap, (int)G[from].size() - 1});
    }

    void bfs(int s) {
        memset(level, -1, sizeof(level));
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while (!que.empty()) {
            int v = que.front(); que.pop();
            for (int i = 0; i < G[v].size(); i++) {
                edge &e = G[v][i];
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    que.push(e.to);
                }
            }
        }
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = iter[v]; i < G[v].size(); i++) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(int s, int t) {
        int flow = 0;
        for (;;) {
            bfs(s);
            if (level[t] < 0) return flow;
            memset(iter, 0, sizeof(iter));
            int f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
    }

};

int main() {

    int N; cin >> N;
    vi a(N), b(N), c(N), d(N);
    REP(i, N) cin >> a[i] >> b[i];
    REP(i, N) cin >> c[i] >> d[i];

    Dinic dinic;

    REP(i, N) REP(j, N) {
        if (a[i] < c[j] && b[i] < d[j]) dinic.add_edge(i, j + N, 1);
    }

    // s -> 2N, t -> 2N + 1
    REP(i, N) {
        dinic.add_edge(2 * N, i, 1);
        dinic.add_edge(i + N, 2 * N + 1, 1);
    }

    cout << dinic.max_flow(2 * N, 2 * N + 1) << endl;


    return 0;
}

