template<typename T,bool directed>
struct Dinic{
  struct edge {
    ll to;
    T cap;
    ll rev;
    edge(){}
    edge(ll to,T cap,ll rev):to(to),cap(cap),rev(rev){}
  };

  vector<vector<edge> > G;
  vector<ll> level,iter;

  Dinic(){}
  Dinic(ll n):G(n),level(n),iter(n){}

  ll add_edge(ll from,ll to,T cap){
    G[from].emplace_back(to,cap,G[to].size());
    G[to].emplace_back(from,directed?0:cap,G[from].size()-1);
    return G[to].back().rev;
  }

  void bfs(ll s){
    fill(level.begin(),level.end(),-1);
    queue<ll> que;
    level[s]=0;
    que.emplace(s);
    while(!que.empty()){
      ll v=que.front();que.pop();
      for(ll i=0;i<(ll)G[v].size();i++){
        edge &e=G[v][i];
        if(e.cap>0&&level[e.to]<0){
          level[e.to]=level[v]+1;
          que.emplace(e.to);
        }
      }
    }
  }

  T dfs(ll v,ll t,T f){
    if(v==t) return f;
    for(ll &i=iter[v];i<(ll)G[v].size();i++){
      edge &e=G[v][i];
      if(e.cap>0&&level[v]<level[e.to]){
        T d=dfs(e.to,t,min(f,e.cap));
        if(d==0) continue;
        e.cap-=d;
        G[e.to][e.rev].cap+=d;
        return d;
      }
    }
    return 0;
  }

  T flow(ll s,ll t,T lim){
    T fl=0;
    while(1){
      bfs(s);
      if(level[t]<0||lim==0) break;
      fill(iter.begin(),iter.end(),0);

      while(1){
        T f=dfs(s,t,lim);
        if(f==0) break;
        fl+=f;
        lim-=f;
      }
    }
    return fl;
  }

  T flow(ll s,ll t){
    return flow(s,t,numeric_limits<T>::max()/2);
  }

  T cut(ll s,ll t,ll x,ll a){
    static_assert(directed, "must be directed");
    auto &e=G[x][a];
    ll y=e.to;
    T ce=e.cap,cr=G[y][e.rev].cap;
    if(cr==0) return 0;
    e.cap=G[y][e.rev].cap=0;
    T cap=cr-flow(x,y,cr);
    if(x!=s&&cap!=0) flow(x,s,cap);
    if(t!=y&&cap!=0) flow(t,y,cap);
    e.cap=ce+cr;
    return cap;
  }
};
