void solve() {
    int n; scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", r[i], r[i]+1);
    }
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", b[i], b[i]+1);
