            cntR[i] = 0;
            for (int j = 0; j < n; ++j) {
                if (used[j]) continue;
                if (r[i][0] < b[j][0] && r[i][1] < b[j][1]) {
                    ++cntR[i];
                    ++cntB[j];
                }
            }
        }
        int ind = 0;
        for (int i = 1; i < n; ++i) {
            if (cntR[i] == 0) continue;
            if (cntR[i] < cntR[ind]) {
                ind = i;
            }
