    int a[n], b[n], c[n], d[n];
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> c[i] >> d[i];
    }

    pair<int, int> cnt_r[n]; // pair<要素数, 赤のID>
    for (int i = 0; i < n; ++i) {
        cnt_r[i].first = 0;
    }
    for (int i = 0; i < n; ++i) {
        cnt_r[i].second = i;
    }
    vector<vector<int>> friend_r(n); // 赤のID<青のID>

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (c[j] - a[i] > 0 && d[j] - b[i] > 0) {
                cnt_r[i].first++;
                friend_r[i].push_back(j);
            }
        }
    }

    sort(cnt_r, cnt_r + n);

    int friend_num = 0;
    for (int i = 0; i < n; ++i) {
        if (cnt_r[i].first == 0) { // 仲良しペアできない
            continue;
        } else {
            friend_num++;
            int friend_pair = friend_r[cnt_r[i].second][0]; // 青のID取得
            for (int j = 0; j < n; ++j) {
                if (vector_finder(friend_r[j], friend_pair) == 1) {
