                    friend_r[j].erase(remove(friend_r[j].begin(), friend_r[j].end(), friend_pair), friend_r[j].end());

                    for (int k = 0; k < n; ++k) {
                        if (j == cnt_r[k].second) {
                            cnt_r[k].first--;
                        }
                    }
                }
            }
        }
    }

    cout << friend_num << endl;
    return 0;
}

