            dist[u] = INT_MAX;
            return false;
        }
        return true;
    }
    void add(int a, int b) { b += n; E[a + 1].push_back(b + 1); E[b + 1].push_back(a + 1); }
    int whois(int x) { return match[x + 1] - 1; }
    int solve() {
        rep(i, n + m + 1) match[i] = 0;
        int res = 0;
        while (bfs()) REP(i, 1, n + 1) if (!match[i] && dfs(i)) res++;
        return res;
    }
};

