int main()
{
    int n; cin >> n;
    vector<int> a(n), b(n), c(n), d(n);
    for (int i = 0; i < n; ++i) cin >> a[i] >> b[i];
    for (int i = 0; i < n; ++i) cin >> c[i] >> d[i];
    int ans = 0;

    for (int i = 0; i < n; ++i) {
        // c_min: bA最小
        auto c_min = min_element(c.begin(), c.end());
        int cd_idx = distance(c.begin(), c_min);

        vector<int> t_idx;
        vector<int> t_num;
        for (int i = 0; i < a.size(); ++i) {
            if (a[i] < *c_min && b[i] < d[cd_idx]) {
                t_idx.push_back(i);
                t_num.push_back(b[i]);
            }
        }

        if (!t_idx.size()) {
            c.erase(c_min);
            d.erase(d.begin() + cd_idx);
            continue;
        }

        auto ab_max = max_element(t_num.begin(), t_num.end());
        int  ab_max_idx = t_idx[distance(t_num.begin(), ab_max)];

        if (ab_max != t_num.end()) {
            a.erase(a.begin() + ab_max_idx);
            b.erase(b.begin() + ab_max_idx);
            c.erase(c.begin() + cd_idx);
            d.erase(d.begin() + cd_idx);
        }

        ++ans;
    }

    cout << ans << endl;

    return 0;
}

