		rep(j, n) {
			if (a[i].first < b[j].first and a[i].second < b[j].second) {
				g[i].emplace_back(n + j);
				g[n + j].emplace_back(i);
			}
		}
	}
	cout << gabowEdmonds(g).size() << endl;
}

