void delCandidate(point bp, vector<redp> &rpv){
	for(int i = 0; i < rpv.size(); i++){
		vector<point> &v = get<2>(rpv[i]);
		for(int j = 0; j < v.size(); j++){
			if(v[j] == bp){
				v.erase(v.begin() + j);
				get<0>(rpv[i]) -= 1;
				break;
			}
		}
		get<0>(rpv[i]) = v.size();
	}
}

int countCandidate(point bp, vector<redp> &rpv){
	int ret = 0;
	for(int i = 0; i < rpv.size(); i++){
		vector<point> &v = get<2>(rpv[i]);
		for(int j = 0; j < v.size(); j++){
			if(v[j] == bp){
				ret++;
			}
		}
	}
	return ret;
}

int getBulePoint(point rp, vector<point> &bpv){
	int ret = 0;
	for(int i=0; i<redv.size(); i++){
		point p = get<1>(redv[i]);
		if(p == rp){
			ret = 1;
			point candp = (get<2>(redv[i]))[0];
			delCandidate(candp, redv);
			bmap[candp] = 0;
			break;
		}
	}
	return ret;
}

void initRedPoints(){
	for(int i=0; i<redv.size(); i++){
		point rp = get<1>(redv[i]);
		vector<point> &v = get<2>(redv[i]);
		for(int j=0; j<bluev.size(); j++){
			point bp = bluev[j];
			if(bp.first > rp.first && bp.second > rp.second){
				v.push_back(bp);
				bmap[bp]++;
			}
		}
		get<0>(redv[i]) = v.size(); 
	}
	int ezero = 1;
	while(ezero == 1){
		for(int i=0; i<redv.size(); i++){
			int cand = get<0>(redv[i]);
			if(cand == 0){
				redv.erase(redv.begin() + i);
				break;
			}
		}
		ezero = 0;
		for(int i=0; i<redv.size(); i++){
			int cand = get<0>(redv[i]);
			if(cand == 0){
				ezero = 1;
				break;
			}
		}
	}
}

point searchBestBluePoint(vector<redp> &v, int &min_r, int &min_b){
	point retp;
	int min_cand = 100;
	for(int i=0; i<v.size(); i++){
		if(get<0>(v[i]) == 0) continue;
		vector<point> w = get<2>(v[i]);
		for(int j=0; j<w.size(); j++){
			if( min_cand > bmap[w[j]] ){
				min_cand = bmap[w[j]];
				retp = w[j];
				min_r = i;
				min_b = j;
			}
		}
	}
	return retp;
}

