		to = _to;
		cap = _cap;
		rev = _rev;
	}
};

typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

struct Flow {
	Graph G;
	vb used;
	int V;
	Flow() {}
	Flow(int _V) {
		V = _V;
		G = Graph(V);
	}
	//fromからtoまでの容量capの辺を張る。
	void add_edge(int from, int to, int cap) {
		G[from].push_back(Edge(to, cap,SZ(G[to])));
		G[to].push_back(Edge(from, 0, SZ(G[from]) - 1));
	}

	int dfs(int v, int t, int f) {
		if (v == t)return f;
		used[v] = true;
		for (Edge &e : G[v]) {

			if (!used[e.to] && e.cap > 0) {
				int d = dfs(e.to, t, min(f, e.cap));
				if (d > 0) {
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	int max_flow(int s, int t) {
		int flow = 0;
		while (true) {
			used = vb(V,false);
			int f = dfs(s, t, INF);
			if (f == 0)return flow;
			flow += f;
		}
	}
};

