{
  cin >> N;
  REP(i, 2 * N)
  {
    v.push_back(false);
  }
  REP(i, N)
  {
    set<ll> t;
    cin >> x >> y;
    ab.push_back(make_pair(x, y));
    n.push_back(t);
  }
  REP(i, N)
  {
    set<ll> t;
    cin >> x >> y;
    REP(j, N)
    {
      if (ab[j].first < x && ab[j].second < y)
      {
        n[j].insert(N + i);
        t.insert(j);
      }
    }
    n.push_back(t);
  }

  REP(i, 2 * N)
  {
    for (auto &j : n[i])
    {
      if (v[i] || v[j])
        continue;

      g.insert(i < j ? (pll){i, j} : (pll){j, i});
      v[i] = v[j] = true;
    };
  }

  calc();

  cout << g.size() << '\n';

  return 0;
}

