			if (used[j] == 0 && red[j].x < bx&&red[j].y<by&&red[j].y>max_red_y) {
				max_red = j;
				max_red_y = red[j].y;
			}
		}
		if (max_red != -1) {
			ans++;
			used[max_red] = 1;
		}
	}
	cout << ans << endl;
	return 0;
}

