#include <bits/stdc++.h>
#define all(x) (x).begin(), (x).end()
typedef long long ll;
#define MOD 1000000007
using namespace std;
#define MAX_V 20
struct edge {
    int to, cap, rev;
};
vector<edge> G[MAX_V];
vector<bool> used;
void add_edge(int from, int to, int cap) {
    // G[to].size()をrevに保持することでG[edge.to][edge.rev]で逆辺の構造体にアクセスできる
    G[from].push_back((edge){to, cap, (int)G[to].size()});
    G[to].push_back((edge){from, 0, (int)G[from].size() - 1});
}
int dfs(int v, int t, int f) {
    if(v == t) {
        return f;
    }
    used[v] = true;
    for(int i = 0; i < (int)G[v].size(); i++) {
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            // d==0ならtにたどり着かない
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
int max_flow(int s, int t) {
    int flow = 0;
    for(;;) {
        used.assign(MAX_V, 0);
        int f = dfs(s, t, MOD);
        if(f == 0) {
            return flow;
        }
        flow += f;
    }
}
int main() {
    int n;
    cin >> n;
    vector<vector<int>> red(n, vector<int>(2));
    for(int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        red[i][0] = a;
        red[i][1] = b;
    }
    vector<vector<int>> blue(n, vector<int>(2));
    for(int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        blue[i][0] = a;
        blue[i][1] = b;
    }
    for(int i = 0; i < n; i++) {
        add_edge(0, i + 1, 1);
    }
    for(int i = 0; i < n; i++) {
        add_edge(i + n + 1, 2 * n + 1, 1);
    }
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(red[i][0] < blue[j][0] && red[i][1] < blue[j][1]) {
                add_edge(i + 1, j + n + 1, 1);
            }
        }
    }
    cout << max_flow(0, 2 * n + 1) << endl;
}

