#include <vector>
using namespace std;

struct edge{
	int to, cap, rev;
};

bool used[V];
vector<vector<edge>> G(V);

void add_edge(int from, int to, int cap){
	edge F, T;
	F.to = to;
	F.cap = cap;
	F.rev = G[to].size();
	G[from].push_back(F);

	T.to = from;
	T.cap = 0;
	T.rev = G[from].size()-1;
	G[to].push_back(T);
}

int dfs(int v, int t, int f){
	if(v==t) return f;
	used[v]=1;
	int i, l=G[v].size();
	for(i=0; i<l; i++){
		edge &e=G[v][i];
		if(used[e.to]==0 && e.cap>0){
			int d = dfs(e.to, t, min(f, e.cap));
			if(d>0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(int s, int t){
	int flow = 0;
	while(1){
		memset(used, 0, sizeof(used));
		int f = dfs(s, t, INT_MAX);
		if(f==0) return flow;
		flow += f;
	}
}

