bool fnd(int x,int n) {
    for(int j=1;j<=n;j++) {
        if(match[x][j]&&!used[j]){
            used[j]=true;
            if(girl[j]==0||fnd(girl[j],n)){
                girl[j]=x;
                return true;
            }
        }
    }
    return false;
}
int solve(int m,int n){
    int ans=0;
    for(int i=1;i<=m;i++) {
        memset(used,false,sizeof(used));
        if(fnd(i,n))ans++;
    }
    return ans;
}
