int main() {
  int N;
  cin >> N;
  int a, b;
  vector<P> red;
  for (int i = 0; i < N; i++) {
    cin >> a >> b;
    red.push_back(P(a, b));
  }
  vector<P> blue;
  for (int i = 0; i < N; i++) {
    cin >> a >> b;
    blue.push_back(P(b, a));
  }

  int ans = 0;
  sort(blue.begin(), blue.end());
  bool flag[N];
  fill(flag, flag + N, false);
  for (int i = 0; i < N; i++) {
    int nearest = -1;
    int dist = INF;
    for (int j = 0; j < N; j++) {
      if (flag[j]) {
        continue;
      }
      if (red[j].first >= blue[i].second || red[j].second >= blue[i].first) {
        continue;
      }

      if (dist > (blue[i].second - red[j].first) + (blue[i].first - red[j].second)) {
        dist = (blue[i].second - red[j].first) + (blue[i].first - red[j].second);
        nearest = j;
      }
    }

    if (nearest != -1) {
      flag[nearest] = true;
      ans++;
    }
  }

  cout << ans << endl;

  return 0;
}

