vector<int> adj[210];
int match[210];
bool used[210];

bool dfs(int v)
{
	used[v] = true;

	for (int i = 0; i < adj[v].size(); i++)
	{
		int u = adj[v][i], w = match[u];


		if (w < 0 || (!used[w] && dfs(w)))
		{
			match[v] = u;
			match[u] = v;
			return true;
		}

	}
	return false;
}

