	}
	for (int i = 1; i <= n; i++)
	{
		cin >> c[i] >> d[i];
	}

	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= n; j++)
		{
			if (a[i] < c[j] && b[i] < d[j])
			{
				adj[i].push_back(j + n);
				adj[j + n].push_back(i);
			}
		}
	}

	int res = 0;

	memset(match, -1, sizeof(match));

	for (int i = 1; i <= n; i++)
	{
		if (match[i] < 0)
		{
			memset(used, 0, sizeof(used));

			if (dfs(i))
			{
				res++;
			}
		}
	}
	cout << res << endl;
}

