//辺の構造体　
struct edge{
    //行き先、容量、逆辺の場所
    ll to,cap,rev;
};
//グラフの隣接リスト
vector<vector<edge>> G(MAX_V);
//DFSで調べた頂点を記録
bool used[MAX_V];

//辺の情報を代入する関数
void add_edge(ll from,ll to,ll cap){
    edge F,T;
    F.to=to;
    F.cap=cap;
    F.rev=G[to].size();
    G[from].push_back(F);
    T.to=from;
    T.cap=0;
    T.rev=G[from].size()-1;
    G[to].push_back(T);
}
//増加パスをDFSで探す
ll dfs(ll v,ll t,ll f){
    if(v==t)return f;
    used[v]=true;
    for(int i=0;i<G[v].size();i++){
        edge &e=G[v][i]; //辺の容量を更新するためのアドレス
        if(!used[e.to]&&e.cap>0){
            ll d=dfs(e.to,t,min(f,e.cap));
            if(d>0){
                e.cap-=d;//使った分減らす
                G[e.to][e.rev].cap+=d;//使った分逆辺の容量を増やす
                return d;
            }
        }
    }
    return 0;
}
//sからtへの最大流を求める
ll max_flow(ll s,ll t){
   ll flow=0;
   while(1){
       memset(used,sizeof(used),false);
       ll f=dfs(s,t,inf);
       if(f==0)return flow;
       flow+=f;
   }
}
