using namespace std;

int main()
{
	int n;
	cin >> n;
	auto a = vector<int>(n);
	auto b = a, c = a, d = a;
	for(auto i = 0; i < n; ++i){
		cin >> a[i] >> b[i];
	}
	for(auto i = 0; i < n; ++i){
		cin >> c[i] >> d[i];
	}
	auto g = vector<vector<int>>(n * 2);
	for(auto i = 0; i < n; ++i){
		for(auto j = 0; j < n; ++j){
			if(a[i] < c[j] && b[i] < d[j]){
				g[i].push_back(n + j);
				g[n + j].push_back(i);
			}
		}
	}
	auto m = vector<int>(n * 2, -1);
	auto bipartite = [&g, &m](auto bipartite, int a, vector<bool>& visited) -> bool {
		for(auto i = 0; i < (int)g[a].size(); ++i){
			int e = g[a][i];
			if(visited[e]) continue;
			if(m[e] == -1){
				m[a] = e;
				m[e] = a;
				return true;
			}else{
				visited[e] = true;
				if(bipartite(bipartite, m[e], visited)){
					m[a] = e;
					m[e] = a;
					return true;
				}
			}
		}
		return false;
	};
	int ans = 0;
	for(auto i = 0; i < n; ++i){
		auto v = vector<bool>(n * 2);
		if(bipartite(bipartite, i, v)) ++ans;
	}
	cout << ans << endl;
	return 0;
}

