struct Edge {
    int from, to, cap, rev;
    Edge(int f, int t, int c, int r) : from(f), to(t), cap(c), rev(r) {} // 初期化
};

struct Graph {
    vector<vector<Edge>> G;
    Graph(int n = 0) : G(n) {} // 初期化

    vector<Edge>& operator[](int i) { return G[i]; }
    int size() { return G.size(); }
    void add_edge(int from, int to, int cap) {
        G[from].push_back(Edge(from, to, cap, (int)G[to].size()));
        G[to].push_back(Edge(to, from, 0, (int)G[from].size() - 1));
    } // 有向辺を加える
};

struct Dinic {
    const int INF = 1e9;
    vector<int> level, iter; 
    Dinic(){}; // 初期化

    void bfs(Graph &G, int s){
        level.assign(G.size(), -1);
        queue<int> que;
        level[s] = 0;
        que.push(s);
        while(!que.empty()){
            int v = que.front(); que.pop();
            for(int i=0; i<G[v].size(); i++){
                Edge &e = G[v][i];
                if(e.cap > 0 && level[e.to] < 0){
                    level[e.to] = level[v]+1;
                    que.push(e.to);
                }
            }
        }
    }

    int dfs(Graph &G,int s, int g, int f){
        if(s == g) return f;
        for(int &i = iter[s]; i < G[s].size(); i++){
            Edge &e = G[s][i];
            if(e.cap > 0 && level[s] < level[e.to]){
                int d = dfs(G, e.to, g, min(e.cap, f));
                if(d > 0){
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int max_flow(Graph &G, int s, int g){
        int flow = 0;
        while(true){
            bfs(G,s);
            if(level[g] < 0) return flow;
            iter.assign(G.size(), 0);
            int f;
            while((f = dfs(G, s, g, INF)) > 0) flow += f;
        }
    }
};

