typedef long long ll;

class Dinic {
  private:
    struct edge {
      int to;
      int capacity;
      int reverse;
    };
    std::vector<std::vector<edge>> G;
    std::vector<int> level;
    std::vector<int> iter;

    int dfs(int v, int t, int f) {
      if ( v == t ) return f;
      for(int &i = iter[v]; i<G[v].size(); i++){
        edge &e = G[v][i];
        if ( e.capacity > 0 && level[v] < level[e.to] ) {
          int d = dfs(e.to, t, std::min(f, e.capacity));
          if ( d > 0 ) {
            e.capacity -= d;
            G[e.to][e.reverse].capacity += d;
            return d;
          }
        }
      }
      return 0;
    }

    void bfs(int s) {
      std::fill(level.begin(), level.end(), -1);
      std::queue<int> que;
      level[s] = 0;
      que.push(s);
      while(!que.empty()){
        int v = que.front(); que.pop();
        for(int i=0; i<G[v].size(); i++) {
          edge &e = G[v][i];
          if ( e.capacity > 0 && level[e.to] < 0 ) {
            level[e.to] = level[v] + 1;
            que.push(e.to);
          }
        }
      }
    }

  public:
    Dinic(int MAX_V){
      G.resize(MAX_V);
      level.resize(MAX_V);
      iter.resize(MAX_V);
    }

    void AddEdge(int from, int to, int capacity) {
      edge k;   k.to = to;    k.capacity = capacity;  k.reverse = G[to].size();
      edge kk; kk.to = from; kk.capacity = 0;        kk.reverse = G[from].size();
      G[from].push_back(k);
      G[to]  .push_back(kk);
    }

    int max_flow(int s, int t) {
      int flow = 0;
      for(;;) {
        bfs(s);
        if ( level[t] < 0 ) return flow;
        std::fill(iter.begin(), iter.end(), 0);
        int f;
        while( (f=dfs(s,t,std::numeric_limits<int>::max())) > 0 ){
          flow += f;
        }
      }
    }
};

int main (void) {
  int N; std::cin >> N;
  std::vector<std::pair<int,int>> Red(N), Blue(N);
  for(int i=0; i<N; i++) std::cin >> Red[i].first  >> Red[i].second;
  for(int i=0; i<N; i++) std::cin >> Blue[i].first >> Blue[i].second;

  // 0 : source,  1~N red, N+1 ~ 2*N blue,  2N+1 sink
  Dinic d(2*N + 2);
  for(int i=0; i<N; i++) d.AddEdge(0, i+1, 1);
  for(int i=0; i<N; i++) d.AddEdge(N+i+1, 2*N+1, 1);
  for(int i=0; i<N; i++) {
    for(int j=0; j<N; j++) {
      if ( Red[i].first < Blue[j].first && Red[i].second < Blue[j].second ) {
        d.AddEdge(i+1, N+j+1, 1);
      }
    }
  }
  std::cout << d.max_flow(0, 2*N+1) << std::endl;
  return 0;
}

