void rec(const pair<int, int> *a, const pair<int, int> *b, const int &n, const int &index, int m, const V<char> table, int &ans) {
    if (n == index) {
        Max(ans, m);

        return;
    }

    pair<int, int> p1, p2;

    int i, j;

    repi(i, n, index) {
        p1 = a[i];

        rep(j, n) {
            if (table[j] == 1) continue;

            p2 = b[j];

            if (p1.first < p2.first && p1.second < p2.second) {
                V<char> _table = V<char>(all(table));

                _table[j] = 1;

                rec(a, b, n, i + 1, m + 1, _table, ans);
            }
        }
    }
}

void solve(const pair<int, int> *a, const pair<int, int> *b, const int &n) {
    int ans = 0;
    pair<int, int> p1, p2;

    int i, j;

    rep(i, n) {
        p1 = a[i];

        rep(j, n) {
            p2 = b[j];

            if (p1.first < p2.first && p1.second < p2.second) {
                V<char> table(n, 0);

                table[j] = 1;

                rec(a, b, n, i + 1, 1, table, ans);
            }
        }
    }

    Out(ans);
}

