bool compare_by_a(pair<int, int> a, pair<int, int> b) {
    if(a.first != b.first){
        return a.first < b.first;
    }else{
        return a.second < b.second;
    }
}

int main(){
  int n; 
  cin >> n;
  vector<pair<int, int>> red;
  vector<pair<int, int>> blue;
  for(int i=0; i<n; i++){
    int a, b;
    cin >> a >> b;
    red.push_back(make_pair(a, b));
  }
  for(int i=0; i<n; i++){
    int a, b;
    cin >> a >> b;
    blue.push_back(make_pair(a, b));
  }
  sort(red.begin(), red.end(), compare_by_a);
  sort(blue.begin(), blue.end(), compare_by_a);

  int count = 0;
  for(int i=0; i<n; i++){
    vector<int> leftThanBlue;
    for(int j=0; j<n; j++){
      if(red[j].first < blue[i].first) leftThanBlue.push_back(j);
    }
    int topOfUnderThanBlue = -1;
    int index = -1;
    for(int j=0; j<leftThanBlue.size(); j++){
      int checkingRedY = red[leftThanBlue[j]].second;
      if(checkingRedY < blue[i].second && checkingRedY > topOfUnderThanBlue){
        topOfUnderThanBlue = checkingRedY;
        index = leftThanBlue[j];
      }
    }
    if(index != -1){
      red.erase(red.begin() + index);
      count++;
    }
  }
  cout << count << endl;
  return 0;
}

