using namespace std;

typedef long long ll;
typedef pair<int, int> P;

bool pairCompare(const P& firstElof, const P& secondElof)
{
    return firstElof.second < secondElof.second;
}

int main()
{
    int N;
    cin >> N;
    vector<P> red, blue;
    REP(i, N)
    {   
        int x, y;
        cin >> x >> y;
        P p(x, y);
        red.push_back(p);
    }
    REP(i, N)
    {   
        int x, y;
        cin >> x >> y;
        P p(x, y);
        blue.push_back(p);
    }

    // x座標でソート
    sort(red.begin(), red.end());
    sort(blue.begin(), blue.end());
    int redAns = 0;
    bool isUsedX[N] = {false};
    REP(i, N)
    {
        int a, b;
        a = red[i].first;
        b = red[i].second;
        REP(j, N)
        {
            if (!isUsedX[j])
            {
                int c, d;
                c = blue[j].first;
                d = blue[j].second;
                if (a < c && b < d)
                {
                    redAns++;
                    isUsedX[j] = true;
                    break;
                }
            }
        }
    }

    // y座標でソート
    sort(red.begin(), red.end(), pairCompare);
    sort(blue.begin(), blue.end(), pairCompare);
    int blueAns = 0;
    bool isUsedY[N] = {false};
    REP(i, N)
    {
        int a, b;
        a = red[i].first;
        b = red[i].second;
        REP(j, N)
        {
            if (!isUsedY[j])
            {
                int c, d;
                c = blue[j].first;
                d = blue[j].second;
                if (a < c && b < d)
                {
                    blueAns++;
                    isUsedY[j] = true;
                    break;
                }
            }
        }
    }

    int ans = max(redAns, blueAns);

    cout << ans << endl;
}

