class xy{
public:
  int x, y;
  xy() {x = y = 0;}
  xy(int u, int v) {x = u; y = v;}
};

bool compare_U(const pair<xy, bool> &u, const pair<xy, bool> &v)
{
  if(u.first.y == v.first.y) return u.first.x < v.first.x;
  return u.first.y < v.first.y;
}

bool compare_V(const pair<xy, bool> &u, const pair<xy, bool> &v)
{
  if(u.first.x == v.first.x) return u.first.y < v.first.y;
  return u.first.x < v.first.x;
}

void Main(){
  int N; cin >> N;
  vector<pair<xy, bool>> U, V;
  rep(i, 0, N){
    int x, y; cin >> x >> y;
    xy tmp(x, y);
    pair<xy, bool> p = make_pair(tmp, false);
    U.push_back(p);
  }
  rep(i, 0, N){
    int x, y; cin >> x >> y;
    xy tmp(x, y);
    pair<xy, bool> p = make_pair(tmp, false);
    V.push_back(p);
  }
  sort(U.begin(), U.end(), compare_U);
  sort(V.begin(), V.end(), compare_V);
  int res = 0;
  rep(i, 0, N){
    rep(j, 0, N){
      if(V[j].second) continue;
      if(U[N-i-1].first.x < V[j].first.x && U[N-i-1].first.y < V[j].first.y){
        U[N-i-1].second = true;
        V[j].second = true;
        res++;
        break;
      }
    }
  }
  cout << res << endl;
}

