typedef pair<int,int> pii;
int N;

bool fa_sd(pii A, pii B){
    if(A.first != B.first){
      return A.first < B.first;
    }else{
      A.second > B.second;
    }
  }
bool sd_fd(pii A, pii B){
    if(A.second != B.second){
      return A.second > B.second;
    }else{
      A.first > B.first;
    }
  }

struct Solver{
  vector<pii> _r;
  vector<pii> _b;
  explicit Solver(vector<pii> r, vector<pii> b) : _r(r), _b(b){
    sort(_b.begin(), _b.end(), fa_sd);
    sort(_r.begin(), _r.end(), sd_fd);
  }
  bool check(pii Blue, pii Red){
    if(Blue.first > Red.first && Blue.second > Red.second){
      return true;
    }else{
      return false;
    }
  }
  int solve(){
    int ans=0;
    for(int i=0; i<N; i++){
      int M = (int)_r.size();
      for(int j=0; j<M; j++){
        if(check(_b[i], _r[j])){
          ans++;
          _r.erase(_r.begin()+j);
          break;
        }
      }
    }
    return ans;
  }
};

