int R_paired[101];

void solve()
{
    int N;
    cin >> N;
    vector<pii> R(N);
    vector<pii> B(N);

    REP0(i, N)
    {
        cin >> R[i].first >> R[i].second;
    }

    REP0(i, N)
    {
        cin >> B[i].first >> B[i].second;
    }

    sort(R.begin(), R.end());
    sort(B.begin(), B.end());

    int ans = 0;

    for (auto b : B)
    {
        int max_r_y = -1;
        int argmax_r_y = -1;

        for (int i = 0; R[i].first < b.first; i++)
        {
            if (R_paired[i])
                continue;

            if (max_r_y < R[i].second and R[i].second < b.second)
            {
                max_r_y = max(R[i].second, max_r_y);
                argmax_r_y = i;
            }
        }

        if (argmax_r_y != -1)
        {
            R_paired[argmax_r_y] = 1;
            ans++;
        }
    }

    cout << ans << endl;
}

