template <class T> T modpower(T a,T b,T MOD)
{
    T ans=1;
    while(b!=0)
    {
        if(b%2==1)
        ans=(ans*a)%MOD;
        a=(a*a)%MOD;
        b/=2;
    }
    return ans;
}

bool bp[102][102];

bool bpm(int N, int u, bool seen[], int matchR[])
{
    for (int v = 0; v < N; v++)
    {
        if (bp[u][v] && !seen[v])
        {
            seen[v] = true;
            if (matchR[v] < 0 || bpm(N, matchR[v], seen, matchR))
            {
                matchR[v] = u;
                return true;
            }
        }
    }
    return false;
}

int maxbpm(int N)
{
    int matchR[N];
    memset(matchR, -1, sizeof(matchR));
    int result = 0;
    for (int u = 0; u < N; u++)
    {
        bool seen[N];
        memset(seen, 0, sizeof(seen));
        if (bpm(N,u, seen, matchR))
            result++;
    }
    return result;
}

