        cin >> p.x >> p.y;
        a.push_back(p);
    }
    for(int i = 0; i<N; i++){
        pt p;
        cin >> p.x >> p.y;
        b.push_back(p);
    }

    sort_pt(a);
    sort_pt(b);

    for(auto& p : b){
        for(auto it = a.begin(); it != a.end(); it++){
