DWORD dfs(DWORD v, DWORD t, DWORD f)
{
	if (v == t) return f;
	used[v] = true;
	for (int i = 0; i < G[v].size(); i++) {
		EDGE &e = G[v][i];

		if(!used[e.to] && e.cap > 0) {
			DWORD d = dfs(e.to, t, min(f, e.cap));
			if (d > 0) {
				e.cap  -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

DWORD maxFlow(DWORD s, DWORD t)
{
	DWORD flow = 0;

	while(1) {
		memset(used, 0, sizeof(used));
		DWORD f = dfs(s, t, INF);
		if (f == 0) return flow;
		flow += f;
	}

}

