    {
      if (ab[i].first < cd[j].first && ab[i].second < cd[j].second)
      {
        addEdge(i, j + n, 1, g);
      }
    }
  }

  REP(i, n)
  {
    addEdge(2 * n, i, 1, g);
    addEdge(i + n, 2 * n + 1, 1, g);
  }

