    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (a[i] < c[j] and b[i] < d[j]) {
                add_edge(i+1, n+j+1, 1);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        add_edge(0, i+1, 1);
        add_edge(n+i+1, 2*n+1, 1);
    }

    cout << max_flow(start, goal) << endl;

    return 0;
}

