lnt PAIR(const lnt &x0, const lnt &N) {
  lnt x = x0;
  vector<lnt> tri;
  LOOP(N) {
    tri.push_back(x % 3);
    x /= 3;
  }

  lnt y = 0;
  INVREP(j, N) {
    y *= 3;
    y += (3 - tri.at(j)) % 3;
  }
  return y;
}

