        return min(riLeft.first,riLeft.second) < min(riRight.first , riRight.second) || (min(riLeft.first,riLeft.second) == min(riRight.first , riRight.second) && riLeft.first < riRight.first) || (min(riLeft.first,riLeft.second) == min(riRight.first , riRight.second) && riLeft.first == riRight.first && riLeft.second < riRight.second); // ここでは、元の < の意味に合わせてあるが、異なる判断も可能。
    }
};

