using namespace std;

#define N 100

int board[2*N][2*N] = {0};
int n;

bool search( int x, int y )
{
	int remain = max( 2*n - x, 2*n - y );
	for( int w = 1; w < remain; w++ ) {
		if( y+w < 2*n ) {
			int xlimit = x+w+1;
			if( xlimit > 2*n ) {
				xlimit = 2*n;
			}
			for ( int xx = x; xx < xlimit; xx++ ) {
				if( board[xx][y+w] < 0 ) {
					board[xx][y+w] = 0;
					return true;
				}
			}
		}
		if( x+w < 2*n ) {
			int ylimit = y+w+1;
			if( ylimit > 2*n ) {
				ylimit = 2*n;
			}
			for ( int yy = y; yy < ylimit; yy++ ) {
				if( board[x+w][yy] < 0 ) {
					board[x+w][yy] = 0;
					return true;
				}
			}
		}
	}
	return false;
}

int main()
{
	int a, b, c, d;
	int ans = 0;

	cin >> n;

	for( int i = 1; i <= n; i++ ) {
		cin >> a >> b;
		board[a][b] = i;
	}
	for( int i = 1; i <= n; i++ ) {
		cin >> c >> d;
		board[c][d] = -i;
	}

	for( int w = 2*n - 1; w >= 0; w-- ) {
		for( int i = 0; i <= w; i++ ) {
			if( board[w - i][w] > 0 ) {
				bool b = search( w - i, w );
				if( b == true ) {
					ans++;
					board[w - i][w] = 0;
				}
			}
			if( i == 0 ) {
				continue;
			}
			if( board[w][w - i] > 0 ) {
				bool b = search( w, w - i );
				if( b == true ) {
					ans++;
					board[w][w - i] = 0;
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

