  for (int i = 0; i < n; i++)
  {
    add_edge(s, i, 1);
  }

  for (int i = 0; i < n; i++)
  {
    add_edge(n + i, t, 1);
  }

  for (int i = 0; i < n; i++)
  {
    for (int j = 0; j < k; j++)
    {
      if (can[i][j])
      {
        add_edge(i, n + j, 1);
      }
    }
