        blue[i].x = a;
        blue[i].y = b;
    }

    sort(red.begin(), red.end(), comp_x);
    sort(blue.begin(), blue.end(), comp_y);

    int cnt=0, i=0, j=0;
    bool used[n];
    for(int i=0; i<n; i++) used[i] = false;

    while(i<n) {
        j=0;
        while(j<n && (red[i].x>=blue[j].x || red[i].y>=blue[j].y || used[j])) {
            j++;
        }
        if(j<n && !(used[j])) {
            used[j]=true;
            cnt++;
        }
        i++;
    }
    cout << cnt << endl;


    return 0;
}

