int dfs(int x, vector<bool> &check) {
  int y = 0;
  if (x == N) return y;
  for (int i = 0; i < G[x].size(); i++) {
    if (check[G[x][i]]) {
      check[G[x][i]] = false;
      y = max(y,1 + dfs(x+1, check));
      check[G[x][i]] = true;
    } 
