int main()
{
	int n,A[100],B[100],C[100],D[100];
	int big[100],small[100];
	cin>>n;
	for(int i=0;i<n;i++){
		cin>>A[i]>>B[i];
		big[i]=0;
	} 
	for(int i=0;i<n;i++){
		cin>>C[i]>>D[i];
		small[i]=0;
		for(int j=0;j<n;j++){
			if(A[j]<C[i] and B[j]<D[i]){
				small[i]++;
				big[j]++;
			}
		}
	} 

	int ans=0;
	while(1){
		int k=-1;
		int count=101;
		for(int i=0;i<n;i++){
			if(small[i]<=0) continue;
			if(small[i]<count){
				k=i;
				count=small[i];
			}
		}
		if(count>100) break;
		small[k]=0;
		count=0;
		int x=-1;
		int count1=101;
		for(int j=0;j<n;j++){
			if(big[j]<=0) continue;
			if(A[j]<C[k] and B[j]<D[k]){
				big[j]--;
				if(big[j]<count1) {
					count1=big[j];
					x=j;
				}
				count++;
			}
		}
		if(count>0) ans++;
		if(x>=0) {
			big[x]=0;
			for(int i=0;i<n;i++){
				if(A[x]<C[i] and B[x]<D[i]) small[i]--;
			}
		}
	}
	cout<<ans;
	system ("pause");
    return 0;
}

