typedef long long ll;
using Graph = vector<vector<int>>;
const ll INF = 1LL << 60;

bool augment(const Graph& g, int u,vector<int>& matchTo, vector<bool>& visited) {
    if (u < 0) return true;
    for(auto to : g[u]){
        if (!visited[to]) {
            visited[to] = true;
            if (augment(g, matchTo[to], matchTo, visited)) {
                matchTo[u] = to;
                matchTo[to] = u;
                return true;
            }
        }
    }
    return false;
}

int bipartiteMatching(const Graph& g, int L, vector<pair<int,int>> &matching) {
    const int n = g.size();
    vector<int> matchTo(n, -1);
    int match = 0;
    rep(u,L) {
        vector<bool> visited(n);
        if (augment(g, u, matchTo, visited)) ++match;
    }
    rep(u, L) if (matchTo[u] >= 0) // make explicit matching
    matching.push_back(make_pair(u,matchTo[u]));
    return match;
}

