    vector<pair<pair<int,int>,bool>> r(n), b(n);
    rep(i, n){
        int x, y;
        cin >> x >> y;
        r[i] = make_pair(make_pair(y,x),false);
    }
    rep(i, n){
        int x, y;
        cin >> x >> y;
        b[i] = make_pair(make_pair(x,y),false);
    }

    int cnt = 0;
    sort(b.begin(), b.end());
    sort(r.rbegin(), r.rend());
    for(auto& bp : b){
        for(auto& rp : r){
            if(bp.first.first > rp.first.second and bp.first.second > rp.first.first and !rp.second){
                bp.second = true;
                rp.second = true;
                cnt++;
                break;
            }
        }
    }

    ppp(cnt);

    return 0;
}

