const int mod = 1e9 + 7;
const ll inf = 3e18 + 5;

int add(int a, int b) { return (a += b) < mod ? a : a - mod; }
int mul(int a, int b) { return 1LL * a * b % mod; }

int r[205][205], n, s, t;
vi g[205], P;

void process(int u, int v, int w){
	g[u].push_back(v), g[v].push_back(u);
	r[u][v] += w;
}

bool AP(){
	queue <int> q;
	q.push(s);
	P.assign(2 * n + 5, -1);
	while(!q.empty()){
		int k = q.front();
		q.pop();
		if(k == t) return true;
		for(int x : g[k]){
			if(P[x] == -1 && r[k][x] > 0){
				P[x] = k;
				q.push(x);
			}
		}
	}
	return false;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;
	ii red[101], blue[101];
	s = 0, t = 2 * n + 1;
	for(int i = 0; i < n; i++){
		cin >> red[i].first >> red[i].second;
	}
	for(int i = 0; i < n; i++){
		cin >> blue[i].first >> blue[i].second;
	}
	for(int i = 0; i < n; i++){
		for(int j = 0; j < n; j++){
			if(red[i].first < blue[j].first && red[i].second < blue[j].second){
				process(i + 1, n + j + 1, mod);
			}
		}
	}
	for(int i = 0; i < n; i++){
		process(s, i + 1, 1);
		process(n + i + 1, t, 1);
	}
	int mf = 0;
	while(AP()){
		int aug = mod;
		for(int x = t; x != s; x = P[x]){
			aug = min(aug, r[P[x]][x]);
		}
		for(int x = t; x != s; x = P[x]){
			r[P[x]][x] -= aug;
			r[x][P[x]] += aug;
		}
		mf += aug;
	}
	cout << mf;
}

