// Nが小さいので、O(N^2)の全探索も可能
// ただ、1つの青点に対して複数の赤点の候補がある場合、どれが最適かはわからない
// a_1,...,a_N,c_1,...c_Nはすべて異なり、b_1,...b_N,d_1,...d_Nはすべて異なるという制約から、
// ペアになることができる赤点が少ない青点からペアを決めていけば最適になりそう(直観)

const int MAX_N = 110;
bool visited[MAX_N];
int a[MAX_N], b[MAX_N], c[MAX_N], d[MAX_N];
int N;
pair<int,int> candidate_num[MAX_N]; // first -- num, second -- index
vector<int> candidate[MAX_N];

int main()
{
    scanf("%d", &N);
    for(int i = 0; i < N; ++i) scanf("%d %d", &a[i], &b[i]);
    for(int i = 0; i < N; ++i) scanf("%d %d", &c[i], &d[i]);

    for(int i = 0; i < N; ++i) {
        candidate_num[i].second = i;
        for(int j = 0; j < N; ++j) {
            if(a[j] < c[i] && b[j] < d[i]) {
                ++candidate_num[i].first;
                candidate[i].push_back(j);
            }
        }
    }
    sort(candidate_num, candidate_num + N);
    int res = 0;
    for(const auto &p : candidate_num) {
        for(const auto &q : candidate[p.second]) {
            if(!visited[q]) {
                visited[q] = true; ++res;
                break;
            }
        }
    }
    printf("%d\n", res);
    return 0;
}

