const int MAX { 110 };

bitset<MAX> found;
vector<int> adj[MAX];

struct Point { int x, y; };

int aug(int u, vector<int>& match)
{
    if (found[u])
        return 0;

    found[u] = true;
#ifdef DEBUG
cout << "   aug(" << u << ")" << endl;
#endif
    for (auto v : adj[u])
    {
#ifdef DEBUG
cout << "   v = " << v << ", match = " << match[v] << endl;
#endif
        if (match[v] == -1 or aug(match[v], match))
        {
            match[v] = u;

#ifdef DEBUG
cout << "   new match: " << v << " -> " << u << endl;
#endif
            return 1;
        }
    }

#ifdef DEBUG
cout << "   nothing for u = " << u << endl;
#endif
    return 0;
}

int solve(int N, const vector<Point>& xs)
{
    for (int u = 0; u < N; ++u)
        for (int v = N; v < 2*N; ++v)
            if (xs[u].x < xs[v].x and xs[u].y < xs[v].y)
                adj[u].push_back(v);

    vector<int> ms(2*N, -1);
    int ans = 0;

    for (int u = 0; u < N; ++u) 
    {
#ifdef DEBUG
cout << "--- Processando u = " << u << endl;
#endif
        found.reset();
        ans += aug(u, ms);
    }

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    vector<Point> xs(2*N);

    for (int i = 0; i < 2*N; ++i)
        cin >> xs[i].x >> xs[i].y;

    auto ans = solve(N, xs);

    cout << ans << '\n';

    return 0;
}

