        blue[i][0] = a;
        blue[i][1] = b;
    }
    for(int i = 0; i < n; i++) {
        add_edge(0, i + 1, 1);
    }
    for(int i = 0; i < n; i++) {
        add_edge(i + n + 1, 2 * n + 1, 1);
    }
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(red[i][0] < blue[j][0] && red[i][1] < blue[j][1]) {
