const int MAX_V=210;

int V;
vector<int> G[MAX_V];
int match[MAX_V]; //マッチングのペア
bool used[MAX_V];

void add_edge(int u, int v){
  G[u].push_back(v);
  G[v].push_back(u);
}

// 増加道を探す
bool dfs(int v){
  used[v]=1;
  for(int i=0;i<G[v].size();i++){
    int u=G[v][i], w=match[u];
    if(w<0 || !used[w] && dfs(w)){
      match[v]=u;
      match[u]=v;
      return 1;
    }
  }
  return 0;
}

// 二部グラフの最大マッチングを求める
int bipartite_matching(){
  int res=0;
  memset(match,-1,sizeof(match));
  for(int v=0;v<V;v++){
    if(match[v]<0){
      memset(used,0,sizeof(used));
      if(dfs(v)){
        res++;
      }
    }
  }
  return res;
}


int main(){
  cin>>V;
  int x[2][V],y[2][V];
  rep(i,2) rep(j,V) cin>>x[i][j]>>y[i][j];
  rep(i,V) rep(j,V){
    if(x[0][i]<x[1][j]&&y[0][i]<y[1][j]){
      add_edge(i,V+j);
    }
  }
  cout<<bipartite_matching()<<endl;
  return 0;
}

