		rep(bl, N) {
			if (a[re] < c[bl] && b[re] < d[bl]) {
				add_arc(G, re, bl + N, 1);
				G[re].back().cap = 1;
			}
		}
	}

	rep(i, N) {
		add_arc(G, 2 * N, i, 1);
		G[2 * N].back().cap = 1;
		add_arc(G, i + N, 2 * N + 1, 1);
		G[i + N].back().cap = 1;
	}

	dinic dn(G);
	cout << dn.solve(2 * N, 2 * N + 1) << "\n";
}

