int ans;

int d[maxn];
inline bool BFS()
{
	bool flag = 0;
	REP(i, 1, n + 2) d[i] = inf;
	d[n + 1] = 0;
	queue <int> q;
	q.push(n + 1);
	while (!q.empty())
	{
		register int x = q.front();
		q.pop();
		for (register int i = bg[x]; i; i = ne[i])
			if (w[i] > 0 && d[to[i]] == inf)
			{
				d[to[i]] = d[x] + 1;
				q.push(to[i]);
				if (to[i] == n + 2) flag = 1;
			}
	}
	return flag;
}
#define dfs DFS
#define bfs BFS
inline int DFS(int now = n + 1, int flow = inf)
{
	if (!flow || now == n + 2) return flow;
	for (register int i = bg[now]; i ; i = ne[i])
		if (d[to[i]] == d[now] + 1 && w[i] > 0)
		{
			register int temp = dfs(to[i], min(flow, w[i]));
			if (temp > 0)
			{
				w[i] -= temp;
				w[i ^ 1] += temp;
				return temp;
			}
		}
	return 0;
}

