template <class cost_t = int, class cap_t = int>
struct Flow {
	struct edge { int to; cost_t cost; cap_t cap; edge *rev; };

	size_t V,E;
	vector<size_t> in_,out_;
	vector<vector<edge>> adj;

	Flow(size_t V_) : V(V_),E() {
		adj.resize(V), in_.resize(V), out_.resize(V);
        for(size_t v = 0; v != V; ++v) adj[v].reserve(V);
	}

	void add_edge(int from, int to, cap_t cap = 1, cost_t cost = 1) {
		adj[from].emplace_back((edge){ to, cost, cap, nullptr });
		adj[to].emplace_back((edge){ from, -cost, 0, nullptr });
        adj[from].back().rev = &(adj[to].back());
        adj[to].back().rev = &(adj[from].back());
		++E, ++out_[from], ++in_[to];
	}

	size_t deg_in(int v) { return in_[v]; }

	size_t deg_out(int v) { return out_[v]; }

	vector<cost_t> Dijkstra(int s) {
		vector<cost_t> dist(V,inf<cost_t>);
		priority_queue<pair<cost_t,int>,vector<pair<cost_t,int>>,greater<pair<cost_t,int>>> que;
		que.emplace(dist[s] = 0, s);
		while(!que.empty()) {
			auto p = que.top(); que.pop();
			int v = p.sec;
			if(dist[v] < p.first) continue;
			for(edge &e : adj[v]) {
				if(e.cap > 0 && dist[v] + e.cost < dist[e.to]) que.emplace(dist[e.to] = dist[v] + e.cost, e.to);
			}
		}
		return dist;
	}

	struct Dinic_impl {
		vector<int> level,itr;
		Flow &F;

		Dinic_impl(Flow &F_) : F(F_) {}

		void bfs(int s) {
			level.assign(F.V, -1);
			queue<int> que;
			level[s] = 0;
			que.emplace(s);
			while(!que.empty()) {
				int v = que.front(); que.pop();
				for(edge &e : F.adj[v]) {
					if(e.cap > 0 && level[e.to] < 0) {
						level[e.to] = level[v] + 1;
						que.emplace(e.to);
					}
				}
			}
		}

		cap_t dfs(int v, int t, cap_t f) {
			if(v == t) return f;
			for(int &i = itr[v]; i != F.adj[v].size(); ++i) {
				edge &e = F.adj[v][i];
				if(e.cap > 0 && level[v] < level[e.to]) {
					cap_t d = dfs(e.to, t, min(f,e.cap));
					if(d > 0) {
						e.cap -= d;
						e.rev->cap += d;
						return d;
					}
				}
			}
			return 0;
		}

		cap_t max_flow(int s, int t) {
			cap_t flow = 0, f;
			while(true) {
				bfs(s);
				if(level[t] < 0) return flow;
				itr.assign(F.V, 0);
				while((f = dfs(s, t, inf<cap_t>)) > 0) flow += f;
			}
		}
 	};

	cap_t Dinic(int s, int t) {
		return Dinic_impl(*this).max_flow(s,t);
	}
};


