		P[i].second = 'B';
	}
}

int solve(void) {
	int cnt = 0;
	for (int i = 0; i < 2 * N; ++i) {
		if (P[i].second == 'R')
			Ry.insert(P[i].first.second);
		else {
			set<int>::reverse_iterator itr;
			for (itr = Ry.rbegin(); itr != Ry.rend(); ++itr) {
				if (*itr < P[i].first.second) {
					Ry.erase(*itr);
					++cnt;
					break;
				}
			}
		}
	}
	return cnt;
}

int main(void) {
	input_data();

	sort(P.begin(), P.end());
	int ans = solve();

	cout << ans << '\n';
	return 0;
}

