struct edgef{
  int to,cap,rev;
  edgef(int to=0,int cap=0,int rev=0):to(to),cap(cap),rev(rev){}
};
struct ford_fulkerson{
  static constexpr int INF = INT_MAX/2;
  static vector<bool> used;
  static void add_edge(vector<vector<edgef>> &g, int src, int dst, int cap)noexcept{
    g[src].emplace_back(dst,cap,g[dst].size());
    g[dst].emplace_back(src,0,g[src].size()-1);
  }
  static int dfs(int now, int t, int f, vector<vector<edgef>> &g)noexcept{
    if(now == t) return f;
    used[now] = true;
    for(auto &e:g[now]){
      if(used[e.to] || e.cap<1) continue;
      int d = dfs(e.to,t,min(f,e.cap),g);
      if(d>0){
        e.cap -= d;
        g[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }
  static int solve(int s, int t, vector<vector<edgef>> &g)noexcept{
    int res = 0, flow=-1;
    used.assign(g.size(),false);
    while(flow){
      fill(used.begin(),used.end(),false);
      flow = dfs(s,t,INF,g);
      res += flow;
    }
    return res;
  }
};
vector<bool> ford_fulkerson::used;
using fk = ford_fulkerson;
