int partial_count(int a, int b, int count) {
  //cout << a << "," << b << "," << count << endl;
  int i = a;
  int j = b;

  int max_count = count;
  int tmp_count;

  for (j = b; j < n; j++) {
    if (rx[i] < bx[j] && ry[i] < by[j]) {
      if (used_r[i] == NOTUSED && used_b[j] == NOTUSED) {
        used_r[i] = USED;
        used_b[j] = USED;
        tmp_count = partial_count(i, j, count + 1);
        if (max_count < tmp_count) {
          max_count = tmp_count;
        }
        used_r[i] = NOTUSED;
        used_b[j] = NOTUSED;

      }
    }
  }

  for (i = a + 1; i < n; i++) {
    for (j = 0; j < n; j++) {
      if (rx[i] < bx[j] && ry[i] < by[j]) {
        if (used_r[i] == NOTUSED && used_b[j] == NOTUSED) {
          used_r[i] = USED;
          used_b[j] = USED;
          tmp_count = partial_count(i, j, count + 1);
          if (max_count < tmp_count) {
            max_count = tmp_count;
          }
          used_r[i] = NOTUSED;
          used_b[j] = NOTUSED;

        }
      }
    }
  }

  return max_count;
}

