    vi parent(n);
    ll new_flow;

    while (new_flow = bfs(s, t, parent,capacity,adj)) 
    {
        flow += new_flow;
        ll cur = t;
        while (cur != s) 
		{
            ll prev = parent[cur];
            capacity[prev][cur] -= new_flow;
            capacity[cur][prev] += new_flow;
            cur = prev;
        }
    }

    return flow;
}

