vector<pair<int, int>> bv;
int ans;

void solve() {
  for (int i = 0; i < rv.size(); ++i) {
    pair<int, int> r = rv[i];
    int min_d = 1000000000;
    int min_d_j = -1;
    for (int j = 0; j < bv.size(); ++j) {
      pair<int, int> b = bv[j];
      if (r.first < b.first && r.second < b.second) {
        int d = pow(b.first - r.first, 2) + pow(b.second - r.first, 2);
        if (d < min_d) {
          min_d = d;
          min_d_j = j;
        }
      }
    }
    if (min_d_j != -1) {
      bv.erase(bv.begin() + min_d_j);
      ++ans;
    }
  }
  cout << ans << endl;
}

