  forn(i, n) {
    forn(j, n) {
      if (a[i][0] < b[j][0] && a[i][1] < b[j][1]) {
        g[i][j] = 1;
      } else {
        g[i][j] = 0;
      }
    }
  }
  _(mt, -1);
  int ans = 0;
  forn(i, n) {
    _(used, 0);	  
    if (dfs(i)) {
	ans++;
    }
  }
  printf("%d\n", ans);
}

