#include <bits/stdc++.h>
#define ll long long
#define rep(i,n) for(ll (i)=0;(i)<(n);++(i))
using namespace std;

template<typename T>
struct Dinic{
    //辺
    struct edge
    {
        //行先と逆辺、revはid参照されているので、
        //追加された順に1,2,3,...となっている
        int to,rev;
        //cap は capacityの略
        T cap;
        edge(int to,T cap,int rev):to(to),cap(cap),rev(rev){};
    };

    const T INF;

    //グラフと探索済みかの配列
    vector<vector<edge>> graph;
    vector<int> iter,level;

    Dinic(int n):INF(numeric_limits<T>::max()){
        graph.resize(n);
    }

    void add_edge(int from, int to, T cap){
        //from ~ toにcapの辺を通す
        graph[from].emplace_back(to,cap,int(graph[to].size()));
        //to~from　に0容量の辺を通す
        graph[to].emplace_back(from,0,int(graph[from].size())-1);
    }

    //容量がある条件で最短距離の検索
    bool bfs(int s, int t){
        level.assign(graph.size(),-1);
        queue<int> que;
        level[s] = 0;
        que.push(s);

        while(!que.empty() and level[t] == -1){
            int p = que.front();
            que.pop();

            for(auto &e : graph[p]){
                if(e.cap > 0 and level[e.to] == -1){
                    que.push(e.to);
                    level[e.to] = level[p] + 1;
                }
            }
        }

        return level[t] != -1;

    }

    //ただのdfs探索
    //これは一本のパスについてflowを返していく
    T dfs(int v, const int t, T flow){
        //終了地点にきたらflowを返す
        if(v == t) return flow;
        for(int &i = iter[v]; i < graph[v].size(); i++){
            //流す余地があって未探索
            auto &e = graph[v][i];
            if(e.cap > 0 and (level[v] < level[e.to])){
                //このノード以降のフローを求める
                T d = dfs(e.to,t,min(flow,e.cap));
                if(d > 0){
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        //ここにたどり着くのは増加パスがない時
        return 0;
    }

    T max_flow(int s,int t){
        T flow = 0;
        //
        //cout << " bfs?" << " " << bfs(s,t) << endl;
        while(bfs(s,t)){
            //探索回数のリセット
            iter.assign(graph.size(),0);

            T f = 0;
            //dfsで見つかる限りflowを追加

            while((f = dfs(s,t,INF)) > 0){

                flow += f;
            }

        }
        return flow;
    }
};
int main(){
    ll n;
    cin>>n;
    Dinic<ll> din(2*n+2);
    vector<pair<ll,ll>> red(n),blue(n);
    rep(i,n){
        ll a,b;
        cin>>a>>b;
        red[i]=make_pair(a, b);
    }
    rep(i,n){
        ll c,d;
        cin>>c>>d;
        blue[i]=make_pair(c, d);
    }
    rep(i,n){
        rep(j,n){
            if(red[i].first<blue[j].first && red[i].second<blue[j].second){
                din.add_edge(i, n+j, 1);
            }
        }
    }
