}a[AX],b[AX];
bool cmp( const Node &a , const Node &b ){
	if( a.y == b.y ){
		return a.x < b.x;
	}else{
		return a.y < b.y;
	}
}
bool cmp2( const Node &a , const Node &b ){
	if( a.x == b.x ){
		return a.y < b.y;
	}else{
		return a.x < b.x;
	}
}
int main(){
