			if( mpb[j] ) continue;
			if( mpa[i] ) continue;
			if( a[i].x < b[j].x && a[i].y < b[j].y ){
				res ++ ;
				mpa[i] = 1;
				mpb[j] = 1;
			}
		}
	}
	int ibest = res ;
	res = 0;
	sort( a , a + n , cmp2 );
	sort( b , b + n , cmp2 );
