#define MAX 300

struct point {
  int X;
  int Y;
};

void Sort(point A[], int n){
  int m = 300;
  for (int j=1; j<n; j++){
    for (int i=j; i<n; i++){
    m = min(m, A[i].X);
    }
    for (int i=j; i<n; i++){
      if (A[i].X==m) {
        swap(A[j-1], A[i]);
      }
    }
  }
}

