  for (int i = 0; i < n; i++) {
    int first, second; cin >> first >> second;
    red.at(i) = make_pair(first, second);
  }
  vector<pair<int, int>> blue(n);
  for (int i = 0; i < n; i++) {
    int first, second; cin >> first >> second;
    blue.at(i) = make_pair(first, second);
  }

  vector<bool> paired(n, false);
  int answer = 0;

  sort(red.begin(), red.end());
  sort(blue.begin(), blue.end());

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (paired.at(j)) continue;
      if (red.at(i).first > blue.at(j).first) {
        paired.at(j) = true;
      } else {
        int minimum = 2 * n;
        int index;
        for (int k = j; k < n; k++) {
          if (paired.at(k)) continue;
          if(blue.at(k).second < minimum) {
            minimum = blue.at(k).second;
            index = k;
          }
        }
        paired.at(index) = true;
        answer++;
        break;
      }
    }
  }     

  cout << answer << endl;
