using namespace std;

class Point{
  public:
    int x;
    int y;

    Point(int x0=0, int y0=0) {
      x = x0;
      y = y0;
    }

    bool is_inner(Point& p) {
      return x < p.x && y < p.y;
    }

    int dist() const {
      return x*x + y*y;
    }
};

bool dist(const Point &left, const Point &right) {
  return left.dist() > right.dist();
}

bool inners_asc(const vector<int> left, const vector<int> right) {
  return left.size() < right.size();
}

std::ostream &operator<<(std::ostream &os, Point const &p) { 
    return os << "(" << p.x << ", " << p.y << ")";
}

