    cin >> x >> y;
    bps.push_back(Point(x, y));
  }

  vector< vector<int> > inners;

  vector<int> tmp;
  REP(i, n) {
    tmp.clear();
    REP(j, n) {
      if (rps[j].is_inner(bps[i])){
        tmp.push_back(j);
      }
    }
