using namespace std;

typedef struct star {
  int x;
  int y;
} star;

map<int, star> red;
map<int, star> blue;
int N;

int ok(int b, int r){
  if((red[r].x < blue[b].x) && (red[r].y < blue[b].y)) return 1;
  return 0;
}

int ans = 0;
void solve(int count){
  int i, j;
  star pr, pb;
  for(i=0;i<N;i++){
    for(j=0;j<N;j++){
      if(ok(i, j)){
        if(count > ans) ans = count;
        pb = blue[i]; pr = red[j];
        blue.erase(i);
        red.erase(j);
        solve(count+1);
        blue[i] = pb; red[j] = pr;
      }
    }
  }
}

