void add_edge(int from,int to,ll cost){
  v[from].push_back({to,cost,(int)v[to].size()});
  v[to].push_back({from,0,(int)v[from].size()-1});
}

void bfs(int s){
  memset(level,-1,sizeof(level));
  queue<int> q;
  q.push(s);
  level[s]=0;
  while(!q.empty()){
    int now=q.front();
    q.pop();
    for(int i=0;i<(int)v[now].size();i++){
      if(v[now][i].cap>0 && level[v[now][i].to]<0){
        level[v[now][i].to]=level[now]+1;
        q.push(v[now][i].to);
      }
    }
  }
}

int dfs(int now,int t,ll f){
  if(now==t)return f;
  for(int &i=iter[now];i<(int)v[now].size();i++){
    if(v[now][i].cap>0 && level[now]<level[v[now][i].to]){
      int d=dfs(v[now][i].to,t,min(f,v[now][i].cap));
      if(d>0){
        v[now][i].cap-=d;
        v[v[now][i].to][v[now][i].rev].cap+=d;
        return d;
      }
    }
  }
  return 0;
}

int max_flow(int s,int t){
  int flow=0;
  for(;;){
    bfs(s);
    if(level[t]<0)return flow;
    memset(iter,0,sizeof(iter));
    int f;
    while((f=dfs(s,t,inf))>0){
      flow+=f;
    }
  }
}

