  int N; cin >> N;
  vector<int> a(N), b(N), c(N), d(N);
  rep(i, N) cin >> a[i] >> b[i];
  rep(i, N) cin >> c[i] >> d[i];

  Dinic<int> dinic(2 * N + 2);
  rep(i, N){
    dinic.add_edge(2 * N, i, 1);
    dinic.add_edge(i + N, 2 * N + 1, 1);
  }
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j){
      if (a[i] < c[j] && b[i] < d[j]) {
        dinic.add_edge(i, j + N, 1);
      }
    }
  }
  cout << dinic.max_flow(2 * N, 2 * N + 1) << endl;
}

