int N;
typedef pair<int, int> point;
typedef tuple<int, point, vector<point>> redp;
vector<redp> redv;
vector<point> bluev;
map<point, int> bmap; //各青点が何個の赤点とペアになりうるかの個数

void delCandidate(point bp, vector<redp> &rpv){
	for(int i = 0; i < rpv.size(); i++){
		vector<point> &v = get<2>(rpv[i]);
		for(int j = 0; j < v.size(); j++){
			if(v[j] == bp){
				v.erase(v.begin() + j);
				get<0>(rpv[i]) -= 1;
				break;
			}
		}
		get<0>(rpv[i]) = v.size();
	}
	bmap[bp] = 0;
	for(int i=0; i<bluev.size(); i++){
		if(bluev[i] == bp){
			bluev.erase(bluev.begin() + i);
			break;
		}
	}
}

void calcbmap(){
	for(auto itr = bmap.begin(); itr != bmap.end(); itr++){
		point bp = itr->first;
		itr->second = 0;
		for(int i=0; i<redv.size(); i++){
			if(get<0>(redv[i]) == 0) continue;
			point rp = get<1>(redv[i]);
			vector<point> &v = get<2>(redv[i]);
			for(int j=0; j<v.size(); j++){
				if(bp == v[j]){
					bmap[bp]++;
				}
			}
		}
	}
}

void initRedPoints(){
	for(int i=0; i<redv.size(); i++){
		point rp = get<1>(redv[i]);
		vector<point> &v = get<2>(redv[i]);
		for(int j=0; j<bluev.size(); j++){
			point bp = bluev[j];
			if(bp.first > rp.first && bp.second > rp.second){
				v.push_back(bp);
			}
		}
		get<0>(redv[i]) = v.size(); 
	}
	calcbmap();
	int ezero = 1;
	while(ezero == 1){
		for(int i=0; i<redv.size(); i++){
			int cand = get<0>(redv[i]);
			if(cand == 0){
				redv.erase(redv.begin() + i);
				break;
			}
		}
		ezero = 0;
		for(int i=0; i<redv.size(); i++){
			int cand = get<0>(redv[i]);
			if(cand == 0){
				ezero = 1;
				break;
			}
		}
	}
}

// 候補の中の重複度が最小の青点候補を探す。
void searchBestBluePoint(vector<redp> &v, int cand, int &min_r, int &min_b, int &bx, int &by){
	int min_cand = 100;
	for(int i=0; i<v.size(); i++){
		if(get<0>(v[i]) != cand) continue;
		vector<point> w = get<2>(v[i]);
		for(int j=0; j<w.size(); j++){
			if( min_cand > bmap[w[j]] ){
				min_cand = bmap[w[j]];
				bx = w[j].first;
				by = w[j].second;
				min_r = i;
				min_b = j;
			}
		}
	}
}

