                    break;
                }

                q.push(t);
            }

            while(!q.empty()){
                int t = q.front();
                pq.push(t);
                q.pop();
            }
        }
        else
            pq.push(P[i].y);
    }

    cout << ans << '\n';
    return 0;
}

