bool dfs(int v){
  used[v] = true;
  for(int i=0; i<graph[v].size(); i++){
    int u=graph[v][i], w = match[u];
    if(w < 0 || !used[w] && dfs(w)){
      match[v] = u;
      match[u] = v;
      return true;
    }
  }
  return false;
}

int mathcing(){
  int res=0;
  memset(match, -1, sizeof(match));
  for(int v=1; v<=n; v++){
    if(match[v]<0){
      memset(used, 0, sizeof(used));
      if(dfs(v)) res++;
    }
  }
  return res;
}

