        return a.second < b.second;
    } else {
        return a.first < b.first;
    }
}

int main() {
    int N;
    cin >> N;
    int x, y;
    vector<pair<int, int> > red, blue;
    for (int i = 0; i < N; ++i) {
        cin >> x >> y;
        red.push_back(make_pair(x, y));
    }
    for (int i = 0; i < N; ++i) {
        cin >> x >> y;
        blue.push_back(make_pair(x, y));
    }
    sort(blue.begin(), blue.end(), compare_by_y);
    int ans = 0;
    for (int i = 0; i < N; ++i) {
        int res = -1;
        for (int j = 0; j < red.size(); ++j) {
            if (red[j].second < blue[i].second && red[j].first < blue[i].first) {
                if (res == -1) {
                    res = j;
                } else {
                    if (red[res].first < red[i].first) { res = j; }
                }
            }
        }
        if (res != -1) {
            red[res] = red.back();
            red.erase(red.end());
            ++ans;
        }
    }
    cout << ans << endl;

