    fill(matched,matched+n,false);

    for (ll i=0;i<n;i++){
        for (ll j=0;j<n;j++){
            if (matched[j]){
                continue;
            }
            if (r[j].second<b[i].second and r[j].first<b[i].first){
                matched[j]=true;
                count++;
                break;
            }
        }
    }
    cout << count << endl;
    return 0;
}

