        for (int i = 0; i < red.size(); ++i) { // red
            if (blue[j].first > red[i].first && blue[j].second > red[i].second) {
                add_edge(i, j);
                add_edge(j, i);
            }
        }
    }

    cout << bipartite_matching() << endl;
}

