        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            // d==0ならtにたどり着かない
            if(d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
int max_flow(int s, int t) {
    int flow = 0;
    for(;;) {
        used.resize(MAX_V, false);
        int f = dfs(s, t, INT_MAX / 100);
        if(f == 0) {
            return flow;
        }
        flow += f;
    }
}
