double dist(PII &a, PII &b) {
  return sqrt((a.first - b.first) * (a.first - b.first) +
              (a.second - b.second) * (a.second - b.second));
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int N; cin >> N;
  vector<PII> R(N), B(N);
  bool used[2*N+1][2*N+1];
  memset(used, 0, sizeof(used));

  rep(i, N) cin >> R[i].first >> R[i].second;
  rep(i, N) cin >> B[i].first >> B[i].second;

  sort(R.begin(), R.end(), [](const PII& a, const PII &b) -> bool {
    double da = sqrt(a.first * a.first + a.second * a.second);
    double db = sqrt(b.first * b.first + b.second * b.second);
    return da > db;
  });

  int cnt = 0;
  for (auto &r: R) {
    double mini = 1e10;
    PII p(-1, -1);
    for (auto &b: B) {
      if (used[b.first][b.second]) continue;
      if (b.first <= r.first || b.second <= r.second) continue;
      double d = dist(r, b);
      if (d >= mini) continue;
      p = b;
      mini = dist(r, b);
    }
    if (p.first != -1 && p.second != -1) {
      cnt++;
      used[r.first][r.second] = true;
      used[p.first][p.second] = true;
    }
  }

  cout << cnt << endl;

  return 0;
}

