class BipGraph{
    int m,n;
    vi *adj;
    int *pairU, *pairV, *dist;

public:
    BipGraph(int m, int n);
    void addEdge(int u, int v);
    bool bfs();
    bool dfs(int u);
    int hopcroftKarp();
};

int BipGraph::hopcroftKarp(){
    pairU = new int[m+1];
    pairV = new int[n+1];
    dist = new int[m+1];

    for(int u = 0; u <= m; ++u)
        pairU[u] = 0;
    for(int v = 0; v <= n; ++v)
        pairV[v] = 0;

    int result = 0;
    while(bfs()){
        for(int u = 1; u <= m; ++u)
            if(pairU[u] == 0 and dfs(u))
                ++result;
    }
    return result;
}

bool BipGraph::bfs(){
    queue<int> Q;

    for(int u = 1; u <= m; ++u){
        if(pairU[u] == 0){
            dist[u] = 0;
            Q.push(u);
        }
        else dist[u] = infi;
    }

    dist[0] = infi;

    while(sz(Q)){
        int u = Q.front(); Q.pop();

        if(dist[u] < dist[0]){
            vi::iterator i;
            for(i = adj[u].begin(); i != adj[u].end(); ++i){
                int v = *i;
                if(dist[pairV[v]] == infi){
                    dist[pairV[v]] = dist[u] + 1;
                    Q.push(pairV[v]);
                }
            }
        }
    }

    return dist[0] != infi;
}

bool BipGraph::dfs(int u){
    if(u){
        for(int v:adj[u]){
            if(dist[pairV[v]] == dist[u]+1){
                if(dfs(pairV[v])){
                    pairV[v] = u;
                    pairU[u] = v;
                    return true;
                }
            }
        }
        dist[u] = infi;
        return false;
    }
    return true;
}

BipGraph::BipGraph(int m, int n){
    this->m = m;
    this->n = n;
    adj = new vi[m+1];
}

void BipGraph::addEdge(int u, int v){
    adj[u].pb(v);
}
