class Edge {
public:
    ll t, cap, rev;
    Edge(ll t, ll cap, ll rev): t(t), cap(cap), rev(rev) {}
};

ll N;
vector<Edge> g[222];
ll used[222];

ll dfs(ll v, ll goal, ll f) {
    if(v==goal) return f;
    used[v]=1;
    ll i;
    for(i=0; i<g[v].size(); i++) {
        Edge &e=g[v][i];

        if(!used[e.t] && e.cap>0) {
            ll d=dfs(e.t, goal, min(f, e.cap));
            if(d>0) {
                e.cap-=d;
                g[e.t][e.rev].cap+=d;
                return d;
            }
        }
    }

    return 0;   //goalまでのパスが見つからなかったとき
}

void addEdge(ll from, ll to, ll cap) {
    g[from].pb(Edge(to, cap, g[to].size()));
    g[to].pb(Edge(from, 0, g[from].size()-1));
}

