        for(j=N; j<N*2; j++) {
            if(a[i]<a[j] && b[i]<b[j]) {
                g[i].pb(Edge(j, 1, g[i].size()));
                g[i].pb(Edge(j, 0, g[i].size()-1));
            }
        }
    }


    ll flow=0;
    while(1) {
        memset(used, 0, sizeof(used));

