using namespace std;

const int SZ = 300;

struct Graph {
    int n, m;
    vector<int> g[SZ];
    bool px[SZ];
    int py[SZ];
    int used[SZ];
    int cc;
    int mSize;

    bool dfs(int v) {
        used[v] = cc;
        for (auto to : g[v]) {
            if (py[to] == -1) {
                py[to] = v;
                px[v] = true;
                return true;
            }
        }
        for (auto to : g[v]) {
            if (used[py[to]] != cc && dfs(py[to])) {
                py[to] = v;
                px[v] = true;
                return true;
            }
        }
        return false;
    }

    inline void khun() {
        cc = 1;
        for (int run = 1; run;) {
            run = 0;
            cc++;
            for (int i = 0; i < n; ++i) {
                if (!px[i] && dfs(i)) {
                    run = 1;
                }
            }
        }
    }

    inline int pars() {
        khun();
        mSize = 0;
        for (int i = 0; i < n; ++i) {
            mSize += px[i];
        }
        return mSize;
    }

    inline void add(int v, int u) {
        g[v].push_back(u);
    }

    Graph(int n) : n(n), m(n) {
        fill_n(px, n, false);
        fill_n(py, m, -1);
        fill_n(used, n, 0);
    }
};

int main() {
    int n;
    cin >> n;
    Graph g(n);
    vector<pair<int, int>> pts(n);
