using namespace std;

template<int SZ> struct MaxMatch {
  int N, flow = 0, match[SZ], rmatch[SZ];
  bitset<SZ> vis; vector<int> adj[SZ];
  MaxMatch() {
    memset(match,0,sizeof match);
    memset(rmatch,0,sizeof rmatch);
  }
  void connect(int a, int b, bool c = 1) {
    if (c) match[a] = b, rmatch[b] = a;
    else match[a] = rmatch[b] = 0;
  }
  void add(int a, int b) {adj[a].push_back(b);}

  bool dfs(int x) {
    if (!x) return 1;
    if (vis[x]) return 0;
    vis[x] = 1;
    for (auto &t : adj[x]) 
      if (t != match[x] && dfs(rmatch[t])) {
        connect(x,t);
        return 1;
      }
    return 0;
  }
  void init(int _N) { 
    N = _N;
    for (int i = 1; i < N+1; ++i) 
      if (!match[i]) {
        vis.reset(); 
