  flow.init(V+V+2);
  vector<int> a(V),b(V);
  for(int i = 0; i < V; i++){
    cin >> a[i] >> b[i];
    flow.add_edge(V+V+1,i,1);
  }
  for(int i = 0; i < V; i++){
    int c,d; cin >> c >> d;
    flow.add_edge(V+i,V+V,1);
    for(int j = 0; j < V; j++){
      if(c > a[j] && d > b[j]){
        flow.add_edge(j,V+i,1);
      }
    }
  }
  cout << flow.maxflow(V+V+1,V+V) << endl;

  return 0;
}

