int main() {
  int N,i,j,x,y,p=0;
  cin >> N;
  vector<pair<int,int>> R(N), B(N);
  set<pair<int,int>> RR;

  for(i=0; i<N; i++) {
    cin >> x >> y;
    R.at(i) = make_pair(x,y);
    RR.insert(R.at(i));
  }
  sort(R.begin(), R.end());

  for(i=0; i<N; i++) {
    cin >> x >> y;
    B.at(i) = make_pair(x,y);
  }
  sort(B.begin(), B.end());

  for(i=0; i<N; i++) {
    priority_queue<pair<int,int>> pq;
    for(j=0; j<N; j++) {
      if(RR.count(R.at(j)) && B.at(i).first>R.at(j).first && B.at(i).second>R.at(j).second)
        pq.push(make_pair(R.at(j).second, R.at(j).first));
      if(B.at(i).first<=R.at(j).first && B.at(i).second<=R.at(j).second)
        break;
    }
    if(!pq.empty()) {
      pair<int,int> m = pq.top();
      int pqx = m.second, pqy = m.first;
      RR.erase(make_pair(pqx, pqy));
      p++;
    }
  }

  cout << p << endl;
}

