struct max_flow {
    struct edge {
        int to;
        i64 cap, rev;
    };
    vector<vector<edge>> graph;
    vector<bool> done;
    max_flow(int size) : graph(size), done(size) {}
    void add_edge(int from, int to, i64 cap) {
        graph[from].push_back(edge{to, cap, (int)graph[to].size()});
        graph[to].push_back(edge{from, 0, (int)graph[from].size() - 1});
    }
    i64 dfs(int v, int t, i64 f) {
        if (v == t) return f;
        done[v] = true;
        for (auto &e : graph[v]) {
            if (done[e.to] or e.cap <= 0) continue;
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }
    i64 calc_max_flow(int s, int t) {
        i64 flow = 0;
        while (true) {
            fill(done.begin(), done.end(), false);
            i64 f = dfs(s, t, inf);
            if (f == 0) return flow;
            flow += f;
        }
    }
};

struct bipartite_matching {
    i64 l, r;
    i64 s, t;
    max_flow mf;
    bipartite_matching(i64 l /* 左側の頂点数 */, i64 r /* 右側の頂点数 */) : l(l), r(r), mf(l + r + 2), s(l + r), t(l + r + 1) {
        rep(i, 0, l) mf.add_edge(s, i, 1);
        rep(i, 0, r) mf.add_edge(i + l, t, 1);
    }

    void add_edge(i64 u, i64 v) {
        mf.add_edge(u, v + l, 1);
    }

    i64 max_matching() {
        return mf.calc_max_flow(s, t);
    }
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;

    i64 N;
    cin >> N;

    vector<i64> a(N),b(N);
    rep(i,0,N) cin >> a[i] >> b[i];

