		{
			if (r.x_ < b_grid_collection_[i].x_ && r.y_ < b_grid_collection_[i].y_)
			{
				b_grid_collection_.erase(b_grid_collection_.begin() + i);
				count_pair_++;
				break;
			}
		}
	}
	void Region(Grid g)
	{
		g.region_ = min(g.x_, g.y_);
	}
};


