struct  Pos{
    int x;
    int y;
};

struct State{
    int pair_cnt;
    int last_red;
    array<int, 100> red;
    array<int, 100> blue;
};

/* Inputs */
int N;
vector<Pos> R, B;


int main() {
    cin >> N;

	for(int i=0; i<N; i++) {
		int x, y;
		cin >> x >> y;
		R.push_back(Pos{x,y});
	}


	for(int i=0; i<N; i++) {
		int x, y;
		cin >> x >> y;
        B.push_back(Pos{x,y});
	}

    queue<State> q;
    State s;
    s.red.fill(-1);
    s.blue.fill(-1);
    s.pair_cnt = 0;
    s.last_red = 0;
    q.push(s);

    int ans = 0;

    while(!q.empty()) {
        s = q.front();
        q.pop();
        for(int ri=s.last_red; ri<N; ri++) {
            if(s.red[ri] >= 0) continue;
            for(int bi=0; bi<N; bi++) {
                if(s.blue[bi] >= 0) continue;
                if(R[ri].x < B[bi].x && R[ri].y < B[bi].y) {
                    q.push(s);
                    q.back().red[ri] = bi;
                    q.back().blue[bi] = ri;
                    q.back().pair_cnt++;
                    q.back().last_red = ri+1;
                }
            }
        }
        ans = max(s.pair_cnt, ans);
    }
    cout << ans << endl;
}

