struct Dinic {
#define Vmax 202
    int s,t,level[Vmax],cup[Vmax][Vmax];
    bool keep_out[Vmax];
    vector<int> v[Vmax];
    stack<int> st;
    int max_flow() {
        int flow = 0,tmp;
        while(bfs()) do {
            int now = s;
            tmp = dfs(s);
            flow += tmp;
            while(!st.empty()) {
                cup[now][st.top()] -= tmp;
                cup[st.top()][now] += tmp;
                now = st.top();
                st.pop();
            }
        } while(tmp);
        return flow;
    }
    bool bfs() {
        queue<pair<int,int>> que;
        rep(i,Vmax) keep_out[i] = false;
        rep(i,Vmax) if (i^t) level[i] = INF;
        rep(i,v[t].size()) if (cup[v[t][i]][t] > 0) que.push(mp(v[t][i], 1));
        while(!que.empty()) {
            int a = que.front().fi, c = que.front().se;que.pop();
            if (level[a] <= c || level[s] < c) continue;
            level[a] = c;
            rep(i,v[a].size()) if (cup[v[a][i]][a] > 0) que.push(mp(v[a][i], c+1));
        }
        if (level[s] == INF) return false;
        else return true;
    }
    int dfs(int a) {
        rep(i,v[a].size()) {
            if (level[a] > level[v[a][i]] && cup[a][v[a][i]] > 0 && !keep_out[v[a][i]]) {
                if (v[a][i] == t) {st.push(t);return cup[a][t];}
                int tmp = dfs(v[a][i]);
                if (tmp) {st.push(v[a][i]);return min(tmp, cup[a][v[a][i]]);}
            }
        }
        keep_out[a] = true;
        return 0;
    }
    //array[Vmax][Vmax] exists!
    //　　-> int cup[Vmax][Vmax] -> map<int,int> cup[Vmax]
};

