const int MAXN = 105;

pair<int, int> A[MAXN], B[MAXN];

int adj[MAXN][MAXN], N;

bool bm(int u, int del[], int match[]){
	for(int i=1; i<=N; ++i){
		if(adj[u][i] && !del[i]){
			del[i] = true;
			if(match[i] < 0 || bm(match[i], del, match)){
				match[i] = u;
				return true;
			}
		}
	}
	return false;
}

int solve(){
	int res = 0;
	int match[MAXN], del[MAXN];
	memset(match, -1, sizeof(match));
	for(int i=1; i<=N; ++i){
		memset(del, 0, sizeof(del));
		if(bm(i, del, match)) res++;
	}
	return res;
}

