  }
  for (int i = 0; i < N; i++) {
    cin >> c[i] >> d[i];
  }

  // 隣接リストの作成
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (a[i] < c[j] && b[i] < d[j]) add_edge(i, j + N);
    }
  }
  int ans = biparticle_matching();
  cout << ans << "\n";
  return 0;
}

