    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
}

void solve() {
    sort(red.begin(), red.begin() + n);
    sort(blue.begin(), blue.begin() + n);
    int pos = 0;
    int ans = 0;
    multiset<int> st;
    for (int i = 0; i < n; ++i) {
        //青よりx座標の小さい赤をピックアップ
        while(red[pos].first < blue[i].first) st.insert(red[pos++].second);
        //青のy座標より大きい赤を選ぶ
        auto itr = st.lower_bound(blue[i].second);
        if (itr != st.begin()) {
            //青のy座標より大きい赤の次にはペアとなれる赤の中で最もy座標が大きい赤が存在するので
            //ペアとしてカウント
            st.erase(--itr);
            ans++;
        }
    }
    cout << ans << endl;
    return;
}

