const ll INF=1e18;
const int mx=200005;

//ford-fulkerson

//辺を表す構造体(行先,容量,逆辺(の番号))
struct edge{ll to,cap,rev;};

class FordFulkerson{
public:
    V<V<edge>> G;//グラフの隣接リスト
    V<bool> used;//DFSですでに調べたかのフラグ

    explicit FordFulkerson(ll max_V){
        G.resize(max_V);
        used.resize(max_V);
    }

    //fromからtoへ容量capの辺をグラフに追加
    void add_edge(ll from,ll to,ll cap){
        G[from].push_back((edge){to,cap,(ll)G[to].size()});
        G[to].push_back((edge){from,0LL,(ll)G[from].size()-1});
    }

    //増加パスをDFSで探す
    ll dfs(ll v,ll t,ll f){
        if(v==t) return f;
        used[v]=1;
        for(int i=0;i<(int)G[v].size();i++){
            edge &e=G[v][i];
            if(!used[e.to]&&e.cap>0){
                ll d=dfs(e.to,t,min(f,e.cap));
                if(d>0){
                    e.cap-=d;
                    G[e.to][e.rev].cap+=d;
                    return d;
                }
            }
        }
        return 0;
    }

    //sからtへの最大流を求める
    ll max_flow(ll s,ll t){
        ll flow=0;
        while(true){
            rep(i,(ll)used.size()) used[i]=0;
            ll f=dfs(s,t,INF);
            if(f==0) return flow;
            flow+=f;
        }
    }
};

int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    ll n;
    cin>>n;
    V<ll> a(n),b(n),c(n),d(n);
    rep(i,n) cin>>a[i]>>b[i];
    rep(i,n) cin>>c[i]>>d[i];
    FordFulkerson ff(2*n+2);
    for(int i=1;i<=n;i++){
        ff.add_edge(0,i,1);
        ff.add_edge(i+n,2*n+1,1);
    }
    rep(i,n){
        rep(j,n){
            if(a[i]<c[j]&&b[i]<d[j]){
                ff.add_edge(i+1,j+n+1,1);
            }
        }
    }
    out(ff.max_flow(0,2*n+1));
}

