#include <iostream>

using namespace std;

int N;

int a[105], b[105], c[105], d[105];

int C[220][220], F[220][220];

int p[220];  //parent
int check[220];

void FIND_PATH(int n) {
	check[n] = 1;
	if (p[2 * N + 1] != -1) { return; }
	//cout << "n= " << n << endl;
	for (int i = 0; i <= 2 * N + 1; i++) {
		if (i == n) { continue; }
		if (C[n][i] - F[n][i] > 0 && check[i] < 0) { p[i] = n; FIND_PATH(i); }
	}
};

void FLOW(int m) {

		F[p[m]][m] += 1;
		F[m][p[m]] -= 1;

	//cout << "m= " << m << endl;

	if (p[p[m]] >= 0) { FLOW(p[m]); }
}

int main(void) {
	// input
	cin >> N;

	for (int i = 1; i <= N; i++) {
		cin >> a[i]; cin >> b[i];
	}

	for (int i = 1; i <= N; i++) {
		cin >> c[i]; cin >> d[i];
	}

	//=====================================
	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			if (a[i] < c[j] && b[i] < d[j]) { C[i][j + N] = 1; }
		}
	}

	for (int i = 1; i <= N; i++) { C[0][i] = 1; }

	for (int i = 1; i <= N; i++) { C[i + N][2 * N + 1] = 1; }
     //=======================

	while (1) {
		//cout << "ret" << endl;
		for (int i = 0; i <= 2 * N + 1; i++) { p[i] = -1; check[i] = -1; }
		FIND_PATH(0);
			int J = 2 * N + 1;
		//while (p[J] >= 0) { cout << " " << J; J = p[J]; }cout << endl;
		if (p[2 * N + 1] >= 0) { FLOW(2 * N + 1); }
		else { break; }
	}

	int ans = 0;
	for (int i = 1; i <= N; i++) {
		ans += F[0][i];
	}

	cout << ans << endl;

	//system("pause");
	return 0;
}

