int main()
{
    cin >> n;
    rep(i, n){ int a, b; cin >> a >> b; reds.pb(mp(a, b)); }
    rep(i, n){ int a, b; cin >> a >> b; blues.pb(mp(a, b)); }
    rep(i, n){
        vi cand; P blue = blues[i];
        rep(j, n){
            P red = reds[j];
