            int val = (int)cands[i].size();
            if(val < mn && val != 0){ mn = val; mnp = i; }
        }
        if(mnp == -1) break;

        // 一番候補の少ない青の相手を見つける
        int tar = cands[mnp][0];
        unmatched.erase(find(all(unmatched), mnp));

        for(int i: unmatched){
