int V;
vector<int> G[201];
int match[201];
bool used[201];

void add_edge(int u, int v) {
  G[u].push_back(v);
  G[v].push_back(u);
}

bool dfs(int v){
  used[v] = true;
  for (int i=0;i<G[v].size();i++) {
    int u = G[v][i];
    int w = match[u];
    if (w < 0 || (!used[w] && dfs(w))) {
      match[v] = u;
      match[u] = v;
      return true;
    }
  }
  return false;
}

int main(){
  int rx[101], ry[101], bx[101], by[101];
  cin >> V;
  for (int i=0;i<V;i++) {
    cin >> rx[i] >> ry[i];
  }
  for (int i=0;i<V;i++) {
    cin >> bx[i] >> by[i];    
  }
  for (int i=0;i<V;i++) {
    for (int j=0;j<V;j++) {
      if (rx[i] < bx[j] && ry[i] < by[j]) {
	add_edge(i, V+j);
      }
    }
  }

  int res = 0;
  memset(match, -1, sizeof(match));
  for (int v=0;v<(2*V);v++) {
    if (match[v] < 0) {
      memset(used, 0, sizeof(used));
      if (dfs(v)) {
	res++;
      }
    }
  }
  cout << res << endl;
  return 0;
}

