        }
    }

    rep(i, n) {
        mf.add_edge(MP(-1, -1), MP(a[i], b[i]), 1);
        mf.add_edge(MP(c[i], d[i]), MP(INF, INF), 1);
    }
    cout << mf.max_flow(MP(-1, -1), MP(INF, INF)) << endl;
    return 0;
}

