#include <iostream>
#include <vector>

using namespace std;

struct Point
{
    int x, y;
};

struct Node
{
    vector<int> edges;
    int pair = -1;
};

using Graph = pair<vector<Node>, vector<Node>>;

vector<Point> ReadPoints(int size)
{
    vector<Point> points(size);
    for (auto &p : points) {
        cin >> p.x >> p.y;
    }
    return points;
}

bool CanBeFriends(const Point &red, const Point &blue)
{
    return red.x <= blue.x && red.y <= blue.y;
}

Graph BuildGraph(const vector<Point> &red, const vector<Point> &blue)
{
    Graph graph { vector<Node>(red.size()), vector<Node>(blue.size()) };

    for (size_t i = 0; i < red.size(); i += 1) {
        for (size_t j = 0; j < blue.size(); j += 1) {
            if (CanBeFriends(red[i], blue[j])) {
                graph.first[i].edges.push_back(j);
                graph.second[j].edges.push_back(i);
            }
        }
    }
    return graph;
}

int CountPairs(const Graph &g)
{
    int pairs = 0;
    for (const auto &node : g.first) {
        pairs += (node.pair != -1 ? 1 : 0);
    }
    return pairs;
}

bool FindPair(Graph &g, int node, vector<bool> &used)
{
    if (used[node]) {
        return false;
    }
    used[node] = true;

    for (const auto &other : g.first[node].edges) {
        if (g.second[other].pair == -1) {
            g.first[node].pair = other;
            g.second[other].pair = node;
            return true;
        }
    }

    for (const auto &other : g.first[node].edges) {
        if (FindPair(g, g.second[other].pair, used)) {
            g.first[node].pair = other;
            g.second[other].pair = node;
            return true;
        }
    }
    return false;
}

int FindMaxMatch(Graph &g)
{
    auto changed = true;
    while (changed) {
        changed = false;

        vector<bool> used(g.first.size(), false);
        for (size_t i = 0; i < g.first.size(); i += 1) {
            if (g.first[i].pair == -1 && FindPair(g, i, used)) {
                changed = true;
            }
        }
    }
    return CountPairs(g);
}

int main()
{
    int points;
    cin >> points;

    auto red = ReadPoints(points);
    auto blue = ReadPoints(points);

    auto graph = BuildGraph(red, blue);
    auto res = FindMaxMatch(graph);
    cout << res << "\n";

    return 0;
}

