	for (int k = 0; k < N - 1; ++k) {
		for (int l = 1; l < N; ++l) {
			if (c[k] > c[l]) {
				x = c[l];
				c[l] = c[k];
				c[k] = x;
				y = d[l];
				d[l] = d[k];
				d[k] = y;
			}
		}
	}
	for (int n = 0; n < N; ++n) {
		for (int m = 0; m < N; ++m) {
			if (a[n] < c[m] && b[n] < d[m]) {
				nakayoshi++;
				c[m] = 0;
				d[m] = 0;
				break;
			}
		}
	}
	cout << nakayoshi << endl;
    return 0;
}

