class BipartiteMatching {
    vector<vector<ll> > G;
    vll match;
    vector<bool> vis;
    ll N;
    BipartiteMatching(){}
    bool dfs(ll v) {
        vis[v] = true;
        for(auto &u:G[v]) {
            ll w = match[u];
            if(w < 0 || !vis[w] && dfs(w)) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }
public:
    BipartiteMatching(ll size) {
        G.resize(size);
        N = size;
    }
    void initialize(ll size) {
        G.clear();
        G.resize(size);
        N = size;
    }
    void unite(ll u, ll v) {
        G[u].push_back(v);
        G[v].push_back(u);
    }
    ll search() {
        ll res = 0;
        match.assign(N, -1);
        for(int v = 0; v < N; v++) {
            if(match[v] < 0) {
                vis.assign(N, false);
                if(dfs(v)) res++;
            }
        }
        return res;
    }
};

void solve() {
    ll N;
    cin >> N;
    vll a(N), b(N), c(N), d(N);
    BipartiteMatching g(N*2);
    REP(i, N) cin >> a[i] >> b[i];
    REP(i, N) cin >> c[i] >> d[i];
    REP(i, N){
        REP(j, N) {
            if(a[i] < c[j] && b[i] < d[j]) {
                g.unite(i, N+j);
            }
        }
    }
    out(g.search());
}

int main() {
    fast_io;
    solve();
    return 0;
}

