class BipariteGraph {
public:
    // Bipartite Graph G = (A; B, E), A = [0, L), B = [L, L + R)
    BipariteGraph(int _L, int _R) : L(_L), R(_R), adj(L + R), match_to(L + R, -1), visited(L + R), size_match(0) {}

    void add_edge(const int v1, const int v2) {
        adj[v1].push_back(L + v2);
        adj[L + v2].push_back(v1);
    }

    int MaximumMatching() {
        for (int v = 0; v < L; ++v) {
            fill(visited.begin(), visited.end(), false);
            if (Augment(v)) ++size_match;
        }

        return size_match;
    }

private:
    const int L, R;
    vector<vector<int>> adj;
    vector<int> match_to;
    vector<bool> visited;
    int size_match;

    bool Augment(const int cur) {
        for (const int dst : adj[cur])
            if (!visited[dst]) {
                visited[dst] = true;
                if (match_to[dst] < 0 || Augment(match_to[dst])) {
                    match_to[cur] = dst; match_to[dst] = cur;
                    return true;
                }
            }
        return false;
    }
};

