#include<bits/stdc++.h>
#define ll long long
#define N 300
#define M 100000
using namespace std;
int n, a[N], b[N];

struct Edge
{
    struct edge{ int v, nxt; }e[M];
    int tot, hd[N];
    void init(){ tot = 0, memset(hd, 0, sizeof(hd)); }
    void add(int u, int v){ e[++tot].v = v, e[tot].nxt = hd[u], hd[u] = tot; }
}e;

struct Bipartite
{
    int n;
    int result[N + 1], state[N + 1];//M:y集合点数,下标从1开始 result[y]:x集合中对应的当前匹配边,state[y]:当前匹配轮now是否遍历到y点(state[y]==now说明遍历到)
    bool hungary(int u, int now)//now:x集合的遍历起点,下标从1开始
    {
        for(int i = e.hd[u]; i; i = e.e[i].nxt)
        {
            int v = e.e[i].v;
            if(state[v] == now) continue;
            state[v] = now;
            if(!result[v] || hungary(result[v], now))
            {
                result[v] = u;
                return 1;
            }
        }
        return 0;
    }
    void init()
    {
        memset(result, 0, sizeof(result));
        memset(state, 0, sizeof(state));
        //addedge()//伪代码:x集合点[1,N]连向[1,M],可以共用编号[1,max(N,M)]
    }
    int matchNum(int _n)
    {
        n = _n;
        int cnt = 0;
        init();
        for(int i = 1; i <= n; i ++)
            if(hungary(i, i)) cnt ++;
        return cnt;
    }
}bi;


int main()
{
//    freopen("in.txt", "r", stdin);
    //freopen("out.txt","w",stdout);
    scanf("%d", &n);
    e.init();
    for(int i = 1; i <= 2 * n; i ++) scanf("%d%d", &a[i], &b[i]);
    for(int i = 1; i <= n; i ++)
    {
        for(int j = n + 1; j <= 2 * n; j ++)
        {
            if(a[i] < a[j] && b[i] < b[j]) e.add(i, j);
        }
    }
    printf("%d\n", bi.matchNum(n));
    return 0;
}

