const ll MOD = 1000000007;
const ll HIGHINF = (ll)1e18;

const ll MAX_V = 201;
ll vn = MAX_V;
vvll G(MAX_V);
vll match(MAX_V);
V<bool> used(MAX_V, false);

void add_edge(ll u, ll v) {
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(ll v) {
    used[v] = true;
    for (auto u: G[v]) {
        ll w = match[u];
        if (w<0 || (!used[w] && dfs(w))) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

ll bipartite_matching() {
    ll res = 0;
    REP(i, MAX_V) match[i] = -1;
    REP(v, vn) {
        if (match[v] < 0) {
            REP(i, MAX_V) used[i] = false;
            if (dfs(v)) res++;
        }
    }
    return res;
}

