using namespace std;

class Bipartite {
public:
  Bipartite(int n)
    : graph(n), pairs(n, -1), used(n, false) {}

  void addEdge(int u, int v) {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  int run() {
    int res = 0;
    for (int v = 0; v < pairs.size(); ++v) {
      if (pairs[v] < 0) {
        fill(used.begin(), used.end(), false);
        if (dfs(v))
          ++res;
      }
    }
    return res;
  }

private:
  bool dfs(int v) {
    used[v] = true;
    for (int u : graph[v]) {
      int w = pairs[u];
      if (w < 0 || (!used[w] && dfs(w))) {
        pairs[v] = u;
        pairs[u] = v;
        return true;
      }
    }
    return false;
  }

  int v;
  vector<vector<int>> graph;
  vector<int> pairs;
  vector<bool> used;
};

