using namespace std;

typedef tuple<int,int,bool> Tb;

bool tupleCompare(const Tb& firstElof, const Tb& secondElof)
{
    return get<1>(firstElof) > get<1>(secondElof);
}

int arc092_a(){
    int n;
    cin >> n;

    // 方針　→　青点をx座標昇順にソート、赤点をy座標降順にソートして1個ずつ調べる

    vector<Tb> pr(n),pb(n);
    for(int i=0;i<n;++i){
        int tmp1,tmp2;
        cin >> tmp1 >> tmp2;
        pr[i] = make_tuple(tmp1,tmp2,false); //赤点配列。第3引数のboolは赤点をもう使ったかの判定
    }
    for(int i=0;i<n;++i){
        int tmp1,tmp2;
        cin >> tmp1 >> tmp2;
        pb[i] = make_tuple(tmp1,tmp2,false); //青点。こっちのboolは使わない
    }
    int ans = 0;

    sort(pr.begin(), pr.end(),tupleCompare);
    sort(pb.begin(), pb.end());
    for(int i=0;i<n;++i){
        int pbx = get<0>(pb[i]); //青点x座標
        int pby = get<1>(pb[i]); //青点y座標
        for(int j=0;j<n;++j){ //青点x座標昇順、赤点y座標降順に調べる
            if((get<0>(pr[j])<pbx && get<1>(pr[j])<pby) && !get<2>(pr[j])){ //x座標y座標の条件、使ってない赤点の条件
                ++ans;
                get<2>(pr[j]) = true; //赤点を使った判定
                break;
            }
        }
    }

    cout << ans <<endl;
    return 0;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    arc092_a();
    return 0;
}

