void solve(){
	for(int blue_x=2*N-1;blue_x>=0;blue_x--){//青い点のx座標が2*N-1>=blue_x>=0まで調べる
		for(int blue_y : blue[blue_x]){//青い点のx座標がblue_xのもののうち、y座標が大きいものから見ていく
			for(int red_x=blue_x-1;red_x>=0;red_x--){
