using namespace std;

// Ford-Fulkerson
int INF = 100000;
struct edge { int to, cap, rev; };

vector<edge> G[202];
bool used[202];

void add_edge(int from, int to, int cap) {
   G[from].push_back((edge){to, cap, G[to].size()});
   G[to].push_back((edge){from, 0, G[from].size() - 1});
}

int dfs(int v, int t, int f) {
   if (v == t) return f;

   used[v] = true;
   for (int i = 0; i < G[v].size(); i++) {
      edge &e = G[v][i];
      if (!used[e.to] && e.cap > 0) {
         int d = dfs(e.to, t, min(f, e.cap));
         if (d > 0) {
            e.cap -= d;
            G[e.to][e.rev].cap += d;
            return d;
         }
      }
   }
   return 0;
}

int max_flow(int s, int t) {
   int flow = 0;
   for (;;) {
      memset(used, 0, sizeof(used));
      int f = dfs(s, t, INF);
      if (f == 0) return flow;
      flow += f;
   }
}

int main() {
   int N;
   cin >> N;
   int Rx[N], Ry[N], Bx[N], By[N];
   for (int i = 0; i < N; i++) {
      cin >> Rx[i] >> Ry[i];
   }
   for (int i = 0; i < N; i++) {
      cin >> Bx[i] >> By[i];
   }
   int s = 2 * N;
   int t = s + 1;
   for (int i = 0; i < N; i++) {
      add_edge(s, i, 1);
      add_edge(i + N, t, 1);
   }
   for (int r = 0; r < N; r++) {
      for (int b = 0; b < N; b++) {
         if (Rx[r] < Bx[b] && Ry[r] < By[b]) {
            add_edge(r, b + N, 1);
         }
      }
   }
   cout << max_flow(s, t) << endl;
   return 0;
}

