    ll id;
    ll x;
    ll y;

    explicit Point(ll id, ll x, ll y) : id(id), x(x), y(y) {}
    bool operator < (Point p) const{
        return x > p.x;
    }
};

int main() {
    ll n;
    cin >> n;
    vector<Point> reds, blues;
    for (auto &&i: boost::irange(0LL, n)) {
        ll x, y;
        cin >> x >> y;
        reds.emplace_back(Point(i, x, y));
    }
    for (auto &&i: boost::irange(0LL, n)) {
        ll x, y;
        cin >> x >> y;
        blues.emplace_back(Point(i, x, y));
    }
    ll counts{0};
    sort(reds.begin(), reds.end());
    for (Point &p_r: reds) {
        ll id_of_blue_which_nearest_y = -1;
        ll y_of_blue_which_nearest_y = numeric_limits<ll>::max();
        for (Point &p_b: blues) {
            if (!(p_b.valid) || p_r.x >= p_b.x)continue;
            else if (abs(p_r.y - p_b.y) < abs(p_r.y - y_of_blue_which_nearest_y)) {
                id_of_blue_which_nearest_y = p_b.id;
                y_of_blue_which_nearest_y = p_b.y;
            }
        }
        if (id_of_blue_which_nearest_y != -1){
            counts++;
            blues.at(id_of_blue_which_nearest_y).valid = false;
        }
    }
    cout << counts;
