bool compare_by_b(pair<int, int> a, pair<int, int> b) {
	if (a.second != b.second) {
		return a.second < b.second;
	}
	else {
		return a.first < b.first;
	}
}

int main() {
	int N; cin >> N;
	vector<vector<int>> R(N, vector<int>(2, 0));
	vector<vector<int>> B(N, vector<int>(2, 0));
	vector<vector<int>> isPair(N, vector<int>(N, 0));
	vector<pair<int, int>> sums;

	rep(i, N) {
		cin >> R[i][0];
		cin >> R[i][1];
	}
	rep(i, N) {
		cin >> B[i][0];
		cin >> B[i][1];
	}

	rep(i, N) {
		rep(j, N) {
			if (R[i][0] < B[j][0] && R[i][1] < B[j][1]) {
				isPair[i][j] = 1;
			}
		}
		int sum = accumulate(isPair[i].begin(), isPair[i].end(), 0);
		if (sum != 0)sums.push_back(make_pair(i, accumulate(isPair[i].begin(), isPair[i].end(), 0)));
	}
	sort(sums.begin(), sums.end(), compare_by_b);
	int ans = 0;

	while (sums.size() > 0) {
		int num1 = sums[0].first;
		int used = -1;
		rep(j, N) {
			if (isPair[num1][j] == 1) {
				++ans;
				used = j;
				break;
			}
		}
		if (used >= 0) {
			sums = vector<pair<int, int>>();
			rep(j, N) {
				if (j != num1) {
					isPair[j][used] = 0;
					int sum = accumulate(isPair[j].begin(), isPair[j].end(), 0);
					if (sum != 0)sums.push_back(make_pair(j, accumulate(isPair[j].begin(), isPair[j].end(), 0)));
				}
				else {
					rep(k, N)isPair[j][k] = 0;
				}
			}
			//cout << sums.size() << endl;
			sort(sums.begin(), sums.end(), compare_by_b);
		}
	}
	cout << ans;
}

