    for (auto itr = rp.begin(); itr != rp.end(); ++itr) {
        for (auto it = bp.lower_bound(*itr); it != bp.end(); ++it) {
            if (itr->first < it->first) {
                bp.erase(it);
                ++res;
                break;
            }
        }        
    }
    cout << res << endl;
    return 0;
}

