using namespace std;

struct point
{
	short x, y;

	bool operator<(const point& right) const {
		return x < right.x;
	}
};

bool point_true(point red, point blue)
{
	if (red.x < blue.x && red.y < blue.y)
		return true;
	else
		return false;
}

vector<point> red;
vector<point> blue;

int n;

int search(bool red_num[], bool blue_num[])
{
	int num;
	int best = 0;

	for (int i = 0; i < n; i++)
	{
		if (blue_num[i] == false)
		{
			point bl = blue[i];

			for (int j = 0; j < n; j++)
			{
				if (red_num[j] == false)
				{
					point rl = red[j];

					if (rl.x > bl.x)
						break;

					if (point_true(rl, bl))
					{
						blue_num[i] = true;
						red_num[j] = true;

						num = search(red_num, blue_num) + 1;

						if (num > best)
							best = num;

						blue_num[i] = false;
						red_num[j] = false;
					}
				}
			}
		}
	}

	return best;
}

int main(void)
{
	cin >> n;

	for (int i = 0; i < n; i++)
	{
		point p;
		cin >> p.x >> p.y;
		red.push_back(p);
	}
	for (int i = 0; i < n; i++)
	{
		point p;
		cin >> p.x >> p.y;
		blue.push_back(p);
	}

	sort(red.begin(), red.end());
	sort(blue.begin(), blue.end());

	int best = 0;
	int ans = 0;

	bool red_table[104] = {};
	bool blue_table[104] = {};

	cout << search(red_table, blue_table) << endl;

	return 0;
}

