bool cmp(pair<int,int> p, pair<int,int> q) {
  if (p.first == q.first) {
    return p.second<q.second;
  }
  return p.first>q.first;
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

