  int ans = 0;
  for (int i=0; i<n; i++) {
    for (int j=0; j<n; j++) {
      if (used[j]) continue;
      if (compat(i,j)) {
	ans++;
	used[j]=true;
	break;
      }
    }
  }

  out(ans);

