const int maxn=1e2+10;
const int INF=0x3f3f3f3f;
const double eps=1e-6;
int k,n,m,cnt,head[maxn],Rank[maxn],S,T,xx[2*maxn],yy[2*maxn];
struct Edge
{
    int v,f,next;
}edge[maxn*maxn];
void init()
{
    mem(head,-1);
    cnt=0;
    S=0;
    T=2*n+1;
}
void add(int u,int v,int f)
{
    edge[cnt].next=head[u];
    edge[cnt].f=f;
    edge[cnt].v=v;
    head[u]=cnt++;
}
bool ok(int a,int b)
{
    if(xx[a]<xx[b]&&yy[a]<yy[b]) return true;
    return false;
}
bool Bfs()
{
    mem(Rank,-1);
    queue<int> q;
    q.push(S);
    Rank[S]=1;
    while(!q.empty())
    {
        int x=q.front();
        q.pop();
        for(int i=head[x];i!=-1;i=edge[i].next){
            int v=edge[i].v,f=edge[i].f;
            if(!f||Rank[v]!=-1) continue;
            Rank[v]=Rank[x]+1;
            q.push(v);
        }
    }
    if(Rank[T]==-1) return false;
    return true;
}
int dfs(int x,int mark)
{
    int used=0;
    if(x==T) return mark;
    for(int i=head[x];i!=-1;i=edge[i].next){
        int v=edge[i].v,f=edge[i].f;
        if(Rank[v]!=Rank[x]+1||!f) continue;
        int c=dfs(v,min(mark-used,f));
        edge[i].f-=c;
        edge[i^1].f+=c;
        used+=c;
        if(used==mark) break;
    }
    if(!used) Rank[x]=-1;
    return used;
}
int Dinic()
{
    int res=0;
    while(Bfs()){
        while(int x=dfs(S,INF)) res+=x;
    }
    return res;
}
