        for(int i=1;i<=n;i++){
            for(int j=1;j<=n;j++){
                if(ok(i,j+n)){
                    add(i,j+n,1);
                    add(j+n,i,0);
                }
            }
        }
        for(int i=1;i<=n;i++) add(S,i,1),add(i,S,0);
        for(int i=n+1;i<=2*n;i++) add(i,T,1),add(T,i,0);
        int res=Dinic();
        printf("%d\n",res);
    }
