#include <bits/stdc++.h>
using namespace std;

template<class Numeric> struct Dinic {
  struct edge {
    int to; Numeric cap; int rev;
    edge(int t, Numeric c, int r){
      to = t; cap = c; rev = r;
    }
    void print() {
      cout << to << "\t" << cap << "\t" << rev << endl;
    }
  };
  vector< vector<edge> > g; vector<int> iter, level;
  int N; Numeric INF;
  Dinic(int n) {
    N = n; g.resize(N); iter.resize(N); level.resize(N);
    INF = numeric_limits<Numeric>::max();
  }
  void add(int from, int to, Numeric cap) {
    g[from].push_back(edge(to, cap, (int) g[to].size()));
    g[to].push_back(edge(from, 0, (int) g[from].size()-1));
  }
  void bfs(int s){
    level.assign(N,-1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
      int v = q.front(); q.pop();
      for(int i = 0; i < (int) g[v].size(); i++){
        edge &e = g[v][i];
        if (e.cap > 0 and level[e.to] < 0) {
          level[e.to] = level[v] + 1;
          q.push(e.to);
        }
      }
    }
  }
  Numeric dfs(int v, int t, Numeric f) {
    if (v == t) return f;
    for (int i = iter[v]; i < (int) g[v].size(); i++) {
      edge &e = g[v][i];
      if (e.cap > 0 && level[v] < level[e.to]){
        Numeric d = dfs(e.to, t, min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          g[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }
  Numeric solve(int s, int t) {
    Numeric flow = 0;
    while(true){
      bfs(s);
      if (level[t] < 0) return flow;
      iter.assign(N, 0);
      Numeric f;
      while ((f = dfs(s, t, INF)) > 0){
        flow += f;
      }
    }
  }
};


int main(){
  int n; cin >> n;
  Dinic<int> f((n+1)*2);
  vector<int> a(n), b(n), c(n), d(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i] >> b[i];
    f.add(0, i+1, 1);
  }
  for (int i = 0; i < n; i++) {
    cin >> c[i] >> d[i];
    f.add(n+i+1, n*2+1, 1);
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (a[i] < c[j] && b[i] < d[j]) f.add(i+1, n+j+1, 1);
    }
  }
  cout << f.solve(0, n*2+1) << endl;
  return 0;
}

