bool cmp(pair<ll, ll> A, pair<ll, ll> B)
{
    ll a_sum = A.first + A.second;
    ll b_sum = B.first + B.second;
    if (a_sum == b_sum)
    {
        return A.second > B.second;
    }
    return a_sum < b_sum;
}

