template<class T> ostream &operator<<(ostream &os, digraph<T> &g) {    os << endl << g.n << " " << sz(g.edges) << endl;    fore(gi, g.edges) { os << f << " " << t << " " << c << endl; }    return os;}template<class T> ostream &operator<<(ostream &os, undigraph<T> &g) {    os << endl << g.n << " " << sz(g.edges)/2 << endl;    fore(gi, g.edges) { if (f < t)os << f << " " << t << " " << c << endl; }    return os;}

//@判定
template<class T> bool nibu( graph<T> &g) {    int size = 0;    rep(i, g.n)size += sz(g.g[i]);    if (size == 0)return true;    unionfind uf(g.n * 2);    rep(i, g.n)fora(e, g.g[i])uf.unite(e.f, e.t + g.n), uf.unite(e.f + g.n, e.t);    rep(i, g.n)if (uf.same(i, i + g.n))return 0;    return true;}
//頂点ではなく辺の数に依存した計算量 O(E)
template<class T> bool nibu_sub( graph<T> &g) {    umapi col;/*0なら無色 */   queue<int> q;    /*色は01か11 */    fora(e, g.edegs) {        /*fとtの色を持つか否かは同じ*/        if (col[e.f] == 0)q.push(e.f);        while (!q.empty()) {            int f = q.front();            q.pop();            int fc = col[f];            forg(gi, g[f]) {                int &tc = col[t];                /*fcには色がある*/                if (fc == tc)return false;                /*違う色*/                if (tc)continue;                /*無色*/                tc = fc ^ 2;                q.push(tc);            }        }    }    return true;}
    //二部グラフを色分けした際の頂点数を返す
template<class T> vp nibug(graph<T> &g) {    vp cg;    if (!nibu(g)) {        debugline("nibu");        ole();    }    int n = g.size();    vb was(n);    queue<P> q;    rep(i, n) {        if (was[i])continue;        q.push(mp(i, 1));        was[i] = 1;        int red = 0;        int coun = 0;        while (q.size()) {            int now = q.front().fi;            int col = q.front().se;            red += col;            coun++;            q.pop();            forg(gi, g[now]) {                if (was[t])continue;                q.push(mp(t, col ^ 1));                was[t] = 1;            }        }        cg.push_back(mp(red, coun - red));    }    return cg;}
    //連結グラフが与えられる 閉路があるか
template<class T> bool close(undigraph<T> &g) {    int n = 0;    int e = 0;    rep(i, g.n) {        if (sz(g[i]))n++;        forg(gi, g[i]) { e++; }    }    return (e >> 1) >= n;}
template<class T> bool close(undigraph<T> &g, int v) {    unionfind uf(g.n);    rep(i, g.n) {        forg(gi, g[i]) {            if (f < t)break;            if (f == t && f == v)return true;            if (uf.same(f, v) && uf.same(t, v))return true;            uf.unite(f, t);        }    }    return false;}template<class T> bool close(digraph<T> &g) {    vi res;    return topo(res, g);}

