class HopcroftKarp {
    vector<vector<ll> > G;
    vll pU, pV, dist;
    ll Nl, Nr, N;
    HopcroftKarp(){}
    bool bfs(ll m) {
        queue<ll> q;
        for(int u = 1; u <= m; u++) {
            if(pU[u]==0) {
                dist[u] = 0;
                q.push(u);
            }else {
                dist[u] = INF;
            }
        }
        dist[0] = INF;
        while (!q.empty())
        {
            ll u = q.front();q.pop();
            if(dist[u] < dist[0]) {
                for(auto &v:G[u]) {
                    if(dist[pV[v]] == INF) {
                        dist[pV[v]] = dist[u] + 1;
                        q.push(pV[v]);
                    }
                }
            }
        }
        return dist[0] != INF;
    }
    bool dfs(ll u) {
        if(u != 0) {
            for(auto &v:G[u]) {
                if(dist[pV[v]] == dist[u] + 1 && dfs(pV[v])) {
                    pV[v] = u;
                    pU[u] = v;
                    return true;
                }
            }
            dist[u] = INF;
            return false;
        }
        return true;
    }
public:
    HopcroftKarp(ll _Nl, ll _Nr) {
        Nl = _Nl;
        Nr = _Nr;
        N = Nl + Nr;
        G.resize(N+2);
        pU.resize(Nl+1);
        pV.resize(Nr+1);
        dist.resize(N+2);
    }
    void initialize(ll _Nl, ll _Nr) {
        Nl = _Nl;
        Nr = _Nr;
        N = Nl + Nr;
        G.clear();
        G.resize(N+2);
        pU.assign(Nl+1, 0);
        pV.assign(Nr+1, 0);
        dist.assign(N+2, 0);
    }
    void unite(ll u, ll v) {
        if(u == 0 || v == 0) {
            debug("Warning: 0-indexed");
        }
        G[u].push_back(v);
        G[Nl+v].push_back(u);
    }
    ll bipartite_matching() {
        pU.assign(Nl, 0);
        pV.assign(Nr, 0);
        ll ret = 0;
        while(bfs(Nl)) {
            for(int u=1; u <= Nl; u++) {
                if(pU[u] == 0 && dfs(u)) {
                    ret++;
                }
            }
        }
        return ret;
    }
};

void solve() {
    ll N;
    cin >> N;
    vll a(N), b(N), c(N), d(N);
    HopcroftKarp g(N, N);
    REP(i, N) cin >> a[i] >> b[i];
    REP(i, N) cin >> c[i] >> d[i];
    REP(i, N){
        REP(j, N) {
            if(a[i] < c[j] && b[i] < d[j]) {
                g.unite(i+1, j+1);
            }
        }
    }
    out(g.bipartite_matching());
}

int main() {
    fast_io;
    solve();
    return 0;
}

