int main() {
	int n;
	std::cin >> n;
	std::vector<std::pair<int, int>>r(n), b(n);
	std::vector<bool>used(n, 0);
	for (int i = 0; i < 2 * n; i++) {
		if (i < n)std::cin >> r[i].first >> r[i].second;
		else std::cin >> b[i - n].first >> b[i - n].second;
	}

	std::sort(r.begin(), r.end(), [](const auto a, const auto b) {return a.first > b.first; });
	std::sort(b.begin(), b.end(), [](const auto a, const auto b) {return a.second < b.second; });
	int ans = 0;
	for (int i = 0; i < n; i++) {
		int minIdx = -1;
		for (int j = 0; j < n; j++) {
			if (r[i].second < b[j].second&&r[i].first < b[j].first&&!used[j]) {
				minIdx = j;
				break;
			}
		}
		if (minIdx == -1)continue;
		used[minIdx] = true;
		ans++;
	}
	printf("%d\n", ans);
}

