const int N = 111;
bool vis[N];
int a[N], b[N], c[N], d[N], match[N];
vector< int > gr[N];

bool aug ( int x )
{
	if( vis[x] ) return false;
	vis[x] = 1;
	for( int y : gr[x] )
	{
		if( match[y] == -1 || aug( match[y] ) )
		{
			match[y] = x;
			return true;
		}
	}
	return false;
}

int main()
{
	int n;
	scanf("%d", &n );

	for( int i = 0; i < n; ++ i )
		scanf("%d %d", a + i, b + i );

	for( int i = 0; i < n; ++ i )
		scanf("%d %d", c + i, d + i );

	for( int i = 0; i < n; ++ i )
	{
		for( int j = 0; j < n; ++ j )
			if( a[i] < c[j] && b[i] < d[j] )
				gr[i].push_back( j );
	}

	memset( match, -1, sizeof match );
	int ans = 0;
	for( int i = 0; i < n; ++ i )
	{
		memset( vis, 0, sizeof vis );
		ans += aug( i );
	}
	printf("%d\n", ans );
	return 0;
}

