struct BipartiteMatching {
    int n;
    std::vector<std::vector<int>> G;
    std::vector<int> match, used;
    int timestamp;
    BipartiteMatching(int n) : n(n), G(n), match(n), used(n) {}
    void addEdge(int u, int v) {
        G[u].push_back(v);
        G[v].push_back(u);
    }
    bool dfs(int v) {
        used[v] = timestamp;
        for (int i = 0; i < G[v].size(); i++) {
            int u = G[v][i], w = match[u];
            if (w < 0 || used[w] != timestamp && dfs(w)) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }
    std::vector<std::pair<int, int>> getMaxMatching() {
        fill(match.begin(), match.end(), -1);
        fill(used.begin(), used.end(), 0);
        timestamp = 0;
        for (int i = 0; i < n; i++) {
            if (match[i] < 0) {
                timestamp++;
                dfs(i);
            }
        }
        std::vector<std::pair<int, int>> ret;
        for (int i = 0; i < n; i++) {
            if (i < match[i]) { ret.push_back({i, match[i]}); }
        }
        return ret;
    }
};

