int bip_max_matching(Graph &graph, vector<vector<int>> &p) {
	assert(p.size() == 2);
	int N1 = p[0].size(), N2 = p[1].size();
	assert(N1 + N2 == graph.V);
	mf_graph<int> g(N1 + N2 + 2);
	for (int u : p[0]) g.add_edge(N1 + N2, u, 1);
	for (int u : p[0]) for (int v : graph.adj[u]) g.add_edge(u, v, 1);
	for (int v : p[1]) g.add_edge(v, N1 + N2 + 1, 1);
	return g.flow(N1 + N2, N1 + N2 + 1);
}
// graphは前半と後半に分かれた二部グラフ
