using namespace std;
typedef long long ll;

struct edge{ll to, cap, rev;}; //to, capacity, 反対エッジ
struct graph{
  ll N; //ノードの個数
  vector<vector<edge> > G; //G[辺の元]((.to辺の先,.costコスト),...)
  vector<ll> depth; // d[ノード] ノードの深さ

  graph(ll n){ //グラフ生成時
    N = n;
    G.resize(N); //Edge情報
    depth.resize(N); //Node情報,深さ
    rep(i,N) depth[i] = -1;
  }
  void add_edge(ll s, ll t, ll cap){
    G[s].emplace_back((edge){t, cap, (ll)G[t].size()});
    G[t].emplace_back((edge){s, 0, (ll)G[s].size()-1});
  }

  ll dfs(ll v, ll goal, ll water, ll d=1){
    if(v == goal) return water;
    depth[v] = d;
    for(auto& E : G[v]){ // E つなぐエッジ
      if(depth[E.to] == -1 && E.cap > 0){
        ll o_flow = dfs(E.to, goal, min(water, E.cap), d+1);
        if(o_flow > 0){
          E.cap -= o_flow;
          G[E.to][E.rev].cap += o_flow;
          return o_flow;
        }
      }
    }
    return 0;
  }

  ll max_flow(ll s, ll g){
    ll flow = 0;
    while(true){
      rep(i,N) depth[i] = -1;
      ll o_flow = dfs(s, g, INF, 1);
      if (o_flow==0) return flow; //更新がなかったら終了
      flow += o_flow;
    }
  }
};


void Main(){
