template<typename Type>
struct Dinic{
	struct Edge{//Edge:=(辺の情報を表す構造体).
		int to;		//to:=(行先). 
		Type cap;	//cap:=(容量).
		int rev;	//rev:=(逆辺).
	};

	vector<vector<Edge> > g;//g:=(グラフの隣接リスト表現).
	vi level;				//level[i]:=(sからiまでの距離).
	vi iter;				//iter[i]:=(ノードiの)
	Type inf;

	Dinic(int vn):g(vn),level(vn),iter(vn){//constructor.
		if(typeid(Type)==typeid(int)) inf=1e9;
		else if(typeid(Type)==typeid(long long)) inf=1e18;
	};

	void add_egde(int from,int to,Type cap){//fromからtoへ向かう容量capの辺をグラフに追加する.
		g[from].push_back((Edge){to,cap,(int)g[to].size()});
		g[to].push_back((Edge){from,0,(int)g[from].size()-1});
	}
	void bfs(int s){//sからの最短距離を計算する.
		fill(ALL(level),-1);
		level[s]=0;
		queue<int> que;
		que.push(s);
		while(!que.empty()){
			int v=que.front();
			que.pop();
			REP(i,g[v].size()){
				Edge &e=g[v][i];
				if(e.cap>0 and level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}	
	}
	Type dfs(int v,int t,Type f){//増加パスを探す.
		if(v==t) return f;
		for(int &i=iter[v];i<g[v].size();++i){
			Edge &e=g[v][i];
			if(e.cap>0 and level[v]<level[e.to]){
				Type d=dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap-=d;
					g[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}
	Type max_flow(int s,int t){//sからtへの最大流を調べる. O(en*(vn)^2).
		Type flow=0;
		while(1){
			bfs(s);
			if(level[t]<0) return flow;
			fill(ALL(iter),0);
			Type f;
			while((f=dfs(s,t,inf))>0) flow+=f;
		}
	}

};

int main(){//Refering other editorials.
	int n;
	cin>>n;

	vector<pii > red(n),bule(n);
	REP(i,n){
		int a,b;
		cin>>a>>b;
		a--, b--;
		red[i]=pii(a,b);
	}
	REP(i,n){
		int c,d;
		cin>>c>>d;
		c--, d--;
		bule[i]=pii(c,d);
	}
	sort(ALL(red));
	sort(ALL(bule));

	Dinic<int> ob(2*n+2);
	REP(i,n) ob.add_egde(2*n,i,1);
	REP(i,n) ob.add_egde(i+n,2*n+1,1);
	REP(i,n){
		int c,d;
		tie(c,d)=bule[i];
		REP(j,n){
			int a,b;
			tie(a,b)=red[j];
			if(a>=c) break;
			if(b<d) ob.add_egde(j,i+n,1);
		}
	}

	int ans=ob.max_flow(2*n,2*n+1);
	cout<<ans<<endl;
	return 0;
}

