void build_matching(int n, int k)
{
    mt.assign(k, -1);
    used_init.assign(n, false);
    for(int i = 0; i < n; i++)
    {
        for(int k = 0; k < (int) g[i].size(); k++)
        {
            if(mt[g[i][k]] == -1)
            {
                mt[g[i][k]] = i;
                used_init[i] = true;
                break;
            }
        }
    }


    for(int i = 0; i < n; i++)
    {
        if(used_init[i])
        {
            continue;
        }
        used.assign(n, false);
        try_kuhn(i);
    }

    for(int i = 0; i < k; i++)
    {
        if(mt[i] != -1)
        {
            matching.pb(mp(mt[i] + 1, i + 1));
        }
    }
}

