typedef pair<int, int> pii;

class C {
	int n;
	bool red[100][100];
	int ans{ 0 };
	vector<pii> queries;

public:
	C()
	{
		cin >> n;
		queries.reserve(n);

		int y, x;
		REP(i, n)
		{
			cin >> y >> x;
			red[y][x] = true;
		}
		REP(i, n)
		{
			cin >> y >> x;
			queries.emplace_back(MP(y, x));
		}
	}

	void search(const int& sy, const int& sx)
	{
		if (!sx || !sy)
			return;

		deque<int> q{ sy - 1 };

		while (!q.empty())
		{
			int cy{ q.front()};
			q.pop_front();

			RREP(cx, sx)
			{
				if (red[cy][cx])
				{
					red[cy][cx] = false;
					ans++;
					return;
				}
			}

			if (cy > 0)
				q.PB(cy - 1);

		}
	}


	void solve()
	{
		sort(ALL(queries), \
			[](const pii& left, const pii& right)\
		{return ((left.first) == (right.first)) ? (left.second < right.second) : (left.first < right.first); });

		REP(i, n)
			search(queries[i].first, queries[i].second);

		cout << ans << endl;

	}
};

