#include<stack>
using namespace std;

int main(){
	int N;
	cin>>N;
	int a[N],b[N],c[N],d[N];
	for(int i=0;i<N;++i){
		cin>>a[i]>>b[i];
	}
	for(int i=0;i<N;++i){
		cin>>c[i]>>d[i];
	}
	// マッチングに使われていない枝データ:not_used
	vector<vector<int> >not_used;
	for(int i=0;i<N;++i){
		for(int j=0;j<N;++j){
			if(a[i]<c[j] && b[i]<d[j]){
				vector<int>tmp;
				tmp.push_back(i);
				tmp.push_back(N+j);
				not_used.push_back(tmp);
			}
		}
	}
	// 最大流問題として捉える(start:-1,goal:-2)
	for(int i=0;i<N;++i){
		vector<int>tmps;
		tmps.push_back(-1);
		tmps.push_back(i);
		not_used.push_back(tmps);
		vector<int>tmpg;
		tmpg.push_back(N+i);
		tmpg.push_back(-2);
		not_used.push_back(tmpg);
	}
	/*
	for(int i=0;i<not_used.size();++i){
		cout<<not_used[i][0]<<" "<<not_used[i][1]<<endl;
	}
	*/
	int ans=0;
	vector<int>state;
	while(true){
		vector<vector<int> >statearr;
		stack<vector<int> >s;
		for(int i=0;i<not_used.size();++i){
			if(not_used[i][0]==-1)s.push(not_used[i]);
		}
		if(s.empty())break;
		bool add=false;
		while(!s.empty()){
			state=s.top();
			//cout<<state[0]<<" "<<state[1]<<endl;
			s.pop();
			if(statearr.size()==0)statearr.push_back(state);
			else if(statearr[statearr.size()-1][1]!=state[0]){
				while(statearr.size()>0 && statearr[statearr.size()-1][1]!=state[0]){
					statearr.pop_back();
				}
				statearr.push_back(state);
			}
			else {
				statearr.push_back(state);
			}
			/*
			for(int i=0;i<statearr.size();++i){
				cout<<statearr[i][0]<<" "<<statearr[i][1]<<" ";
			}
			cout<<endl;
			*/
			if(state[1]==-2){
				add=true;
				ans++;
				break;
			}

			//cout<<state[0]<<" "<<state[1]<<endl;
			for(int i=0;i<not_used.size();++i){
				if(state[1]==not_used[i][0]){
					//cout<<state[0]<<" "<<state[1]<<" "<<not_used[i][0]<<" "<<not_used[i][1]<<endl;
					int a=0;
					for(int j=0;j<statearr.size();++j){
						if(statearr[j][0]==not_used[i][1] || statearr[j][1]==not_used[i][1]){
							a=1;
						}
					}
					if(a==0)s.push(not_used[i]);
				}
			}
		}
		if(add==false)break;
		else{
			for(int i=0;i<statearr.size();++i){
				for(int j=0;j<not_used.size();++j){
					if(statearr[i]==not_used[j]){
						int tmp1;
						tmp1=not_used[j][0];
						not_used[j][0]=not_used[j][1];
						not_used[j][1]=tmp1;
					}
				}
			}
		}
	}
	cout<<ans<<endl;
}

