    FordFulkerson(int n) : INF(numeric_limits<flow_t>::max()), timestamp(0){
        graph.resize(n);
        used.assign(n, -1);
    }

    void add_edge(int from, int to, flow_t cap){
        graph[from].push_back(edge(to, cap, graph[to].size()));
        graph[to].push_back(edge(from, 0, graph[from].size() - 1));
    }

    flow_t dfs(int s, int t, flow_t flow){
        if(s == t)  return flow;
        used[s] = timestamp;
        for(auto &e : graph[s]){
            if(e.cap > 0 && used[e.to] != timestamp){
                flow_t d = dfs(e.to, t, min(flow, e.cap));
                if(d > 0){
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    flow_t max_flow(int s, int t){
        flow_t flow = 0;
        for(flow_t f; (f = (dfs(s, t, INF)) > 0); timestamp++){
            flow += f;
        }
        return flow;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n), b(n), c(n), d(n);
    FordFulkerson<int> flow(2 * n + 2);
    int s = 0, t = 2 * n + 1;
