struct bipartite_matching {
private:
    int V;
    vector<vector<int>> G;
    vector<int> match;
    vector<bool> used;
public:
    bipartite_matching(int n) {
        V = n;
        G.resize(n);
        match.resize(n);
        used.resize(n);
    }

    void add_edge(int u,int v) {
        G[u].push_back(v);
        G[v].push_back(u);
    }

    bool dfs(int v) {
        used[v] = true;
        for (int& u : G[v]) {
            int w = match[u];
            if (w < 0 || (!used[w] && dfs(w))) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }

    int count() {
        int res = 0;
        match = vector<int>(V,-1);
        for (int v = 0;v < V;++v) if (match[v] < 0) {
            used = vector<bool>(V,false);
            if (dfs(v)) res++;
        }
        return res;
    }
};
