class ABC091C_ball {
public:
	int px = 0;
	int py = 0;
	bool picked = false;

	bool isSmall(const ABC091C_ball& a) {
		return ((px < a.px) && (py < a.py));
	}

	static bool asc_x(const ABC091C_ball& a, const ABC091C_ball& b) {
		return (a.px < b.px);
	}

	static bool dsc_y(const ABC091C_ball& a, const ABC091C_ball& b) {
		return (a.py > b.py);
	}
};

static void ABC091C_2DPlane2NPoints()
{
	//	-----------------------------------------
	//		これまだ解けてないよ！！
	//	-----------------------------------------
	int N;
	get1int(N);

	auto reds = new ABC091C_ball[N + 1];
	for (int i = 0; i < N; i++) {
		get2int(reds[i].px, reds[i].py);
	}

	auto blues = new ABC091C_ball[N + 1];
	for (int i = 0; i < N; i++) {
		get2int(blues[i].px, blues[i].py);
	}

	std::sort(blues, blues + N, ABC091C_ball::asc_x);
	std::sort(reds, reds + N, ABC091C_ball::dsc_y);

	std::vector<ABC091C_ball> paired;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			if ((!reds[j].picked) && (reds[j].isSmall(blues[i]))) {
				paired.push_back(reds[j]);
				reds[j].picked = true;
				break;
			}
		}
	}

	printf("%d\n",paired.size());

	delete[] blues;
	delete[] reds;
}

