/* ---------- Variances ---------- */

int N;
VPL red, blue;
VB used(100, false);
int ans = 0;

/* ---------- Functions ---------- */

bool PLCompare(const PL& a, const PL& b) {
  // firstで小さい順ソート
  if (a.fst < b.fst) {
    return true;
  } else {
    return false;
  }
}

/* ---------- Main Function ---------- */

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N;
  red.resize(N);
  blue.resize(N);

  REP(i, N) {
    cin >> red[i].fst >> red[i].snd;
  }

  REP(i, N) {
    cin >> blue[i].fst >> blue[i].snd;
  }

  sort(ALL(red), PLCompare);
  sort(ALL(blue), PLCompare);

  REP(i, N) {
    ll maxid = -1;
    REP(j, N) {
      if (red[j].fst < blue[i].fst) {
        if (!used[j] && (red[j].snd < blue[i].snd)) {
          if (maxid < 0 || red[j].snd > red[maxid].snd) {
            maxid = j;
          }
        }
      } else {
        break;
      }
    }
    if (maxid >= 0) {
      ans++;
      used[maxid] = true;
    }
  }

  cout << ans << endl;
  return 0;
}

#include<stdio.h>
