#define MAX_N 100

typedef struct{
  int x;
  int y;
} p;

using namespace std;
int N, i, j, cnt, donecd[MAX_N], doneab[MAX_N];
p ab[MAX_N],  cd[MAX_N];

int x_asc(const void *a, const void *b) {
  p A = *(p *)a, B = *(p *)b;
  if (A.x < B.x) {
    return -1;
  } else if (A.x > B.x) {
    return 1;
  } else {
    return 0;
  }
}

int y_desc(const void *a, const void *b) {
  p A = *(p *)a, B = *(p *)b;
  if (A.y > B.y) {
    return -1;
  } else if (A.y < B.y) {
    return 1;
  } else {
    return 0;
  }
}
int not_done(int i, int j) {
  return doneab[j] == 0 && donecd[i] == 0;
}

int main () {
  scanf("%d", &N);
  for (i = 0; i < N; i++) {
    scanf("%d %d", &ab[i].x, &ab[i].y);
  }
  for (i = 0; i < N; i++) {
    scanf("%d %d", &cd[i].x, &cd[i].y);
  }
  qsort((void *)ab, N, sizeof(ab[0]), y_desc);
  qsort((void *)cd, N, sizeof(cd[0]), x_asc);
  for (i = 0; i < N; i++) { donecd[i] = 0; doneab[i] = 0; };
  for (i = 0, cnt = 0; i < N; i++) {
     for (j = 0; j < N; j++) {
        if (not_done(i, j) && cd[i].x > ab[j].x && cd[i].y > ab[j].y) {
          donecd[i] = 1;
          doneab[j] = 1;
          cnt++;
        }
     }
  }
  printf("%d", cnt);
}

