using namespace std;

vector<int> adj[210];
int match[210];
bool used[210];

bool dfs(int v)
{
	used[v] = true;

	for (int i = 0; i < adj[v].size(); i++)
	{
		int u = adj[v][i], w = match[u];

		if (w < 0 || (!used[w] && dfs(w)))
		{
			match[v] = u;
			match[u] = v;
			return true;
		}
	}
	return false;
}

int main()
{
	int n, a[110], b[110], c[110], d[110];

	cin >> n;

	for (int i = 1; i <= n; i++)
	{
		cin >> a[i] >> b[i];
	}
	for (int i = 1; i <= n; i++)
	{
		cin >> c[i] >> d[i];
	}

	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= n; j++)
		{
			if (a[i] < c[j] && b[i] < d[j])
			{
				adj[i].push_back(j + n);
				adj[j + n].push_back(i);
			}
		}
	}

	int res = 0;

	memset(match, -1, sizeof(match));

	for (int i = 1; i <= n; i++)
	{
		if (match[i] < 0)
		{
			memset(used, 0, sizeof(used));

			if (dfs(i))
			{
				res++;
			}
		}
	}
	cout << res << endl;
}

