int main () {
  long long n;
  vector<pair<long long, long long> > ab;
  vector<pair<long long, long long> > cd;
  cin >> n;
  for (long long i = 0; i < n; i++) {
    long long s, ss;
    cin >> s >> ss;
    ab.push_back(make_pair(s, ss));
  }  
  for (long long i = 0; i < n; i++) {
    long long s, ss;
    cin >> s >> ss;
    cd.push_back(make_pair(s, ss));
  }  
  sort(ab.begin(), ab.end());
  sort(cd.begin(), cd.end());
  int score[n][n];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (ab[i].first < cd[i].first &&
          ab[i].second< cd[i].second) {
        score[i][j] = 1;  
      }  
      else {
        score[i][j] = 0;  
      }
    }  
  }
  int ans = 0;
  bool ok = true;
  while (1) {
    int min = -1;
    int it = -1;
    ok = true;
    for (int i = 0; i < n; i++) {
      int nn = 0;
      for (int j = 0; j < n; j++) {
        if (score[i][j] == 1) {
          ok = false;
          nn++;
        }    
      }  
      if (nn > 0) {
        if (nn < min || min < 0) {
          min = nn;
          it = i;  
        }
      }
    }    
    if (ok == true) {
      break;  
    }
    int jt = -1;
    for (int j = 0; j < n; j++) {
      if (score[it][j] == 1) {
        ans++;
        score[it][j] = 0;
        jt = j;
        break;
      }  
    }
    for (int j = 0; j < n; j++) {
      score[it][j] = 0;  
    }
    for (int i = 0; i < n; i++) {
      score[i][jt] = 0;  
    }
  }
  cout << ans << endl;
}

