const int MAX = 100005;

//dinic法
struct max_flow {
    struct edge {int to, cap, rev;};
    int V;
    vector<vector<edge>> G;
    vector<int> itr, level;

    max_flow(int V) : V(V), G(V){}

    void add_edge(int from, int to, int cap) {
        G[from].push_back((edge){to, cap, (int)G[to].size()});
        G[to].push_back((edge){from, 0, (int)G[from].size()-1});
    }

    void bfs(int s) {
        level.assign(V,-1);
        queue<int> q;
        level[s] = 0; q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e: G[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = itr[v]; i < (int)G[v].size(); i++) {
            edge &e = G[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                int d = dfs(e.to, t, min(f,e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    int run(int s, int t) {
        int ret = 0, f;
        while (bfs(s), level[t] >= 0) {
            itr.assign(V,0);
            while ((f = dfs(s,t,inf)) > 0) ret += f;
        }
        return ret;
    }
};

int main() {
    int n; cin >> n;
    vint x(2*n), y(2*n);
    rep(i,2*n) cin >> x[i] >> y[i];
    max_flow dinic(2*n+2);
    int s = 2 * n, t = s + 1;
    rep(i,n) dinic.add_edge(s,i,1);
    rep(i,n) dinic.add_edge(n+i,t,1);
    rep(i,n) {
        rep(j,n) {
            if (x[i] < x[n+j] && y[i] < y[n+j]) {
                dinic.add_edge(i,n+j,1);
            }
        }
    }
    cout << dinic.run(s,t) << endl;
}

