#define all(c) ((c).begin()), ((c).end())

const long long INF = (1ll << 50);
struct graph {
	typedef long long flow_type;
	struct edge {
		int src, dst;
		flow_type capacity, flow;
		size_t rev;
	};
	int n;
	vector<vector<edge>> adj;
	graph(int n) : n(n), adj(n) { }
	void add_edge(int src, int dst, flow_type capacity) {
		adj[src].push_back({ src, dst, capacity, 0, adj[dst].size() });
		adj[dst].push_back({ dst, src, 0, 0, adj[src].size() - 1 });
	}
	flow_type max_flow(int s, int t) {
		vector<int> level(n), iter(n);
		function<int(void)> levelize = [&]() { // foward levelize
			level.assign(n, -1); level[s] = 0;
			queue<int> Q; Q.push(s);
			while (!Q.empty()) {
				int u = Q.front(); Q.pop();
				if (u == t) break;
				for (auto &e : adj[u]) {
					if (e.capacity > e.flow && level[e.dst] < 0) {
						Q.push(e.dst);
						level[e.dst] = level[u] + 1;
					}
				}
			}
			return level[t];
		};
		function<flow_type(int, flow_type)> augment = [&](int u, flow_type cur) {
			if (u == t) return cur;
			for (int &i = iter[u]; i < adj[u].size(); ++i) {
				edge &e = adj[u][i], &r = adj[e.dst][e.rev];
				if (e.capacity > e.flow && level[u] < level[e.dst]) {
					flow_type f = augment(e.dst, min(cur, e.capacity - e.flow));
					if (f > 0) {
						e.flow += f;
						r.flow -= f;
						return f;
					}
				}
			}
			return flow_type(0);
		};
		for (int u = 0; u < n; ++u) // initialize
			for (auto &e : adj[u]) e.flow = 0;

		flow_type flow = 0;
		while (levelize() >= 0) {
			fill(all(iter), 0);
			for (flow_type f; (f = augment(s, INF)) > 0; )
				flow += f;
		}
		return flow;
	}
};

int main() {
	cin >> N;
	vector<pair<ll,ll>> rb(2*N);
	for (int i = 0; i < 2 * N; i++) {
		cin >> A >> B;
		rb[i] = { A,B };
	}
	graph g(2 * N+2);
	for (int i = 0; i < N; i++) {
		for (int j = N; j < 2 * N; j++) {
			if (rb[i].first < rb[j].first&&rb[i].second < rb[j].second) {
				g.add_edge(i, j, 1);
			}
		}
	}
	for (int i = 0; i < 2 * N; i++) {
		if(i<N)g.add_edge(2 * N, i, 1);
		else  g.add_edge(i, 2 * N + 1, 1);
	}
	cout << g.max_flow(2*N, 2 * N + 1) << endl;
}

