bool fnd(int x,int n) {
    for(int j=1;j<=n;j++) {
        if (ccc[x][j]&&!bbb[j]) {
            bbb[j]=true;
            if (aaa[j]==0 || fnd(aaa[j],n)) {
                aaa[j]=x;
                return true;
            }
        }
    }
    return false;
