  }
  for (int i = 0; i < N; i++)
  {
    cin >> c >> d;
    B.at(i) = make_pair(c, d);
  }
  vector<vector<bool>> Grid(N, vector<bool>(N, false));
  vector<int64_t> cntA(N, 0), cntB(N, 0);
  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j < N; j++)
    {
      if (A.at(i).first < B.at(j).first && A.at(i).second < B.at(j).second)
      {
        Grid.at(i).at(j) = true;
        cntA.at(i)++;
        cntB.at(j)++;
      }
    }
  }
  int64_t INF = 100000000;
  vector<vector<int64_t>> Points(N, vector<int64_t>(N, 0));
  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j < N; j++)
    {
      if (Grid.at(i).at(j))
      {
        Points.at(i).at(j) = cntA.at(i) + cntB.at(j) - 1;
      }
      else
      {
        Points.at(i).at(j) = INF;
      }
    }
  }
  int64_t cnt = 0;
  while (true)
  {
    int minp = INF, mini = INF, minj = INF;
    for (int i = 0; i < N; i++)
    {
      for (int j = 0; j < N; j++)
      {
        if (Points.at(i).at(j) == -1)
          break;
        if (Points.at(i).at(j) == INF)
          continue;
        if (Points.at(i).at(j) < minp)
        {
          minp = Points.at(i).at(j);
          mini = i;
          minj = j;
        }
      }
    }
    if (mini == INF)
      break;
    cnt++;
    for (int i = 0; i < N; i++)
    {
      Points.at(i).at(minj) = INF;
      Points.at(mini).at(i) = -1;
    }
    mini = INF;
    minj = INF;
  }
  cout << cnt << endl;
}

