int f(vector<vector<int>> const& cs, int i, vector<bool>& used) {
    if (cs.size() == i) return 0;
    if (cs[i].empty()) return 0;
    int max = 0;
    for (auto j: cs[i]) {
        if (used[j]) {
            continue;
        }
        used[j] = true;
        int n = f(cs, i+1, used);
        used[j] = false;
        if (n > max) {
            max = n + 1;
        }
    }
    return max;
}

