        G.add_edge(0, i + 1, 1);
    }
    for (i = 0; i < N; i++) {
        cin >> C[i] >> D[i];
        G.add_edge(N+i+1, 2*N+1, 1);
    }
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            if (A[i] < C[j] && B[i] < D[j]) G.add_edge(i + 1, N + j + 1, 1);
        }
    }
    FordFulkerson<ll> F;
    co(F.max_flow(G, 0, 2*N+1));
}

