        red_ys.push_back(in());
    }
    rep(i, n)
    {
        blue_xs.push_back(in());
        blue_ys.push_back(in());
    }
    int ans = 0;
    rep(i, 2)
    {
        rep(j, 2)
        {
            if (i == 0)
            {
                sort2vectors(red_xs, red_ys);
                sort2vectors(red_ys, red_xs);
            }
            else
            {
                sort2vectors(red_ys, red_xs);
                sort2vectors(red_xs, red_ys);
            }
            if (j == 0)
            {
                sort2vectors(blue_xs, blue_ys);
                sort2vectors(blue_ys, blue_xs);
            }
            else
            {
                sort2vectors(blue_ys, blue_xs);
                sort2vectors(blue_xs, blue_ys);
            }
            reverse(all(blue_xs));
