                for (int k = bxs.size() - 1; k >= 0; k--)
                {
                    if (rxs.back() < bxs[k] && rys.back() < bys[k])
                    {
                        rxs.pop_back();
                        rys.pop_back();
                        bxs.erase(bxs.begin() + k);
                        bys.erase(bys.begin() + k);
                        cnt++;
                        break;
                    }
                    if (k == 0)
                    {
                        rxs.pop_back();
                        rys.pop_back();
                    }
                }
