struct Edge {
  int to, cap, rev;
  Edge(int to, int cap, int rev) : to(to), cap(cap), rev(rev) {}
};

const int maxv = 205;
vector<Edge> G[maxv];
bool used[maxv];

void add_edge(int from, int to, int cap) {
    G[from].eb((Edge){ to, cap, sz(G[to])});
    G[to].eb((Edge){ from, 0, sz(G[from]) - 1});
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    used[v] = 1;
    for (Edge &e : G[v]) {
        if (!used[e.to] && e.cap != 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d != 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (1) {
        memset(used, 0, sizeof(used));
        int f = dfs(s, t, inf);
        if (f == 0) return flow;
        flow += f;
    }
}

