    int NUM_MEN = N, NUM_WOMEN = N;

    // グラフの定義 (ノード数を引数に)
    Graph G(2 * N + 2);

    // スーパーノード S, T の index
    int S_node = 2 * N;
    int T_node = 2 * N + 1;

    // グラフに枝を張っていく
    for (int i = 0; i < N; ++i) {
