struct coordinate {
    int x, y;

    coordinate(int x, int y) : x(x), y(y) {}

    bool operator==(const coordinate& a) const
    {
        return this->x == a.x && this->y == a.y;
    }

    bool operator<(const coordinate& a) const
    {
        return this->x < a.x || (this->x == a.x && this->y > a.y);
    }

    bool operator>(const coordinate& a) const
    {
        return this->x > a.x || (this->x == a.x && this->y < a.y);
    }

    bool operator<=(const coordinate& a) const
    {
        return *this == a || *this < a;
    }

    bool operator>=(const coordinate& a) const
    {
        return *this == a || *this > a;
    }
};

