    red_points.reserve(n);
    blue_points.reserve(n);
    for(int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;
        red_points.emplace_back(x, y);
    }
    std::sort(
        red_points.begin(), red_points.end(),
        [](const std::pair<int, int>& p, const std::pair<int, int>& q) {
            return p.second > q.second;
        }
    );
    for(int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;
        blue_points.emplace_back(x, y);
    }
    std::sort(
        blue_points.begin(), blue_points.end(),
        [](const std::pair<int, int>& p, const std::pair<int, int>& q) {
            return p.first < q.first;
        }
    );
    int ans = 0;
    for(const auto& blue_point : blue_points) {
        for(auto red_itr = red_points.begin(), red_end = red_points.end(); red_itr != red_end; ++red_itr) {
            if(red_itr->first < blue_point.first && red_itr->second < blue_point.second) {
                ans++;
                red_points.erase(red_itr);
                break;
            }
        }
    }
    std::cout << ans << std::endl;
}

