int main(void) {
  ios::sync_with_stdio(false);
  int N;
  cin >> N;

  list<pair<int, int>> red;
  rep(i, N) {
    int a, b;
    cin >> a >> b;
    red.push_back(make_pair(a, b));
  }
  red.sort();

  list<pair<int, int>> blue;
  rep(i, N) {
    int c, d;
    cin >> c >> d;
    blue.push_back(make_pair(c, d));
  }
  blue.sort();

  int Ans = 0;
  for (auto itr_b = blue.begin(); itr_b != blue.end(); ++itr_b) {
    auto &b = *itr_b;

    int r_y_max = -1;
    auto r_max = red.begin();
    bool flag = false;
    for (auto itr_r = red.begin(); itr_r != red.end(); ++itr_r) {
