struct p {
    int a;
    int b;
    bool isPaird = false;

    bool operator<(const p &another) const {
        if (b == another.b)
            return a < another.a;
        else
            return b < another.b;
    };
};

int main() {
    int N;
    cin >> N;
    vector<p> A(N);
    vector<p> B(N);
    rep(i, N) cin >> A[i].a >> A[i].b;
    rep(i, N) cin >> B[i].a >> B[i].b;
    sort(all(A));
    sort(all(B));

    int ans = 0;
    rep(i, N) {
        int a     = B[i].a;
        int b     = B[i].b;
        int ymax  = -1;
        int ymaxi = -1;
        rep(j, N) {
            if(A[j].isPaird) continue;
            if (A[j].a < a && A[j].b < b) {
                if (A[j].b > ymax) {
                    ymax  = A[j].b;
                    ymaxi = j;
                }
            }
        }
        if(ymax>=0){
          B[i].isPaird = true;
          A[ymaxi].isPaird = true;
          ans++;
        }
    }
    cout << ans << endl;
}

