using namespace std;

int main() {
    int N;
    cin >> N;

    vector<pair<int, int> > red, blue;
    for (int i = 0; i < N; ++i) {
        int a, b;
        cin >> a >> b;

        red.emplace_back(make_pair(a, b));
    }
    sort(red.begin(), red.end(), greater<pair<int, int> >());

    for (int i = 0; i < N; ++i) {
        int c, d;
        cin >> c >> d;

        blue.emplace_back(make_pair(c, d));
    }
    sort(blue.begin(), blue.end(), greater<pair<int, int> >());

    int ans = 0;
    for (int i = 0; i < red.size(); ++i) { // red ith element
        int min_dist = 114514100;
        int min_index = -1;
        for (int j = 0; j < blue.size(); ++j) {
            if (red[i].first >= blue[j].first || red[i].second >= blue[j].second) {
                continue;
            }

            if (min_dist >= (red[i].first - blue[j].first) * (red[i].first - blue[j].first) +
                            (red[i].second - blue[j].second) * (red[i].second - blue[j].second)) {
                min_dist = (red[i].first - blue[j].first) * (red[i].first - blue[j].first) +
                           (red[i].second - blue[j].second) * (red[i].second - blue[j].second);
                min_index = j;
            }
        }

        if (min_index != -1) {
            ans++;
            blue.erase(blue.begin() + min_index);
            red.erase(red.begin() + i);
            i = -1;
        }
    }

    cout << ans << endl;
}

