	sort( b , b + n , cmp );
	for( int i = n - 1 ; i >= 0 ; i-- ){
		for( int j = 0 ; j < n ; j++ ){
			if( mpb[j] ) continue;
			if( mpa[i] ) break;
			if( a[i].x < b[j].x && a[i].y < b[j].y ){
				res ++ ;
				mpa[i] = 1;
				mpb[j] = 1;
			}
		}
	}

	int ibest = res ;
	res = 0;
	sort( a , a + n , cmp2 );
	sort( b , b + n , cmp2 );
	mpa.clear();
	mpb.clear();
	for( int i = n - 1 ; i >= 0 ; i-- ){
		for( int j = 0 ; j < n ; j++ ){
			if( mpb[j] ) continue;
			if( mpa[i] ) break;
			if( a[i].x < b[j].x && a[i].y < b[j].y ){
				res ++ ;
				mpa[i] = 1;
				mpb[j] = 1;
			}
		}
	}
	ibest = max( res , ibest );
	cout << ibest << endl;
	return 0 ;
}

