template<typename T>
struct FordFulkerson {
	//辺
	struct edge
	{
		//行先と逆辺、revはid参照されているので、
		//追加された順に1,2,3,...となっている
		int to, rev;
		//cap は capacityの略
		T cap;
		edge(int to, T cap, int rev) :to(to), cap(cap), rev(rev) {};
	};

	const T INF;
	int timestamp;

	//グラフと探索済みかの配列
	vector<vector<edge>> graph;
	vector<int> used;

	FordFulkerson(int n) :INF(numeric_limits<T>::max()), timestamp(0) {
		graph.resize(n);
		used.assign(n, -1);
	}

	void add_edge(int from, int to, T cap) {
		//from ~ toにcapの辺を通す
		graph[from].emplace_back(to, cap, int(graph[to].size()));
		//to~from　に0容量の辺を通す
		graph[to].emplace_back(from, 0, int(graph[from].size()) - 1);
	}

	//ただのdfs探索
	//これは一本のパスについてflowを返していく
	T dfs(int v, const int t, T flow) {
		//終了地点にきたらflowを返す
		if (v == t) return flow;
		//探索済み
		used[v] = timestamp;

		for (auto& e : graph[v]) {
			//流す余地があって未探索
			if (e.cap > 0 and used[e.to] != timestamp) {
				//このノード以降のフローを求める
				T d = dfs(e.to, t, min(flow, e.cap));
				if (d > 0) {
					e.cap -= d;
					graph[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		//ここにたどり着くのは増加パスがない時
		return 0;
	}

	T max_flow(int s, int t) {
		T flow = 0;
		while (1) {
			//これは2回目の探索ならused[v]=1で2回目の探索、となっている。
			T f = dfs(s, t, INF);
			//cout << f << endl;
			//増加する限り続行
			if (f == 0) return flow;
			flow += f;
			timestamp++;
		}
	}
};

int main() {
	cin >> N;
	FordFulkerson<ll> ff(2 * N + 2);
	for (int i = 1; i <= N; i++) {
		cin >> a[i] >> b[i];
		ff.add_edge(0, i, 1);
	}
	for (int i = 1; i <= N; i++) {
		cin >> c[i] >> d[i];
		ff.add_edge(i + N, 2 * N + 1, 1);
	}
	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			if (a[i] < c[j] && b[i] < d[j])ff.add_edge(i, j + N, 1);
		}
	}
	cout << ff.max_flow(0, 2 * N + 1) << endl;
	return 0;
}

