struct Coor{
    int x;
    int y;
};

bool comp_x(const Coor &a, const Coor &b) {
    if(a.x!=b.x) return a.x < b.x;
    else return a.y < b.y;
}

bool comp_y(const Coor &a, const Coor &b) {
    if(a.y!=b.y) return a.y < b.y;
    else return a.x < b.x;
}

int main() {
    int n;
    cin >> n;
    vector<Coor> red(n), blue(n);
    for(int i=0; i<n; i++) {
        int a, b;
        cin >> a >> b;
        red[i].x = a;
        red[i].y = b;
    }
    for(int i=0; i<n; i++) {
        int a, b;
        cin >> a >> b;
        blue[i].x = a;
        blue[i].y = b;
    }

    sort(red.begin(), red.end(), comp_x);
    sort(blue.begin(), blue.end(), comp_y);

    bool used[n];
    for(int i=0; i<n; i++) used[i] = false;

    int cnt=0, i=0, j=0;
    while(i<n) {
        j=0;
        while(j<n && (red[i].x>=blue[j].x || red[i].y>=blue[j].y || used[j])) {
            j++;
        }
        if(j<n && !(used[j])) {
            used[j]=true;
            cnt++;
        }
        i++;
    }
    cout << cnt << endl;


    return 0;
}

