{
    scanf("%d", &N);
    for(int i = 0; i < N; ++i) scanf("%d %d", &a[i], &b[i]);
    for(int i = 0; i < N; ++i) scanf("%d %d", &c[i], &d[i]);

    for(int i = 0; i < N; ++i) {
        candidate_num[i].second = i;
        for(int j = 0; j < N; ++j) {
            if(a[j] < c[i] && b[j] < d[i]) {
                ++candidate_num[i].first;
                candidate[i].push_back(j);
            }
        }
    }
    sort(candidate_num, candidate_num + N);
    int res = 0;
    for(const auto &p : candidate_num) {
        for(const auto &q : candidate[p.second]) {
            if(!visited[q]) {
                visited[q] = true; ++res;
                break;
            }
        }
    }
    printf("%d\n", res);
    return 0;
