#define N 100

int board[2*N][2*N] = {0};

bool search( int x, int y )
{
	for( int i = x + 1; i < 2*N; i++ ) {
		for( int j = y + 1; j < 2*N; j++ ) {
			if( board[i][j] < 0 ) {
				board[i][j] = 0;
				return true;
			}
		}
	}
	return false;
}

int main()
{
	int n;
	int a, b, c, d;
	int ans = 0;

	cin >> n;

	for( int i = 1; i <= n; i++ ) {
		cin >> a >> b;
		board[a][b] = i;
	}
	for( int i = 1; i <= n; i++ ) {
		cin >> c >> d;
		board[c][d] = -i;
	}

	for( int w = 2*n - 1; w >= 0; w-- ) {
		for( int i = 0; i <= w; i++ ) {
			if( board[w - i][w] > 0 ) {
				bool b = search( w - i, w );
				if( b == true ) {
					ans++;
					board[w - i][w] = 0;
				}
			}
			if( i == 0 ) {
				continue;
			}
			if( board[w][w - i] > 0 ) {
				bool b = search( w, w - i );
				if( b == true ) {
					ans++;
					board[w][w - i] = 0;
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

