        int a, b;
        cin >> a >> b;
        reds[i] = {a, b};
    }
    sort(reds.begin(), reds.end());

    vector<pair<int, int>> blues(N);
    for (int i = 0; i < N; i++) {
        int a, b;
        cin >> a >> b;
        blues[i] = {a, b};
