    for (int ri = 0; ri < N; ri++) {
        for (int bi = 0; bi < N; bi++) {
            auto red = reds[ri];
            auto blue = blues[bi];
            if (red.first < blue.first && red.second < blue.second) {
                counter[bi]++;
            }
        }
