lint gcd(lint a, lint b) {
    lint r;
    while (b != 0) {
        r = a % b;
        a = b; 
        b = r;
    }
    return a;
}

lint lcm(lint a, lint b) {
    return (a / gcd(a, b)) * b;
}

lint power(lint x, lint n, lint mod = MOD) {
    lint ret = 1;
    while(n > 0) {
        if(n & 1){
            (ret *= x) %= mod;
        }
        (x *= x) %= mod;
        n >>= 1;
    }
    return ret;
}

vector<lint> make_power(int n, lint base){
    lint num = 1;
    vector<lint> ret;
    for (int i=0; i<=n; ++i){
        ret.push_back(num);
        num *= base;
    }
    return ret;
}

bool ps(pair<int, set<int>> p1, pair<int, set<int>> p2){
    if(p1.snd.size() == p2.snd.size()){
        return p1.fst < p2.fst;
    }
    return p1.snd.size() < p2.snd.size();
}

int main()
{
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<pint> red(n);
    vector<pint> blue(n);
    REP(i, n){
        cin >> red[i].fst >> red[i].snd;
    }
    REP(i, n){
        cin >> blue[i].fst >> blue[i].snd;
    }
    vector<pair<int, set<int>>> p(n);
    vector<int> cnt(n, 0);
    REP(i, n){
        p[i].fst = i;
        REP(j, n){
            if(red[j].fst < blue[i].fst && red[j].snd < blue[i].snd){
                p[i].snd.insert(j);
                cnt[j]++;
            }
        }
    }
    vector<int> used_red(n, 0);
    vector<int> used_blue(n, 0);
    int ans = 0;
    REP(i, 2*n){
        sort(ALL(p), ps);
        int b = -1;
        REP(j, p.size()){
            if(p[j].snd.size() >= 1){
                b = j;
                break;
            }
        }
        //debug(b);
        int rest = n+1;
        int nr = -1;
        if(b == -1){break;}
        for (auto r : p[b].snd){
            if(used_red[r] == 0 && used_blue[b] == 0){
                if(rest > cnt[r]){
                    rest = cnt[r];
                    nr = r;
                }
            }
        }
        if(nr != -1){
            ans++;
            used_red[nr]++;
            used_blue[b]++;
            cnt[nr]--;
            //debugpair(nr, b);
            REP(j, p.size()){
                p[j].snd.erase(nr);
            }
        }
        else {
            p[b].snd.clear();
        }
    }
    cout << ans << endl;
    return 0;
}

