const ll INFLL=1e+17;
struct edge{
  int to,cap,rev;
};
vector<edge> g[200000];
bool used[200000];

void add_edge(int from,int to){
  edge e;
  e.to=to;e.cap=1;e.rev=g[to].size();
  g[from].push_back(e);
  e.to=from;e.cap=0;e.rev=g[from].size()-1;
  g[to].push_back(e);
}

int dfs(int v,int t,int f){
  if(v==t) return f;
  used[v]=true;
  rep(i,g[v].size()){
    edge &e=g[v][i];
    if(e.cap>0&&!used[e.to]){
      int d=dfs(e.to,t,min(f,e.cap));
      if(d>0){
	e.cap-=d;
	g[e.to][e.rev].cap+=d;
	return d;
      }
    }
  }
  return 0;
}

int max_flow(int s,int t){
  int flow=0;
  while(1){
    fill(used,0);
    int f=dfs(s,t,INF);
    if(f==0) return flow;
    flow+=f;
  }
}
