		a.push_back({x, y});
	}
	for(int i = 0; i < n; i++){
		int x, y;
		cin >> x >> y;
		b.push_back({x, y});
	}
	int ans = 0;
	auto x_sorter = [](point a, point b) -> bool {
		return a.first < b.first;
	};
//	auto y_sorter = [](point a, point b) -> bool {
//		return a.second < b.second;
//	};
	// a, b を x座標で昇順にソート
