    rep(i, N) rep(j, N) {
        if(red[i].first < blue[j].first && red[i].second < blue[j].second) g.add_edge(i, N+j, 1);
    }

    ll s = 2*N, t = 2*N+1;
    rep(i, N) g.add_edge(s, i, 1), g.add_edge(N+i, t, 1);

    FordFulkerson<ll> ff;
    ll ans = ff.max_flow(g, s, t);
    cout << ans << endl;
}

