  for (int i = 0; i < N; i++)
  {
    cin >> a >> b;
    A.push(make_pair(a, b));
  }
  for (int i = 0; i < N; i++)
  {
    cin >> c >> d;
    B.push(make_pair(c, d));
  }
  priority_queue<pair<int, int>> pqa;
  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pqb;
  for (int x = 1; x < 2 * N; x++)
  {
    while (!B.empty() && B.top().first <= x)
    {
      pqb.emplace(B.top());
      B.pop();
    }
    while (!A.empty() && A.top().first < x)
    {
      pqa.emplace(A.top());
      A.pop();
    }
    if (pqa.empty() || pqb.empty())
      continue;
    queue<pair<int, int>> tmp;
    while (!pqa.empty())
    {
      if (pqa.top().second < pqb.top().second && pqa.top().first < pqb.top().first)
      {
        pqa.pop();
        ans++;
        break;
      }
      else
      {
        tmp.push(pqa.top());
        pqa.pop();
      }
    }
    pqb.pop();
    while (!tmp.empty())
    {
      pqa.push(tmp.front());
      tmp.pop();
    }
  }
