  for(ll i=0;i<n;i++){
    for(ll j=0;j<n;j++){
      if((a[i].a<b[j].a)&&(a[i].b<b[j].b)){
        D.add_edge(1+i,1+n+j,1);
      }
    }
  }
  for(ll i=0;i<n;i++){
    D.add_edge(0,1+i,1);
  }
  for(ll i=0;i<n;i++){
    D.add_edge(1+n+i,n*2+1,1);
  }
  ans=D.max_flow(0,n*2+1);
  cout<<ans<<endl;
}

