#include <bits/stdc++.h> 
using namespace std;
typedef long long ll;
typedef pair<int,int> Pint;
typedef pair<ll, ll> P;
#define INF 1e9 //10^9
#define MOD 1000000007
#define INFL 100000000000000000//10^18 = 2^60


#define MAX_V 1000010

struct edge {
    int to, cap, rev;
};

vector<vector<edge>> G(MAX_V);
bool used[MAX_V];


void add_edge(int from, int to, int cap){
    edge F;
    edge T;
    F.to = to;
    F.cap = cap;
    F.rev = G[to].size();
    G[from].push_back(F);

    T.to = from;
    T.cap = 0;
    T.rev = G[from].size() - 1;
    G[to].push_back(T);
}

int dfs(int v, int t, int f){
    if(v == t) return f;
    used[v] = true;
    for(int i = 0; i < G[v].size(); i++){
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0){
            int d = dfs(e.to, t, min(f, e.cap));
            if(d > 0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t){
    int flow = 0;
    while(1){
        memset(used, 0, sizeof(used));
        int f = dfs(s, t, INF);
        if(f == 0) return flow;
        flow += f;
    }
}


int main(void){
    int N;
    cin >> N;

    vector<pair<int, int>> R(N), B(N);

    for(int i = 0; i < N; i++) cin >> R[i].first >> R[i].second;
    for(int i = 0; i < N; i++) cin >> B[i].first >> B[i].second;

    int s = N * 2, t = N * 2 + 1;

    for(int i = 0; i < N; i++){
        add_edge(s, i, 1);
        add_edge(i + N, t, 1);
    }

    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            if(R[i].first < B[j].first && R[i].second < B[j].second){
                add_edge(i, j + N, 1);
            }
        }
    }

    cout << max_flow(s, t) << endl;

}

