const int MAX_V = 1000;
struct edge{int end,cap,rev;};
vector<edge> G[MAX_V];
int level[MAX_V];
int iter[MAX_V];


void Dinic_add_edge(int from,int end,int cap){
    G[from].push_back((edge){end,cap,(int)G[end].size()});
    G[end].push_back((edge){from,0,(int)G[from].size()-1});
}

void Dinic_bfs(int s){
    memset(level,-1,sizeof(level));
    queue<int> que;
    level[s]=0;
    que.push(s);
    while(!que.empty()){
        int v=que.front();
        que.pop();
        for(int i=0;i<G[v].size();i++){
            edge &e = G[v][i];
            if(e.cap>0 && level[e.end]<0){
                level[e.end]=level[v]+1;
                que.push(e.end);
            }
        }
    }
}

int Dinic_dfs(int v,int t,int f){
    if(v==t)return f;
    for(int &i=iter[v];i<G[v].size();i++){
        edge &e = G[v][i];
        if(e.cap>0 && level[v]<level[e.end]){
            int d = Dinic_dfs(e.end,t,min(f,e.cap));
            if(d>0){
                e.cap -= d;
                G[e.end][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

int Dinic(int s,int t){
    int flow=0;
    while(1){
        Dinic_bfs(s);
        if(level[t]<0){return flow;}
        memset(iter,0,sizeof(iter));
        int f;
        while((f=Dinic_dfs(s,t,INF))>0){
            flow+=f;
        }
    }
}

