#define swap(x,y) {int tp; tp=x; x=y; y=tp;}

void sort(int *a,int *b, int N){
  int i,j,tmp,norm;
  for(i=0; i<N; i++){
    norm = a[i]+b[i];
    tmp = i;
    for(j=i; j<N; j++){
      if(norm<a[j]+b[j]){
        norm = a[j]+b[j];
        tmp = j;
      }
    }
    swap(a[i],a[tmp]);
    swap(b[i],b[tmp]);
  }
}

