        R[i] = make_pair(a, b);
    }
    for(int i = 0; i < N; i++){
        int a, b;
        cin >> a >> b;
        B[i] = make_pair(a, b);
    }
    int NUM_MEN = N, NUM_WOMEN = N;

    // グラフの定義 (ノード数を引数に)
    Graph G(2 * N + 2);

    // スーパーノード S, T の index
    int S_node = 2 * N;
    int T_node = 2 * N + 1;

    // グラフに枝を張っていく
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (R[i].first < B[j].first && R[i].second < B[j].second) {
                G.addedge(i, j + N, 1);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        // S から男 i へと、容量 1 の枝を張る
        G.addedge(S_node, i, 1);
    }

    for (int j = 0; j < N; ++j) {
        // 女 j から T へと、容量 1 の枝を張る
        G.addedge(j + N, T_node, 1);
    }

    // 最大流を求める
    FLOW res = Dinic(G, S_node, T_node);

    cout << res << endl;
    return 0;
}

