struct Graph{
	int V; // 0-ind
	vector<vector<int>> adj;
	vector<bool> r; // reached
	vector<int> dis; // struct内に置く
	Graph(int _V) {
		V = _V;
		adj = vector<vector<int>>(V);
		r = vector<bool>(V);
		dis = vector<int>(V);
	}
	void add_edge(int u, int v) { // u-v (indirected)
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	// 連結成分ごとに，番号の最も若い頂点からの距離を求めるBFS(struct内に置く)
	void bfs_dis(int s) {
		dis[s] = 0; // 値と到達フラグを分ける
		queue<int> q; q.push(s); r[s] = true;
		while (!q.empty()) {
			int u = q.front(); q.pop();
			for (int v : adj[u]) {
				if (r[v]) continue;
				q.push(v); r[v] = true;
				dis[v] = dis[u] + 1;
			}
		}
	}
	void bfs_dis() {
		r = vector<bool>(V, false); // 到達フラグ初期化
		dis = vector<int>(V, -1); // 距離初期化
		for (int s = 0; s < V; s++) {
			if (r[s]) continue;
			bfs_dis(s); // sを始点としてBFS
		}
	}
	bool is_bipartite(int s) {
		queue<int> q; q.push(s); r[s] = true;
		while (!q.empty()) {
			int u = q.front(); q.pop();
			for (int v : adj[u]) {
				if ((dis[v] - dis[u]) % 2 == 0) return false;
				if (!r[v]) {
					q.push(v); r[v] = true;
				}
			}
		}
		return true;
	}
	bool is_bipartite() {
		bfs_dis();
		r = vector<bool>(V, false);
		for (int s = 0; s < V; s++) {
			if (r[s]) continue;
			if (!is_bipartite(s)) return false;
		}
		return true;
	}
	// 色分け // 非連結な場合，色の組合せ方が複数あることに注意
	vector<vector<int>> parts() {
		assert(is_bipartite());
		vector<vector<int>> p(2);
		for (int i = 0; i < V; i++) {
			p[dis[i] % 2].push_back(i);
		}
		return p;
	}
	void show() {
		for (int i = 0; i < V; i++) {
			cout << i << ": { ";
			for (int j : adj[i]) cout << j << ", ";
			cout << "}" << endl;
		}
	}
	template <typename T> // #defineに移す
	void show(vector<T> &val) {
		cout << "{ ";
		for (int i = 0; i < val.size(); i++) cout << val[i] << ", ";
		cout << "}" << endl;
	}
};

// graphは前半と後半に分かれた二部グラフ 
int bip_max_matching(Graph &graph, int N1, int N2) {
	assert(N1 + N2 == graph.V);
	assert(graph.is_bipartite());
	mf_graph<int> g(N1 + N2 + 2); // s=N1+N2->u in[0,N1)->v in[N1,N1+N2)->t=N1+N2+1
	for (int u = 0; u < N1; u++) g.add_edge(N1 + N2, u, 1);
	for (int u = 0; u < N1; u++) for (int v : graph.adj[u]) g.add_edge(u, v, 1);
	for (int v = N1; v < N1 + N2; v++) g.add_edge(v, N1 + N2 + 1, 1);
	return g.flow(N1 + N2, N1 + N2 + 1);
}

int main() {
	// 0-ind
	int N; cin >> N;
	vector<pair<int, int>> r(N), b(N);
	rep(i, N) cin >> r[i].first >> r[i].second;
	rep(i, N) cin >> b[i].first >> b[i].second;
	Graph g(2 * N);
	rep(i, N) rep(j, N) if (r[i].first < b[j].first and r[i].second < b[j].second) g.add_edge(i, N + j);
	cout << bip_max_matching(g, N, N) << endl;
}

