struct Edge {
    ll rev, from, to;
    ll cap, original_cap;
    Edge(ll r, ll f, ll t, ll c) : rev(r), from(f), to(t), cap(c), original_cap(c) {};
};

struct Graph {
    vector<vector<Edge>> g;
    Graph(ll n) { g = vector<vector<Edge>>(n); };
    vector<Edge>& operator[](ll i) { return g[i]; }
    size_t size() {return g.size(); }
    Edge& redge(Edge e) {
        return g[e.to][e.rev];
    }
    void add_edge(ll from, ll to, ll cap) {
        g[from].push_back(Edge(g[to].size(), from, to, cap));
        g[to].push_back(Edge(g[from].size() - 1, to, from, 0));
    }
};

struct FordFulkerson {
    vector<bool> used;
    Graph& G;
    FordFulkerson(Graph& g) : G(g) {};
    ll dfs(ll v, ll t, ll f) {
        if(v == t) return f;
        used[v] = true;
        for(auto& e : G[v]) {
            if(used[e.to] || e.cap <= 0) continue;
            ll d = dfs(e.to, t, min(f, e.cap));
            if(d <= 0) continue;
            e.cap -= d;
            G.redge(e).cap += d;
            return d;
        }
        return 0;
    }
    ll max_flow(ll s, ll t) {
        ll flow = 0;
        while(true) {
            used.assign(G.size(), false);
            ll f = dfs(s, t, INFL);
            if(f == 0) return flow;
            else flow += f;
        }
        return 0;
    }
};

