    Graph g(2 * n + 2);
    for(ll i = 1; i <= n; i++) {
        g.add_edge(0, i, 1);
        g.add_edge(n + i, 2 * n + 1, 1);
    }
    for(ll i = 0; i < n; i++) {
        for(ll j = 0; j < n; j++) {
            if(red[i].first < blue[j].first && red[i].second < blue[j].second) {
                g.add_edge(i + 1, j + n + 1, 1);
            }
        }
    }
    FordFulkerson f(g);
    cout << f.max_flow(0, 2 * n + 1) << endl;
    return;
}

