const int MAX_DIFF = (int)114514;
const int MAX_N = (int)100 + 5;

struct point {
  int x, y;
};

int canddt[MAX_N][MAX_N];
vector<point> red, blue;
int n;

bool reddid[MAX_N];

int ans;

int mhtdiff(point red, point blue) {
  return blue.y - red.y + blue.x - red.x;
}

int main(void){
  scanf("%d", &n);

  for (int i = 0; i < n; ++i) {
    point tmppoint;
    int tmpx, tmpy;
    scanf("%d %d", &tmpx, &tmpy);
    tmppoint.x = tmpx;
    tmppoint.y = tmpy;
    red.push_back(tmppoint);
  }

  for (int i = 0; i < n; ++i) {
    point tmppoint;
    int tmpx, tmpy;
    scanf("%d %d", &tmpx, &tmpy);
    tmppoint.x = tmpx;
    tmppoint.y = tmpy;
    blue.push_back(tmppoint);
  }

  fill((int*)(canddt), (int*)(canddt + MAX_N), -1);

  for (int i = 0; i < n; ++i) {
    point cred = red[i];
    for (int j = 0; j < n; ++j) {
      point cblue = blue[j];
      if ((cred.x < cblue.x) && (cred.y < cblue.y)) {
        canddt[i][j] = mhtdiff(cred, cblue);
      }
    }
  }

  fill(reddid, reddid + MAX_N, false);

  for (int j = 0; j < n; ++j) {
    point cblue = blue[j];

    int nrstdiff = MAX_DIFF;
    int nrstrpi = -1;

    // find nearest point for current blue
    for (int i = 0; i < n; ++i) {
      if (reddid[i]) continue;

      point cred = red[i];

      if (canddt[i][j] != -1 && canddt[i][j] < nrstdiff) {
        nrstdiff = canddt[i][j];
        nrstrpi = i;
      }
    }

    if (nrstdiff != MAX_DIFF) {
      // delete
      reddid[nrstrpi] = true;
      // cout << red[nrstrpi].x << cblue.x << red[nrstrpi].y << cblue.y << endl;
      ans += 1;
    }
  }

  printf("%d\n", ans);
  return 0;
}

