void solve(){
    int n;
    cin >> n;
    vector<P> red(n), blue(n);
    rp(i,n) cin >> red[i].first >> red[i].second;
    rp(i,n) cin >> blue[i].first >> blue[i].second;
    vector<set<int>> pos(n);
    vi num(n);
    rp(i,n){
        rp(j,n){
            if(red[i].first<blue[j].first&&red[i].second<blue[j].second)
            pos[i].insert(j);
            num[j]++;
        }
    }
    vi sizes(n);
    rp(i,n){
        int si=pos[i].size();
        sizes[i]=si;
    }
    int ctr=0;
    while(1){
        int rem;
        int min_size=1<<10;
        int turn=-1;
        rp(i,n){
            if(sizes[i]<=0) continue;
            if(chmin(min_size,sizes[i])) turn=i;
        }
        if(turn==-1) break;
        ctr++;
        auto it=pos[turn].begin();
        int m=1000;
        while(it!=pos[turn].end()){
            if(chmin(m,num[*it])) rem=*it;
            it++;
        }
        it=pos[turn].begin();
        while(it!=pos[turn].end()){
            num[*it]--;
            it++;
        }
        pos[turn].clear();
        sizes[turn]=0;
        rp(i,n){
            if(pos[i].count(rem)){
                pos[i].erase(rem);
                sizes[i]--;
            }
        }
    }
    print(ctr);
    return;
}
int main(){
    cin.tie(0);ios::sync_with_stdio(false);
    std::cout<<std::fixed<<std::setprecision(30);
    solve();
    return 0;
}

