    cin >> x >> y;
    b[i] = P(x, y);
  }
  vector<vector<int>> to(N * 2);
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      int d = cmp(r[j], b[i]);
      if (d) {
        to[i].push_back(j + N);
        to[j + N].push_back(i);
      }
    }
  }
  vector<int> used(N * 2);
