      bcnt++;
    } else {
      rcnt++;
    }
    for (auto& u : to[v]) {
      dfs(u, v);
    }
  };
  dump(to);
  int ans = 0;
  for (int i = 0; i < N; i++) {
    bcnt = 0;
    rcnt = 0;
    dfs(i, -1);
    ans += min(rcnt, bcnt);
    dump(bcnt, rcnt, ans);
  }
  cout << ans << endl;

  return 0;
}

