    sort(all(bsort));

    for(int i=0;i<N+M;i++){
        asort[i].first=i+1;
        bsort[i].first=i+1;

        if(asort[i].second<N) X[asort[i].second].first=asort[i].first;
        else Y[asort[i].second-N].first=asort[i].first;

        if(bsort[i].second<N) X[bsort[i].second].second=bsort[i].first;
        else Y[bsort[i].second-N].second=bsort[i].first;
    }

    sort(all(X),compare);

    init(N+M);

    for(int i=0;i<M;i++){
        update(Y[i].first,Y[i].second);
    }

    int ans=0;

    for(int q=0;q<N;q++){
        if(query(X[q].first,n+1,0,0,n)<X[q].second) continue;
        int left=X[q].first,right=N+M;
        while(right-left>1){
            int mid=(left+right)/2;
            if(query(X[q].first,mid+1,0,0,n)<X[q].second) left=mid;
            else right=mid;
        }
        ans++;
        update(right,-INF);
