int n,ax[200],ay[200],bx[200],by[200],i,j;
bool bpm(bool bpGraph[200][200], int u, bool seen[], int matchR[])
{
    for (int v = 0; v < n; v++)
    {
        if (bpGraph[u][v] && !seen[v])
        {
            seen[v] = true;
            if (matchR[v] < 0 || bpm(bpGraph, matchR[v], seen, matchR))
            {
                matchR[v] = u;
                return true;
            }
        }
    }
    return false;
}
int maxBPM(bool bpGraph[200][200])
{
    int matchR[n];
    memset(matchR, -1, sizeof(matchR));
    int result = 0;
    for (int u = 0; u < n; u++)
    {
        bool seen[n];
        memset(seen, 0, sizeof(seen));
        if (bpm(bpGraph, u, seen, matchR))
            result++;
    }
    return result;
}
