using namespace std;

class bipartite_matching {
public:
    int n;
    vector<vector<int>> g;
    vector<int> match;

    bipartite_matching(int n_) : n(n_), g(n_), match(n_), used(n_) {}

    void add_edge(int u, int v) {
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int maximum_matching(void) {
        int res = 0;
        fill(begin(match), end(match), -1);
        for (int v = 0; v < n; ++v) {
            if (match[v] == -1) {
                fill(begin(used), end(used), false);
                if (dfs(v)) res++;
            }
        }
        return res;
    }

private:
    vector<int> used;
    bool dfs(int v) {
        used[v] = true;
        for (int u : g[v]) {
            int w = match[u];
            if (w == -1 || (!used[w] && dfs(w))) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        return false;
    }
};


int main(void) {
  int N; cin >> N;
  vector<pair<int, int>> R, B;
  for (int i = 0; i < N; i++) {
    int xi, yi; cin >> xi >> yi;
    R.push_back(make_pair(xi, yi));
  }
  for (int i = 0; i < N; i++) {
    int xi, yi; cin >> xi >> yi;
    B.push_back(make_pair(xi, yi));
  }

  bipartite_matching bm(N);
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (R[i].first < B[j].first && R[i].second < B[j].second) {
        bm.add_edge(i, j);
      }
    }
  }
  cout << bm.maximum_matching() << endl;
}

