              [](const auto& a, const auto& b) {
                  return a.first < b.first;
              });

    int count = 0;
    for (auto&& b: B) {
        // bのx軸的相方候補検索
        std::vector<std::vector<Point>::iterator> candItrs;
        for (auto redItr = R.begin(); redItr != R.end(); ++redItr) {
            if (redItr->first < b.first) {
               candItrs.push_back(redItr);
            }
        }
        /*
