          Rはy軸降順にソートされているので、candsもy軸降順になっている
          最初に見つかった範囲内が相方
        */
        for (auto&& candItrsItr = candItrs.begin(); candItrsItr != candItrs.end(); ++candItrsItr) {
            if ((*candItrsItr)->second < b.second) {
                count++;
                R.erase(*candItrsItr);
                break;
            }
        }
    }

    std::cout << count << std::endl;

    return 0;
}

