	MM.resize(N, N);
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			if (a[i] < c[j] && b[i] < d[j])
				MM.add_edge(i, j);
		}
	}

	cout << MM.maximum_matching() << '\n';

	return 0;
}

