      if (A[i][0]<B[j][0] && A[i][1]<B[j][1]) {
        add_edge(i+1,j+N+1,1,g);
      }
    }
  }
  for (int i=0;i<N;i++) {
    add_edge(i+N+1,2*N+1,1,g);
  }
  cout << max_flow(0,2*N+1,g) << endl;
}

