struct BipartiteMatching
{
  vector<vector<int>> graph;
  vector<int> match, used;
  int timestamp;

  BipartiteMatching(int n) : graph(n), used(n, 0), match(n, -1), timestamp(0) {}

  void add_edge(int u, int v)
  {
    dump(u, v);
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int idx)
  {
    used[idx] = timestamp;
    for (auto& to : graph[idx]) {
      int to_match = match[to];
      dump(idx, to, to_match);
      if (to_match == -1 || (used[to_match] != timestamp && dfs(to_match))) {
        match[idx] = to;
        match[to] = idx;
        dump(match);
        return true;
      }
    }
    return false;
  }

  int bipartite_matching()
  {
    int ret = 0;
    for (int i = 0; i < graph.size(); i++) {
      if (match[i] == -1) {
        ++timestamp;
        ret += dfs(i);
        dump(timestamp, ret, match);
      }
    }
    return ret;
  }

  void output()
  {
    for (int i = 0; i < graph.size(); i++) {
      if (i < match[i]) {
        cout << i << "-" << match[i] << endl;
      }
    }
  }
};

int cmp(const P& a, const P& b)
{
  int dx = b.first - a.first;
  int dy = b.second - a.second;
  if (0 < dx && 0 < dy)
    return dx + dy;
  else
    return 0;
}

