		cin >> a >> b;
		red.push_back(make_pair(a, b));
	}

	Int c, d;
	for (Int i = 0; i < N; i++) {
		cin >> c >> d;
		blue.push_back(make_pair(c, d));
	}

	sort(red.begin(), red.end());
	sort(blue.begin(), blue.end());

	DMP(red, blue);

	vector<Int> seen(N);
	Int cnt = 0;
	Int temp;
	for (Int i = 0; i < N; i++) {//左端の青から固定して見ていく

		temp = -INF;
		for (Int j = 0; j < N; j++) {
			if (red[j].first>blue[i].first) {//赤のx	座標が青を超えるとbreak
				break;
			}
			else if (seen[j]) {//既にその赤の座標が使用済みならcontinue
				continue;
			}
			else if (temp==-INF) {//まだ一つも青の候補がない場合
				if (red[j].second>blue[i].second) {
					continue;
				}
				else {
					temp = j;
				}
			}
			else {//既に一つ以上青の候補が決まっている場合
				if (red[j].second > blue[i].second) {
					continue;
				}
				else if (red[j].second>red[temp].second) {
					temp = j;
				}
			}
		}

		if (temp==-INF) {
			continue;
		}
		else {
			cnt++;
			seen[temp]++;
		}

	}

	cout << cnt << "\n";


}

