#define ALL(v) (v).begin(), (v).end()
#define p(s) cout<<(s)<<endl
#define p2(s, t) cout << (s) << " " << (t) << endl
#define pn(s) cout << (#s) << " " << (s) << endl

const ll mod = 1e9 + 7;
const ll inf = 1e18;

class Point{
    public:
    Point(int a, int b){
        x = a;
        y = b;
    }
    int x;
    int y;

    bool operator<(const Point &another) const
    {
        return x < another.x;
    };

    bool operator==(const Point &another) const{
        return x==another.x && y==another.y;
    }

    static bool sortByY(Point a, Point b){
        if(a.y == b.y){
            return a.x < a.y;
        }else{
            return a.y < b.y;
        }
    }
};

void PrintPointVector(vector<Point> P){
    p("[vector]");
    if(P.size()==0){
        p("nothing");
    }
    for(auto p : P){
        cout << p.x << " " << p.y << endl;
    }
}


int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    int N;
    cin >> N;

    vector<Point> R;
    FOR(i, 0, N){
        int x, y;
        cin >> x >> y;
        R.push_back(Point(x, y));
    }

    vector<Point> B;
    FOR(i, 0, N){
        int x, y;
        cin >> x >> y;
        B.push_back(Point(x, y));
    }

    // Bをxの小さい順に並べる
    sort(ALL(B));

    int pairNum = 0;

    for(auto blue : B){
        // blue.xよりxが小さいものだけ集める
        vector<Point> temp;
        for(auto red : R){
            if(red.x < blue.x && red.y < blue.y){
                temp.push_back(red);
            }
        }

        if(temp.size() > 0){
            // yの小さい方からソート
            sort(ALL(temp), Point::sortByY);

            // yが最大の点をペアに選ぶ
            auto selectedRed = temp[temp.size()-1];

            // それをRから消す
            auto it = find(ALL(R), selectedRed);
            R.erase(it);
            pairNum++;
        }
    }

    p(pairNum);

    return 0;
}

