    vector<P> blue(n);
    rep(i,n) {
        int a,b;
        cin >> a >> b;
        red[i] = {a,b};
    }
    rep(i,n) {
        int c,d;
        cin >> c >> d;
        blue[i] = {c,d};
    }
    sort(blue.begin(),blue.end());
    auto judge = [&](P bl,P re) {
        return re.first < bl.first && re.second < bl.second;
    };
    int ans = 0;
    vector<bool> used(n,false);
    for(auto bl : blue) {
        int maxy = -1;
        int now;
        rep(i,n) {
