struct Edge {
    int from, to, cap, rev;
    Edge(int f, int t, int c, int r) : from(f), to(t), cap(c), rev(r) {} // 初期化
};

struct Graph {
    vector<vector<Edge>> G;
    Graph(int n = 0) : G(n) {} // 初期化

    vector<Edge>& operator[](int i) { return G[i]; }
    int size() { return G.size(); }
    void add_edge(int from, int to, int cap) {
        G[from].push_back(Edge(from, to, cap, (int)G[to].size()));
        G[to].push_back(Edge(to, from, 0, (int)G[from].size() - 1));
    } // 有向辺を加える
};

struct FordFulkerson {
    const int INF = 1e5;
    vector<int> used; 
    FordFulkerson(){}; // 初期化

    int dfs(Graph &G, int s, int g, int f) {  // 増加可能経路を見つけて増加分のフローを返す
        if (s == g) return f;
        used[s] = true;
        for (auto &e : G[s]) {
            if (!used[e.to] && e.cap > 0) {
                int d = dfs(G, e.to, g, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    } // 増加可能経路を見つけて増加分のフローを返す

    int max_flow(Graph &G, int s, int g) {
        int flow = 0;
        while (true) {
            used.assign(G.size(), false);
            int f = dfs(G, s, g, INF);  // f が増加分のフロー
            if (f == 0) {
                return flow;
            } else {
                flow += f;
            }
        }
        return 0;
    }
};

int main(){
    int n; cin >> n;
    int a[n], b[n], c[n], d[n];
    rep(i,n) cin >> a[i] >> b[i];
    rep(i,n) cin >> c[i] >> d[i];

    Graph data(2*n+2);

    rep(i,n){
        rep(j,n){
            if(a[i] < c[j] && b[i] < d[j]){
                data.add_edge(i, j+n, 1);
            }
        }
    }
    rep(i,n) data.add_edge(2*n, i, 1);
    rep(i,n) data.add_edge(n+i, 2*n+1, 1);

    FordFulkerson ans;
    cout << ans.max_flow(data, 2*n, 2*n+1) << endl;
}

