vector<int> edges[100];
int match[100];

bool dfs(int v, vector<int> visited){
    for (auto &u : edges[v]) {
        if (find(visited.begin(),visited.end(),u) != visited.end()) continue;
        visited.push_back(u);
        if (match[u] == -1 || dfs(match[u],visited)){
            match[u] = v;
            return true;
        }
    }
    return false;
}

