    vector<pair<int, int>> v1;
    vector<pair<int, int>> v2;

    for(int i = 0; i < N; ++i) {
        int a, b; cin >> a >> b;
        v1.push_back(make_pair(a, b));
    }

    for(int i = 0; i < N; ++i) {
        int c, d; cin >> c >> d;
        v2.push_back(make_pair(c, d));
    }

    // 条件 ax, ay, bx, by
    int bx, by;
    int c = 0; // 選択したペアの個数
    for(auto itr = v2.begin(); itr != v2.end(); ++itr) {
        bx = itr->first;
        by = itr->second;
        // cout << "bは(" << bx << ", " << by << ")をえらびました" << endl;

        int ax = 0;
        int ay = 0;
        bool select = false;
        int select_index;
        for(int i = 0; i < N; ++i) {
            if(!selected[i+1]) {
                pair<int, int> p = v1[i];
                // cout << "aは" << i << "番目の(" << p.first << ", " << p.second << ")をえらびました" << endl;
                if(ax <= p.first && p.first < bx && ay <= p.second && p.second < by) {
                    ax = p.first;
                    ay = p.second;
                    select_index = i+1;
                    select = true;

                    // cout << "条件を[" << ax << ", " << bx << ") && [" << ay << ", " << by << ")に変更しました" << endl;

                    // 最善の選択なので探索終了
                    if(bx - ax == 1 && by - ay == 1) {
                        break;
                    }
                }
            } else {
                // cout << i + 1 << "番目のaは選択されているのでだめです" << endl;
            }
        }

        if(select) {
            // cout << select_index << "番目のaがマッチングしました！" << endl;
            selected[select_index] = true;
            ++c;
        }
    }

    cout << c << endl;
}

