#define swap(type,x,y) do{type t=x;x=y;y=t;}while(0)

void quick(int a[], int b[],  int left, int right) {
	int pl = left;
	int pr = right;
	int x = a[(pl + pr) / 2];

	do {
		while (a[pl] < x)pl++;
		while (a[pr] > x)pr--;
		if (pl <= pr) {
			swap(int, a[pl], a[pr]);
			swap(int, b[pl], b[pr]);
			pl++;
			pr--;
		}
	} while (pl <= pr);
	if (left < pr) quick(a, b, left, pr);
	if (pl < right) quick(a, b, pl, right);
}

