    }//input

    while(r.size()!=0){//赤点が消えるまで
        bool erased=false;
        vector<int>  rflag(r.size(),0);//可能ペアの個数

        for(int i=0;i < r.size();i++){//ある赤点を見て}

            for(int j=0;j < b.size();j++){
                if(r.at(i).first < b.at(j).first && r.at(i).second < b.at(j).second){
                    rflag.at(i)++;
