	ll N;
	cin>>N;
	vector<ll> a(N),b(N),c(N),d(N);
	rep(i,N)cin>>a[i]>>b[i];
	rep(i,N)cin>>c[i]>>d[i];

	vector<vector<ll>> g(2*N);
