#include <iostream>
using namespace std;
typedef pair<int ,int > pp;


void swap(pp *kr,pp *kl){
    pp t=*kr;
    *kr=*kl;
    *kl=t;
}

void sortR(pp *k, int N)
{   int count=0;
    for(int i=0;i<N-1-count;i++){
        for(int j=1;j<N-count;j++){
            if(k[i].first>k[j].first){
                swap(&k[i],&k[j]);
                count++;
            }
        }
    }
}

int main()
{
    int N;
    cin >> N;
    pp red[N], blue[N];
    for (int i = 0; i < N; i++)
    {
        cin >> red[i].first >> red[i].second;
    }
    for (int i = 0; i < N; i++)
    {
        cin >> blue[i].first >> blue[i].second;
    }
    sortR(blue,N);
    bool isUsed[N]={};
    int count =0;
    int MaxY=-1;
    int Max=0;
    for(int i=0;i<N;i++){
        MaxY=-1;
        Max=0;
        for(int j=0;j<N;j++){
            if((blue[i].first<=red[j].first)||(blue[i].second<=red[j].second)){
                continue;
            }
            if(isUsed[j]){
                continue;
            }
            if(MaxY<red[j].second){
                MaxY=red[j].second;
                Max=j;
            }
        }
        if(MaxY!=-1){
            count++;
            isUsed[Max]=true;
        }
    }
    cout << count <<endl;
    return 0;
}

