class point{
public:
  int x, y, c, l;
  bool operator<(const point& another) const{
    return x < another.x;
  };
};


void solve(){
  int n; cin >> n;
  vector<point> p(2 * n);
  for(int i = 0; i < 2 * n; i++){
    cin >> p[i].x >> p[i].y;
    if(i <= n - 1) p[i].c = 0;
    else p[i].c = 1;
    p[i].l = 1;
  }
  sort(p.begin(), p.end());
  /*for(int i = 0; i < 2 * n; i++){
    cout << p[i].x << " " << p[i].y << " " << p[i].c << endl;
  }*/
  unsigned long long int ans = 0;
  for(int i = 0; i < 2 * n; i++){
    if(p[i].c == 0) continue;
    int j;
    for(j = i - 1; j >= 0; j--){
      if(p[j].c == 0 && p[j].l == 1) break;
    }
    if(j == -1) continue;
    int y = p[i].y;
    int maxyid = j;
    for(int k = j; k >= 0; k--){
      if(p[k].c == 1 || p[k].l == 0) continue;
      if(p[k].y < y && p[k].y > p[maxyid].y) maxyid = k;
    }
    p[maxyid].l = 0;
    ans++;
  }
  cout << ans << endl;
  return;
}

int main(){
  solve();
  return 0;
}

