typedef pair<int, int> P;

bool pairsort1(const P& element1, const P& element2)
{//first昇順
	return element1.F < element2.F;
}
bool pairsort2(const P& element1, const P& element2)
{//first降順
	return element1.F > element2.F;
}
bool pairsort3(const P& element1, const P& element2)
{//second昇順
	return element1.S < element2.S;
}
bool pairsort4(const P& element1, const P& element2)
{//second降順
	return element1.S > element2.S;
}

int main() {
	int N;
	scanf("%d",& N);
	vector <pair<int, int>>ab(N), cd(N);
	vector<vector<bool>>map(N*2, vector<bool>(N*2));
	rep(i, N) {
		scanf("%d %d",& ab[i].F ,&ab[i].S);
		map[ab[i].F][ab[i].S]=true;
	}
	rep(i, N) {
		scanf("%d %d",& cd[i].F,& cd[i].S);
	}
	sort(all(cd), pairsort1);
	sort(all(ab),pairsort1);
	vector<pair<int,int>>pair(N);
	int atmp = 0 , btmp = 0;
	int count = 0;
	rep(i, N) {
		int j = 0;
		int atmp = 0;
		int btmp = -1;
		bool flag = false;
		while (ab[j].F < cd[i].F){
			if (ab[j].S < cd[i].S &&
			       btmp < ab[j].S &&
				map[ab[j].F][ab[j].S] ==true) {
				atmp = ab[j].F;
				btmp = ab[j].S;
				flag = true;
			}
			j++;
			if (j == N) {
				break;
			}
		}
		if (flag) {
			count++;
			map[atmp][btmp] = false;
		}
	}
	printf("%d\n",count);
}

