struct  Pos{
    int x;
    int y;
};

struct State{
    array<int, 100> red;
    array<int, 100> blue;
};

/* Inputs */
int N;
vector<Pos> R, B;


int main() {
    cin >> N;

	for(int i=0; i<N; i++) {
		int x, y;
		cin >> x >> y;
		R.push_back(Pos{x,y});
	}


	for(int i=0; i<N; i++) {
		int x, y;
		cin >> x >> y;
        B.push_back(Pos{x,y});
	}

    queue<State> q;
    State s;
    s.red.fill(-1);
    s.blue.fill(-1);
    q.push(s);

    int ans = 0;

    while(!q.empty()) {
        s = q.front();
        q.pop();
        int pair_n = 0;
        for(int ri=0; ri<N; ri++) {
            if(s.red[ri] >= 0) {
                pair_n ++;
                continue;
            }
            for(int bi=0; bi<N; bi++) {
                if(s.blue[bi] >= 0) continue;
                if(R[ri].x < B[bi].x && R[ri].y < B[bi].y) {
                    q.push(s);
                    q.back().red[ri] = bi;
                    q.back().blue[bi] = ri;
                }
            }
        }
        ans = max(pair_n, ans);
    }
    cout << ans << endl;
}

