class ABC91C
{
public:
	ABC91C()
	{
		cin >> n_;
		count_pair_ = 0;
		r_grid_collection_.resize(n_);
		loop(i, n_)
		{
			cin >> r_grid_collection_[i].x_;
			cin >> r_grid_collection_[i].y_;
			r_grid_collection_[i].region_ = max(r_grid_collection_[i].x_, r_grid_collection_[i].y_);
		}
		sort(all(r_grid_collection_));
		b_grid_collection_.resize(n_);
		loop(i, n_)
		{
			cin >> b_grid_collection_[i].x_;
			cin >> b_grid_collection_[i].y_;
			b_grid_collection_[i].region_ = max(b_grid_collection_[i].x_, b_grid_collection_[i].y_);
		}
		sort(all(b_grid_collection_)));
	}
	void Run(void)
	{
		loop(i, (llong)r_grid_collection_.size())
			CompareAllBlue(r_grid_collection_[i]);

		cout << count_pair_;
	}
private:
	llong n_;
	llong count_pair_;
	vector<Grid> r_grid_collection_;
	vector<Grid> b_grid_collection_;
	void CompareAllBlue(Grid r)
	{
		if (b_grid_collection_.size() == 0)
			return;

		loop(i, (llong)b_grid_collection_.size())
		{
			if (r.x_ < b_grid_collection_[i].x_ && r.y_ < b_grid_collection_[i].y_)
			{
				b_grid_collection_.erase(b_grid_collection_.begin() + i);
				count_pair_++;
				break;
			}
		}
	}
	void Region(Grid g)
	{
		g.region_ = min(g.x_, g.y_);
	}
};


