bool canPair(const P& red, const P& blue) {
    return red.x < blue.x && red.y < blue.y;
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        P& red = reds[i];
        std::cin >> red.x  >> red.y ;
        red.pairedIdx = -1;
    }
    for (int i = 0; i < n; ++i) {
        P& blue = blues[i];
        std::cin >> blue.x  >> blue.y ;
        blue.pairedIdx = -1;
    }

    int ret = 0;
    for (int i = 0; i < n; ++i) {
        P& red = reds[i];
        P& blue = blues[i];
        if (canPair(red, blue)) {
            red.pairedIdx = i;
            blue.pairedIdx = i;
            ++ ret;
            continue;
        }
        for (int j = 0; j < i; ++j) {
            P& anotherBlue = blues[j];
            if (!canPair(red, anotherBlue)) {
                continue;
            }
            if (anotherBlue.pairedIdx == -1) {
                red.pairedIdx = j;
                anotherBlue.pairedIdx = i;
                ++ ret;
                break;
            }
            P& anotherRed = reds[anotherBlue.pairedIdx];
            if (canPair(anotherRed, blue)) {
                red.pairedIdx = j;
                anotherBlue.pairedIdx = i;
                anotherRed.pairedIdx = i;
                blue.pairedIdx = j;
                ++ ret;
                break;
            }
        }
    }
    std::cout << ret << std::endl;
    return 0;
}

