  for(int i=0; i<=2*MAX_N; i++) {
    dp[i][0][0] = 0;
    dp[i][0][1] = 0;
    dp[i][0][2] = 0;
    dp[0][i][0] = 0;
    dp[0][i][1] = 0;
    dp[0][i][2] = 0;
  }


  for(int y=1; y<=2*MAX_N; y++) {
    for(int x=1; x<=2*MAX_N; x++) {
      dp[y][x][0] = dp[y-1][x][0] + dp[y][x-1][0] - dp[y-1][x-1][0];
      dp[y][x][1] = dp[y-1][x][1] + dp[y][x-1][1] - dp[y-1][x-1][1];
      dp[y][x][2] = dp[y-1][x][2] + dp[y][x-1][2] - dp[y-1][x-1][2];
      if(contains(reds, YX(y-1, x-1))) {
        // std::cout << "red y=" << y << " x=" << x << std::endl;
        dp[y][x][0]++;
      }
