        if(dp[y][x][0] > dp[y][x][2]) {
          // std::cout << "pair y=" << y << " x=" << x << std::endl;
          dp[y][x][2]++;
        }
      }
    }
  }

  std::cout << dp[2*MAX_N][2*MAX_N][2] << std::endl;

