const int N = 100;
const int INF = 1000000;

int n;
vector<int> adj[N+1];	// 0 is for NIL.
int pair_u[N+1], pair_v[N+1], dist[N+1];

bool bfs() {
	for (int u = 0; u <= n; u++) dist[u] = INF;
	queue<int> q;
	for (int u = 1; u <= n; u++) {
		if (pair_u[u] == 0) {
			dist[u] = 0;
			q.push(u);
		}
	}

	while (!q.empty()) {
		int u = q.front();
		q.pop();

		if (dist[u] < dist[0]) {
			for (auto v : adj[u]) {
				if (dist[pair_v[v]] == INF) {
					dist[pair_v[v]] = dist[u] + 1;
					q.push(pair_v[v]);
				}
			}
		}
	}

	return dist[0] != INF;
}

bool dfs(int u) {
	if (u == 0) return true;

	for (int v : adj[u]) {
		if (dist[pair_v[v]] == dist[u] + 1) {
			if (dfs(pair_v[v])) {
				pair_u[u] = v;
				pair_v[v] = u;
				return true;
			}
		}
	}

	// no augmenting path beginning with u.
	dist[u] = INF;
	return false;
}

