typedef long long ll;
const ll INF = 1000000000000;
struct edge {ll to, cap, rev; };
vector<edge> G[210];
bool used[210];
ll n, a[110], b[110], c[110], d[110], flow;

ll dfs(ll v, ll f){
    if (v == 2 * n + 1) return f;
    used[v] = true;
    for (ll i = 0; i < G[v].size(); i++){
        edge e = G[v][i];
        if (used[e.to] || e.cap == 0) continue;
        ll g = dfs(e.to, min(f, e.cap));
        if (g > 0){
            G[v][i].cap -= g;
            G[e.to][e.rev].cap += g;
            return g;
        }
    }
    return 0;
}

int main(void){
    // Your code here!
    cin >> n;
    for (ll i = 1; i <= n; i++){
        G[0].push_back(edge{i, 1, 0});
        G[i].push_back(edge{0, 0, i - 1});
        G[n + i].push_back(edge{2 * n + 1, 1, i - 1});
        G[2 * n + 1].push_back(edge{n + i, 0, 0});
    }
    for (ll i = 1; i <= n; i++) cin >> a[i] >> b[i];
    for (ll i = 1; i <= n; i++) cin >> c[i] >> d[i];
    for (ll i = 1; i <= n; i++){
        for (ll j = 1; j <= n; j++){
            if (a[i] < c[j] && b[i] < d[j]){
                G[i].push_back(edge{n + j, 1, (ll)G[n + j].size()});
                G[n + j].push_back(edge{i, 0, (ll)G[i].size() - 1});
            }
        }
    }
    while(true){
        memset(used, 0, sizeof(used));
        ll w = dfs(0, INF);
        if (w == 0) break;
        flow += w;
    }
    cout << flow << endl;
}

