bool compare(const tuple<int, int, char>& lhs, const tuple<int, int, char>& rhs) {
  if (get<0>(lhs) != get<0>(rhs)) {
    return get<0>(lhs) <= get<0>(rhs);
  }
  if (get<1>(lhs) != get<1>(rhs)) {
    return get<1>(lhs) <= get<1>(rhs);
  }
  return get<2>(lhs) <= get<2>(rhs);
}

