struct edge{
    int64_t to, cap, rev;
};

class Flow{
    int64_t size_;
    vector<vector<edge>> G;
    vector<bool> used;
	public:
    Flow(int64_t size){
        size_ = size;
        G.resize(size);
        used.resize(size,false);
    }
    void add_edge(int64_t from, int64_t to, int64_t cap){
        G[from].push_back((edge) {to, cap, G[to].size()});
        G[to].push_back((edge) {from, 0ll, G[from].size() - 1});
    }
    int64_t dfs(int64_t v, int64_t t, int64_t f){
        if(v == t) return f;
        used[v] = true;
        for(int i = 0;i < G[v].size();i++){
            edge &e = G[v][i];
            if(!used[e.to] && e.cap > 0){
                int64_t d = dfs(e.to, t, min(f, e.cap));
                if(d > 0ll){
                    e.cap -=d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    int64_t max_flow(int64_t s, int64_t t){
        int64_t flow = 0;
        while(1){
            for(int i = 0;i < size_;i++)used[i] = false;
            int64_t f = dfs(s, t, 1e16);
            if(f == 0)return flow;
            flow += f;
        }
    }
};

