template<typename T>
struct edge{
    int to;
    T cap;
    int rev;
};
template<typename T>
struct FordFulkerson{
    int V;
    vector<vector<edge<T>>> G;
    vector<bool> used;
    T inf;
    FordFulkerson(int V_, T inf_):V(V_), inf(inf_){
        G.resize(V);
        used.assign(V, false);
    }
    void add_edge(int from, int to, T cap){
        G[from].push_back((edge<T>){to, cap, (int)G[to].size()});
        G[to].push_back((edge<T>){from, 0, (int)G[from].size()-1});
    }
    T dfs(int v, int t, T f){
        if(v == t)return f;
        used[v] = true;
        for(auto &&e: G[v]){
            if(used[e.to])continue;
            if(e.cap <= 0)continue;
            T d = dfs(e.to, t, min(f, e.cap));
            if(d > 0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
        return 0;
    }
    T max_flow(int s, int t){
        T flow = 0;
        for( ; ; ){
            used.assign(V, false);
            T f = dfs(s, t, inf);
            if(f == 0)return flow;
            flow += f;
        }
    }
};

int main() {
    int N;
    cin >> N;
    auto encode = [&](int i, int j) -> int{ return i*2*N + j; };
    FordFulkerson<ll> G(10000, INF+5);
    vector<int> a(N), b(N), c(N), d(N);
    int s = 2*N*2*N+1;
    int t = s + 1;
    rep(i,N){
        cin >> a[i] >> b[i];
        G.add_edge(s, encode(a[i], b[i]), 1);
    }
    rep(i,N){
        cin >> c[i] >> d[i];
        G.add_edge(encode(c[i], d[i]), t, 1);
    }
    rep(i,N)rep(j,N){
        if(a[i] < c[j] && b[i] < d[j]){
            G.add_edge(encode(a[i], b[i]), encode(c[j], d[j]), 1);
        }
    }
    cout << G.max_flow(s, t) << endl;
}

