  rep(i, n) cin >> as[i] >> bs[i];
  rep(i, n) cin >> cs[i] >> ds[i];

  to.resize(2 * n + 2);
  rep(i, n) rep(j, n) {
    bool ok = as[i] < cs[j] && bs[i] < ds[j];
    if (ok) {
      addE(i, n + j, 1);
    }
  }
  rep(i, n) addE(2 * n, i, 1);
  rep(j, n) addE(n + j, 2 * n + 1, 1);

  ll ans = 0;
  while (true) {
    used.assign(n + 1, false);
    ll add = dfs(2*n, 2*n+1, INF);
    if (add == 0) {
      cout << ans << endl;
      return 0;
    } else
      ans += add;
  }

  cout << ans << endl;

  return 0;
}

