  auto check=[](pair<int,int> a,pair<int,int> b){return (a.first<b.first&&a.second<b.second); };
  rep(i,n)
  {
    rep(j,n)
    {
      if(check(re[i],bl[j]))
      {
        ff.add_edge(i+1,j+n+1,1,0);
      }
    }
  }
