            if ((*it_r).x < (*it_b).x && (*it_r).y < (*it_b).y) {
                Pair p;

                found = true;
                p.red = *it_r;
                p.blue = *it_b;
                pairs.push_back(p);
                reds.erase(it_r);
                break;
            }

            ++it_r;
        }

        if (found) {
            it_b = blues.erase(it_b);
        } else {
            ++it_b;
        }
    }

    std::cout << pairs.size() << std::endl;
}

