	}

	// [0, N): 赤 [N, 2N-1), 青, 2N: s, 2N+1: t
	int s = 2 * N, t = 2 * N + 1;
	atcoder::mf_graph<int> g(2 * N + 2);

	rep(re, N) {
		rep(bl, N) {
			if (a[re] < c[bl] && b[re] < d[bl]) {
				g.add_edge(re, bl + N, 1);
			}
		}
	}

	rep(i, N) {
		g.add_edge(s, i, 1);
		g.add_edge(i + N, t, 1);
	}

