int n, a[100], b[100], c[100], d[100];
vector<int> es[200];
bool used[200];
int match[200];

bool dfs(int v) {
	used[v] = true;
	REP(i, es[v].size()) {
		int t = es[v][i];
		int m = match[t];
		if (m < 0 || (!used[m] && dfs(m))) {
			match[v] = t;
			match[t] = v;
			return true;
		}
	}
	return false;
}

int flow() {
	int f = 0;
	memset(match, -1, sizeof(match));
	REP(i, n*2) if (match[i] < 0) {
		memset(used, 0, sizeof(used));
		if (dfs(i)) ++f;
	}
	return f;
}

