	REP(i, n) cin >> a[i] >> b[i];
	REP(i, n) cin >> c[i] >> d[i];
	REP(i, n) REP(j, n) if (a[i] < c[j] && b[i] < d[j]) {
		es[i].push_back(n+j);
		es[n+j].push_back(i);
	}
	cout << flow() << endl;
	return 0;
}

