class twoNum
{
public:
    int X;
    int Y;
    int small;
    void setSmall()
    {
        if (X > Y)
        {
            small = Y;
        }
        else
        {
            small = X;
        }
    };
};

void swap(twoNum *kr,twoNum *kl){
    twoNum t=*kr;
    *kr=*kl;
    *kl=t;
}

void quick(int l, int r, twoNum *k)
{
    if (r - l > 1)
    {
        int base = k[r].small;
        int dl = l;
        int dr = r-1;
        while (true)
        {
            while (k[dl].small <= base)
            {   
                if (dl >= dr)
                {
                    break;
                }
                dl++;
            }
            while (k[dr].small > base)
            {   
                if (dl >= dr)
                {
                    break;
                }
                dr--;
            }
            if (dl >= dr)
            {
                break;
            }
            swap(&k[dl], &k[dr]);
        }
        swap(&k[dr],&k[r]);
        quick(l, dr, k);
        quick(dr + 1, r, k);
    }else{
        if(k[r].small<k[l].small){
            swap(k[r],k[l]);
        }
    }
}

void sort(twoNum *k, int N)
{
    quick(0, N - 1, k);
}

