int ans;
int N;
pair<int, int> A[105], B[105];
bool paired[105];

int main(void) {
    scanf("%d", &N);
    REP(i, 0, N) {
    	int a, b;
    	scanf("%d %d", &a, &b);
    	A[i] = make_pair(a, b);
    }

    REP(i, 0, N) {
    	int c, d;
    	scanf("%d %d", &c, &d);
    	B[i] = make_pair(c, d);
    }
    sort(A, A+N);
    sort(B, B+N);

    REP(i, 0, N) {
    	int j = 0;
    	int idx = -1;
    	int maxy = -1;
    	while (A[j].first < B[i].first && j < N) {
    		if (A[j].second < B[i].second && paired[j] == false && A[j].second > maxy) {
    			maxy = A[j].second;
    			idx = j;
    		}
    		j++;
    	}
    	if (idx != -1) {
    		paired[idx] = true;
    	} 
    }

    REP(i, 0, N) if (paired[i]) ans++;

    printf("%d\n", ans);

	return 0;
}

