int N;
int cnt;

bool DFS(int x, int st)
{
	int y;

	for(y=st; y<N; y++)
	{
		if(c1[x][0] < c2[y][0] && c1[x][1] < c2[y][1])
		{
			//printf("try: %d %d\n", x, y);

			if(m2[y] == -1)
			{
				m1[x] = y;
				m2[y] = x;

				//printf("connect: %d %d\n", x, y);

				return true;
			}
			else
			{
				int tx = m2[y];
				int ty = y;

				m1[tx] = -1;
				m2[ty] = -1;

				bool b = DFS(tx, ty+1);

				if(b)
				{
					m1[x] = y;
					m2[y] = x;

					//printf("connect: %d %d\n", x, y);

					return true;
				}
				else
				{
					m1[tx] = ty;
					m2[ty] = tx;
				}
			}
		}
	}

	return false;
}

