signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
//    cout << fixed << setprecision(15);

    i32 n; cin >> n;
    vec<PII> red(n), blue(n);
    rep(i,n) cin >> red[i].first >> red[i].second;
    rep(i,n) cin >> blue[i].first >> blue[i].second;
    sort(begin(blue), end(blue));

    multiset<PII> reds;
    for(auto p : red) reds.insert(p);
    for(auto bluePair : blue) {
        using Iter = std::multiset<std::pair<long, long>, std::less<std::pair<long, long> >, std::allocator<std::pair<long, long> > >::iterator;
        Iter del_iter = reds.begin();  // 最も原点に近いはずの点
        for(auto iter = reds.begin(); iter != reds.end(); ++iter) if(bluePair > *iter) {
            if(cmp(*del_iter, *iter)) del_iter = iter;
        }
        if(*del_iter >= bluePair) continue;
        reds.erase(del_iter);
    }
    i32 cnt = n-reds.size();

    cout << cnt << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

