const int N=210;
const int INF=0x3f3f3f3f;
struct Node{
	int x,y;
}a[N],b[N];
bool operator<(const Node t1,const Node t2){
	return t1.x<t2.x&&t1.y<t2.y;
}
struct node{
	int u,v,cap,next;
}edge[N*N];
int last[N],cur[N],le;
void cl(){
	memset(last,0,sizeof(last));
	le=1;
}
void add(int u,int v,int cap){
	edge[++le].u=u,edge[le].v=v,edge[le].cap=cap,edge[le].next=last[u],last[u]=le;
	edge[++le].u=v,edge[le].v=u,edge[le].cap=0,edge[le].next=last[v],last[v]=le;
}
int s,t;
int d[N];
queue<int> q;
bool bfs(){
	q.push(s);
	memset(d,0,sizeof(d));
	d[s]=1;
	while (!q.empty()){
		int u=q.front();q.pop();
		for (int i=last[u];i;i=edge[i].next){
			int v=edge[i].v;
			if (!d[v]&&edge[i].cap){
				d[v]=d[u]+1;
				q.push(v);
			}
		}
	}
	return d[t];
}
int dfs(int u,int a){
	if (u==t||!a) return a;
	int flow=0;
	for (int &i=cur[u];i;i=edge[i].next){
		int v=edge[i].v;
		if (d[v]==d[u]+1){
			int f=dfs(v,min(a,edge[i].cap));
			if (f){
				edge[i].cap-=f,edge[i^1].cap+=f;
				flow+=f,a-=f;if (!a) break;
			}
		}
	}
	return flow;
}
int dinic(){
	int flow=0;
	while (bfs()){
		for (int i=1;i<=t;++i) cur[i]=last[i];
		flow+=dfs(s,INF);
	}
	return flow;
}
