        rp(j,n){
            if(red[i].first<blue[j].first&&red[i].second<blue[j].second)
            pos[i].insert(j);
        }
    }
    vi sizes(n);
    rp(i,n){
        int si=pos[i].size();
        sizes[i]=si;
    }
    int ctr=0;
    while(1){
        int rem;
