        if(turn==-1) break;
        ctr++;
        rem=*pos[turn].begin();
        pos[turn].clear();
        rp(i,n){
            if(pos[i].count(rem)){
                pos[i].erase(rem);
            }
        }
    }
    print(ctr);
    return;
}
