void init() {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
}

const int N = 123;

int r[N][2], b[N][2];
bool used[N];
int cntR[N], cntB[N];

void solve() {
    int n; scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", r[i], r[i]+1);
    }
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", b[i], b[i]+1);
    }
    int ans = 0;
    while (true) {
        for (int i = 0; i < n; ++i) cntB[i] = 0;
        for (int i = 0; i < n; ++i) {
            if (cntR[i] == 0) continue;
            cntR[i] = 0;
            for (int j = 0; j < n; ++j) {
                if (used[j]) continue;
                if (r[i][0] < b[j][0] && r[i][1] < b[j][1]) {
                    ++cntR[i];
                    ++cntB[j];
                }
            }
        }
        int ind = 0;
        for (int i = 1; i < n; ++i) {
            if (cntR[i] == 0) continue;
            if (cntR[i] < cntR[ind]) {
                ind = i;
            }
        }
        if (cntR[ind] == 0) break;
        debug(ans);
        int sel = -1, c = 0;
        for (int i = 0; i < n; ++i) {
            if (used[i]) continue;
            // I don't trust this
            if (r[ind][0] < b[i][0] && r[ind][1] < b[i][1]) {
                if (cntB[i] > c) {
                    sel = i;
                    c = cntB[i];
                }
            }
        }
        cntR[ind] = 0;
        used[sel] = true;
        ++ans;
    }
    printf("%d", ans);
}

int main() {
    init();
    int t = 1; //scanf("%d", &t);
    while (t--) {
        solve();
    }
    return 0;
}

