struct ford_fulkerson{
  struct edgef{
    int to,cap,rev;
    edgef(int to=0,int cap=0,int rev=0):to(to),cap(cap),rev(rev){}
  };
  static constexpr int INF = numeric_limits<int>::max()/2;
  vector<bool> used;
  vector<vector<edgef>> nw;

  ford_fulkerson(int sz):used(sz),nw(sz){}

  inline void add_edge(int src, int dst, int cap)noexcept{
    nw[src].emplace_back(dst,cap,nw[dst].size());
    nw[dst].emplace_back(src,0,nw[src].size()-1);
  }
  inline int dfs(int now, int t, int f=INF)noexcept{
    if(now == t) return f;
    used[now] = true;
    int res = 0;
    for(auto &e:nw[now]){
      if(used[e.to] || e.cap<1) continue;
      int d = dfs(e.to,t,min(f,e.cap));
      if(d>0){
        e.cap -= d;
        nw[e.to][e.rev].cap += d;
        res += d;
        f -= d;
      }
    }
    return res;
  }
  int solve(int s, int t)noexcept{
    int res = 0, flow=-1;
    used.assign(nw.size(),false);
    while(flow){
      fill(used.begin(),used.end(),false);
      flow = dfs(s,t);
      res += flow;
    }
    return res;
  }
};
signed main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);
	int n;
	cin >> n;
	ford_fulkerson fk(2*n+2);
	V<pii> ab(n),cd(n);
	REP(i,n) cin >> ab[i].fi >> ab[i].se;
	REP(i,n) cin >> cd[i].fi >> cd[i].se;
	REP(i,n)REP(j,n){
		if(ab[i].fi < cd[j].fi && ab[i].se < cd[j].se){
			fk.add_edge(i,j+n,1);
		}
	}
	REP(i,n) fk.add_edge(2*n,i,1);
	REP(i,n) fk.add_edge(n+i,2*n+1,1);
	cout << fk.solve(2*n,2*n+1) << endl;
}

