#define INF (1 << 30)
#define MAX_N 101
#define MP make_pair
using namespace std;
typedef pair<int, int> P;

int xr[MAX_N], yr[MAX_N], xb[MAX_N], yb[MAX_N], blue_count[MAX_N];
bool is_checked[MAX_N];
vector<int> red_node[MAX_N];
vector<P> red_count;

int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) cin >> xr[i] >> yr[i];
    for (int i = 0; i < N; i++) cin >> xb[i] >> yb[i];
    for (int i = 0; i < N; i++) {
        // i番目の青い点について
        for (int j = 0; j < N; j++) {
            if (xb[i] > xr[j] && yb[i] > yr[j]) {
                red_node[i].push_back(j);
                blue_count[j]++;
            }
        }
    }
    for (int i = 0; i < N; i++) red_count.push_back(MP(red_node[i].size(), i));
    sort(red_count.begin(), red_count.end());
    for (int i = 0; i < red_count.size(); i++) {
        int now_blue = red_count[i].second;
        int min_blue = INF, red_idx = -1;
        for (int j = 0; j < red_node[now_blue].size(); j++) {
            // 被覆されている青い点が最も少ないものからペアにする
            int now_red = red_node[now_blue][j];
            if (min_blue > blue_count[now_red] && !is_checked[now_red]) {
                min_blue = blue_count[now_red];
                red_idx = now_red;
            }
        }
        if (red_idx != -1) is_checked[red_idx] = true;
    }
    int pair_count = 0;
    for (int i = 0; i < N; i++) {
        if (is_checked[i]) pair_count++;
    }
    cout << pair_count << endl;
    return 0;
}

