ll dist(mp p1, mp p2)
{
    ll xx = p1.X - p2.X;
    ll yy = p1.Y - p2.Y;
    return xx * xx + yy * yy;
}

bool cmp(mp a, mp b)
{
    ll da = dist(a, mp(0, 0));
    ll db = dist(b, mp(0, 0));
    return da > db;
}

int main()
{
    ll res = 0;
    ll n; cin >> n;
    vector<mp> r, b;
    for (ll i = 0; i < n; i++) { ll x, y; cin >> x >> y; r.pb(mp(x, y)); }
    for (ll i = 0; i < n; i++) { ll x, y; cin >> x >> y; b.pb(mp(x, y)); }
    sort(r.begin(), r.end());
    sort(b.begin(), b.end(), cmp);

    vector<bool> used(n);
    for (ll i = 0; i < n; i++) {
        mp a = b[i];
        ll d2 = INF;
        mp p; ll idx = -1;
        for (ll j = 0; j < n; j++) {
            mp b = r[j];
            if (used[j]) continue;
            if (b.X < a.X && b.Y < a.Y && dist(a, b) < d2) {
                d2 = dist(a, b);
                p = b; idx = j;
            }
        }
        if (idx >= 0) {
            used[idx] = true;
            res++;
            //pr_vars(a.X, a.Y, p.X, p.Y);
        }
    }

    cout << res << endl;
