struct point {
	int x, y;

};
bool comp(const point &left, const point &right) {
	if (left.x < left.y && right.x < right.y) {
		return left.x < right.x;
	}
	if (left.y < left.x && right.y < right.x) {
		return left.y < right.y;
	}
	if (left.x < left.y && right.y < right.x) {
		return left.x < right.y;
	}
	return left.y < right.x;
}
void twoDPlanTowNPoints() {
	cin >> N;
	point ab[101];
	point cd[101];
	for (size_t i = 0; i < N; i++)
	{
		int a, b;
		cin >> a >> b;
		ab[i].x = a;
		ab[i].y = b;
	}
	for (size_t i = 0; i < N; i++)
	{
		int c, d;
		cin >> c >> d;
		cd[i].x = c;
		cd[i].y = d;
	}
	sort(ab, ab + N, comp);
	sort(cd, cd + N, comp);
	int res = 0;
	bool use[101];
	fill(use, use + N, false);
	for (size_t i = 0; i < N; i++)
	{
		int best = 300;
		int besti = -1;
		for (int j = N - 1; j >= 0; j--)
		{
			if (!use[j] && ab[j].x < cd[i].x && ab[j].y < cd[i].y) {
				int tm = min(best, min((cd[i].x - ab[j].x), (cd[i].y - ab[j].y)));
				if (best > tm) {
					best = tm;
					besti = j;
				}
			}
		}
		if (besti != -1) {
			res++;
			use[besti] = true;
		}
	}
	cout << res << endl;
}
