        B[i] = make_pair(x, y);
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            G[i][j] = 0;
            G[N+j][N+i] = 0;
            if (R[i].first < B[j].first && R[i].second < B[j].second) {
                G[i][N+j] = 1;
                G[N+j][i] = 1;
            }
            else {
                G[i][N+j] = 0;
                G[N+j][i] = 0;                
            }
