                for (int j = 0; j < 2*N; j++) {
                    if (G[q][j] == 2) {
                        G[q][j] = 1;
                        G[j][q] = 1;
                    }
                }
                q = F[q];
            }
            while (p != F[p]) {
                G[p][F[p]] = 2;
                G[F[p]][p] = 2;
                p = F[p];
            }
            C++;
            stop = 0;
        }
        else {
            stop++;
        }
