        fl.add_edge(n+i, n*2+1, 1);
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (a[i] < c[j] && b[i] < d[j]) {
                fl.add_edge(i, n+j, 1);
            }
        }
    }

    cout << fl.max_flow(n*2, n*2+1) << "\n";
    return 0;
}

