int N, V;

int bipartite_matching()
{
    int res=0;
    vector<int> match(V, -1);
    for(int v=0; v<V; ++v) if (match[v]<0) {
        vector<bool> used(V);

        function<bool(int)> dfs=[&](int x) {
            used[x]=true;
            for(int u: g[x]) {
                int w=match[u];
                if (w<0 || (!used[w] && dfs(w))) {
                    match[x]=u;
                    match[u]=x;
                    return true;
                }
            }
            return false;
        };

        if (dfs(v)) ++res;
    }
    return res;
}

