void solve() {	
	int N;
	vector<pair<int,int>> v1,v2;
	cin >> N;
	for (int i = 0; i < N; ++i) {
		int a,b;
		cin >> a >> b;
		v1.pb(make_pair(a,b));
	} 

	for (int i = 0; i < N; ++i) {
		int c,d;
		cin >> c >> d;
		v2.pb(make_pair(c,d));
	}

	sort(ALL(v1), [](const pair<int,int> a, const pair<int,int> b) {
		if (a.first != b.first) {
			return a.first < b.first;
		} else {
			return a.second < b.second;
		}
	});

	sort(ALL(v2), [](const pair<int,int> a, const pair<int,int> b) {
		if (a.first != b.first) {
			return a.first < b.first;
		} else {
			return a.second < b.second;
		}
	});

	int ans = 0;

	int cnt = 0;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			if (used[j])
				continue;
			if (v1[i].first < v2[j].first && v1[i].second < v2[j].second) {
				++cnt;
				used[j] = true;
				break;
			}
		}
	}

	ans = max(ans,cnt);


	sort(ALL(v1), [](const pair<int,int> a, const pair<int,int> b) {
		if (a.second != b.second) {
			return a.second < b.second;
		} else {
			return a.first < b.first;
		}
	});

	sort(ALL(v2), [](const pair<int,int> a, const pair<int,int> b) {
		if (a.second != b.second) {
			return a.second < b.second;
		} else {
			return a.first < b.first;
		}
	});

	cnt = 0;
	fill(used,used+N,false);

	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			if (used[j])
				continue;
			if (v1[i].first < v2[j].first && v1[i].second < v2[j].second) {
				++cnt;
				used[j] = true;
				break;
			}
		}
	}
	ans = max(ans,cnt);

	cout << ans << '\n';
}	

