struct graph
{
	struct R
	{
		lint to, cap, re;
	};

	lint v, e;

	vector<vector<R>> gr;

	graph(lint _v) : v(_v), e(0), gr(v)
	{}

	void add_e(lint from, lint to, lint cap)
	{
		lint re = gr[to].size(), rre = gr[from].size();

		gr[from].push_back({ to, cap, re });
		gr[to].push_back({ from, 0, rre });
		e++;
	}

	auto bfs(lint s)
	{
		vector<lint> d(v, intmax);
		d[s] = 0;

		queue<lint> q;

		q.push(s);
		while (!q.empty())
		{
			lint next = q.front();
			q.pop();
			rep(i, gr[next].size())
			{
				if (gr[next][i].cap > 0 && d[next] + 1 < d[gr[next][i].to])
				{
					d[gr[next][i].to] = d[next] + 1;
					q.push(gr[next][i].to);
				}
			}
		}

		return d;
	}

	lint dfs(vector<lint>& it, vector<lint>& d, lint s, lint t, lint neck = intmax)
	{
		if (s == t)
			return neck;
		repi(i, it[s], gr[s].size())
		{
			if (d[s] < d[gr[s][i].to] && gr[s][i].cap > 0)
			{
				lint neck2 = mmin(
					neck,
					dfs(it, d, gr[s][i].to, t, mmin(neck, gr[s][i].cap)));
				if (neck2 > 0)
				{
					gr[s][i].cap -= neck2;
					gr[gr[s][i].to][gr[s][i].re].cap += neck2;
					return neck2;
				}
			}
		}

		return 0;
	}

	auto dinic(lint s, lint t)
	{
		lint flow = 0;

		vec lev;

		while (lev = bfs(s), lev[t] != intmax)
		{
			vec it(v, 0);
			lint f;
			while ((f = dfs(it, lev, s, t)) > 0)
			{
				flow += f;
			}
		}

		return flow;
	}
};


int main()
{
	lint n;
	cin >> n;

	vec a(n), b(n), c(n), d(n);
	rep(i, n)
		cin >> a[i] >> b[i];
	rep(i, n)
		cin >> c[i] >> d[i];

	graph g(2*n+2);

	rep(i, n)
		g.add_e(2 * n, i, 1);
	rep(i, n)
		g.add_e(i+n, 2 * n + 1, 1);

	rep(i, n)
	{
		rep(j, n)
		{
			if (a[i] < c[j] && b[i] < d[j])
			{
				g.add_e(i, j + n, 1);
			}
		}
	}

	cout << g.dinic(2*n, 2 * n + 1) << endl;

	return 0;
}

