int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m, sum = 0;
    vector<PI8> v, w;
    cin >> n;
    v.resize(n);
    w.resize(n);

    for (int i = 0; i < n; i++) {
        cin >> v[i].first >> v[i].second;
    }
    for (int i = 0; i < n; i++) {
        cin >> w[i].first >> w[i].second;
    }

    for (auto &x : v) {
        int pos = 0, posDel = -1, len = INF;
        for (auto &y : w) {
            if (x.first < y.first && x.second < y.second) {
                // 距離を格納する
                int tmp = (y.first) * (y.first) + (y.second) * (y.second);
                if (tmp < len) {
                    posDel = pos;
                    len = tmp;
                }
            }
            pos++;
        }
        // 距離が一番近いものを削除
        if (posDel >= 0) {
            w.erase(w.begin() + posDel);
            sum++;
        }
    }

    cout << sum << endl;

    return 0;
}

