#include <bits/stdc++.h>

using namespace std;

using ll = long long;

struct Edge {
    int src, dst;
    Edge(int f, int t) :
        src(f), dst(t) {}
};

using Edges = vector<Edge>;
using Graph =  vector<Edges>;

bool Augment(const Graph& g, int u,
             vector<int>& matchTo, vector<bool>& visited) {
    if (u < 0)
        return true;

    for (auto e : g[u])
        if (!visited[e.dst]) {
            visited[e.dst] = true;
            if (Augment(g, matchTo[e.dst], matchTo, visited)) {
                matchTo[e.src] = e.dst;
                matchTo[e.dst] = e.src;
                return true;
            }
        }

    return false;
}

// 二部グラフG=(A;B, E)の最大マッチングを求める
// A:[0,L-1], B:[L,g.size()-1]
int BipartiteMaximumMatching(const Graph& g, int L) {
    const int n = g.size();
    Edges matching;
    vector<int> matchTo(n, -1);
    int match = 0;

    for (int u = 0; u < L; ++u) {
        vector<bool> visited(n);
        if (Augment(g, u, matchTo, visited))
            ++match;
    }

    for (int u = 0; u < L; ++u)
        if (matchTo[u] >= 0) // make explicit matching
            matching.emplace_back(Edge(u, matchTo[u]));

    return match;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    int n;

    cin >> n;
    vector<pair<int, int>> red(n), blue(n);
    for (int i = 0; i < n; ++i) cin >> red[i].first >> red[i].second;
    for (int i = 0; i < n; ++i) cin >> blue[i].first >> blue[i].second;

    Graph g(2 * n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (red[i].first < blue[j].first && red[i].second < blue[j].second) {
                g[i].emplace_back(Edge(i, n + j));
            }
        }
    }

    cout << BipartiteMaximumMatching(g, n) << endl;

    return 0;
}

