bool cmp2(int a,int b){
    return a>=b;
}

int main()
{
    int n;
    cin>>n;

    node list[2*n];
    for(int i=0;i<2*n;i++){
        if(i<n){
            cin>>list[i].x>>list[i].y;
            list[i].color = red;
        }else{
            cin>>list[i].x>>list[i].y;
            list[i].color = blue;
        }
    }


    sort(list,list+2*n,cmp);
    int res=0;
    int height[n];
    int pos=0;
    for(int i=0;i<n;i++){
        height[i]=-1;
    }

    for(int i=0;i<2*n;i++){
        if(list[i].color ==red){
            height[pos] = list[i].y;
            ++pos;
        }else{
            if(pos>0){
                sort(height,height+n,cmp2);
                for(int j=0;j<pos;j++){
                    if(height[j]<list[i].y){
                        ++res;
                        height[j]=-1;
                        --pos;
                        break;
                    }
                }
            }
        }
    }
    cout<<res<<endl;
    return 0;

}

