const int MAXN=1e6+5;
pair<int,int> red[MAXN],blue[MAXN];

vector <int> g[MAXN];
int matcha[MAXN],matchb[MAXN],vis[MAXN];

bool dfs(int s){
    if(vis[s]) return false;
    vis[s]=1;
    for(int to:g[s])
        if(matchb[to]==-1 || dfs(matchb[to])){
            matchb[to]=s;
            matcha[s]=to;
            return true;
        }
    return false;
}

int maxMatching(int n,int m){
    fill(matcha,matcha+n,-1);
    fill(matchb,matchb+n+m,-1);
    int res=0,czy=1;
    while(czy){
        czy=0;
        fill(vis,vis+n,0);
        for(int i=0;i<n;i++)
            if(matcha[i]==-1)
                czy+=dfs(i);
        res+=czy;
    }
    return res;
}

