bool dfs(int v) {
    used[v] = true;
    rep(i, G[v].size()) {
        int u = G[v][i], w = match[u];
        if(w < 0 || (!used[w] && dfs(w))){
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching() {
    int res = 0;
    memset(match, -1, sizeof(match));
    rep(v, V) if(match[v] < 0) {
        memset(used, 0, sizeof(used));
        if(dfs(v)) res++;
    }
    return res;
}

