namespace solver {
  using namespace std;
  using ll = long long;

  struct edge {
    int to, cap, rev;
  };
  int N, as[110], bs[110], cs[110], ds[110];
  vector<vector<edge> > G;
  vector<int> used;

  void init() {
    cin >> N;
    rep(i, N) {
      cin >> as[i] >> bs[i];
    }
    rep(i, N) {
      cin >> cs[i] >> ds[i];
    }
    G.resize(2*N+2);
    used.resize(2*N+2);
  }

  int dfs(int u, int t, int f) {
    used[u] = true;
    if(u == t) return f;
    for(auto& e : G[u]) {
      if(used[e.to] || e.cap <= 0) continue;
      int d = dfs(e.to, t, min(f, e.cap));
      if(d > 0) {
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
    return 0;
  }

  void solve() {
    int s = 2 * N, t = s + 1;
    rep(i, N) {
      G[s].push_back((edge){ i, 1, (int)G[i].size() });
      G[i].push_back((edge){ s, 0, (int)G[s].size()-1 });
      G[i+N].push_back((edge){ t, 1, (int)G[t].size() });
      G[t].push_back((edge){ i+N, 0, (int)G[i+N].size()-1 });
    }
    rep(i, N) rep(j, N) {
      if(as[i] < cs[j] && bs[i] < ds[j]) {
        G[i].push_back((edge){ j+N, 1, (int)G[j+N].size() });
        G[j+N].push_back((edge){ i, 0, (int)G[i].size()-1 });
      }
    }
    int ans = 0;
    while(1) {
      fill(ALL(used), false);
      int d = dfs(s, t, IINF);
      if(d <= 0) break;
      ans += d;
    }
    cout << ans << "\n";
  }
}

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  solver::init();
  solver::solve();
  return 0;
}

