#include <bits/stdc++.h>
using namespace std;

//#define errOut(s) { std::cerr << "LINE:" << __LINE__ << " " << #s << " = " << s << std::endl; }
#define errOut(s)

struct Point {
    std::vector<int> connectableIdxes;
    int x;
    int y;
    int connectedIdx;
    bool fixed;

    Point(int xx, int yy, int n = 0) : x(xx), y(yy), fixed(false), connectedIdx(-1) {
        if (n) {
            connectableIdxes.reserve(n);
        }
    }

    const bool operator<(const Point &another) const {
        return x + y < another.x + another.y;
    }
};

std::vector<Point> reds;
std::vector<Point> blues;

bool searchOddCycleTransversal(int redIdx, std::set<int> &visited) {
    auto &red = reds[redIdx];
    for (auto &&blueIdx : red.connectableIdxes) {
        if (visited.find(blueIdx) != visited.end()) {
            continue;
        }
        auto &blue = blues[blueIdx];
        if (blue.fixed) {
            continue;
        }
        auto nextRedIdx = blue.connectedIdx;
        if (nextRedIdx < 0) {
            red.connectedIdx = blueIdx;
            blue.connectedIdx = redIdx;
            return true;
        }
        visited.insert(blueIdx);
        if (searchOddCycleTransversal(nextRedIdx, visited)) {
            red.connectedIdx = blueIdx;
            blue.connectedIdx = redIdx;
            return true;
        }
        visited.erase(blueIdx);
    }
    return false;
}

bool maximizeMatchings(int redIdx) {
    std::set<int> visited;
    return searchOddCycleTransversal(redIdx, visited);
}

bool canPair(const Point &red, const Point &blue) {
    return red.x < blue.x && red.y < blue.y;
}

int main() {
    int n;
    std::cin >> n;
    reds.reserve(n);
    blues.reserve(n);
    for (int i = 0; i < n; ++i) {
        int x, y;
        std::cin >> x >> y;
        reds.emplace_back(x, y, n);
    }
    for (int i = 0; i < n; ++i) {
        int x, y;
        std::cin >> x >> y;
        blues.emplace_back(x, y, n);
    }

    std::sort(reds.begin(), reds.end());
    std::sort(blues.begin(), blues.end());

    int ret = 0;
    int bound = 0;
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        bound = (int) (std::lower_bound(blues.begin() + bound, blues.end(), red) - blues.begin());
        for (int j = bound; j < n; ++j) {
            auto &blue = blues[j];
            if (!canPair(red, blue)) {
                continue;
            }
            red.connectableIdxes.push_back(j);
            blue.connectableIdxes.push_back(i);
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.connectableIdxes.size() == 0) {
            red.fixed = true;
        }
        auto &blue = blues[i];
        if (blue.connectableIdxes.size() == 0) {
            blue.fixed = true;
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectableIdxes.size() > 1) {
            continue;
        }
        auto &blue = blues[red.connectableIdxes[0]];
        if (blue.fixed || blue.connectableIdxes.size() > 1) {
            continue;
        }
        red.fixed = true;
        blue.fixed = true;
        red.connectedIdx = red.connectableIdxes[0];
        blue.connectedIdx = i;
        ++ret;
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectedIdx >= 0 || red.connectableIdxes.size() > 1) {
            continue;
        }
        auto &blue = blues[red.connectableIdxes[0]];
        if (blue.fixed || blue.connectedIdx >= 0) {
            continue;
        }
        red.fixed = true;
        blue.fixed = true;
        red.connectedIdx = red.connectableIdxes[0];
        blue.connectedIdx = i;
        ++ret;
    }
    for (int i = 0; i < n; ++i) {
        auto &blue = blues[i];
        if (blue.fixed || blue.connectedIdx >= 0 || blue.connectableIdxes.size() > 1) {
            continue;
        }
        auto &red = reds[blue.connectableIdxes[0]];
        if (red.fixed || red.connectedIdx >= 0) {
            continue;
        }
        red.fixed = true;
        blue.fixed = true;
        red.connectedIdx = i;
        blue.connectedIdx = blue.connectableIdxes[0];
        ++ret;
    }

    bool anyFound = true;
    while(anyFound) {
        anyFound = false;

        for (int i = 0; i < n; ++i) {
            auto &red = reds[i];
            if (red.fixed || red.connectedIdx >= 0) {
                continue;
            }

            int notFixedOnlyBlueIdx = -1;
            for (auto&& blueIdx : red.connectableIdxes) {
                auto& blue = blues[blueIdx];
                if (blue.fixed) {
                    continue;
                }
                if (notFixedOnlyBlueIdx >= 0) {
                    notFixedOnlyBlueIdx = -1;
                    break;
                }
                notFixedOnlyBlueIdx = blueIdx;
            }

            if (notFixedOnlyBlueIdx < 0) {
                continue;
            }

            auto& blue = blues[notFixedOnlyBlueIdx];
            red.fixed = true;
            blue.fixed = true;
            red.connectedIdx = notFixedOnlyBlueIdx;
            blue.connectedIdx = i;
            ++ret;
            anyFound = true;
        }

        for (int i = 0; i < n; ++i) {
            auto &blue = blues[i];
            if (blue.fixed || blue.connectedIdx >= 0) {
                continue;
            }

            int notFixedOnlyRedIdx = -1;
            for (auto&& redIdx : blue.connectableIdxes) {
                auto& red = reds[redIdx];
                if (red.fixed) {
                    continue;
                }
                if (notFixedOnlyRedIdx >= 0) {
                    notFixedOnlyRedIdx = -1;
                    break;
                }
                notFixedOnlyRedIdx = redIdx;
            }

            if (notFixedOnlyRedIdx < 0) {
                continue;
            }

            auto& red = reds[notFixedOnlyRedIdx];
            red.fixed = true;
            blue.fixed = true;
            red.connectedIdx = i;
            blue.connectedIdx = notFixedOnlyRedIdx;
            ++ret;
            anyFound = true;
        }
    }

    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectedIdx >= 0) {
            continue;
        }
        int numberOfBlueConnectableIdxes = INT_MAX;
        int blueIdx = -1;
        for (auto&& candidateIdx : red.connectableIdxes) {
            auto &candidate = blues[candidateIdx];
            if (candidate.fixed || candidate.connectedIdx >= 0) {
                continue;
            }
            if (candidate.connectableIdxes.size() < numberOfBlueConnectableIdxes) {
                blueIdx = candidateIdx;
                numberOfBlueConnectableIdxes = static_cast<int>(candidate.connectableIdxes.size());
            }
        }
        if (blueIdx >= 0) {
            auto& blue = blues[blueIdx];
            red.connectedIdx = blueIdx;
            blue.connectedIdx = i;
            ++ret;
        }
    }

    std::vector<int> soloRedIdxes;
    soloRedIdxes.reserve(n);
    for (int i = 0; i < n; ++i) {
        auto &red = reds[i];
        if (red.fixed || red.connectedIdx >= 0) {
            continue;
        }
        soloRedIdxes.push_back(i);
    }
    std::sort(soloRedIdxes.begin(), soloRedIdxes.end(), [](int idx1, int idx2) -> int {
        const auto& red1 = reds[idx1];
        const auto& red2 = reds[idx2];
        return red1.connectableIdxes.size() < red2.connectableIdxes.size();
    } )

    errOut(ret);
    for (auto&& redIdx: soloRedIdxes) {
        auto &red = reds[redIdx];
        if (red.connectedIdx >= 0) {
            continue;
        }
        if (maximizeMatchings(redIdx)) {
            ++ret;
        }
    }

    errOut(ret);
    std::cout << ret << std::endl;
    return 0;
}

