bool used[210];
void add_edge(int u, int v) {
	vec[u].push_back(v);
	vec[v].push_back(u);
}
bool dfs(int v) {
	used[v] = true;
	for (int i = 0; i < vec[v].size(); i++) {
		int u = vec[v][i];
		int w = match[u];
		if (w < 0 || !used[w] && dfs(w)) {
			match[v] = u;
			match[u] = v;
			return true;
		}
	}
	return false;
}
int bipartite_batching() {
	int res = 0;
	memset(match, -1, sizeof(match));
	for (int v = 0; v < 2 * n; v++) {
		if (match[v] < 0) {
			memset(used, 0, sizeof(used));
			if (dfs(v))res++;
		}
	}
	return res;
}
