	for (int i = 0; i < N; i++) {
		int ai, bi;
		cin >> ai >> bi;
		RedP[i] = make_pair(ai, bi);
	}
	for (int i = 0; i < N; i++) {
		int ci, di;
		cin >> ci >> di;
		BlueP[i] = make_pair(ci, di);
		for (int j = 0; j < N; j++) {
			if (CMP(BlueP[i], RedP[j]))Lines.push_back(make_pair(i, j));
		}
	}
    priority_queue<tuple<int, int, int>>Q; //-青x座標, 赤y座標, Lines添字
    for(int i=0; i<Lines.size(); i++){
        Q.push(make_tuple(-BlueP[Lines[i].first].first, RedP[Lines[i].second].second, i));
    }
    int c=0;
    while(!Q.empty()){
        c++;
        tuple<int, int, int>lp=Q.top();
        int ersrp = Lines[get<2>(lp)].second, ersbp = Lines[get<2>(lp)].first;
	    queue<int>el;
	    for (int i = 0; i < (int)Lines.size(); i++) {
	    	if (Lines[i].first == ersbp || Lines[i].second == ersrp)el.push(i);
	    }
	    int ersc = 0;
	    while (!el.empty()) {
	    	Lines.erase(Lines.begin() + el.front() - ersc);
	    	el.pop();
	    	ersc++;
	    }
        priority_queue<tuple<int, int, int>>newQ;
        for(int i=0; i<Lines.size(); i++){
            newQ.push(make_tuple(-BlueP[Lines[i].first].first, RedP[Lines[i].second].second, i));
        }
        newQ.swap(Q);
    }
    cout << c;
    return 0;
}

