template<typename... args>struct dfs{
    public:
    queue<function<void(void)>> que;
    function<void(args...,dfs<args...>&)> func;
    void run(){
        while(!que.empty()){
            que.front()();
            que.pop();
        }
    }
    void push(args... arg){
        que.push(bind(func,arg...,ref(*this)));
    }
    dfs(args... init,function<void(args...,dfs<args...>&)> func):func(func){
        push(init...);
