lint mod_pow(lint x,lint y,lint mod){
    if(y==0)return 1;
    else if(y==1)return x;
    else if(y%2==1)return x*mod_pow(x,y-1,mod)%mod;
    else return mod_pow(x,y/2,mod)*mod_pow(x,y/2,mod)%mod;
}
lint binary_search(function<bool(lint)> func) {
    lint left = -1;
    lint right =IINF;
    while (right - left > 1) {
        lint mid = left + (right - left) / 2;
        if (func(mid)) right = mid;
        else left = mid;
    }
    return right;
}
struct MF {
    struct edge { lint to, cap, rev; };
    lint V;
    vector<vector<edge>> G;
    vector<lint> itr, level;

    MF(lint V) : V(V) { G.assign(V,vector<edge>()); }

    void add_edge(lint from, lint to, lint cap) {
        G[from].push_back((edge) {to, cap, (lint) G[to].size()});
        G[to].push_back((edge) {from, 0, (lint) G[from].size()-1});
    }

    void bfs(lint s) {
        level.assign(V,-1);
        queue<lint> q;
        level[s] = 0; q.push(s);
        while (!q.empty()) {
            lint v = q.front(); q.pop();
            for(auto &e: G[v]){
                if (e.cap > 0 and level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    lint dfs(lint v, lint t, lint f) {
        if (v == t) return f;
        for (lint& i = itr[v]; i < (lint) G[v].size(); ++i) {
            edge& e = G[v][i];
            if (e.cap > 0 and level[v] < level[e.to]) {
                lint d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    G[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    lint run(lint s, lint t) {
        lint ret = 0, f;
        while (bfs(s), level[t] >= 0) {
            itr.assign(V,0);
            while ((f = dfs(s, t, INF)) > 0) ret += f;
        }
        return ret;
    }
};
int main(){
    lint n;
    cin>>n;
    vector<pair<lint,lint>> a(n),b(n);
    rep(i,n){
        lint x,y;
        cin>>x>>y;
        a[i]=make_pair(x,y);
    }
    rep(i,n){
        lint x,y;
        cin>>x>>y;
        b[i]=make_pair(x,y);
    }
    MF mf=MF(2*n+2);
    rep(i,n){
        mf.add_edge(2*n,i,1);
        mf.add_edge(n+i,2*n+1,1);
    }
    rep(i,n)rep(j,n){
        if(a[i].first<b[j].first&&a[i].second<b[j].second)mf.add_edge(i,n+j,1);
    }
    cout<<mf.run(2*n,2*n+1);
}

