//ford-fulkerson
struct edge {
	int to, cap, rev;
};

int N;
vector<vector<edge>> graph(202);
vector<bool> node(202);

void make_adge(int from, int to, int cap){
	graph[from].push_back({ to,cap,(int)graph[to].size() });
	graph[to].push_back({ from,0,(int)graph[from].size() - 1});
}

int dfs(int from, int flow) {

	if (from == 201) return flow;
	node[from] = false;
	REP(i, graph[from].size()) {
		if(node[graph[from][i].to] && (graph[from][i].cap > 0)){
			int dflow = dfs(graph[from][i].to, min(flow, graph[from][i].cap));
			if(dflow > 0){
				graph[from][i].cap -= dflow;
				graph[graph[from][i].to][graph[from][i].rev].cap += dflow;
				return dflow;
			}
		}
	}
	return 0;
}

int maxflow(void){
	int maxflow = 0;
	while(1){
		REP(i, 202) node[i] = true;
		int flow = dfs(200, 1);
		if (flow == 0) return maxflow;
		maxflow += flow;
	}
}

int main() {

	cin >> N;
	REP(i, N) make_adge(200,i,1);
	REP(i, N) make_adge(100 + i,201,1);

	VP red(N), blue(N);
	REP(i, N) cin >> red[i].first >> red[i].second;
	REP(i, N) cin >> blue[i].first >> blue[i].second;
	REP(i,N)REP(j,N)if(red[i].first < blue[j].first && red[i].second < blue[j].second) make_adge(i, 100 + j, 1);

	cout << maxflow() << endl;

	return 0;
}

