int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m, sum = 0;
    cin >> n;
    vector<T> v(n), w(n);

    for (int i = 0; i < n; i++) {
        int in1, in2;
        cin >> in1 >> in2;
        v[i].x = in1;
        v[i].y = in2;
        v[i].z = 0;
    }
    for (int i = 0; i < n; i++) {
        cin >> w[i].x >> w[i].y;
        w[i].z = 0;
    }
    sort(ALL(v));
    sort(ALL(w));
    for (int i = 0; i < n; i++) {
        // 組み合わせの個数を保存
        int cnt = 0;
        for (int j = 0; j < n; j++) {
            if (v[i].x < w[j].x) {
                if (v[i].y < w[j].y) {
                    cnt++;
                }
            } else {
                v[i].z = cnt;
                break;
            }
        }
    }
    // 組み合わせが少ないものから先にペアを作る
    sort(ALL(v), [](const T &a, const T &b) { return a.z < b.z; });
    for (int i = 0; i < n; i++) {
        int pos = 0;
        for (auto &ww : w) {
            if (v[i].x < ww.x && v[i].y < ww.y) {
                w.erase(w.begin() + pos);
                sum++;
                break;
            }
            pos++;
        }
    }

    cout << sum << endl;

    return 0;
}

