static const int MAX_N = 110, INF = 999;
typedef pair<int, int> Pr;

int main(void){
  //入力
  int N;
  int a[MAX_N], b[MAX_N], c[MAX_N], d[MAX_N];
  cin >> N;
  for(int i = 0; i < N; i++){
    cin >> a[i] >> b[i];
  }
  for(int i = 0; i < N; i++){
    cin >> c[i] >> d[i];
  }
  Pr red[MAX_N], blue[MAX_N];//red(x, y), blue(x, y)とした。
  for(int i = 0; i < N; i++){
    red[i].first = a[i];
    red[i].second = b[i];
    blue[i].first = c[i];
    blue[i].second = d[i];
  }

  //Greedyにとく二部マッチング
  sort(red, red + N, greater<Pr>());//redは降順
  sort(blue, blue + N);//blueは昇順
  //redの大きい方から，マッチングをとっていく。redより大きく，その中で一番小さいblueとマッチングしていく。
  int numPair = 0;
  //red[i]とblue[j]のマッチング
  for(int i = 0; i < N; i++){
    for(int j = 0; j < N; j++){
      if(red[i].first < blue[j].first && red[i].second < blue[j].second){
        numPair++;
        blue[j].first = -INF;
        blue[j].second = -INF;
        break;
      }
    }
  }
  cout << numPair << endl;
  return 0;
}

