#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
const int maxx = 1e2 + 7;
const int Inf = 1 << 30;
const LL INF = 1LL << 60;
int n, ans, res;
struct PP {
	int x, y;
} p[maxx], q[maxx];
bool cmp1(PP a, PP b) {
	return a.x < b.x;
}
bool cmp2(PP a, PP b) {
	return a.y < b.y;
}
bool vis[255];

int main() {
	cin >> n;
	for(int i = 1; i <= n; i++) cin >> p[i].x >> p[i].y;
	for(int i = 1; i <= n; i++) cin >> q[i].x >> q[i].y;
	sort(p + 1, p + n + 1, cmp1); //按x升序
	sort(q + 1, q + n + 1, cmp2); //按y升序
	for(int i = 1; i <= n; i++) { //n^2内枚举
		for(int j = 1; j <= n; j++) {
			if(p[i].x < q[j].x && p[i].y < q[j].y && !vis[q[j].x]) {
				vis[q[j].x] = 1;
				ans++;
				break;
			}
		}
	}
	memset(vis, 0, sizeof(vis));
	sort(p + 1, p + n + 1, cmp2); //按y升序
	sort(q + 1, q + n + 1, cmp1); //按x升序
	for(int i = 1; i <= n; i++) { //n^2内枚举
		for(int j = 1; j <= n; j++) {
			if(p[i].x < q[j].x && p[i].y < q[j].y && !vis[q[j].x]) {
				vis[q[j].x] = 1;
				res++;
				break;
			}
		}
	}
	cout << max(ans, res) << endl;
	return 0;
}

