struct Point {
    int x;
    int y;
    int pair = -1;
};

bool red_sort(const Point &a, const Point &b) {
    if (a.y == b.y) {
        return (a.x < b.x);
    }

    return (a.y > b.y);
}

bool blue_sort(const Point &a, const Point &b) {
    if (a.x == b.x) {
        return (a.y < b.y);
    }

    return (a.x < b.x);
}

