            if ((red[i].x < blue[ii].x) && (red[i].y < blue[ii].y) && (blue[ii].pair == -1)) {
                red[i].pair = ii;
                blue[ii].pair = i;
                ans++;
                break;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

