using namespace std;

struct BipartiteMatching {
  vector<vector<int>> graph;
  vector<int> match, alive, used;  int timestamp;

  BipartiteMatching(int n){
    graph=vector<vector<int>>(n);
    alive=vector<int>(n,1);
    used=vector<int>(n,0);
    match=vector<int>(n,-1);
    timestamp=0;
  }

  void add_edge(int u, int v) {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int idx) {
    used[idx] = timestamp;
    for(auto &to : graph[idx]) {
      int to_match = match[to];
      if(alive[to] == 0) continue;
      if(to_match==-1 || (used[to_match]!=timestamp && dfs(to_match))) {
        match[idx]=to;  match[to]=idx;
        return true;
      }
    }
    return false;
  }

  int bipartite_matching() {
    int ret = 0;
    for(int i=0; i<graph.size(); i++) {
      if(alive[i]==0) continue;
      if(match[i]==-1){++timestamp; ret+=dfs(i);}
    }
    return ret;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      if(i < match[i]) {cout << i << "-" << match[i] << endl;}
    }
  }
};

int main() {
  int N; cin >> N;
  BipartiteMatching bm(2*N);
  vector<int> a(N),b(N),c(N),d(N);
  for(int i=0;i<N;i++)cin >> a[i] >> b[i];
  for(int i=0;i<N;i++)cin >> c[i] >> d[i];
  for(int i=0;i<N;i++){
    for(int j=0;j<N;j++){
      if(a[i]<c[j] && b[i]<d[j]){bm.add_edge(i,j+N);}
    }
  }
  cout << bm.bipartite_matching() << endl;
  //bm.output();
}

