// 辺を表す構造体 (行き先、容量、逆辺)
struct edge {
    int to, cap, rev;
};

void add_edge(int,int,int);
int dfs(int,int,int);
int max_flow(int, int);
void solve();

int INF = pow(10,7);
// 入力
int N;
bool can[100][100]; // can[i][j]:=コンピュータiが仕事jをこなせる

int main(){
    cin >> N;
