vector<edge> G[300]; // グラフの隣接リスト表現
bool used[300]; // DFSですでに調べたかのフラグ

// fromからtoへ向かう容量capの辺をグラフに追加する 
void add_edge(int from, int to, int cap) {
    G[from].push_back((edge){to, cap, G[to].size()});
    G[to].push_back((edge){from, 0, G[from].size() - 1}); 
}

// 増加パスをDFSで探す
int dfs(int v, int t, int f) {
    if (v == t) return f;
    used[v] = true;
    for (int i = 0; i < G[v].size(); i++) {
        edge &e = G[v][i];
            if (!used[e.to] && e.cap > 0) {
                int d = dfs(e.to, t, min(f, e.cap)); if (d > 0) {
                    e.cap -= d; G[e.to][e.rev].cap += d; return d;
                } 
            }
    }
    return 0;
}

// sからtへの最大流を求める
int max_flow(int s, int t) {
    int flow = 0;
    for (;;) {
        memset(used, 0, sizeof(used));
        int f = dfs(s, t, INF);
        if (f == 0) return flow;
        flow += f;
    } 
}


void solve() {
    // 0~N-1: コンピュータに対応する頂点 // N~N+K-1: 仕事に対応する頂点
    int s = 2*N, t = s + 1;
    // sとコンピュータを結ぶ
    for (int i = 0; i < N; i++) {
        add_edge(s, i, 1);
    }
    // 仕事とtを結ぶ
    for (int i = 0; i < N; i++) {
        add_edge(N + i, t, 1);
    }
    // コンピュータと仕事を結ぶ
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++){
            if (can[i][j]) {
                add_edge(i, N + j, 1);
            }
        }
    }
    printf("%d\n", max_flow(s, t));
}

