const int MAX_V = 1000000;

//辺を表す構造体（行先、容量、逆辺）
struct edge { int to, cap, rev; };

vector<vector<edge>> G(MAX_V);        //グラフの隣接リスト表現
int level[MAX_V];                     //ｓからの距離
int iter[MAX_V];                      //どこまで調べ終わったか

//fromからtoへ向かう容量capの辺をグラフに張る
void add_edge(int from, int to, int cap) {
    edge F, T;
    F.to = to; F.cap = cap; F.rev = G[to].size();
    G[from].push_back(F);

    T.to = from; T.cap = 0; T.rev = G[from].size() - 1;
    G[to].push_back(T);
}

//sからの最短経路をBFSで調べる
void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front(); que.pop();
        rep(i, G[v].size()) {
            edge& e = G[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

//増加パスをdfsで調べる
int dfs(int v, int t, int f) {
    if (v == t)return f;
    for (int& i = iter[v]; i < G[v].size(); i++) {
        edge& e = G[v][i];                  //辺の容量を更新するのでアドレスをもっておく
        if (level[v] < level[e.to] && e.cap > 0) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;                 //使った分容量を減らす
                G[e.to][e.rev].cap += d;    //使った分逆辺の容量を増やす
                return d;
            }
        }
    }
    return 0;
}

//sからｔへの最大流を求める
int max_flow(int s, int t) {
    int flow = 0;
    for (;;) {
        bfs(s);
        if (level[t] < 0)return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, t, inf)) > 0) {
            flow += f;
        }
    }
}


