{
public:
    int X;
    int Y;
};

void swap(twoNum *kr,twoNum *kl){
    twoNum t=*kr;
    *kr=*kl;
    *kl=t;
}

void sort(twoNum *k, int N)
{   int count=0;
    for(int i=0;i<N-1-count;i++){
        for(int j=1;j<N-count;j++){
            if(k[i].X>k[j].X){
                swap(&k[i],&k[j]);
                count++;
            }
        }
    }
}

int main()
{
    int N;
    cin >> N;
    twoNum red[N], blue[N];
    for (int i = 0; i < N; i++)
    {
        cin >> red[i].X >> red[i].Y;
    }
    for (int i = 0; i < N; i++)
    {
        cin >> blue[i].X >> blue[i].Y;
    }
    sort(blue,N);
    bool isUsed[N]={};
    int count =0;
    int MaxY=-1;
    int Max=0;
    for(int i=0;i<N;i++){
        MaxY=-1;
        for(int j=0;j<N;j++){
            if((blue[i].X<=red[j].X)||(blue[i].Y<=red[j].Y)){
                continue;
            }
            if(isUsed[j]){
                continue;
            }
            if((MaxY<red[j].Y)&&(!isUsed[j])){
                MaxY=red[j].Y;
                Max=j;
            }
        }
        if(MaxY!=-1){
            count++;
            isUsed[Max]=true;
        }
    }
    cout << count <<endl;
    return 0;
}

