pair<PII, PII> bfs(int i, int j, const vector<vector<char>>& x, vector<vector<bool>> &used, pair<PII, PII>&	 cur)
{
	if (i < 0 || j < 0 || i >= SZ(x) || j >= SZ(x[0]) || used[i][j] || x[i][j] == '*')
	{
		return cur;
	}
	used[i][j] = 1;
	cur.f.f = min(cur.f.f, i);
	cur.f.s = min(cur.f.s, j);
	cur.s.f = max(cur.s.f, i);
	cur.s.s = max(cur.s.s, j);
	bfs(i + 1, j, x, used, cur);
	bfs(i - 1, j, x, used, cur);
	bfs(i, j + 1, x, used, cur);
	bfs(i, j - 1, x, used, cur);
	return cur;
}


