struct poi
{
	int64 xx;
	int64 yy;

	bool operator < (const poi &right) const
	{
		return xx == right.xx ? yy < right.yy : xx < right.xx;
	}
};

int main()
{
	int64 nn, xx, yy, rp, bp, ma, tmp, ans = 0;
	cin >> nn;
	bool flag, botti[nn];
	vector<poi> rr(nn), bb(nn);
	for(int64 ii = 0;ii < nn;ii++)
	{
		cin >> xx >> yy;
		rr[ii].xx = xx;
		rr[ii].yy = yy;
		botti[ii] = true;
	}
	for(int64 ii = 0;ii < nn;ii++)
	{
		cin >> xx >> yy;
		bb[ii].xx = xx;
		bb[ii].yy = yy;
	}
	sort(rr.begin(), rr.end());
	sort(bb.begin(), bb.end());

	for(bp = nn-1;bp >= 0;bp--)
	{
		flag = true;
		rp = 0;
		ma = -1;
		while(rr[rp].xx < bb[bp].xx)
		{
			rp++;
			if(rp == nn)
			{
				flag = false;
				break;
			}
		}
		if(!flag)
		{
			break;
		}
		for(int64 ii = 0;ii < rp;ii++)
		{
			if(botti[ii] && ma <= rr[ii].yy && rr[ii].yy < bb[bp].yy)
			{
				tmp = ii;
				ma = rr[ii].yy;
			}
		}
		if(ma != -1)
		{
			ans++;
			botti[tmp] = false;
		}
	}
	cout << ans << endl;
	return 0;
}

