typedef long long ll;
typedef pair<ll, ll> P;
priority_queue<P, vector<P>, greater<P>> red, blue;
map<ll, bool> mp;
ll n, x, y, res;
int main(void){
    // Your code here!
    cin >> n;
    for (ll i = 0; i < n; i++) {
        cin >> x >> y;
        red.push(P(x, y));
    }
    for (ll i = 0; i < n; i++) {
        cin >> x >> y;
        blue.push(P(x, y));
    }
    while (blue.size()) {
        P p1 = blue.top(); blue.pop();
        while (red.size()) {
            P p2 = red.top();
            if (p2.first > p1.first) break;
            red.pop();
            mp[p2.second] = true;
        }
        auto itr = mp.upper_bound(p1.second);
        if (itr == mp.begin()) continue;
        res++; itr--; itr->second = false;
    }
    cout << res << endl;
}

