//二部マッチング問題と捉えて解く
#include <iostream>
#include <cstring>
#include <vector>
#include <cstdio>

#define N_MAX 100
using namespace std;

struct edge {int to,cap,rev;};


//G[0]=s,G[1~N]=R,G[N+1~2N]=B,G[2N+1]=t;
vector<edge> G[2*N_MAX+2];
bool used[2*N_MAX+2];

void add_edge(int from,int to){
  G[from].push_back( (edge){to,1,G[to].size()} );
  G[to].push_back( (edge){from,0,G[from].size()-1} );
}

int dfs(int v,int t,int f){
  if(v==t) return f;
  used[v]=true;
  for(int i=0;i<G[v].size();i++){
    edge &e=G[v][i];
    if(!used[e.to] && e.cap){
      int d = dfs(e.to,t,min(f,e.cap));
      if(d>0){
        e.cap-=d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}

int max_flow(int s,int t){
  int flow=0;
  for(;;){
    memset(used,0,sizeof(used));
    int f=dfs(s,t,1);
    if(f==0)return flow;
    flow+=f;
  }
}

int main(){
  int i,k,N;
  int rc[N_MAX][2]={0},bc[N_MAX][2]={0};

  cin >> N;
  for(i=0;i<N;i++){
    cin >> rc[i][0] >> rc[i][1];
  }
  for(i=0;i<N;i++){
    cin >> bc[i][0] >> bc[i][1];
  }

  //辺の追加
  for(i=0;i<N;i++){
    //s→R
    add_edge(0,i+1);
    //B→t
    add_edge(i+1+N,2*N+1);
  }

  for(i=0;i<N;i++){
    for(k=0;k<N;k++){
      if((rc[i][0]<bc[k][0]) && 
         (rc[i][1]<bc[k][1]) )
        add_edge(i+1,k+1+N);
    }
  }

  cout << max_flow(0,2*N+1) << endl;
  return 0;
}

#include <algorithm>
#include <iostream>
#include <list>

class Point {
public:
    int x;
    int y;
};

class Pair {
public:
    Point red;
    Point blue;
};

bool cmpYDescendant(const Point &left, const Point &right) {
    return left.y > right.y;
}

bool cmpXAscendant(const Point &left, const Point &right) {
    return left.x < right.x;
}

int N;
std::list<Point> reds;
std::list<Point> blues;
std::list<Pair> pairs;
typedef std::list<Point>::iterator ItP;

int main() {
    Point p;

    std::cin >> N;

    for (int i = 1; i <= N; ++i) {
        std::cin >> p.x >> p.y;
        reds.push_back(p);
    }

    for (int i = 1; i <= N; ++i) {
        std::cin >> p.x >> p.y;
        blues.push_back(p);
    }

    reds.sort(cmpYDescendant);
    blues.sort(cmpXAscendant);
    ItP it_b = blues.begin();

    while(it_b != blues.end()) {
        bool found = false;
        ItP it_r = reds.begin();

        while(it_r != reds.end()) {
            if ((*it_r).x < (*it_b).x && (*it_r).y < (*it_b).y) {
                Pair p;

                found = true;
                p.red = *it_r;
                p.blue = *it_b;
                pairs.push_back(p);
                reds.erase(it_r);
                break;
            }

            ++it_r;
        }

        if (found) {
            it_b = blues.erase(it_b);
        } else {
            ++it_b;
        }
    }

    std::cout << pairs.size() << std::endl;
}

