        cin >> a[i] >> b[i];

    for (int i = 0; i < n; i++)
        cin >> c[i] >> d[i];

    G.resize(2*n+2);

    for (int i = 0; i < n; i++) {
        add_edge(G, 0, i+1, 1);
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (a[i] < c[j] && b[i] < d[j]) {
                add_edge(G, i+1, j+n+1, 1);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        add_edge(G, i+n+1, 2*n+1, 1);
    }


