#include<cstdio>
static const int MAX = 100;
#define SENTINEL  2000000000
int nonpaired = -1;
int paired = 1;

struct Point
{
    int x;
    int y;
    int state;
};

Point Red[MAX];
Point Blue[MAX];

void BlueMerge(int n, int left, int mid, int right)
{
    int n1 = mid - left;
    int n2 = right - mid;

    Point L[MAX/2 + 2], R[MAX/2 + 2];

    for (int i = 0; i < n1; i++) 
    {
        L[i] = Blue[left + i];
    }
    for (int i = 0; i < n2; i++)
    {
        R[i] = Blue[mid + i];
    }
    L[n1].x = R[n2].x = SENTINEL;
    int i = 0, j = 0;
    for (int k = left; k < right; k++)
    {
        if (L[i].x <= R[j].x)
        {
            Blue[k] = L[i];
            i++;
        }
        else
        {
            Blue[k] = R[j];
            j++;
        }
    }
}

void MergeSortBP(int n, int left, int right)
{
    if (left + 1 < right)
    {
        int mid = (left + right) / 2;
        MergeSortBP(n, left, mid);
        MergeSortBP(n, mid, right);
        BlueMerge(n, left, mid, right);
    }
}

void RedMerge(int n, int left, int mid, int right)
{
    int n1 = mid - left;
    int n2 = right - mid;

    Point L[MAX/2 + 2], R[MAX/2 + 2];

    for (int i = 0; i < n1; i++) 
    {
        L[i] = Red[left + i];
    }
    for (int i = 0; i < n2; i++)
    {
        R[i] = Red[mid + i];
    }
    L[n1].y = R[n2].y = SENTINEL;
    int i = 0, j = 0;
    for (int k = left; k < right; k++)
    {
        if (L[i].y <= R[j].y)
        {
            Red[k] = L[i];
            i++;
        }
        else
        {
            Red[k] = R[j];
            j++;
        }
    }
}

void MergeSortRP(int n, int left, int right)
{
    if (left + 1 < right)
    {
        int mid = (left + right) / 2;
        MergeSortRP(n, left, mid);
        MergeSortRP(n, mid, right);
        RedMerge(n, left, mid, right);
    }
}


