    MergeSortBP(N, 0, N);

    int count = 0;
    for (int i = 0; i < N; i++)
    {
        for (int j = N - 1; j >= 0; j--)
        {
            if (Red[j].state == nonpaired && Red[j].x < Blue[i].x && Red[j].y < Blue[i].y)
            {
                Red[j].state = paired;
                count++;
                break;
            }
        }
    }
    printf("%d\n", count);
