struct Match {
    int n;
    vector<vector<int>> G;
    vector<bool> used;
    vector<int> match;

    Match(int n_) : n(n_) { G.resize(n); }
    void add_edge(int u, int v) {
        G[u].push_back(v);
        G[v].push_back(u);
    }
    bool dfs(int v) {
        used[v] = true;
        for(auto nv : G[v]) {
            int vv = match[nv];
            if(vv < 0 || (!used[vv] && dfs(vv))) {
                match[v] = nv;
                match[nv] = v;
                return true;
            }
        }
        return false;
    }
    int solve() {
        int res = 0;
        match.assign(n,-1);
        for (int i = 0; i < n; i++) {
            if(match[i] >= 0) continue;
            used.assign(n,false);
            if(dfs(i)) res++;
        }
