bool used[210];
void ae(int from,int to,int cap){
  v[from].push_back((edge){to,cap,v[to].size()});
  v[to].push_back((edge){from,0,v[from].size()-1});
}
int dfs(int now,int t,int f){
  if(now==t)return f;
  used[now]=true;
  for(int i=0;i<v[now].size();i++){
    edge &e=v[now][i];
    if(used[e.to]==false&&e.cap>0){
      int d=dfs(e.to,t,min(f,e.cap));
      if(d>0){
        e.cap-=d;
        v[e.to][e.rev].cap+=d;
        return d;
      }
    }
  }
  return 0;
}
