const int inf = 999999999;
const int mod = 1000000007;

typedef struct{
	int x, y;
}data;

typedef struct{
	int to, cap, rev;
}edge;

vector<edge> G[202];
bool used[100];

void add_edge(int from, int to, int cap){
	G[from].pb((edge){to, cap, G[to].size()});
	G[to].pb((edge){from, 0, G[from].size()});
}

int dfs(int v, int t, int f){
	if(v == t) return f;
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		edge &e = G[v][i];
		if(!used[e.to] && e.cap > 0){
			int d = dfs(e.to, t, min(f, e.cap));
			if(d > 0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}

int max_flow(int s, int t){
	int flow = 0;
	while(1){
		Rep(i, 100){
			used[i] = false;
		}
		int f = dfs(s, t, inf);
		if(f == 0) return flow;
		flow += f;
	}
}

