		b[i].x = x; b[i].y = y;
	}
	Rep(i, n){
		add_edge(s, i, 1);
	}
	Rep(i, n){
		add_edge(n + i, t, 1);
	}
	Rep(i, n){
		Rep(j, n){
			if(a[i].x < b[j].x && a[i].y < b[j].y){
				add_edge(i, n + j, 1);
			}
		}
	}
	int ans = max_flow(s, t);
	cout << ans << endl;
	return 0;
}

