template <class T>
vector<pair<T, int>> zip_vi(vector<T> v) {
  int n = sz(v);
  vector<pair<T, int>> w(n);
  for (int i = 0; i < n; i++) w[i] = make_pair(v[i], i);
  return w;
}
template <class T>
vector<pair<int, T>> zip_iv(vector<T> v) {
  int n = sz(v);
  vector<pair<int, T>> w(n);
  for (int i = 0; i < n; i++) w[i] = make_pair(i, v[i]);
  return w;
}
template <class T, class S>
vector<pair<T, S>> zip(vector<T> v, vector<S> w) {
  int n = min(sz(v), sz(w));
  vector<pair<T, S>> x(n);
  for (int i = 0; i < n; i++) x[i] = make_pair(v[i], w[i]);
  return x;
}
template <class T, class S>
pair<vector<T>, vector<S>> unzip(vector<pair<T, S>> v) {
  int n = sz(v);
  auto w = make_pair(vector<T>(n), vector<S>(n));
  for (int i = 0; i < n; i++) {
    w.first[i] = v[i].first;
    w.second[i] = v[i].second;
  }
  return w;
}
template <class T, class S>
vector<T> unzip_first(vector<pair<T, S>> v) {
  int n = sz(v);
  vector<T> w(n);
  for (int i = 0; i < n; i++) w[i] = v[i].first;
  return w;
}
template <class T, class S>
vector<S> unzip_second(vector<pair<T, S>> v) {
  int n = sz(v);
  vector<S> w(n);
  for (int i = 0; i < n; i++) w[i] = v[i].second;
  return w;
}

void solve(int N, vi a, vi b, vi c, vi d) {
  vp ab = zip(a, b), cd = zip(c, d);
  greater_queue<pii> abq(all(ab)), cdq(all(cd));
  set<int, greater<int>> bs;
  int ans = 0;
  rep(i, N * 2) {
    while(!abq.empty() && abq.top().first < i) {
      bs.insert(abq.top().second);
      abq.pop();
    }
    while(!cdq.empty() && cdq.top().first <= i) {
      auto it = bs.upper_bound(cdq.top().second);
      if(it != bs.cend()) {
        bs.erase(it);
        ans++;
      }
      cdq.pop();
    }
  }
  COUT(ans);
}


