    }
    rep(j,N){
        cin >> c[j] >> d[j];
        G.add_edge(j+N, t, 1);
    }
    rep(i,N)rep(j,N){
        if(a[i] < c[j] && b[i] < d[j]){
            G.add_edge(i, j+N, 1);
        }
    }
    cout << G.max_flow(s, t) << endl;
}

