// 0 - n-1 : nodes(source side)
// n - 2n-1 : nodes(target side)
vector<li> graph[333];

PI ab[111];
PI cd[111];

inline bool small(PI a, PI b) {
    return a.F < b.F && a.S < b.S;
}

bool augment(li u,
             vector<li>& matchTo,
             vector<bool>& visited) {
    if (u < 0) {
        return true;
    }
    rep(i, sz(graph[u])) {
        const li next = graph[u][i];
        if (visited[next]) {
            continue;
        }
        visited[next] = true;
        if (augment(matchTo[next], matchTo, visited)) {
            matchTo[u] = next;
            matchTo[next] = u;
            return true;
        }
    }
    return false;
}

inline li bipertite_matching(li n) {
    const li nn = n * 2;
    vector<li> matchTo(nn, -1);
    li match = 0;
    rep(u, n) {
        vector<bool> visited(nn);
        if (augment(u, matchTo, visited)) ++match;
    }
    return match;
}

