#include <bits/stdc++.h>
using namespace std;

class BipartiteMatching {
private:
  struct edge {
    int to, cap, rev;
  };
  int U, V;
  vector<vector<edge>> G;
  vector<int> level;
  vector<int> iter;
public:
  BipartiteMatching(int u, int v) : U(u), V(v), G(U + V + 2) {
    for (int i = 0; i < U; i++) {
      init_edge(0, i + 1);
    }
    for (int i = 0; i < V; i++) {
      init_edge(U + i + 1, U + V + 1);
    }
  }
  void init_edge(int from, int to) {
    G.at(from).push_back((edge) {to, 1, (int) G.at(to).size()});
    G.at(to).push_back((edge) {from, 0, (int) G.at(from).size() - 1});
  }
  void add(int from, int to) {
    from += 1, to += U + 1;
    G.at(from).push_back((edge) {to, 1, (int) G.at(to).size()});
    G.at(to).push_back((edge) {from, 0, (int) G.at(from).size() - 1});
  }
  void bfs(int s) {
    fill(level.begin(), level.end(), -1);
    queue<int> que;
    level.at(s) = 0;
    que.push(s);
    while (!que.empty()) {
      int v = que.front();
      que.pop();
      for (auto &e : G.at(v)) {
        if (e.cap > 0 && level.at(e.to) < 0) {
          level.at(e.to) = level.at(v) + 1;
          que.push(e.to);
        }
      }
    }
  }
  int dfs(int v, int t, int f) {
    if (v == t) {
      return f;
    }
    for (int &i = iter.at(v); i < (int) G.at(v).size(); i++) {
      edge &e = G.at(v).at(i);
      if (e.cap > 0 && level.at(v) < level.at(e.to)) {
        int d = dfs(e.to, t, min(f, e.cap));
        if (d > 0) {
          e.cap -= d;
          G.at(e.to).at(e.rev).cap += d;
          return d;
        }
      }
    }
    return 0;
  }
  int solve() {
    level.resize(U + V + 2),  iter.resize(U + V + 2);
    int flow = 0;
    int s = 0, t = U + V + 1;
    for (;;) {
      bfs(s);
      if (level.at(t) < 0) return flow;
      fill(iter.begin(), iter.end(), 0);
      int f;
      while ((f = dfs(s, t, numeric_limits<int>::max())) > 0) {
        flow += f;
      }
    }
  }
  vector<int> allocate() {
    vector<int> res(U, -1);
    for (int i = 0; i < U; i++) {
      for (auto &e : G.at(i + 1)) {
        if (e.cap == 0 && e.to != 0) {
          res.at(i) = e.to - U - 1;
          break;
        }
      }
    }
    return res;
  }
};

int main() {
  int N;
  cin >> N;
  vector<pair<int, int>> R(N), B(N);
  for (int i = 0; i < N; i++) {
    int a, b;
    cin >> a >> b;
    R.at(i) = {a, b};
  }
  for (int i = 0; i < N; i++) {
    int c, d;
    cin >> c >> d;
    B.at(i) = {c, d};
  }
  BipartiteMatching BM(N, N);
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      auto[a, b] = R.at(i);
      auto[c, d] = B.at(j);
      if (a < c && b < d) BM.add(i, j);
    }
  }
  cout << BM.solve() << "\n";
}

