int main() {
	int n; cin >> n;
	vector<pii> p(n),q(n);
	for (int i = 0 ; i < n ; ++i) {
		scanf("%d %d",&p[i].f,&p[i].s);
	}
	for (int i = 0 ; i < n ; ++i) {
		scanf("%d %d",&q[i].f,&q[i].s);
	}
	int match = 0;
	sort(all(p)), sort(all(q));
