using namespace std;
typedef long long ll;
typedef pair<int,int> pt;

bool cmp(pt a, pt b) {
  if (a.second == b.second) return a.first > b.first;
  return a.second > b.second;
}

int main() {

  ios_base::sync_with_stdio(false);
  cin.tie(0); cout.tie(0);

  vector<pt> reds;
  vector<pt> blues;

  int N; cin >> N;
  for (int i = 0; i < N; i++) {
    int a,b; cin >> a >> b;
    reds.push_back(make_pair(a,b));
  }
  for (int i = 0; i < N; i++) {
    int c,d; cin >> c >> d;
    blues.push_back(make_pair(c,d));
  }

  sort(reds.begin(), reds.end(), cmp);
  sort(blues.begin(), blues.end());

  int ans = 0;
  vector<bool> used(N);
  for (int i = 0; i < N; i++) {
    pt B = blues[i];
    int minDist = INT_MAX;
    int ansJ;
    for (int j = 0; j < N; j++) {
      pt R = reds[j];
      int dist = abs(R.first - B.first) + abs(R.second - B.second);
      if (R.first < B.first && R.second < B.second && !used[j] && dist < minDist) {
	minDist = dist;
	ansJ = j;
      }
    }
    if (minDist < INT_MAX) {
      used[ansJ] = true;
      ans++;
    }
  }

  cout << ans << endl;
  return 0;
}

