struct point
{
    int32_t x;
    int32_t y;
    bool checked;
    point()
    { x = 0; y = 0; checked = false;}
    point(int32_t x, int32_t y, bool checked)
        :x(x), y(y), checked(checked)
    {}
    bool operator<(const point &rth) const{
        return x < rth.x;
    }
    bool can_make_friend(const point &rth) const{
        return (x < rth.x) && (y < rth.y);
    }
};

bool greater_cmp(const point &a, const point &b){
    return a.y > b.y;
}


int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);

    int32_t N;
    std::cin >> N;
    assert(1 <= N);
    std::vector<point> reds(N);
    std::vector<point> blues(N);
    for(auto& i : reds){
        std::cin >> i.x >> i.y;
        i.checked = false;
    }
    for(auto& i : blues){
        std::cin >> i.x >> i.y;
        i.checked = false;
    }
    std::sort(reds.begin(), reds.end(), greater_cmp);
    std::sort(blues.begin(), blues.end());

    int32_t num_pair = 0;
    for(int32_t red_idx = 0; red_idx < N; red_idx++){
        for(int32_t blued_idx = 0; blued_idx < N; blued_idx++){
            if(blues[blued_idx].checked) continue;
            if(reds[red_idx].can_make_friend(blues[blued_idx])){
                num_pair++;
                blues[blued_idx].checked = true;
                break;
            }
        }
    }

    std::cout << num_pair << std::endl;
    return 0;
}

