using namespace std;

struct Edge{
    int to, cap, rev;
    Edge(int t, int c, int r):to(t), cap(c), rev(r) {}
};

void AddEdge(int fr, int to, int cap, vector<vector<Edge> >& gr)
{
    gr[fr].push_back( Edge(to, cap, gr[to].size()) );
    gr[to].push_back( Edge(fr, 0, gr[fr].size()-1) );
}

int dfs(int v, int G, int f, vector<vector<Edge> >& gr, vector<int>& used )
{
    if(v==G) return f;
    used[v]=1;
    auto it = gr[v].begin();
    for(; it!=gr[v].end(); ++it) {
        if(!used[it->to] && it->cap>0) {
            int d = dfs( it->to, G, MIN(f, it->cap), gr, used);
            if(d>0) {
                it->cap -= d;
                gr[it->to][it->rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow( int S, int G, vector<vector<Edge> >& g)
{
    int flow=0;
    while(1) {
        vector<int> used(g.size(), 0);
        int f = dfs(S, G, INF, g, used);
        if(f==0) break;
        flow += f;
    }
    return flow;
}


int main(int argc, char* argv[])
{
    int n;
    scanf("%d", &n);

    vector<vector<Edge> > gr(n*2+2);
    vector<int> a(n),b(n),c(n),d(n);

    int S=n*2;
    int G=n*2+1;
    int i;
    for(i=0; i<n; i++) {
        scanf("%d%d", &a[i], &b[i]);
        AddEdge(S, i, 1, gr);
    }
    for(i=0; i<n; i++) {
        scanf("%d%d", &c[i], &d[i]);
        AddEdge(n+i, G, 1, gr);
    }

    int j;
    for(i=0; i<n; i++) {
        for(j=0; j<n; j++) {
            if(a[i]<c[j] && b[i]<d[j]) {
                AddEdge(i, n+j, 1, gr);
            }
        }
    }

    int f=max_flow(S, G, gr);
    printf("%d\n", f);

    return 0;
}

