int main() {

  int N = ii();
  vector<int> As;
  vector<int> Bs;
  vector<int> Cs;
  vector<int> Ds;

  rep(i, N){
    As.PB(ii());
    Bs.PB(ii());
  }
  rep(i, N){
    Cs.PB(ii());
    Ds.PB(ii());
  }


  //最大二部マッチングをネットワークフロー問題（最大流問題）に帰着させて解く

  //グラフの定義（S, Tを合わせたノード数を引数に）
  int G1num = N; //グループ1のノード数
  int G2num = N; //グループ2のノード数
  Graph graph(G1num + G2num + 2);

  //追加するS, Tのindexを決める
  //グラフデータの最後2つに入れるようにすればいい
  int S_idx = G1num + G2num;
  int T_idx = G1num + G2num + 1;

  //グラフに枝を張る

  //まず、Sから全てのG1ノードへ、全てのG2ノードからTへと枝を張る
  //3つ目の引数は枝ごとの最大容量であり、最大二部マッチングでは常に1とする
  rep(g1_idx, G1num){
    graph.addedge(S_idx, g1_idx, 1);
  }
  rep(g2_idx, G2num){
    //G2のidxはG1のノード数だけ後ろにズレるので注意
    graph.addedge(G1num + g2_idx, T_idx, 1);
  }

  //G1の各ノードとG2の各ノードのうち、マッチングできるところに枝を張る
  //今回は、x,y座標ともにg1<g2となることがマッチングの条件
  rep(g1_idx, G1num){
    rep(g2_idx, G2num){
      if (As[g1_idx] < Cs[g2_idx] && Bs[g1_idx] < Ds[g2_idx]){
        //G2のidxはG1のノード数だけ後ろにズレるので注意
        graph.addedge(g1_idx, G1num + g2_idx, 1);
      }
    }
  }

  //最大流を求める
  FLOW ans = Dinic(graph, S_idx, T_idx);

  oi(ans);



// -- main() end -- //
}

