    vector<P> a(n),b(n);
    for(int i=0;i<n;i++){
       int x,y;
       cin>>x>>y;
       a.at(i)=P(x,y);
    }
    for(int i=0;i<n;i++){
       int x,y;
       cin>>x>>y;
       b.at(i)=P(x,y);
    }
    sort(a.begin(),a.end(),greater<P>());
    vector<bool> b1(n,true);
    int count=0;
  for(int i=0;i<n;i++){
      priority_queue<P> u;
      for(int j=0;j<n;j++){
          if(b1.at(j)&&a.at(i).fi<b.at(j).fi&&a.at(i).se<b.at(j).se){
              int x=b.at(j).fi,y=b.at(j).se;
              u.push(P(x,y));
          }
      }
      if(u.size()==0)continue;
      count++;
      P c=u.top();
      int c1=c.fi;
      int c2=c.se;
      int check;
      for(int k=0;k<n;k++){
          if(b.at(k).fi==c2&&b.at(k).se==c1){
              check=k;
              break;
          }   
      }
     b1.at(check)=false;
  }
cout<<count<<endl;
}

