#define FOR(i,c) for(__typeof((c).begin())i=(c).begin(),ie=(c).end();i!=ie;++i)
#define ALL(c) (c).begin(), (c).end()

int main() {
    int n;cin>>n;
    vector<ii> r(n), b(n);
    REP(i,n) {
        int x,y;cin>>x>>y;
        r[i] = make_pair(x,y);
    }
    REP(i,n) {
        int x,y;cin>>x>>y;
        b[i] = make_pair(x,y);
    }

    auto cmpX = [](const ii& a, const ii& b){
        return a.first < b.first;
    };
    auto cmpY = [](const ii& a, const ii& b){
        return a.second < b.second;
    };

