template<typename T> struct MaxFlow {
	const T INF =  1LL<<59; //1 <<29;
	const int V;
	struct Edge { int to, rev; T cap; };
	vector<vector<Edge>> g;
	vector<int>  iter, level;
	/// 初期化
	void init() { for(int i = 0; i < V; i++) g[i].clear(); }
	MaxFlow(int su) : V(su), g(V) { };
	/// 有向辺の追加
	void add(int from, int to, T cap) {
		g[from].push_back(Edge{to, (int)g[to].size(), cap});
		g[to].push_back(Edge{from, (int)g[from].size()-1, 0});
	}
	/// 無向辺の追加
	void add_multi(int from, int to, T cap) {
		g[from].push_back(Edge{to, (int)g[to].size(), cap});
		g[to].push_back(Edge{from, (int)g[from].size()-1, cap});
	}
	void bfs(int s) {
		fill(level.begin(), level.end(), -1);
		queue<int> que;
		level[s] = 0;
		que.push(s);
		for(;!que.empty();) {
			int v = que.front(); que.pop();
			for(const Edge& e: g[v]) if(e.cap > 0){
				if (level[e.to] < 0) {
					level[e.to] = level[v] + 1;
					que.push(e.to);
				}
			}
		}
	}
	T dfs(int v, int t, T f) {
		if (v == t) return f;
		for(int &i = iter[v]; i < (int)g[v].size(); i++) {
			Edge &e = g[v][i];
			if (e.cap <= 0) continue;
			if (level[v] < level[e.to]) {
				T d = dfs(e.to, t, min(f, e.cap));
				if (d <= 0) continue;
				e.cap -= d;
				g[e.to][e.rev].cap += d;
				return d;
			}
		}
		return 0;
	}
	// sからtへの最大流を返す
	T exec(int s, int t) {
		level.assign(V, -1);
		iter.assign(V, 0);
		T flow = 0;
		for(;;) {
			bfs(s);
			if (level[t] < 0) return flow;
			fill(iter.begin(), iter.end(), 0);
			T f;
			for(;(f = dfs(s, t, INF)) > 0;) flow += f;
		}
	}
};

int main()
{

	cin.tie(0); ios_base::sync_with_stdio(false);

	int n; cin >>n;
	MaxFlow<ll> mkf(2*n+4);
	VI a(n), b(n), c(n), d(n);
	rep(i,n) cin >>a[i] >>b[i];
	rep(i,n) cin >>c[i] >>d[i];

	rep(i,n) rep(j,n){
		if(a[i] < c[j] && b[i] < d[j]){
			mkf.add(i,n+j, 1);
		}
	}

	int vs=2*n+2, vt=2*n+3;
	rep(i,n){
		mkf.add(vs,i, 1 );
		mkf.add(n+i, vt,1 );
	}
	auto ans = mkf.exec(vs, vt);
	cout << ans <<"\n";
	return 0;

}

