int fa(int x, int xm = -1){
	it.at(x) = 1;
	if(x == 2*n+1){
		f = 1;
		if(xm != -1){
			c.at(xm).at(x) -= ma;
			c.at(x).at(xm) += ma;
		}
		return 0;
	}
	rep(i, g.at(x).size()){
		if(it.at(g.at(x).at(i)) == 0 && c.at(x).at(g.at(x).at(i)) != 0 && f == 0){
			if(ma > c.at(x).at(g.at(x).at(i))) ma = c.at(x).at(g.at(x).at(i));
			fa(g.at(x).at(i), x);
		}
	}
	if(f == 1){
		if(xm != -1){
			c.at(xm).at(x) -= ma;
			c.at(x).at(xm) += ma;
		}
	}
	return 0;
}

