class ABC091C_ball {
public:
	int px = 0;
	int py = 0;
	bool picked = false;
	bool used = true;

	bool isSmall(const ABC091C_ball& a) {
		return ((px < a.px) && (py < a.py));
	}

	static bool asc_dist(const ABC091C_ball& a, const ABC091C_ball& b) {
		return(a.px * a.py < b.px * b.py);
	}
};

static void ABC091C_2DPlane2NPoints()
{
	int N;
	get1int(N);

	auto blues = new ABC091C_ball[N + 1];
	for (int i = 0; i < N; i++) {
		get2int(blues[i].px, blues[i].py);
	}

	auto reds = new ABC091C_ball[N + 1];
	for (int i = 0; i < N; i++) {
		get2int(reds[i].px, reds[i].py);
	}

	std::sort(blues, blues + N, ABC091C_ball::asc_dist);
	std::sort(reds, reds + N, ABC091C_ball::asc_dist);

	auto smaller = new bool[N];
	std::vector<ABC091C_ball> farReds;
	for (int i = 0; i < N; i++) {
		smaller[i] = false;
		for (int j = 0; j < N; j++) {
			if (blues[i].isSmall(reds[j])) {
				smaller[i] = true;
