    for(i=0; i<N; i++){
        cin >> c >> d;
        blue.push_back(make_pair(c,d));
    }

    //calc
    vector<int> G[N];//r->b
    vector<int> G_sub[N];//b->r
    for(i=0; i<N; i++){
        for(j=0; j<N; j++){
            if(red[i].first<blue[j].first&&red[i].second<blue[j].second){
                G[i].push_back(j);
                G_sub[j].push_back(i);
            }
        }
    }
    int counta=0;
    while(1){
        vector<pair<int, int> > vec;
        for(i=0; i<N; i++){
            if(G[i].size()>0){
                vec.push_back(make_pair(G[i].size(),i));
            }
        }
        if(vec.empty()){
            break;
        }
        counta++;
        sort(vec.begin(),vec.end());
        i=vec[0].second;
        j=G[i][0];
        G[i].erase(G[i].begin(),G[i].end());
        for(k=0; k<N; k++){
            for(l=0; l<G[k].size(); l++){
                if(G[k][l]==j){
                    G[k].erase(G[k].begin()+l);
                    break;
                }
            }
        }
    }
    int counta_sub=0;
    while(1){
        vector<pair<int, int> > vec;
        for(i=0; i<N; i++){
            if(G_sub[i].size()>0){
                vec.push_back(make_pair(G_sub[i].size(),i));
