        counta_sub++;
        sort(vec.begin(),vec.end());
        i=vec[0].second;
        j=G_sub[i][0];
        G_sub[i].erase(G_sub[i].begin(),G_sub[i].end());
        for(k=0; k<N; k++){
            for(l=0; l<G_sub[k].size(); l++){
                if(G_sub[k][l]==j){
                    G_sub[k].erase(G_sub[k].begin()+l);
                    break;
                }
            }
        }
    }
    //answer
    cout << max(counta,counta_sub) << endl;
    system("pause");
    return 0;
}

