        rep(j, n) {
            p2 = blue[j];

            if (blueTable[j] == 1) continue;

            if (p1.first < p2.first && p1.second < p2.second) {
                diff = min(p2.first - p1.first, p2.second - p1.second);

                if (diff < m) {
                    index = j;
                    m = diff;
                }
            }
        }

        if (index != -1) {
            ans++;

            blueTable[index] = 1;
        }
    }

    Out(ans);

