struct edge{
	ll cap;
	int rev;
	int to;
};

vector<edge> g[225];
bool used[225];

void make_edge(int u, int v){
	edge e;
	e.cap = 1ll; e.rev = g[v].l_ength(); e.to = v;
	g[u].push_back(e);
	e.cap = 0ll; e.rev = g[u].l_ength()-1; e.to = u;
	g[v].push_back(e);
}

ll dfs(int s, int t, ll cap){
	int i;
	ll d;
	if(s==t){
		return cap;
	}
	used[s] = true;
	for(i=(g[s].l_ength()-1); i>=0; --i){
		if(used[g[s][i].to]){
			continue;
		}
		if(g[s][i].cap>0){
			d = dfs(g[s][i].to,t,min(cap,g[s][i].cap));
			if(d>0){
				g[s][i].cap -= d;
				g[g[s][i].to][g[s][i].rev].cap += d;
				return d;
			}
		}
	}
	return 0ll;
}

