struct edge {
  int target;
  int capacity;
  int reversal;
};

void add_edge(vector<vector<edge>> &g, int source, int target, int capacity) {
  g[source].push_back((edge){target, capacity, (int)g[target].size()});
  g[target].push_back((edge){source, 0, (int)g[source].size()-1});
}

int dfs(vector<vector<edge>> &g, vector<bool> &used, int vertex, int target, int flow) {
  if(vertex == target) return flow;
  used[vertex] = true;
  for(int i = 0; i < (int)g[vertex].size(); i++) {
    edge &e = g[vertex][i];
    if(!used[e.target] && e.capacity > 0) {
      int d = dfs(g, used, e.target, target, min(flow, e.capacity));
      if(d > 0) {
        e.capacity -= d;
        g[e.target][e.reversal].capacity += d;
        return d;
      }
    }
  }
  return 0;
}

int max_flow(vector<vector<edge>> &g, int source, int target) {
  int max_flow = 0;
  while(true) {
    vector<bool> used(g.size(), false);
    int flow = dfs(g, used, source, target, INF);
    if(flow == 0) return max_flow;
    max_flow += flow;
  }
}

