template <typename flow_t>
struct Dinic{
private:
    const flow_t INF;
    struct edge{
        int to;
        flow_t cap;
        int rev;
        bool isrev;
        int idx;
    };
    VV<edge> graph;
    V<int> min_cost, iter;

    bool bfs(int s, int t){
        min_cost.assign(SZ(graph), -1);
        queue<int> que;
        min_cost[s] = 0;
        que.push(s);
        while(!que.empty() and min_cost[t] == -1){
            int p = que.front(); que.pop();
            for(auto &e : graph[p]){
                if(e.cap > 0 and min_cost[e.to] == -1){
                    min_cost[e.to] = min_cost[p] + 1;
                    que.push(e.to);
                }
            }
        }
        return min_cost[t] != -1;
    }

    flow_t dfs(int idx, const int t, flow_t flow){
        if(idx == t) return flow;
        for(int &i = iter[idx]; i < SZ(graph[idx]); i++){
            edge &e = graph[idx][i];
            if(e.cap > 0 and min_cost[idx] < min_cost[e.to]){
                flow_t d = dfs(e.to, t, min(flow, e.cap));
                if(d > 0){
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

public:
    Dinic(int v = 0) : INF(numeric_limits<flow_t>::max()), graph(v) {}

    void add_edge(int from, int to, flow_t cap, int idx = -1){
        graph[from].eb(edge{to, cap, SZ(graph[to]), false, idx});
        graph[to].eb(edge{from, 0, SZ(graph[from]) - 1, true, idx});
    }

    flow_t max_flow(int s, int t){
        flow_t flow = 0;
        while(bfs(s, t)){
            iter.assign(SZ(graph), 0);
            flow_t f = 0;
            while((f = dfs(s, t, INF)) > 0) flow += f;
        }
        return flow;
    }

    void output(){
        for (int i = 0; i < SZ(graph); i++){
            for(auto &e : graph[i]){
                if(e.isrev) continue;
                auto &rev_e = graph[e.to][e.rev];
                cout << i << "->" << e.to << " (flow:" << rev_e.cap << "/" << e.cap + rev_e.cap << ")\n";
                }
        }
    }

    void resize(int x){ graph.resize(x);}

    int size(){return SZ(graph);}
};

int main(){
    INT(n);

    Dinic<int> dinic(2 * n + 2);

    int s = 2 * n, t = 2 * n + 1;
    REP(i, n) dinic.add_edge(s, i, 1);
    REP(i, n) dinic.add_edge(i + n, t, 1);

    V<pii> ab(n), cd(n);
    REP(i, n) cin >> ab[i];
    REP(i, n) cin >> cd[i];

    REP(i, n) REP(j, n){
        auto [a, b] = ab[i];
        auto [c, d] = cd[j];
        if(a < c and b < d) dinic.add_edge(i, j + n, 1);
    }

    print(dinic.max_flow(s, t));

    return 0;
}

