class BiparateMatching {
 public:
  vector<vector<ll> > G;
  ll V;
  vector<ll> match;
  vector<bool> used;

  BiparateMatching(ll V) {
    this->V = V;
    G = vector<vector<ll> >(V);
    match = vector<ll>(V);
    used = vector<bool>(V);
  }

  void addEdge(ll from, ll to) {
    G[from].push_back(to);
    G[to].push_back(from);
  }

  bool dfs(int v) {
    used[v] = true;
    for (int i = 0; i < G[v].size(); ++i) {
      ll u = G[v][i];
      ll w = match[u];
      if (w < 0 || !used[w] && dfs(w)) {
        match[v] = u;
        match[u] = v;
        return true;
      }
    }
    return false;
  }

  ll solve() {
    ll res = 0;
    fill(match.begin(), match.end(), -1);
    for (ll v = 0; v < V; ++v) {
      if (match[v] < 0) {
        fill(used.begin(), used.end(), 0);
        if (dfs(v)) {
          ++res;
        }
      }
    }
    return res;
  }
};

