	std::sort(v.begin(), v.end());
	for (int i = 0;i < n * 2 - 1;i++) {
		int x = v[i].first, y = v[i].second;
		P p = std::make_pair(INF, INF);
		if (!r[x][y])continue;
		for (int j = i + 1;j < n * 2;j++) {
			int bx = v[j].first, by = v[j].second;
			if (r[bx][by])continue;
			if (b[bx][by] && y < by&&by < p.second) {
				if(p.first!=INF)b[p.first][p.second] = true;
				b[bx][by] = false;
				p = std::make_pair(bx, by);
			}
		}
		if (p.first != INF)ans++;
	}
	std::cout << ans << std::endl;
}

