struct edge{ll to,cap,rev;};
vector<edge> G[205];
bool used[205];
void add_edge(ll from,ll to,ll cap){
	ll g1=G[to].size();
	ll g2=G[from].size()-1;
	G[from].push_back((edge){to,cap,g1});
	G[to].push_back((edge){from,0,g2});
}
ll dfs(ll v,ll t,ll f){
	if(v==t) return f;
	used[v]=true;
	for(ll i=0; i<G[v].size(); i++){
		edge &e=G[v][i];
		if(!used[e.to]&&e.cap>0){
			ll d=dfs(e.to,t,min(f,e.cap));
			if(d>0){
				e.cap-=d;
				G[e.to][e.rev].cap+=d;
				return d;
			}
		}
	}
	return 0;
}
ll max_flow(ll s,ll t){
	ll flow=0;
	for(;;){
		memset(used,0,sizeof(used));
		ll f=dfs(s,t,mod);
		if(f==0) return flow;
		flow+=f;
	}
}

