void is_good(ll idx1, ll idx2){
    bool x_judge = red[idx1].e2 < blue[idx2].e1;
    bool y_judge = red[idx1].e1 < blue[idx2].e2;
    if (x_judge && y_judge) good[idx1][idx2] = true;
}

int main(void){
    in1(n);
    rep(i, n){
        in2(a, b);
        red.pb(mp(b, a));
    }
    rep(i, n){
        in2(c, d);
        blue.pb(mp(c, d));
    }

    sort(all(blue));
    sort(rall(red));

    rep(i, n) rep(j, n) is_good(i, j);
    mll cnt;
    rep(bi, n) rep(ri, n){
        okay = true;
        items(kv, cnt) if (kv.e1 == ri){okay = false; break;}
        if (okay && good[ri][bi]){
            answer ++;
            cnt[ri] = 1;
            break;
        }
    }

    prl(answer);

    return 0;
}

