template <class T = long long>
struct BIT {
	//もとの配列a[i]はBIT内部ではvec[i+1]に対応
	vector<T> vec;
	int n;
	int pw2 = 1;  // n以下の最大の2冪
	BIT(int sz) : vec(sz + 1, 0), n(sz) {
		while(pw2 * 2 <= n) {
			pw2 *= 2;
		}
	}
	//元の値に足す 更新は不可
	void add(int place, T val, bool index = 0) {
		if(!index) place++;
		for(int x = place; x <= n; x += x & -x) vec[x] += val;
	}
	//端からの合計値計算
	T sum0(int a, bool index = 0) {
		if(index) a--;
		T ret = 0;
		for(int x = a; x > 0; x -= x & -x) ret += vec[x];
		return ret;
	}
	//クエリ
	T sum(int a, int b) { return sum0(b) - sum0(a); }
	//更新 クエリと併用で可能にした
	void update(int place, T val, bool index = 0) {
		T old = sum(place, place + 1);
		add(place, val - old);
		return;
	}
	int LowerBound(T val, int start = 0) {
		// startから足していって初めてval以上になる箇所を0-indexedで返す
		// 要素が全て非負のときのみ
		// [start, ret) >= val を満たすstart以上の最小のret
		// どこまで足してもvalに達しないときはn+1を返す
		if(val <= 0) return start;
		val += sum0(start);
		int x = 0;
		for(int k = pw2; k > 0; k /= 2) {
			if(x + k <= n && vec[x + k] < val) {
				val -= vec[x + k];
				x += k;
			}
		}
		return max(start, x + 1);
	}
	int UpperBound(T val, int start = 0) {
		// startから足していって初めてvalより大になる箇所を0-indexedで返す
		// 要素が全て非負のときのみ
		// [start, ret) > val を満たすstart以上の最小のret
		// どこまで足してもvalより大に達しないときはn+1を返す
		if(val < 0 /*LBとの変更点*/) return start;
		val += sum0(start);
		int x = 0;
		for(int k = pw2; k > 0; k /= 2) {
			if(x + k <= n && vec[x + k] <= /*LBとの変更点*/ val) {
				val -= vec[x + k];
				x += k;
			}
		}
		return max(start, x + 1);
	}
};

template <class T = long long>
struct edge {
	T cap;
	int from;
	int to;
	int rev;  // fromの方の配列で逆辺が何番目に存在するか
	bool operator<(const edge a) const {
		if(cap != a.cap) return cap < a.cap;
		if(from != a.from) return from < a.from;
		return to < a.to;
	}
	bool operator>(const edge a) const {
		if(cap != a.cap) return cap > a.cap;
		if(from != a.from) return from > a.from;
		return to > a.to;
	}
};

template <class T = long long>
class Dinic {
   private:
	int ver;  //頂点数
	vector<vector<edge<T>>> edges;
	vector<int> level;
	vector<int> chk;

   public:
	Dinic(int vertex) : ver(vertex), edges(vertex), level(vertex, -1), chk(vertex, 0) {}

	//辺と逆辺の追加 (0-indexed)
	void update(int from, int to, T cap = 1) {
		edge<T> e;
		e.cap = cap;
		e.from = from;
		e.to = to;
		e.rev = (int)edges[to].size();
		edges[from].push_back(e);

		e.cap = (T)0;
		swap(e.to, e.from);
		e.rev = (int)edges[from].size() - 1;
		edges[to].push_back(e);
	}

	//入力受取 (1-indexed)
	void input(int edge_num, int index = 1) {
		for(int i = 0; i < edge_num; i++) {
			int a;
			int b;
			T cap;
			cin >> a >> b >> cap;
			a -= index;
			b -= index;
			update(a, b, cap);
		}
	}

   private:
	//有効な辺のみを用いた幅優先探索で距離を求める
	void bfs(int s) {
		level.assign(ver, -1);
		level[s] = 0;
		queue<int> q;
		q.push(s);
		while(!q.empty()) {
			int now = q.front();
			q.pop();
			for(auto &e : edges[now]) {
				if(level[e.to] >= 0) continue;
				if(e.cap <= 0) continue;
				level[e.to] = level[now] + 1;
				q.push(e.to);
			}
		}
		return;
	}

	//流せる辺を探す
	T dfs(int now, int t, T f) {
		if(now == t) return f;
		for(int i = chk[now]; i < (int)edges[now].size(); i++) {
			auto &e = edges[now][i];
			if(level[now] + 1 != level[e.to] || e.cap <= 0) {
				chk[now]++;
				continue;
			}
			T k = dfs(e.to, t, min(f, e.cap));
			if(k > 0) {
				e.cap -= k;
				edges[e.to][e.rev].cap += k;
				return k;
			}
			chk[now]++;
		}
		return (T)0;
	}

   public:
	T maxflow(int s, int t) {
		T flow = 0;
		const T INF = 3e16;	 // T == int だとバグる
		while(1) {
			bfs(s);
			if(level[t] < 0) return flow;
			for(int i = 0; i < ver; i++) chk[i] = 0;
			T fl = 1;
			while(fl > 0) {
				fl = dfs(s, t, INF);
				flow += fl;
			}
		}
	}
};

