class Edge {
public:
    ll t, cap, rev;
    Edge(ll t, ll cap, ll rev): t(t), cap(cap), rev(rev) {}
};

ll N;
vector<Edge> g[222];
ll used[222];

ll dfs(ll v, ll goal, ll f) {
    if(v==goal) return f;
    used[v]=1;
    ll i;
    for(i=0; i<g[v].size(); i++) {
        Edge &e=g[v][i];

        if(!used[e.t] && e.cap>0) {
            ll d=dfs(e.t, goal, min(f, e.cap));
            if(d>0) {
                e.cap-=d;
                g[e.t][e.rev].cap+=d;
                return d;
            }
        }
    }

    return 0;   //goalまでのパスが見つからなかったとき
}

void addEdge(ll from, ll to, ll cap) {
    g[from].pb(Edge(to, cap, g[to].size()));
    g[to].pb(Edge(from, 0, g[from].size()-1));
}

int main(void) {
    cin >> N;
    ll i, j;
    ll a[222], b[222];

    for(i=0; i<N; i++) {
        cin >> a[i] >> b[i];
        addEdge(N*2, i, 1);     //N*2番目の頂点をsとした
    }

    for(i=N; i<N*2; i++) {
        cin >> a[i] >> b[i];
        addEdge(i, N*2+1, 1);   //N*2+1番目の頂点をtとした
    }

    for(i=0; i<N; i++) {
        for(j=N; j<N*2; j++) {
            if(a[i]<a[j] && b[i]<b[j]) addEdge(i, j, 1);
        }
    }


    ll flow=0;
    while(1) {
        memset(used, 0, sizeof(used));

        ll f=dfs(N*2, N*2+1, INF);  //s(N*2番目)からt(N*2+1番目)に流す
        if(f>0) flow+=f;
        else break;
    }

    pt(flow);
}

