#define FOR(i, m, n) for(int i = m; i < n; i++)
#define IFOR(i, m, n) for(int i = n - 1; i >= m; i-- )
#define REP(i, n) FOR(i,0,n)
#define IREP(i, n) IFOR(i,0,n)
#define FOREACH(x,a) for(auto& (x) : (a) )
#define ALL(v) (v).begin(), (v).end()
using namespace std;
typedef long long ll;
const ll INF = 1e18;
/* テンプレートここまで */
ll dfs(ll v, vector<ll>& visited, vector<ll>& matched, vector<vector<ll>>& edges){
  FOREACH(u, edges[v]){
    //uが通過済みなら，次のノードを探索する
    if(find(ALL(visited), u) != visited.end()) continue;
    visited.push_back(u);
    //増加道がある
    if(matched[u] == -1 || dfs(matched[u], visited, matched, edges)){
      matched[u] = v;
      return 1;
    }
  }
  //増加道がない
  return 0;
}

int main() {
  ll N;
  cin >> N;
  vector<vector<ll>> edges(N);
  vector<pair<ll,ll> > ab(N), cd(N);
  REP(i, N){
    cin >> ab[i].first >> ab[i].second;
  }
  REP(i, N){
    cin >> cd[i].first >> cd[i].second;
  }

  REP(i, N){
    REP(j, N){
      if(ab[i].first < cd[j].first && ab[i].second < cd[j].second){
        edges[i].push_back(j);
      }
    }
  }

  vector<ll> matched(N,-1);
  ll ans = 0;
  REP(i, N){
    vector<ll> visited;
    ans += dfs(i, visited, matched, edges);
  }
  cout << ans << endl;
}

