using namespace std;

int f(vector<vector<int>> const& cs, int i, vector<bool>& used) {
    if (cs.size() == i) return 0;
    if (cs[i].empty()) return f(cs, i + 1, used);
    bool ok = false;
    for (auto j: cs[i]) {
        if (!used[j]) {
            ok = true;
            break;
        }
    }
    if (!ok) {
        return f(cs, i+1, used);
    }
    int max = 1;
    for (auto j: cs[i]) {
        if (used[j]) {
            continue;
        }
        used[j] = true;
        int n = f(cs, i+1, used) + 1;
        used[j] = false;
        if (n > max) {
            max = n;
        }
    }
    return max;
}

