std::bitset<NMAX> vis;
array<int, NMAX> match;

bool augment(int u){
  if (vis[u])
    return(false);
  vis[u] = true;
  for (int v : adj[u]){
    if (match[v] == -1 || augment(match[v])){
      match[v] = u;
      return(true);
    }
  }
  return(false);
}


