		for (int j = 0;j < n;j++) {
			ll bx = b[j].first, by = b[j].second;
			if (used[bx][by])continue;
			if (bx > x&&bx<=p.first) {
				if (by > y&&p.second <= by) {
					if (bx - x >= p.second - y) {
						used[bx][by] = true;
						if (p.first != INF)used[p.first][p.second] = false;
						p = std::make_pair(bx, by);
					}
				}
				else if(by>y&&p.second>=by) {
					if (p.first != INF)used[p.first][p.second] = false;
					p = std::make_pair(bx, by);
					used[bx][by] = true;
				}
			}
			else if (by > y&&by<=p.second) {
				if (bx > x&&p.first <= bx) {
					if (by - y >= p.first - x) {
						if (p.first != INF)used[p.first][p.second] = false;
						used[bx][by] = true;
						p = std::make_pair(bx, by);
					}
				}
				else if (bx>x&&p.first>=bx) {
					if (p.first != INF)used[p.first][p.second] = false;
					p = std::make_pair(bx, by);
					used[bx][by] = true;
				}
			}
		}
		if (p.first != INF)ans++;
	}
	std::cout << ans << std::endl;
}

