const ll INF = 1LL << 50;

struct edge {
  ll to, cap, rev;
};

vector<vector<edge>> to;
vector<bool> used;
void addE(ll u, ll v, ll w) {
  to[u].push_back({v, w, (ll)to[v].size()});
  to[v].push_back({u, 0, (ll)to[u].size() - 1});
}

ll dfs(ll u, ll t, ll f) {
  assert(f > 0);
  if (u == t) return f;
  used[u] = true;
  for (edge& e : to[u]) {
    if (used[e.to] || e.cap <= 0) continue;
    ll d = dfs(e.to, t, min(f, e.cap));
    if (d == 0) continue;
    e.cap -= d;
    to[e.to][e.rev].cap += d;
    return d;
  }
  return 0;
}

