bool nakayoshi(vector<int> a,vector<int> b)
{
  return a[0]<b[0] and a[1]<b[1];
}

int main()
{
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  vector<vector<int>> p(n+2,vector<int>(2)),q(n+2,vector<int>(2));;
  for(int i=1;i<n+1;i++)
  {
    cin >> p[i][0]>>p[i][1];
  }
  for(int i=1;i<n+1;i++)
  {
    cin >> q[i][0]>>q[i][1];
  }
  vector<vector<int>> edge(2*n+2,vector<int>(2*n+2)),qedge(2*n+2,vector<int>(2*n+2));
  for(int i=1;i<n+1;i++)
  {
    for(int j=1;j<n+1;j++)
    {
      edge[i][n+j]=nakayoshi(p[i], q[j]);
      qedge[i][j]=nakayoshi(p[i], q[j]);
    }
  }
  for(int i=1;i<n+1;i++){edge[0][i]=true;edge[n+i][2*n+1]=true;}
  do{
      queue<int> que{};
      que.push(0);
      vector<int> flag(2*n+2);
      for(int i=0;i<2*n+2;i++){flag[i]=-1;}
      flag[0]=0;
      while(que.size()>0)
      {
        int tmp;
        tmp=que.front();
        que.pop();
        if(tmp==2*n+1){que.push(-1);break;}
        for(int i=0;i<2*n+2;i++)
        {
          if(edge[tmp][i] and flag[i]==-1 ){que.push(i);flag[i]=tmp;}
        }

      }
      if(que.empty()){break;}
      que.pop();
      vector<int>track;
      track.clear();
      int i=2*n+1;
      track.push_back(i);
      edge[i][flag[i]]=!edge[i][flag[i]];
      edge[flag[i]][i]=!edge[flag[i]][i];
      for(int j=0;j<3*n;j++)
      {

        i=flag[i];
        track.push_back(i);


        if(i==0){break;}

        edge[i][flag[i]]=!edge[i][flag[i]];
        edge[flag[i]][i]=!edge[flag[i]][i];
      }

  }while(1);
  int res=0;
  for(int i=1;i<n+1;i++){res+=!edge[0][i];}
  cout <<res<<endl;
  return 0;





}

