int N, A[205], B[205], Count[205];
vector <int> Graph[205];

int main(){
  scanf("%d", &N);
  for (int i = 0; i < N; i++){
    scanf("%d%d", A + i, B + i);
  }

  for (int i = 100; i < N + 100; i++){
    scanf("%d%d", A + i, B + i);
    for (int j = 0; j < N; j++){
      if (A[j] < A[i] && B[j] < B[i]){
        Graph[i].push_back(j);
        Graph[j].push_back(i);
        Count[i]++; Count[j]++;
      }
    }
  }

  int ans = 0, cnt = 0;
  while (cnt < N){
    cnt++;

    priority_queue <Pii, vector<Pii>, greater<Pii> > que;
    for (int i = 0; i < N; i++){
      if (Count[i] == 0) continue;
      que.push({Count[i], i});
    }
    for (int i = 100; i < N + 100; i++){
      if (Count[i] == 0) continue;
      que.push({Count[i], i});
    }

    if (que.empty()) break;

    int edge = que.top().se, next = -1, num = 1e9;
    Count[edge] = 0;

    for (int i = 0; i < Graph[edge].size(); i++){
      if (Count[Graph[edge][i]] == 0) continue;

      if (Count[Graph[edge][i]] < num){
        num = Count[Graph[edge][i]];
        next = Graph[edge][i];
      }
    }
    if (next == -1) continue;
    ans++;
    Count[next] = 0;
  }
  cout << ans << endl;


  return 0;
}

