vector<vector<int>> L(200);
vector<int> match(200);
vector<bool> Visited(200);
bool DFS(int v)
{
	Visited[v]=true;

	for(int i=0; i<(int)L[v].size(); i++){
		int u=L[v][i], w=match[u];
		if(w<0||!Visited[w]&&DFS(w)){
			match[v]=u; match[u]=v;
			return true;
		}
	}
	return false;
}
int bipartite_matching(int n)
{
	int res=0;

	for(int i=0; i<200; i++) match[i]=-1;

	for(int v=0; v<n; v++){
		if(match[v]<0){
			for(int i=0; i<200; i++) Visited[i]=false;

			if(DFS(v)) res++;
		}
	}
	return res;
}
