using namespace std;

void solve() {
    int n;
    cin >> n;
    set<array<int, 2>> r;
    r.insert({-1, -1});
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        r.insert({x, y});
    }
    vector<array<int, 2>> b(n);
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        b[i] = {x, y};
    }
    sort(b.begin(), b.end());
    int ans = 0;
    for (auto x : b) {
        auto t = r.end();
        t--;
        while(t != r.begin() && ((*t)[0] >= x[0] || (*t)[1] >= x[1])) {
            t--;
        }
        if(t != r.begin()) {
            ans++;
            int mn = (x[0] - (*t)[0]) + (x[1] - (*t)[1]);
            auto p = t;
            while(t != r.begin()) {
                int tmn = (x[0] - (*t)[0]) + (x[1] - (*t)[1]);
                if(tmn < mn) {
                    p = t;
                    mn = tmn;
                }
                t--;
            }
            r.erase(p);
        }
    }
    cout << ans;
}


