                }
            }
        }

        // 赤い点が見つかったなら ペアを作る 赤い点を使えなくする
        if (index_greedy_red_point != -1)
        {
            reds[index_greedy_red_point] = {INF, INF};
            sort(reds.begin(), reds.end());

