			if (a[j].first < b[i].first && a[j].second < b[i].second) {
				add_edge(g, j + 1, i + n + 1, 1, true, 0);
			}
		}
	}

	REP(i, n) {
		add_edge(g, 0, i+1, 1, true, 0);
		add_edge(g, i + n + 1, 2 * n + 1, 1, true, 0);
	}

