int main(){
    int N; cin >> N;
    vector<pair<int, int> > red(N), blue(N);
    for(size_t i = 0; i < N; i++)
    {
        cin >> red[i].first >> red[i].second;
    }
    for(size_t i = 0; i < N; i++)
    {
        cin >> blue[i].first >> blue[i].second;
    }
    sort(red.begin(), red.end());
    sort(blue.begin(), blue.end());
    int ret = 0;
    for(size_t i = 0; i < N; i++)
    {
        auto it = lower_bound(red.begin(), red.end(), blue[i]);
        if (it == red.begin())
            continue; // no pair
        it--;
        bool found = false;
        auto max_second_it = it;
        int max_second = -1;
        while(it != red.begin()-1){
            it--;
            if (it->second < blue[i].second && it->second > max_second) {
                found = true;
                max_second = it->second;
                max_second_it = it;
            }
        }
        if(found){
            ret++;
            red.erase(max_second_it);
        }
    }
    cout << ret << endl;
    return 0;
}

