using namespace std;

typedef long long ll;
typedef pair<ll,ll> P;

std::vector<P> v;

struct edge{int to,cap,rev;};
vector<edge> G[MAX_V];
bool used[MAX_V];

void add_edge(int from,int to,int cap){
	G[from].push_back((edge){to,cap,(int)G[to].size()});
	G[to].push_back((edge){from,0,(int)G[from].size()-1});
}

int dfs(int v, int t,int f){
	if(v == t) return f;
	used[v] = true;
	for (int i = 0; i < G[v].size(); ++i)
	{
		edge &e = G[v][i];
		if(!used[e.to] && e.cap > 0){
			int d = dfs(e.to,t,min(f,e.cap));
			if(d > 0){
				e.cap -= d;
				G[e.to][e.rev].cap += d;
				return d;
			}
		}
	}
	return 0;
}
int max_flow(int s, int t){
	int flow = 0;
	for(;;){
		memset(used,0,sizeof(used));
		int f = dfs(s,t,INF);
		if(f == 0) return flow;
		flow += f;
	}
}
int main(){
	int V;
	cin >> V;
	for (int i = 0; i < V; ++i)
	{
		int a,b;
		cin >> a >> b;
		v.push_back(P(a,b));
		add_edge(0,i+1,1);
	}
	for (int i = 0; i < V; ++i)
	{
		int a,b;
		cin >> a >> b;
		for (int j = 0; j < V; ++j)
		{
			if(v[j].first < a && v[j].second < b){
				add_edge(j+1,V+i+1,1);
				// cout << j+1 << "," << V+i+1 << endl;
			}
		}
		add_edge(V+i+1,V*2+1,1);
	}
	int ans = max_flow(0,V*2+1);
	cout << ans << endl;
	return 0;
}

