        v[i] = P(x, 1, y);
    }
    for(ll i=0; i<n; i++) {
        ll x, y;
        cin >> x >> y;
        v[i+n] = P(x, 0, y);
    }

    sort(v.begin(), v.end());

    SegmentTree<long> st(2*n, [&](long a, long b){return max(a, b);}, 0);
    ll r = 0;
    for(auto &t: v) {
        ll x, y, z;
        tie(x, z, y) = t;
        if(z == 1) {
            // red
            st.update(y, st[y]+1);
        } else {
            // blue
            if(!st.query(0, y)) continue;
            ll ok = y, ng = 0;
            while(abs(ok - ng) > 1) {
                ll m = (ok + ng) / 2;
                (st.query(m, y) ? ok : ng) = m;
            }
            st.update(ok, st[ok]-1);
            r++;
        }
    }
    cout << r << endl;
}

