int N;
vector<int> graph[210];
int match[210];
bool used[210];

void add_edge(int u, int v) {
  graph[u].push_back(v);
  graph[v].push_back(u);
}

bool dfs(int v) {
  used[v] = true;
  for (int i = 0; i < graph[v].size(); i++) {
    int u = graph[v][i];
    int w = match[u];
    if (w < 0 || !used[w] && dfs(w)) {
      match[v] = u;
      match[u] = v;
      return true;
    }
  }
  return false;
}

int bipartite_matching() {
  int res = 0;
  memset(match, -1, sizeof(match));
  for (int v = 0; v < 2 * N; v++) {
    if (match[v] < 0) {
      memset(used, false, sizeof(used));
      if (dfs(v)) {
        res++;
      }
    }
  }
  return res;
}

