bool find(int n, int m)
{
	if (n < m) swap(n, m);
	if (m == 0) return false;
	if (n % m == 0) return true;
	int next = (n / m) * m;
	bool f = find(n - next, m);
	//printf("find %d %d: %d\n", n - next, m, f);
	if (!f) return true;
	if (n - next + m < n) return true;
	return false;
}
