		int sum = accumulate(isPair[i].begin(), isPair[i].end(), 0);
		if (sum != 0)sums.push_back(make_pair(i, accumulate(isPair[i].begin(), isPair[i].end(), 0)));
	}
	sort(sums.begin(), sums.end(), compare_by_b);
	//cout << sums[0].first << " " << sums[0].second << endl;
	int ans = 0;

	while (sums.size() > 0) {
		int num1 = sums[0].first;
		int used = -1;
		rep(j, N) {
			if (isPair[num1][j] == 1) {
				++ans;
				used = j;
				break;
			}
		}
		sums = vector<pair<int, int>>();
		rep(j, N) {
			if (j != num1) {
				isPair[j][used] = 0;
				int sum = accumulate(isPair[j].begin(), isPair[j].end(), 0);
				if (sum != 0)sums.push_back(make_pair(j, accumulate(isPair[j].begin(), isPair[j].end(), 0)));
			}
			else {
				rep(k, N)isPair[j][k] = 0;
			}
		}
		//cout << sums.size() << endl;
		sort(sums.begin(), sums.end(), compare_by_b);
	}
	cout << ans;
}

