    }
    for(int i=0; i<n; ++i){
        cin >> cds[i].first >> cds[i].second;
    }
    vector<vector<int>> g(n, vector<int>());
    for(int i=0; i<n; ++i){
        for(int j=0; j<n; ++j){
            if(abs[i].first < cds[j].first && abs[i].second < cds[j].second){
                g[i].push_back(j);
            }
        }
    }
    int ans=0;
    vector<int> matched(n, -1);
    for(int i=0; i<n; ++i){
        vector<bool> visited(n);
        if(dfs(i, g, visited, matched)) ++ans;
    }
    cout << ans << endl;
    return 0;
}

