        cnt_b[i].first = 0;
    }
    for (int i = 0; i < n; ++i) {
        cnt_b[i].second = i;
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (c[j] - a[i] > 0 && d[j] - b[i] > 0) {
                cnt_r[i].first++;
                friend_r[i].push_back(j);
                cnt_b[j].first++;
            }
        }
    }

    sort(cnt_r, cnt_r + n);
    sort(cnt_b, cnt_b + n);

    int friend_num = 0;
    for (int i = 0; i < n; ++i) {
        if (cnt_r[i].first == 0) { // 仲良しペアできない
