using namespace std;

struct Node
{
	int a;
	int b;
};
Node vb[101];
Node vr[101];
int n;
bool ex[101];
int maxn;
bool mb = false;


void bfs(int ri,int num)
{
	if (ri == n)
	{
		if (mb = false)
		{
			maxn = num;
			mb = true;
		}
		else
		{
			maxn = max(maxn, num);
		}
		return;
	}
	for (int i = 0; i < n; i++)
	{
		if (vb[i].a <= vr[ri].a)continue;
		if (ex[i] ==false)
		{	
			if (vb[i].b > vr[ri].b)
			{
				ex[i] = true;
				bfs(ri + 1, num + 1);
				ex[i] = false;
			}
		}
	}
	bfs(ri + 1, num);
}
int main()
{

	scanf("%d",&n);
	int a, b;
	for (int i = 0; i < n; i++)
	{	
		scanf("%d%d",&a,&b);
		vr[i].a = a;
		vr[i].b = b;
	}
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", &a, &b);
		vb[i].a = a;
		vb[i].b = b;
	}

	bfs(0,0);
	printf("%d",maxn);
	return 0;
}

