const ll MAXn=1e2+5;
const ll MOD=1000000007;
const ll INF=(ll)1e18;

ii r[MAXn],b[MAXn];
ll rr[MAXn],bb[MAXn];

bool cmp(ii x,ii y){
	return x.S<y.S;
}

ll dis(ll a,ll b,ll x,ll y){
	return min(x-a,y-b);
}

int main(){
	IOS();
	ll n;cin>>n;
	REP(i,n) cin>>r[i].F>>r[i].S;
	sort(r,r+n);
	REP(i,n) cin>>b[i].F>>b[i].S;
	sort(b,b+n);
	ll ans=0;
	REP(i,n){
		ll tmp=INF,ti,tj;
		bool fg=false;
		REP(j,n){
			if(rr[i] || bb[j]) continue;
			if(r[i].F<b[j].F && r[i].S<b[j].S && tmp>dis(r[i].F,r[i].S,b[j].F,b[j].S)){
				tmp=dis(r[i].F,r[i].S,b[j].F,b[j].S);
				fg=true;
				ti=i,tj=j;
			}
		}
		if(fg){
			ans++;
			rr[ti]=true,bb[tj]=true;
		}
	}
	ll ans1=0;
	RST(rr,0);
	RST(bb,0);
	sort(r,r+n,cmp);
	sort(b,b+n,cmp);
	REP(i,n){
		ll tmp=INF,ti,tj;
		bool fg=false;
		REP(j,n){
			if(rr[i] || bb[j]) continue;
			if(r[i].F<b[j].F && r[i].S<b[j].S && tmp>dis(r[i].F,r[i].S,b[j].F,b[j].S)){
				tmp=dis(r[i].F,r[i].S,b[j].F,b[j].S);
				fg=true;
				ti=i,tj=j;
			}
		}
		if(fg){
			ans1++;
			rr[ti]=true,bb[tj]=true;
		}
	}
	chkmax(ans,ans1);
	cout<<ans<<endl;
}

#include <bits/stdc++.h>
#define p pair<int, int>
using namespace std;

int main(){
  int n;
  cin >> n;
  vector<p> ab, cd;
  for(int i = 0; i < n; i++){
    int a, b;
    cin >> a >> b;
    ab.push_back(p(a, b));
  }
  for(int i = 0; i < n; i++){
    int c, d;
    cin >> c >> d;
    cd.push_back(p(c, d));
  }
  sort(ab.begin(), ab.end());
  sort(cd.begin(), cd.end());
  int sum = 0, idx = 0;
  int used[205] = {};
  for(int i = 0; i < n; i++){
    int min = 1e9, tmp;
    for(int j = 0; j < n; j++){
      if(used[j]) continue;
      if(ab[i].first < cd[j].first){
        tmp = abs(ab[i].second - cd[j].second);
        if(tmp < min){
          min = tmp;
          idx = j;
        }
      }
    }
    if(!used[idx] && min != 1e9){
      sum++;
      used[idx] = 1;
    }
  }
  cout << sum << endl;
  return 0;
}

