using namespace std;
pair<int, int> ap[100];
pair<int, int> bp[100];
int n;
int m = 0;
int tas(int count, bool b[100], int sum) {
	int mini = 201;
	int num_min = 100;
	FOR(i, 0, n) {
		if (!b[i]) {
			if (ap[count].first < bp[i].first) {
				if (mini > min(mini, bp[i].first - ap[count].first)) {
					num_min = i;
					mini = bp[i].first - ap[count].first;
				}
				if (ap[count].second < bp[i].second) {
					if (mini > min(mini, bp[i].second -ap[count].second)) {
						num_min = i;
						mini = bp[i].second - ap[count].second;
					}
				}
			}
		}
	}
	if (num_min < 100) {
		if (count >= n - 1) {
			m = max(m, sum + 1);
			return 0;
		}
		b[num_min] = true;
		tas(count + 1, b, sum + 1);
	}
	m = max(m, sum);
	return 0;
}

int main() {
	cin >> n;
	bool b[100] = {};
	FOR(i, 0, n) {
		cin >> ap[i].first >> ap[i].second;
	}
	FOR(i, 0, n) {
		cin >> bp[i].first >> bp[i].second;
	}
	sort(ap, ap + n);
	sort(bp, bp + n);
	tas(0, b, 0);
	cout << m;
	return 0;
}

