        int a, b;
        std::cin >> a >> b;
        R.push_back({a, b});
    }

    std::vector<Point> B;
    for (size_t i = 0; i < N; ++i) {
        int c, d;
        std::cin >> c >> d;
        B.push_back({c, d});
