void add_edge(int from,int to){
  G[from].PB(to);
  G[to].PB(from);
}
//増加パスを探す
bool DFS(int v){
  used[v]=true;
  FOR(i,0,(int)G[v].size()){
    int u=G[v][i],w=match[u];
    if(w<0||!used[w]&&DFS(w)){
      match[v]=u;
      match[u]=v;
      return true;
    }
  }
  return false;
}
//最大マッチング
int bipartite_matching(){
  int res=0;
  memset(match,-1,sizeof(match));
  FOR(v,0,V){
    if(match[v]<0){
      memset(used,0,sizeof(used));
      if(DFS(v)){
        res++;
      }
    }
  }
  return res;
}
