                ans++;
                used[count]=j;
                count++;
                break;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

//ソート用の交換関数
void swap(Point* a,Point* b){
    Point tmp;
    tmp=*a;
    *a=*b;
    *b=tmp;
    return;
}

//使われた赤い点リストにその数があればスキップ(カウンタ+=bool)
bool check(int j,int* used,int count){
    for(int i=0; i<count; i++){
        if(*(used+i)==j)
        return false;
    }
    return true;
}

