    for (int i = 0; i < n; i++) {
        add_edge(n+i, t, 1);
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if(a[i] < c[j] && b[i] < d[j]) {
                add_edge(i, n+j, 1);
            }
        }
    }

    cout << max_flow(s, t) << endl;

    return 0;
}

