stack<pll> ss(stack<pll> m, set<ll> c, ll i, bool f, ll l = -1)
{
  if (!v[i] && 2 < m.size() && m.size() % 2 == 1)
    return m;

  c.insert(i);
  for (auto &p : n[i])
  {
    if (p <= l)
      continue;

    pll nn = i < p ? (pll){i, p} : (pll){p, i};

    if (c.find(p) == c.end() && (g.find(nn) == g.end()) == f)
    {
      m.push(nn);
      return ss(m, c, p, !f);
    }
  }

  if (m.empty())
    return m;

  pll t = m.top();
  ll lt = t.first == i ? t.second : t.first;
  m.pop();
  c.erase(lt);
  return ss(m, c, lt, !f, i);
}

bool bb(ll i)
{
  stack<pll> t = ss({}, {}, i, true);

  if (0 < t.size())
  {
    while (!t.empty())
    {
      pll p = t.top();
      t.pop();
      auto itr = g.find(p);
      if (itr == g.end())
        g.insert(p);
      else
        g.erase(itr);
    }

    return true;
  }
  else
    return false;
}

void calc()
{
  REP(i, 2 * N)
  {
    v[i] = false;
  }
  for (auto &p : g)
    v[p.first] = v[p.second] = true;

  REP(i, 2 * N)
  {
    if (!v[i] && bb(i))
      return calc();
  }
  return;
}

