using namespace std;


int V;
vector<int> G[101];
int match[101];
bool used[101];

void add_edge(int u, int v) {
  G[u].push_back(v);
  G[v].push_back(u);
}

bool dfs(int v){
  used[v] = true;
  for (int i=0;i<G[v].size();i++) {
    int u = G[v][i];
    int w = match[u];
    if (w < 0 || (!used[w] && dfs(w))) {
      match[v] = u;
      match[u] = v;
      return true;
    }
  }
  return false;
}

int main(){
  int rx[101], ry[101], bx[101], by[101];
