  }
  for (int i=0;i<V;i++) {
    cin >> bx[i] >> by[i];    
  }
  for (int i=0;i<V;i++) {
    for (int j=0;j<V;j++) {
      if (rx[i] < bx[j] && ry[i] < by[j]) {
	add_edge(i, V+j);
      }
    }
  }

  int res = 0;
  memset(match, -1, sizeof(match));
  for (int v=0;v<(2*V);v++) {
    if (match[v] < 0) {
      memset(used, 0, sizeof(used));
      if (dfs(v)) {
	res++;
      }
    }
  }
  cout << res << endl;
  return 0;
}

