#include <stdio.h>

typedef struct{
  int x;
  int y;
  int color;
} Dot;


void sort(int n,Dot dot[20000]){
  int i,j;
  Dot temp;
  for(i = 0;i < n;i++){
    for(j = n-1;j > i;j--){
      if(dot[j].y < dot[j-1].y || (dot[j].y == dot[j-1].y && dot[j].x < dot[j-1].x)){
        temp.x = dot[j-1].x;
        temp.y = dot[j-1].y;
        temp.color = dot[j-1].color;
        dot[j-1].x = dot[j].x;
        dot[j-1].y = dot[j].y;
        dot[j-1].color = dot[j].color;
        dot[j].x = temp.x;
        dot[j].y = temp.y;
        dot[j].color = temp.color;
      }
    }
  }
}

