struct point{
    int x;
    int y;
    int already;
};

void select_sort(struct point poi[200], int N){
    for(int i = 0; i < N; i++){
        int min_index = i;
        int min_x = poi[i].x;
        int min_y = poi[i].y;

        for(int j = i + 1; j < N; j++){
            if(min_x > poi[j].x && min_y > poi[j].y){
                min_x = poi[j].x;
                min_y = poi[j].y;
                min_index = j;
            }
        }
        if (min_index != i){
            poi[i].x += poi[min_index].x;
            poi[min_index].x = poi[i].x - poi[min_index].x;
            poi[i].x -= poi[min_index].x;

            poi[i].y += poi[min_index].y;
            poi[min_index].y = poi[i].y - poi[min_index].y;
            poi[i].y -= poi[min_index].y;


        }
    }
}

int main(int argc, const char * argv[]) {

    int N = 0;
    scanf("%d", &N);

    struct point red[200];
    struct point blue[200];

    for(int i = 0; i < N; i++){
        scanf("%d%d", &red[i].x, &red[i].y);
        red[i].already = 0;
    }
    for(int i = 0; i < N; i++){
        scanf("%d%d", &blue[i].x, &blue[i].y);
        blue[i].already = 0;
    }
    select_sort(red, N);
    select_sort(blue, N);

    int count = 0;
    for(int i = 0; i < N; i++){
        int index = 0;
        double min = 10000000;
        for(int j = 0; j < N; j++){
            if(red[j].x > blue[i].x && red[j].y > blue[i].y){
                if(min == 10000000)
                    break;
                red[index].already = 1;
                count++;
                min = 10000000;
                break;
            }

            if(red[j].x < blue[i].x && red[j].y < blue[i].y && red[j].already == 0){
                if(min > sqrt(pow(red[j].x - blue[i].x,2) + pow(red[j].y - blue[i].y,2))){
                    min = sqrt(pow(red[j].x - blue[i].x,2) + pow(red[j].y - blue[i].y,2));
                    index = j;
                }
            }
        }

        if(min != 10000000){
            red[index].already = 1;
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}

