const int N=100;
mint inv[N],fac[N],invfac[N];   // mod MODの逆元, 階乗, 階乗の逆元
void calc_inv(){
    inv[1]=1;
    rep3(i,2,N){ // 2以上N-1以下
        inv[i]=inv[MOD%i]*(MOD-MOD/i);
    }
    return;
}
void calc_product(){
    fac[0]=fac[1]=1;
    invfac[0]=invfac[1]=1;
    rep3(i,2,N){ // 2以上N-1以下
        fac[i]=fac[i-1]*i;
        invfac[i]=inv[i]*invfac[i-1];
    }
    return;
}

