typedef struct {
	int to, cap, rev;
} edge;

edge e[102][102];
int l[102];
char u[102];

void add(int from, int to, int cap){
	int l1=l[from], l2=l[to];
	e[from][l1].to=to;
	e[from][l1].cap=cap;
	e[from][l1].rev=l2;
	e[to][l2].to=from;
	e[to][l2].cap=0;
	e[to][l2].rev=l1;
	l[from]++, l[to]++;
}

int dfs(int from, int to, int cap){
	if(from==to) return cap;
	if(u[from]!=0) return 0;
	u[from]=1;
	for(int i=0, j=l[from]; i<j; i++){
		int k=e[from][i].cap;
		if(k>cap) k=cap;
		k=dfs(e[from][i].to, to, k);
		if(k>0){
			e[from][i].cap -= k;
			e[e[from][i].to][e[from][i].rev].cap += k;
			u[from]=0;
			return k;
		}
	}
	u[from]=0;
	return 0;
}

