int queue[100];
int front=0;
int rear=0;
int parent[100];
int f[202][202];

int search(int nn,int num,int **rc,int goal){
  int i,j,flag=1,flag2;
  if(rc[nn][goal]!=0){
    parent[goal]=nn;
    return 1;
  }
  for(i=0;i<num-1;i++){
    if(rc[nn][i]!=0){
	flag=1;
	for(j=0;j<rear;j++){
	  if(i==queue[j])  flag=0;
	}
	if(flag){
	  queue[rear]=i;
	  rear++;
	  parent[i]=nn;
	}
    }
  }

  flag2=0;
  front++;
  while(front<rear&&flag2==0){
    flag2= search(queue[front],num,rc,goal);
    front++;
  }
  return flag2;
}

