        temp=d[i];
        d[i]=d[j];
        d[j]=temp;
      }
    }
  }
  for(i=1;i<=n;i++) {
    m[0][i]=1;
    m[i+n][2*n+1]=1;
  }
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      if(a[i]<c[j]&&b[i]<d[j]) m[i+1][n+j+1]=1;
