int queue[202];
int front=0;
int rear=0;
int parent[202];
int f[202][202];

int search(int nn,int num,int **rc,int goal){
  int i,j,flag=1,flag2;
  if(rc[nn][goal]!=0){
    parent[goal]=nn;
    return 1;
  }
  for(i=0;i<num-1;i++){
    if(rc[nn][i]!=0){
	flag=1;
	for(j=0;j<rear;j++){
	  if(i==queue[j])  flag=0;
	}
	if(flag){
	  queue[rear]=i;
	  rear++;
	  parent[i]=nn;
	}
    }
  }

  flag2=0;
  front++;
  while(front<rear&&flag2==0){
    flag2= search(queue[front],num,rc,goal);
    front++;
  }
  return flag2;
}

int main(){
  int n,i,j,temp,a[100],b[100],c[100],d[100],flag[100]={},sum=0,max=0,m[202][202]={};
  int flow,*rc[202];
  scanf("%d",&n);
  for(i=0;i<n;i++){
    scanf("%d %d",&a[i],&b[i]);
  }
  for(i=0;i<n;i++){
    scanf("%d %d",&c[i],&d[i]);
  }

  for(i=1;i<=n;i++) {
    m[0][i]=1;
    m[i+n][2*n+1]=1;
  }
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      if(a[i]<c[j]&&b[i]<d[j]) m[i+1][n+j+1]=1;
    }
  }

  front=0;
  queue[0]=0;
  rear=1;

  for(i=0;i<2*n+2;i++) rc[i]=m[i];

  flow=search(0,2*n+2,rc,2*n+1);

  while(flow!=0){
    for(i=0;i<(2*n+2);i++)
	for(j=0;j<(2*n+2);j++)
	  f[i][j]=0;
    i=(2*n+2)-1;
    do{
	rc[parent[i]][i]-=flow;
	rc[i][parent[i]]+=flow;
