#define NUM_MAX 100

struct point2d {
    int x;
    int y;
};

struct pair {
    int val;
    int idx;
};

int is_big(struct point2d b, struct point2d s) {
    return b.x > s.x && b.y > s.y;
}

int asc_by_val(const void *a1, const void *a2) {
    struct pair *pa1 = (struct pair*)a1;
    struct pair *pa2 = (struct pair*)a2;
    return pa1->val - pa2->val;
}

int main(void) {
    int num = get_int();
    static struct point2d reds[NUM_MAX];
    static struct point2d blues[NUM_MAX];
    int i, j;

    for(i = 0; i < num; i++) {
        get_int2(&reds[i].x, &reds[i].y);
    }
    for(i = 0; i < num; i++) {
        get_int2(&blues[i].x, &blues[i].y);
    }

    // flags[BLUE}[RED]
    static char flags1[NUM_MAX][NUM_MAX];
    static struct pair red_cnt[NUM_MAX]; //RED
    static struct pair blue_cnt[NUM_MAX]; //RED
    for(i = 0; i < num; i++) red_cnt[i].idx = i;
    for(i = 0; i < num; i++) blue_cnt[i].idx = i;
    for(i = 0; i < num; i++) {
        for(j = 0; j < num; j++) {
            if(is_big(blues[i], reds[j])) {
                flags1[i][j] = 1;
                red_cnt[j].val++;
                blue_cnt[i].val++;
            }
        }
    }
    static char flags[NUM_MAX][NUM_MAX];
    memcpy(flags, flags1, NUM_MAX*NUM_MAX);
    qsort(red_cnt, num, sizeof(struct pair), asc_by_val);
    int ans = 0;
    int k;
    for(k = 0; k < num; k++) {
        int j = red_cnt[k].idx;
        // find j
        for(i = 0; i < num; i++) if(flags[i][j]) break;
        if(i == num) continue;
        ans++;
        for(j = 0; j < num; j++) {
            if(flags[i][j]) {
                flags[i][j] = 0;
                red_cnt[j].val--;
            }
        }
    }

    memcpy(flags, flags1, NUM_MAX*NUM_MAX);
    qsort(blue_cnt, num, sizeof(struct pair), asc_by_val);
    int res = 0;
    for(k = 0; k < num; k++) {
        int i = blue_cnt[k].idx;
        // find j
        for(j = 0; j < num; j++) if(flags[i][j]) break;
        if(j == num) continue;
        res++;
        for(i = 0; i < num; i++) {
            if(flags[i][j]) {
                flags[i][j] = 0;
                blue_cnt[j].val--;
            }
        }
    }
    printf("%d\n", max(ans, res));
    return 0;
}

#include<stdio.h>

int queue[100];
int front=0;
int rear=0;
int parent[100];
int f[202][202];

int search(int nn,int num,int **rc,int goal){
  int i,j,flag=1,flag2;
  if(rc[nn][goal]!=0){
    parent[goal]=nn;
    return 1;
  }
  for(i=0;i<num-1;i++){
    if(rc[nn][i]!=0){
	flag=1;
	for(j=0;j<rear;j++){
	  if(i==queue[j])  flag=0;
	}
	if(flag){
	  queue[rear]=i;
	  rear++;
	  parent[i]=nn;
	}
    }
  }

  flag2=0;
  front++;
  while(front<rear&&flag2==0){
    flag2= search(queue[front],num,rc,goal);
    front++;
  }
  return flag2;
}

int main(){
  int n,i,j,temp,a[100],b[100],c[100],d[100],flag[100]={},sum=0,max=0,m[202][202]={};
  int flow,*rc[202];
  scanf("%d",&n);
  for(i=0;i<n;i++){
    scanf("%d %d",&a[i],&b[i]);
  }
  for(i=0;i<n;i++){
    scanf("%d %d",&c[i],&d[i]);
  }

  for(i=1;i<=n;i++) {
    m[0][i]=1;
    m[i+n][2*n+1]=1;
  }
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      if(a[i]<c[j]&&b[i]<d[j]) m[i+1][n+j+1]=1;
    }
  }

  front=0;
  queue[0]=0;
  rear=1;

  for(i=0;i<2*n+2;i++) rc[i]=m[i];

  flow=search(0,2*n+2,rc,2*n+1);

  while(flow!=0){
    for(i=0;i<(2*n+2);i++)
	for(j=0;j<(2*n+2);j++)
	  f[i][j]=0;
    i=(2*n+2)-1;
    do{
	rc[parent[i]][i]-=flow;
	rc[i][parent[i]]+=flow;
	i=parent[i];
    }while(i!=0);
    sum+=flow;
    front=0;
    queue[0]=0;
    rear=1;
    flow=search(0,2*n+2,rc,2*n+1);
  }
  printf("%d\n",sum);
}

