// 内部定数
#define D_POINT_KIND	2										// 点の種類
#define D_POINT_RED		0										// 点 - 赤
#define D_POINT_BLUE	1										// 点 - 青
#define D_POINT_MAX		100										// 点の数最大

// 内部構造体 - 点情報
typedef struct Point {
	int miX, miY;												// 座標
	int mi1Pair[D_POINT_MAX];									// ペア可能な点
	int miPCnt;													// ペア可能な点の数
} Point;

// 内部変数
static Point sz2Point[D_POINT_KIND][D_POINT_MAX];				// 点
static int siPCnt;												// 点の数

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
	static FILE *szpFpT, *szpFpA;
#endif

// ペア取得
int
fGetPair(
	int *pipRNo					// <O> 赤い点
	, int *pipBNo				// <O> 青い点
)
{
	int i, j;

	// ペア可能な点の数が少ない点を検索
	int liCnt = INT_MAX;
	int liKNo, liPNo;
	for (i = 0; i < D_POINT_KIND; i++) {
		for (j = 0; j < siPCnt; j++) {
			if (sz2Point[i][j].miPCnt > 0) {
				if (liCnt > sz2Point[i][j].miPCnt) {
					liCnt = sz2Point[i][j].miPCnt;
					liKNo = i;
					liPNo = j;
				}
			}
		}
	}
	if (liCnt == INT_MAX) {			// なし
		return -1;
	}

	// 相手取得
	int liTNo;
	for (i = 0; i < D_POINT_MAX; i++) {
		if (sz2Point[liKNo][liPNo].mi1Pair[i] > 0) {
			liTNo = i;
			break;
		}
	}

	// ペアセット
	if (liKNo == D_POINT_RED) {		// 赤
		*pipRNo = liPNo;
		*pipBNo = liTNo;
	}
	else {
		*pipRNo = liTNo;
		*pipBNo = liPNo;
	}

	return 0;
}

// ペア可能な点削除
int
fDelPair(
	int piKNo					// <I> 色の種類
	, int piPNo					// <I> 点番号 0～
)
{
	int i;

	// 相手の種類
	int liTNo;
	if (piKNo == D_POINT_RED) {
		liTNo = D_POINT_BLUE;
	}
	else {
		liTNo = D_POINT_RED;
	}

	// 相手側
	for (i = 0; i < D_POINT_MAX; i++) {
		if (sz2Point[piKNo][piPNo].mi1Pair[i] > 0) {
			sz2Point[liTNo][i].mi1Pair[piPNo] = 0;
			sz2Point[liTNo][i].miPCnt--;
		}
	}

	// 自分
	sz2Point[piKNo][piPNo].miPCnt = 0;

	return 0;
}

