	// 青い点取得
	for (i = 0; i < siPCnt; i++) {
#ifdef D_TEST
		fgets(lc1Buf, sizeof(lc1Buf), szpFpT);
#else
		fgets(lc1Buf, sizeof(lc1Buf), stdin);
#endif
		sscanf(lc1Buf, "%d%d", &sz2Point[D_POINT_BLUE][i].miX, &sz2Point[D_POINT_BLUE][i].miY);
	}

	// ペア可能な点セット
	for (i = 0; i < siPCnt; i++) {
		for (j = 0; j < siPCnt; j++) {
			if (sz2Point[D_POINT_RED][i].miX < sz2Point[D_POINT_BLUE][j].miX) {
