typedef struct dpoint{
  int x,y;
} point;

void isort(point *a,int n){
  int i,j;
  for(i=1;i<n;i++){
    point t=a[i];
    j=i-1;
    while(j>=0 && t.x<a[j].x){
      a[j+1]=a[j];
      j--;
    }
    a[j+1]=t;
  }
  return;
}

void run(void){
  int n;
