    static struct edge edges[NUM_MAX*2];
    int eidx = 0;
    for(i = 0; i < num; i++) {
        for(j = 0; j < num; j++) {
            if(is_big(blues[i], reds[j])) {
                struct point2d dp = {
                    blues[i].x-reds[j].x,
                    blues[i].y-reds[j].y
                };
                edges[eidx++] = (struct edge){
                    i, j,
                    dp.x*dp.x+dp.y*dp.y
                };
            }
        }
    }

    qsort(edges, eidx, sizeof(struct edge), asc);
    int ans = 0;
    static int blue_map[NUM_MAX+1];
    static int red_map[NUM_MAX+1];
    for(i = 0; i < eidx; i++) {
        struct edge e = edges[i];
