int func(int i, int N, friend p){
    int max = 0;
    int j;
    if(i == N - 1){
        int ret = 0;
         REP(j, N){
             if(p.pair[i][j] == 1){
                 ret = 1;
                 break;
             }
         }
         return ret;
    }
    REP(j, N){
        int isFriend = p.pair[i][j] == 1? 1 : 0;
        int k;
        char temp[N];
        if(isFriend){
            REP(k, N){
                temp[k] = p.pair[k][j];
                p.pair[k][j] = 0;
            }
        }
        int ret = func(i + 1, N, p) + isFriend;
        if(max < ret) max = ret;
        if(isFriend){
            REP(k, N){
                p.pair[k][j] = temp[k];
            }
        }
    }
    return max;
}

