void quicksortr(struct red data[],int left,int right)
{
	int i,j;
	struct red std,work;
	if(left<right)
	{
		i=left,j=right;
		std=data[(i+j)/2];//基準
		do
		{
			while(data[i].y > std.y)i++;
			while(data[j].y < std.y)j--;
			if(i<=j)
			{
				if(i<j)
				{
					work=data[i];
					data[i]=data[j];
					data[j]=work;
				}
				i++; j--;
			}
		}while(i<=j);
		if(left<j)quicksortr(data,left,j);
		if(i<right)quicksortr(data,i,right);
	}
}
void quicksortb(struct blue data[],int left,int right)
{
	int i,j;
	struct blue std,work;
	if(left<right)
	{
		i=left,j=right;
		std=data[(i+j)/2];//基準
		do
		{
			while(data[i].x < std.x)i++;
			while(data[j].x > std.x)j--;
			if(i<=j)
			{
				if(i<j)
				{
					work=data[i];
					data[i]=data[j];
					data[j]=work;
				}
				i++; j--;
			}
		}while(i<=j);
		if(left<j)quicksortb(data,left,j);
		if(i<right)quicksortb(data,i,right);
	}
}

