  for(int i = 0; i < n; i++) {
    if(!red[i].searched && red[i].x < p->x && red[i].y < p->y) {
      int current_dist = min(p->x - red[i].x, p->y - red[i].y);
      if(current_dist < dist) {
        point = &red[i];
        dist = current_dist;
      }
    }
  }
  if(dist == DEFAULT_DIST) {
    return 0;
  } else {
    point->searched = 1;
    return 1;
  }
}

