import java.math.*
import java.util.BitSet

class FordFulkerson(val N: Int) {
    // 辺の配列
    // 容量は別に持つため、ここでは終点のリストのみ持つ
    val edges = Array(N, {mutableListOf<Int>()})
    val capacity = Array(N, {IntArray(N, {-1})})
    val used = BitSet(N)

    private fun dfs(s: Int, d: Int, flow: Int): Int {
        used.set(s)

        if (s == d) {
            return flow
        }

        for (e in edges[s]) {
            if (!used.get(e) && capacity[s][e] > 0) {
                val flowTmp = dfs(e, d, Math.min(capacity[s][e], flow))
                if (flowTmp > 0) {
                    capacity[s][e] -= flowTmp
                    capacity[e][s] += flowTmp
                    return flowTmp
                }
            }
        }

        return 0
    }

    fun add(from: Int, to: Int, cap: Int) {
        edges[from].add(to)
        edges[to].add(from)
        capacity[from][to] = cap
        capacity[to][from] = 0
    }

    fun solve(source: Int, sink: Int): Int {
        var flow = 0
        while (true) {
            used.clear()

            val flowTmp = dfs(source, sink, Int.MAX_VALUE)

            if (flowTmp == 0) {
                break
            }

            flow += flowTmp
        }
        return flow
    }
}

