data class Point(val x: Int, val y: Int) {
    fun isOver(point: Point) = (point.x < x && point.y < y)
}
fun main(args: Array<String>) {
    val sc = Scanner(System.`in`)
    val reds = HashMap<Point, HashSet<Point>>()
    val blues = HashMap<Point, HashSet<Point>>()
    val n = sc.nextLine().toInt()
    for (i in 0 until n) {
        val (x, y) = sc.nextLine().split(" ")
        val point = Point(x.toInt(), y.toInt())
        reds.put(point, HashSet())
    }
    for (i in 0 until n) {
        val (x, y) = sc.nextLine().split(" ")
        val point = Point(x.toInt(), y.toInt())
        blues.put(point, HashSet())
    }
    reds.forEach { red, redSet ->
        blues.forEach { blue, blueSet ->
            if (blue.isOver(red)) {
                redSet.add(blue)
                blueSet.add(red)
            }
        }
    }

    var count = 0
    while (true) {
        var redMin: Map.Entry<Point, HashSet<Point>>? = null
        val redRemoves = ArrayList<Point>()
        reds.forEach { entry ->
            if (entry.value.size <= 0) {
                redRemoves.add(entry.key)
            } else {
                val current = redMin
                if (current == null || entry.value.size < current.value.size) {
                    redMin = entry
                }
            }
        }
        redRemoves.forEach {
            reds.remove(it)
        }
        var blueMin: Map.Entry<Point, HashSet<Point>>? = null
        val blueRemoves = ArrayList<Point>()
        blues.forEach { entry ->
            if (entry.value.size <= 0) {
                blueRemoves.add(entry.key)
            } else {
                val current = blueMin
                if (current == null || entry.value.size < current.value.size) {
                    blueMin = entry
                }
            }
        }
        blueRemoves.forEach {
            blues.remove(it)
        }
        val redEntry = redMin
        val blueEntry = blueMin
        if (redEntry == null || blueEntry == null) {
            break
        }
        ++count
        if (redEntry.value.size < blueEntry.value.size) {
            val blue = redEntry.value.minBy { blues[it]!!.size }
            reds.remove(redEntry.key)
            redEntry.value.forEach {
                blues[it]!!.remove(redEntry.key)
            }
            blues[blue]!!.forEach {
                reds[it]!!.remove(blue)
            }
            blues.remove(blue)
        } else {
            val red = blueEntry.value.minBy { reds[it]!!.size }
            blues.remove(blueEntry.key)
            blueEntry.value.forEach {
                reds[it]!!.remove(blueEntry.key)
            }
            reds[red]!!.forEach {
                blues[it]!!.remove(red)
            }
            reds.remove(red)
        }
    }
    println(count)
}

