                if (flowTmp > 0) {
                    capacity[s][e] -= flowTmp
                    capacity[e][s] += flowTmp
                    return flowTmp
                }
            }
        }

        return 0
    }

    fun add(from: Int, to: Int, cap: Int) {
        edges[from].add(to)
        edges[to].add(from)
        capacity[from][to] = cap
        capacity[to][from] = 0
    }

    fun solve(source: Int, sink: Int): Int {
        var flow = 0
        while (true) {
            used.clear()

            val flowTmp = dfs(source, sink, Int.MAX_VALUE)

            if (flowTmp == 0) {
