fun search(reds: MutableList<Pair<Int, Int>>, brues: MutableList<Pair<Int, Int>>, count: Int): Int {
    if (reds.size == 0 || brues.size == 0) {
        return count
    }
    var maxcount = count

    for (red in reds) {
        val okList = brues.filter { brue -> red.first < brue.first && red.second < brue.second }
        if (okList.size > 0) {
            val reds2 = reds.toMutableList()
            reds2.remove(red)
            for (ok in okList) {
                brues.remove(ok)
                val count2 = search(reds2, brues, count + 1)
                if (count2 > maxcount) {
                    maxcount = count2
                }
                brues.add(ok)
            }
        }
    }
    return maxcount
}

