    }

    ArrayList<int[]> redL = new ArrayList<>();
    Collections.addAll(redL, mergeSort(red));

    ArrayList<int[]> blueL = new ArrayList<>();
    Collections.addAll(blueL, mergeSort(blue));

    /*
    for (int[] i : redL) {
