        // -----------------------------------------
        public void solve() {
        	int N = ni();
        	List<PP> R = new ArrayList<>();
        	List<PP> B = new ArrayList<>();
        	int x, y;
        	for (int i = 0; i < N; i++) {
				x = ni();
				y = ni();
				R.add(new PP(x,y));
			}
        	R.sort(comparing(PP::getKey, reverseOrder()).thenComparing(PP::getVal, reverseOrder()));
        	for (int i = 0; i < N; i++) {
				x = ni();
				y = ni();
				B.add(new PP(x,y));
			}
        	B.sort(comparing(PP::getKey, reverseOrder()).thenComparing(PP::getVal, reverseOrder()));
        	int ans = 0;
        	PP sv = null;
        	for (PP bb : B) {
            	for (PP rr : R) {
//        			prn("bb x = " + bb.key + " y = " + bb.val + "  rr x = " + rr.key + " y = " + rr.val);
					sv = null;
        			if(rr.key < bb.key && rr.val < bb.val) {
						ans++;
						sv = rr;
						break;
					}
            	}
            	if(sv != null)	R.remove(R.indexOf(sv));
			}
        	prn(ans);
    	}

        // -----------------------------------------
        // Integer のキーに対して、Integer のカウントを管理する（カウントを足したり、引いたりする）
        // キーの最大、最小の取得、データの追加、削除も O(long(N)) で処理できる
        //
        static class MapCounter {
        	private TreeMap<Integer, Integer> map;
        	// 昇順のマップ
        	public MapCounter() {
        		map = new TreeMap<>();
        	}
        	// reverse = tree なら降順のマップ
        	public MapCounter(boolean reverse) {
        		if(reverse) {
        			map = new TreeMap<Integer, Integer>(Collections.reverseOrder());
        		} else {
            		map = new TreeMap<>();
        		}
        	}
        	// キーを追加する（キーが存在すれば、カウントに１足す）
        	public void add(Integer key) {
        		add(key, 1);
        	}
           	public void add(Integer key, int cnt) {
           		Integer val = map.get(key);
        		if(val == null) {
        			map.put(key, cnt);
        		} else {
        			map.put(key,  val + cnt);
        		}
        	}
        	// キーを消す（キーが存在すれば、カウントを１減らす）
        	public void remove(Integer key) {
        		sub(key, 1, false);
        	}
           	// キーのカウントを減らす
        	public void sub(Integer key) {
        		sub(key, 1);
        	}
        	// キーのカウントから値を引く（マイナスのカウントを許す）
        	public void sub(Integer key, int cnt) {
        		sub(key, cnt, true);
        	}
        	// キーのカウントから値を引く
        	//  →　マイナスを許可しない場合で、カウントがマイナスになったら消す
           	public void sub(Integer key, int cnt, boolean minus) {
        		Integer val = map.get(key);
        		if(val == null) {
        			if(minus) {
        				map.put(key, -cnt);				// カウントのマイナスを許す
        			}
        		} else if(val > cnt || minus){
       				map.put(key, val - cnt);
        		} else {
        			map.remove(key);
        		}
