    List<PP> BLUE = new ArrayList<>();
    public void solve() {
    	int N = ni();
    	int x, y;
    	for (int i = 0; i < N; i++) {
			x = ni();
			y = ni();
			RED.add(new PP(x, y));
		}
    	for (int i = 0; i < N; i++) {
			x = ni();
			y = ni();
			BLUE.add(new PP(x, y));
		}
    	RED.sort(comparing(PP::getKey).thenComparing(PP::getVal));
    	BLUE.sort(comparing(PP::getKey).thenComparing(PP::getVal));
    	int max, ans = 0;
    	PP sv;
    	for (PP ab : BLUE) {
    		sv = null;
    		max = -1;
			for (PP cd : RED) {
				if(cd.key > ab.key)	break;
				if(cd.val < ab.val && cd.val > max) {
					sv = cd;
					max = cd.val;
				}
			}
			if(sv == null)	continue;
			ans++;
			sv.val = 1000;
		}
    	out.println(ans);
