/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author mikit
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        C2DPlane2NPoints solver = new C2DPlane2NPoints();
        solver.solve(1, in, out);
        out.close();
    }

    static class C2DPlane2NPoints {
        private static int n;
        private static Vec2i[] red;
        private static Vec2i[] blue;

        public void solve(int testNumber, LightScanner in, PrintWriter out) {
            n = in.ints();
            red = new Vec2i[n];
            blue = new Vec2i[n];
            for (int i = 0; i < n; i++) {
                red[i] = new Vec2i(in.ints(), in.ints());
            }
            for (int i = 0; i < n; i++) {
                blue[i] = new Vec2i(in.ints(), in.ints());
            }
            out.println(dfs(0, new boolean[n]));
        }

        private static int dfs(int r, boolean[] b) {
            if (r == n) {
                return 0;
            }
            int ans = dfs(r + 1, b);
            int xmin = Integer.MAX_VALUE, xminIndex = -1;
            int ymin = Integer.MAX_VALUE, yminIndex = -1;
            for (int i = 0; i < n; i++) {
                if (!b[i] && red[r].getX() < blue[i].getX() && red[r].getY() < blue[i].getY()) {
                    if (blue[i].getX() < xmin) {
                        xmin = blue[i].getX();
                        xminIndex = i;
                    }
                    if (blue[i].getY() < ymin) {
                        ymin = blue[i].getY();
                        yminIndex = i;
                    }
                }
            }
            if (xminIndex >= 0) {
                boolean[] nb = b.clone();
                nb[xminIndex] = true;
                ans = Math.max(ans, 1 + dfs(r + 1, nb));
            }
            if (yminIndex >= 0 && xminIndex != yminIndex) {
                boolean[] nb = b.clone();
                nb[yminIndex] = true;
                ans = Math.max(ans, 1 + dfs(r + 1, nb));
            }
            return ans;
        }

    }

    static class Vec2i {
        private final int x;
        private final int y;

        public Vec2i(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Vec2i vec2i = (Vec2i) o;
            return x == vec2i.x &&
                    y == vec2i.y;
        }

        public int hashCode() {
            return Objects.hash(x, y);
        }

        public String toString() {
            return "(" + x + ", " + y + ")";
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
}

