import java.util.Scanner;
import java.util.ArrayList;
import java.util.HashSet;

public class Main {

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();

    int[][] red = new int[n][2];
    int[][] blue = new int[n][2];

    for (int i = 0; i < n; ++i) {
      red[i][0] = sc.nextInt();
      red[i][1] = sc.nextInt();
    }

    for (int i = 0; i < n; ++i) {
      blue[i][0] = sc.nextInt();
      blue[i][1] = sc.nextInt();
    }

    ArrayList<Integer>[] binds = new ArrayList[n];
    for (int i = 0; i < n; ++i)
      binds[i] = new ArrayList<>();

    for (int j = 0; j < n; ++j) {
      for (int i = 0; i < n; ++i) {
        if (red[j][0] < blue[i][0] && red[j][1] < blue[i][1]) {
          binds[i].add(j);
        }
      }
    }

    System.out.println(match(n, binds, 0));
  }

  public static int match(int n, ArrayList<Integer>[] binds, int res) {
    int min = -1;
    int minSize = n + 1;
    for (int i = 0; i < n; ++i) {
      int sz = binds[i].size();
      if (sz > 0 && sz < minSize) {
        min = i;
        minSize = sz;
      }
    }

    if (min == -1) {
      return res;
    }

    ++res;

    HashSet<Integer> nextResults = new HashSet<>();

    for (int i = 0; i < binds[min].size(); ++i) {
      ArrayList<Integer>[] newBinds = new ArrayList[n];
      for (int j = 0; j < n; ++j) {
        newBinds[j] = (ArrayList<Integer>) binds[j].clone();
      }
      int j = newBinds[min].get(i);
      newBinds[min].clear();
      for (ArrayList list : newBinds) {
        list.remove(new Integer(j));
      }
      nextResults.add(match(n, newBinds, res));
    }

    int max = 0;

    for (int i : nextResults) {
      if (i > max)
        max = i;
    }

    return max;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.StringTokenizer;

public class Main {
    int n;
    Point[] rs, bs;

    public static void main(String args[]) {
        new Main().run();
    }

    void run() {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        rs = new Point[n];
        bs = new Point[n];
        for (int i = 0; i < n; i++) {
            rs[i] = new Point(sc.nextInt(), sc.nextInt());
        }
        for (int i = 0; i < n; i++) {
            bs[i] = new Point(sc.nextInt(), sc.nextInt());
        }
        solve();
    }

    void solve() {
        int count = 0;
        boolean[] paired = new boolean[n];
        Arrays.sort(bs, new sortByX());
        for (int i = 0; i < n; i++) {
            Point b = bs[i];
            int index = -1;
            int maxY = -1;
            for (int j = 0; j < n; j++) {
                if (paired[j] || rs[j].x >= b.x || rs[j].y >= b.y) {
                    continue;
                }
                if (rs[j].y > maxY) {
                    index = j;
                    maxY = rs[j].y;
                }
            }
            if (maxY > -1) {
                paired[index] = true;
                count++;
            }
        }
        System.out.println(count);
    }

    class sortByX implements Comparator<Point> {
        public int compare(Point a, Point b) {
            return a.x - b.x;
        }
    }

    class Point {
        int x;
        int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

