class ReturnArray{
    public int[] ary1;
    public int[] ary2;
    ReturnArray(int N){

	ary1 = new int[N];
	ary2 = new int[N];
    }
}

class Sort{
    ReturnArray value;

    public ReturnArray method(int[] array1, int[] array2, int N){
	value = new ReturnArray(N);
	for(int i = 0; i < N-1; i++){
	    for(int j = i+1; j < N; j++){
		if(array1[i] > array1[j]){
		    int tmp1 = array1[i];
		    array1[i] = array1[j];
		    array1[j] = tmp1;
		    int tmp2 = array2[i];
		    array2[i] = tmp2;
		}
	    }
	}

	for(int i = 0; i < N; i++){
	    value.ary1[i] = array1[i];
	    value.ary2[i] = array2[i];
	}

	return value;
    }
}

