/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Kenji
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ABC091C solver = new ABC091C();
        solver.solve(1, in, out);
        out.close();
    }

    static class ABC091C {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            int[] redX = new int[N];
            int[] redY = new int[N];
            int[] blueX = new int[N];
            int[] blueY = new int[N];
            boolean[] used = new boolean[N];
            int ans = 0;
            List<Integer> redList = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                redX[i] = in.nextInt();
                redY[i] = in.nextInt();
                redList.add(i);
            }
            for (int i = 0; i < N; i++) {
                blueX[i] = in.nextInt();
                blueY[i] = in.nextInt();
                used[i] = false;
            }

            // sort
            Collections.sort(redList, new Comparator<Integer>() {

                public int compare(Integer o1, Integer o2) {
                    return (redX[o2] * redX[o2] + redY[o2] * redY[o2]) - (redX[o1] * redX[o1] + redY[o1] * redY[o1]);
                }
            });

            //for (int i = 0; i < N; i++) {
            for (Integer i : redList) {
                List<Integer> candidate = new ArrayList<>();
                for (int j = 0; j < N; j++) {
                    if (redX[i] < blueX[j]
                            && redY[i] < blueY[j]
                            && !used[j]) {
                        candidate.add(j);
                    }
                }

                double distance = Double.MAX_VALUE;
                int index = -1;
                for (Integer j : candidate) {
                    double d = Math.sqrt(Math.pow(blueX[j] - redX[i], 2) + Math.pow(blueY[j] - redY[i], 2));
                    if (distance > d) {
                        distance = d;
                        index = j;
                    }
                }
                if (index != -1) {
                    ans++;
                    used[index] = true;
                }
            }
            out.println(ans);
        }

    }
}

