  public static ArrayList<Point> sub_array_x
  (
    ArrayList<Point> array,
    Point            point
  )
  {
    ArrayList<Point> ret;
    int              x;
    int              num;
    int              cnt;


    x   = point.x;
    ret = null;

    num = array.size();
    for(cnt=0; cnt<num; cnt++)
    {
      if(x < array.get(cnt).x)
      {
        ret = new ArrayList<Point>(array.subList(cnt, num));
        break;
      }
    }

    return ret;
  }


