        int x,y;

        public Point(int x,int y) {
            this.x = x;
            this.y = y;
        }
    }

    private int dfs(int n,int m) {
        if (n == N) {
            return 0;
        }

        Point curRed = red.get(n);

        int ret = 0;
        ret = Math.max(ret,dfs(n + 1,m));
        for(int i = m;i < N;i++) {
            if(curRed.x < blue.get(i).x && curRed.y < blue.get(i).y) {
                ret = Math.max(ret,dfs(n + 1,i + 1) + 1);
            }
        }

        return ret;
    }

    private void solve() {
        N = nextInt();

        red = new ArrayList<>();
        blue = new ArrayList<>();

        for(int i = 0;i < N;i++) {
            int a = nextInt();
            int b = nextInt();

            red.add(new Point(a,b));
        }

        for(int i = 0;i < N;i++) {
            int c = nextInt();
            int d = nextInt();

            blue.add(new Point(c,d));
        }

        Collections.sort(red, new Comparator<Point>() {
            @Override
            public int compare(Point a, Point b) {
                return a.x - b.x;
            }
        });
        Collections.sort(blue, new Comparator<Point>() {
            @Override
            public int compare(Point a, Point b) {
                return a.x - b.x;
            }
        });

        Collections.sort(red, new Comparator<Point>() {
            @Override
            public int compare(Point a, Point b) {
                return a.y - b.y;
            }
        });
        Collections.sort(blue, new Comparator<Point>() {
            @Override
            public int compare(Point a, Point b) {
                return a.y - b.y;
            }
        });

        out.println(dfs(0,0));
    }

