import java.awt.Point;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

public class Main
{


  public static void main
  (
    String[] args
  )
  {
    BufferedReader in_stream;
    String         in_str;
    String[]       in_str_split;

    int   in_N;
    ArrayList<Point> in_red;
    ArrayList<Point> in_blue;

    ArrayList<Point> tmp1;
    ArrayList<Point> tmp2;

    int tmp_x;
    int tmp_y;
    Point tmp_point;

    int cnt;
    int num;
    int cnt2;
    int num2;
    int ans;

    try
    {
      in_stream = new BufferedReader(new InputStreamReader(System.in));

      /*----------------
       * 引数
       *----------------*/
      in_str = new String(in_stream.readLine());
      in_N   = Integer.parseInt(in_str);

      in_red = new ArrayList<Point>();
      for(cnt=0; cnt<in_N; cnt++)
      {
        in_str       = new String(in_stream.readLine());
        in_str_split = in_str.split(" ");

        in_red.add( new Point(Integer.parseInt(in_str_split[0]), Integer.parseInt(in_str_split[1])) );
      }

      in_blue = new ArrayList<Point>();
      for(cnt=0; cnt<in_N; cnt++)
      {
        in_str       = new String(in_stream.readLine());
        in_str_split = in_str.split(" ");

        in_blue.add( new Point(Integer.parseInt(in_str_split[0]), Integer.parseInt(in_str_split[1])) );
      }

      /*----------------
       * 計算
       *----------------*/
      ans = 0;

      /* まず、xでソート */
      sort_x(in_red);
      sort_x(in_blue);

      /* 赤い点をベースに、ペアの青い点を探す */
      num = in_red.size();
      for(cnt=0; cnt<num; cnt++)
      {
        tmp_point = in_red.get(cnt);

        /* 青い点群から、赤のxより大きい部分のみ抽出 */
        tmp1 = sub_array_x(in_blue, tmp_point);

        /* 見つかれば、一番若い部分をペアに */
        if(null != tmp1)
        {
          sort_y(tmp1);
          num2 = tmp1.size();
          for(cnt2=0; cnt2<num2; cnt2++)
          {
            if(tmp_point.y < tmp1.get(cnt2).y)
            {
              ans++;
              in_blue.remove(tmp1.get(cnt2));
              break;
            }
          }
        }
      }



      System.out.println("" + ans);
    }
    catch(Exception e)
    {
      e.printStackTrace();
    }
  }



  public static void sort_x
  (
    ArrayList<Point> array
  )
  {
    Collections.sort
    (
      array,
      new Comparator<Point>()
      {
        public int compare
        (
          Point obj1,
          Point obj2
        )
        {
          return obj2.x - obj1.x;
        }
      }
    );
  }



  public static void sort_y
  (
    ArrayList<Point> array
  )
  {
    Collections.sort
    (
      array,
      new Comparator<Point>()
      {
        public int compare
        (
          Point obj1,
          Point obj2
        )
        {
          return obj1.y - obj2.y;
        }
      }
    );
  }



  public static ArrayList<Point> sub_array_x
  (
    ArrayList<Point> array,
    Point            point
  )
  {
    ArrayList<Point> ret;
    int              x;
    int              num;
    int              cnt;


    x   = point.x;
    ret = null;

    num = array.size();
    for(cnt=0; cnt<num; cnt++)
    {
      if(x < array.get(cnt).x)
      {
        ret = new ArrayList<Point>(array.subList(cnt, num));
        break;
      }
    }

    return ret;
  }


  static class Point
  {
    public int x;
    public int y;

    public Point
    (
      int x,
      int y
    )
    {
      this.x = x;
      this.y = y;
    }
  }

}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[][] g = new int[N*2][N*2]; // 1:red. 2:blue.
        for(int i = 0; i < N; i++){
            int x = sc.nextInt();
            int y = sc.nextInt();
            g[x][y] = 1;
        }
        for(int i = 0; i < N; i++){
            int x = sc.nextInt();
            int y = sc.nextInt();
            g[x][y] = 2;
        }
        int[][] rest = new int[N*2][N*2];
        int ans = 0;
        for(int x = 0; x < N*2; x++){
            for(int y = 0; y < N*2; y++){
                if(x > 0 && y > 0) rest[x][y] = rest[x-1][y] + rest[x][y-1] - rest[x-1][y-1];
                else if(x == 0 && y > 0) rest[x][y] = rest[x][y-1];
                else if(x > 0 && y == 0) rest[x][y] = rest[x-1][y];

                if(g[x][y] == 1){
                    rest[x][y]++;
                }else if(g[x][y] == 2 && rest[x][y] > 0){
                    ans++;
                    rest[x][y]--;
                }
            }
        }
        System.out.println(ans);
        sc.close();

    }

}

import com.sun.tools.javac.util.Pair;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;



public class Main {

  static Scanner sc = new Scanner(System.in);

  static List<Pair<Integer, Integer>> red = new ArrayList<>();
  static List<Pair<Integer, Integer>> blue = new ArrayList<>();
  static int n;

  public static void main(String[] args) {
    n = sc.nextInt();
    red = new ArrayList<>();
    blue = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      int x = sc.nextInt();
      int y = sc.nextInt();
      red.add(new Pair<>(x, y));
    }
    for (int i = 0; i < n; i++) {
      int x = sc.nextInt();
      int y = sc.nextInt();
      blue.add(new Pair<>(x, y));
    }
    Collections.sort(red, new Comparator<Pair<Integer, Integer>>() {
      @Override public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
        return o1.getKey() - o2.getKey();
      }
    });
    Collections.sort(blue, new Comparator<Pair<Integer, Integer>>() {
      @Override public int compare(Pair<Integer, Integer> o1, Pair<Integer, Integer> o2) {
        return o1.getKey() - o2.getKey();
      }
    });

    int answer = 0;
    answer = search(0, 0, answer);
    System.out.println(answer);
  }

  private static int search(int i, int j, int answer) {
    if (i == n || j == n) {
      return answer;
    }
    if ((red.get(i).getKey() < blue.get(j).getKey()) && (red.get(i).getValue() < blue.get(j)
      .getValue())) {
      answer++;
      i++;
      j++;
      return search(i, j, answer);
    } else {
      return Math.max(search(i + 1, j, answer), search(i, j + 1, answer));
    }
  }
}

