		}

		Comparator<Point> cmp = new Comparator<Main.Point>() {
			@Override
			public int compare(Point o1, Point o2) {
				// TODO Auto-generated method stub
				if (o1.x == o2.x) {
					return o1.y - o2.y;
				} else {
					return o1.x - o2.x;
				}
			}
		};

		Arrays.sort(red, cmp);
		Arrays.sort(blue, cmp);
		boolean[] matched = new boolean[N];
		int pairs = 0;

		for (int i = 0; i < N; i++) {
