    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        Point[] r = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            r[i] = p;
        }
        Point[] b = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            b[i] = p;
        }
        Arrays.sort(r, new PointComparator());
        Arrays.sort(b, new PointComparator());
        int r_l = 0;
        int b_l = 0;
        PointComparator c = new PointComparator();
        int answer = 0;
        boolean[] d = new boolean[N];
        Arrays.fill(d, false);
        while (r_l < N) {
            Point p1 = r[r_l];
            b_l = 0;
            while (b_l < N) {
                if (d[b_l]) {
                    b_l += 1;
                    continue;
                }
                Point p2 = b[b_l];
                if (c.compare(p1, p2) < 0) {
                    answer += 1;
                    d[b_l] = true;
                    break;
                }
                b_l += 1;
            }
            r_l += 1;
        }
