/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            Point[] red = new Point[n];
            Point[] blue = new Point[n];
            for (int i = 0; i < n; i++) {
                red[i] = new Point(in.nextInt(), in.nextInt());
            }

            for (int i = 0; i < n; i++) {
                blue[i] = new Point(in.nextInt(), in.nextInt());
            }

            Arrays.sort(red, new Comparator<Point>() {

                public int compare(Point o1, Point o2) {
                    return o2.y - o1.y;
                }
            });


            Arrays.sort(blue, new Comparator<Point>() {

                public int compare(Point o1, Point o2) {
                    return o1.x - o2.x;
                }
            });

            int cnt = 0;
            for (Point redPoint : red) {
                for (Point bluePoint : blue) {
                    if (bluePoint.x > redPoint.x &&
                            bluePoint.y > redPoint.y) {
                        if (!bluePoint.isPair && !redPoint.isPair) {
                            cnt++;
                            bluePoint.isPair = true;
                            redPoint.isPair = true;
                            break;
                        }
                    }
                }
            }

            out.print(cnt);
        }

    }

    static class Point {
        int x;
        int y;
        boolean isPair;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
            this.isPair = false;
        }

    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
	public static void main(String[] args) {
		final Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		TreeMap<Integer, Integer> map = new TreeMap<>();
		Set<Integer> isRed = new HashSet<>();
		for(int i = 0; i < n; i++) {
			int a = sc.nextInt();
			map.put(a, sc.nextInt());
			isRed.add(a);
		}
		for(int i = 0; i < n; i++) {
			map.put(sc.nextInt(), sc.nextInt());
		}
		TreeSet<Integer> redyset = new TreeSet<>();
		int ans = 0;
		for(Integer x : map.keySet()) {
			if(isRed.contains(x)) {
				redyset.add(map.get(x));
			} else {
				int y = map.get(x);
				if(!redyset.isEmpty() && redyset.first() < y) {
					redyset.pollFirst();
					ans++;
				}
			}
		}
		System.out.println(ans);
	}
}

