	static class Point implements Comparable<Point> {
		int x,y;
		public Point (int x,int y) {
			this.x = x;
			this.y = y;
		}
		@Override
		public int compareTo(Point o) {
			if (this.x == o.x) {
				return this.y - o.y;
			}
			return this.x - o.x;
		}
	}
	public static void main(String[]args) throws Throwable {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		Point red[] = new Point[n];
		Point blue[] = new Point[n];
		for (int i = 0 ; i < n ; ++i) {
			red[i] = new Point(sc.nextInt(),sc.nextInt());
		}
		for (int i = 0 ; i < n ; ++i) {
			blue[i] = new Point(sc.nextInt(),sc.nextInt());
		}
		int ans = 0;
		boolean done[] = new boolean[n];
		Arrays.sort(red);
		Arrays.sort(blue);
		for (int i = n - 1 ; i >= 0 ; --i) {

			int ind = -1, ret = 1 << 30;
			for (int j = 0 ; j < n ; ++j) {
				if (done[j]) {
					continue;
				}
				if (red[i].x >= blue[j].x) {
					continue;
				}
				if (blue[j].y > red[i].y) {
					if (ret > blue[j].y) {
						ret = blue[j].y;
						ind = j;
					}
				}
			}
			if (ind != -1) {
				done[ind] = true;
				++ans;
			}
		}
