	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			List<Integer> x1 = new ArrayList<>();
			List<Integer> y1 = new ArrayList<>();
			List<Integer> x2 = new ArrayList<>();
			List<Integer> y2 = new ArrayList<>();

			for (int i = 0; i < n; i++) {
