			}

			Collections.sort(x1);
			Collections.sort(y1);
			Collections.sort(x2);
			Collections.sort(y2);

			int count1 = 0;
			int count2 = 0;

			for (int i = x1.size() - 1; i >= 0; i--) {
				for (int j = x2.size()-1; j >= 0; j--) {
					if (x1.get(i) < x2.get(j)) {
						count1++;
						x2.remove(j);
						break;
					}
				}
			}

			for (int i = y1.size() - 1; i >= 0; i--) {
				for (int j = y2.size()-1; j >= 0; j--) {
					if (y1.get(i) < y2.get(j)) {
						count2++;
						y2.remove(j);
						break;
					}
				}
			}

			out.println(Math.min(count1, count2));
		}
