import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }
    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        Point[] r = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            r[i] = p;
        }
        Point[] b = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            b[i] = p;
        }
        Arrays.sort(r, new PointComparator());
        Arrays.sort(b, new ReversePointComparator());
        int r_l = 0;
        int b_l = 0;
        PointComparator c = new PointComparator();
        int answer = 0;
        boolean[] d = new boolean[N];
        Arrays.fill(d, false);
        while (r_l < N) {
            Point p1 = r[r_l];
            b_l = 0;
            while (b_l < N) {
                if (d[b_l]) {
                    b_l += 1;
                    continue;
                }
                Point p2 = b[b_l];
                if (c.compare(p1, p2) < 0) {
                    answer += 1;
                    d[b_l] = true;
                    break;
                }
                b_l += 1;
            }
            r_l += 1;
        }
        System.out.println(answer);
    }
    class Point {
        int x;
        int y;
    }
    class PointComparator implements Comparator<Point> {
        @Override
        public int compare(Point o1, Point o2) {
            if (o1.x == o2.x) {
                return Integer.compare(o1.y, o2.y);
            }
            return Integer.compare(o1.x, o2.x);
        }
    }
    class ReversePointComparator implements Comparator<Point> {
        @Override
        public int compare(Point o1, Point o2) {
            if (o1.y == o2.y) {
                return -Integer.compare(o1.x, o2.x);
            }
            return -Integer.compare(o1.y, o2.y);
        }
    }
}

