import java.util.Scanner;
import java.util.ArrayList;

public class Main {

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();

    int[][] red = new int[n][2];
    int[][] blue = new int[n][2];

    for (int i = 0; i < n; ++i) {
      red[i][0] = sc.nextInt();
      red[i][1] = sc.nextInt();
    }

    for (int i = 0; i < n; ++i) {
      blue[i][0] = sc.nextInt();
      blue[i][1] = sc.nextInt();
    }

    ArrayList<Integer>[] binds = new ArrayList[n];
    for (int i = 0; i < n; ++i)
      binds[i] = new ArrayList<>();

    for (int j = 0; j < n; ++j) {
      for (int i = 0; i < n; ++i) {
        if (red[j][0] < blue[i][0] && red[j][1] < blue[i][1]) {
          binds[i].add(j);
        }
      }
    }

    int res = 0;

    int min;

    do {
      min = -1;
      int minSize = n + 1;
      for (int i = 0; i < n; ++i) {
        int sz = binds[i].size();
        if (sz > 0 && sz < minSize) {
          min = i;
          minSize = sz;
        }
      }

      if (min > -1) {
        int j = binds[min].get(0);
        binds[min].clear();
        for (ArrayList list : binds) {
          list.remove(new Integer(j));
        }
        ++res;
      }
    } while (min > -1);

    System.out.println(res);
  }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        D2[] red = new D2[n];
        D2[] blue = new D2[n];
        for (int i = 0;i < n;++i){
            red[i] = new D2(sc.nextInt(),sc.nextInt());
        }
        for (int i = 0;i < n;++i){
            blue[i] = new D2(sc.nextInt(),sc.nextInt());
        }
        boolean[][] select = new boolean[n][n];
        for (int i = 0;i < red.length;++i){
            for (int j = 0;j < blue.length;++j){
                if(red[i].x < blue[j].x&&red[i].y < blue[j].y){select[i][j] = true;}
            }
        }
        System.out.println(search(select,n));

    }

    public static int search(boolean[][] select,int n){
        int max = -1;
        for (int i = 0;i < n;++i){
            for (int j = 0;j < n;++j){
                if(select[i][j]){
                    boolean[][] selectv = new boolean[n][n];
                    for (int k1 = 0;k1 < n;++k1){
                        System.arraycopy(select[k1], 0, selectv[k1], 0, n);
                    }
                    for (int k = 0;k < n;++k){
                        selectv[i][k] = false;
                        selectv[k][j] = false;
                    }
                    int k = search(selectv,n);
                    if(k > max){
                        max = k;
                    }
                }
            }
        }
        return max + 1;
    }


    static class D2{
        public int x,y;
        public D2(int x,int y){
            this.x = x;this.y = y;
        }
    }

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        List<Point> redList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int a = Integer.parseInt(sc.next());
            int b = Integer.parseInt(sc.next());
            redList.add(new Point(a,b));
        }

        List<Point> blueList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int a = Integer.parseInt(sc.next());
            int b = Integer.parseInt(sc.next());
            blueList.add(new Point(a,b));
        }

        int ans = calc(redList, blueList);
        System.out.println(ans);

        sc.close();
    }

    static int calc(List<Point> redList, List<Point> blueList) {
//        System.out.println(redList);
        if (redList.isEmpty()) return 0;
        int[] result = new int[blueList.size()+1];

        Point redPoint = redList.remove(redList.size()-1);
        for (int i = 0; i < blueList.size(); i++) {
            if (redPoint.isGood(blueList.get(i))) {
                List<Point> blueList2 = new ArrayList<>(blueList);
                blueList2.remove(i);
//                Point bluePoint = blueList2.remove(i);
//                System.out.println("[IN ]red:" + redPoint + " / blue:" + bluePoint);
                result[i] = 1 + calc(new ArrayList<>(redList), blueList2);
//                System.out.println("[OUT]red:" + redPoint + " / blue:" + bluePoint + ", result:" + result[i]);
            }
        }
//        result[blueList.size()] = calc(new ArrayList<>(redList), new ArrayList<>(blueList));
        result[blueList.size()] = calc(redList, blueList);

        int max = 0;
        for (int i = 0; i <= blueList.size(); i++) {
            if (max < result[i]) max = result[i];
        }

        return max;
    }

    static class Point {
        int x;
        int y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        boolean isGood(Point o) {
            return ((x < o.x) && (y < o.y));
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }
    }

}

