    private static int[] sort(int[] array, int N){
	for(int i = 0; i < N-1; i++){
	    for(int j = i+1; j < N; j++){
		if(array[i] > array[j]){
		    int tmp = array[i];
		    array[i] = array[j];
		    array[j] = tmp;
		}
	    }
	}

	return array;
    }
