    }
    System.out.println();
    */

    int res = 0;

    for (int j = redL.size() - 1; j >= 0; --j) {
      int[] rPoint = redL.get(j);
      for (int i = blueL.size() - 1; i >= 0; --i) {
        int[] bPoint = blueL.get(i);
        if (rPoint[0] < bPoint[0] && rPoint[1] < bPoint[1]) {
          ++res;
          blueL.remove(i);
          break;
        }
      }
    }

    redL = new ArrayList<>();
    Collections.addAll(redL, mergeSort2(red));

    blueL = new ArrayList<>();
    Collections.addAll(blueL, mergeSort2(blue));

    int res2 = 0;

    for (int j = redL.size() - 1; j >= 0; --j) {
      int[] rPoint = redL.get(j);
      for (int i = blueL.size() - 1; i >= 0; --i) {
        int[] bPoint = blueL.get(i);
        if (rPoint[0] < bPoint[0] && rPoint[1] < bPoint[1]) {
          ++res2;
          blueL.remove(i);
          break;
        }
      }
    }

    System.out.println(Math.max(res, res2));
  }

  public static int[][] mergeSort(int[][] a) {
    if (a.length <= 1)
      return a;

    int mid = a.length / 2;
    int[][] left = new int[mid][2];
    int[][] right = new int[a.length - mid][2];

    for (int i = 0; i < mid; ++i)
      left[i] = a[i];

    for (int i = mid; i < a.length; ++i)
      right[i - mid] = a[i];

    return merge(mergeSort(left), mergeSort(right));
  }

  public static int[][] merge(int[][] l, int[][] r) {
    int[][] merged = new int[l.length + r.length][2];

    int i = 0, j = 0, k = 0;
    while (i < l.length && j < r.length) {
      if (l[i][0] < r[j][0] || (l[i][0] == r[j][0] && l[i][1] <= r[i][1]))
      //if (l[i][0] + l[i][1] <= r[i][0] + r[i][1])
        merged[k++] = l[i++];
      else
        merged[k++] = r[j++];
    }

    while (i < l.length)
      merged[k++] = l[i++];
    while (j < r.length)
      merged[k++] = r[j++];

    return merged;
  }

  public static int[][] mergeSort2(int[][] a) {
    if (a.length <= 1)
      return a;

    int mid = a.length / 2;
    int[][] left = new int[mid][2];
    int[][] right = new int[a.length - mid][2];

    for (int i = 0; i < mid; ++i)
      left[i] = a[i];

    for (int i = mid; i < a.length; ++i)
      right[i - mid] = a[i];

    return merge2(mergeSort2(left), mergeSort2(right));
  }

  public static int[][] merge2(int[][] l, int[][] r) {
    int[][] merged = new int[l.length + r.length][2];

    int i = 0, j = 0, k = 0;
    while (i < l.length && j < r.length) {
      if (l[i][1] < r[j][1] || (l[i][1] == r[j][1] && l[i][0] <= r[i][0]))
        merged[k++] = l[i++];
      else
        merged[k++] = r[j++];
    }

    while (i < l.length)
      merged[k++] = l[i++];
    while (j < r.length)
      merged[k++] = r[j++];

    return merged;
  }
}

