			}
		}

public void solve() {
	int num = ni();
	int red[][] = ni(num, 2);
	Arrays.sort(red, (a, b) -> Long.compare(a[1], b[1]));
	Arrays.sort(red, (a, b) -> Long.compare(a[0], b[0]));
	int blue[][] = ni(num, 2);

	Random rnd = new Random();
	boolean used[][] = new boolean[2][num];
	fill(used, false);
	int maxCnt = 0;
	long startTime = System.currentTimeMillis();
	double rndIndex[][] = new double[num][2];
	int pairCnt[] = new int[num];
	int index[] = new int[num];
	while(System.currentTimeMillis() - startTime < 1700) {
		int cnt = 0;
		for(int j = 0; j < num; j ++) {
			rndIndex[j][0] = rnd.nextDouble();
			rndIndex[j][1] = j;
		}
		Arrays.sort(rndIndex, (a, b) -> Double.compare(a[0], b[0]));
		for(int i = 0; i < num + 10; i ++) {
			fill(pairCnt, 0);
			fill(index, -1);
			for(int j = 0; j < num; j ++) {
				if(used[1][j]) { continue; }
				for(int l = 0; l < num; l ++) {
					int k = (int)rndIndex[l][1];
					if(used[0][k]) { continue; }
					if(red[k][0] < blue[j][0] && red[k][1] < blue[j][1]) {
						index[j] = k;
						pairCnt[j] ++;
					}
				}
				if(pairCnt[j] <= 0) { used[1][j] = true; }
			}
			int minPairCnt = num + 10;
			for(int j = 0; j < num; j ++) {
				if(!used[1][j]) { minPairCnt = min(minPairCnt, pairCnt[j]); }
			}
			for(int j = 0; j < num; j ++) {
				if(pairCnt[j] == minPairCnt) {
					cnt ++;
					used[1][j] = true;
					used[0][index[j]] = true;
					break;
				}
			}
		}
		maxCnt = max(maxCnt, cnt);
	}

	prtln(maxCnt);
}



