import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {
    private static class Pos implements Comparable<Pos> {
        final int x;
        final int y;
        Pos(int x, int y) {
            this.x = x;
            this.y = y;
        }
        @Override
        public int compareTo(Pos o) {
            if (x < o.x)
                return -1;
            if (x > o.x)
                return 1;
            if (y < o.y)
                return -1;
            if (y > o.y)
                return 1;
            return 0;
        }
    }
    static void solve(MyScanner in, PrintWriter out) {
        int n = in.nextInt();
        Pos[] reds = new Pos[n];
        for (int i = 0; i < n; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            reds[i] = new Pos(a, b);
        }
        Pos[] blues = new Pos[n];
        for (int i = 0; i < n; i++) {
            int c = in.nextInt();
            int d = in.nextInt();
            blues[i] = new Pos(c, d);
        }
        Arrays.sort(blues);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            Pos blue = blues[i];
            int maxY = -1;
            int pair = -1;
            for (int j = 0; j < n; j++) {
                Pos red = reds[j];
                if (red == null) {
                    continue;
                }
                if (red.compareTo(blue) < 0 && red.y > maxY) {
                    maxY = red.y;
                    pair = j;
                }
            }
            if (pair != -1) {
                reds[pair] = null;
                ans++;
            }
        }
        out.println(ans);
    }

    public static void main(String[] args) {
        PrintWriter w = new PrintWriter(System.out);
        solve(new MyScanner(System.in), w);
        w.flush();
    }

    static final class MyScanner {
        static final int BUFFER_SIZE = 8192;
        private final InputStream in;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int point;
        private int readLength;
        MyScanner(InputStream in) {
            this.in = in;
        }
        private int readByte() {
            if (point < readLength) {
                int result = buffer[point];
                point += 1;
                return result;
            }
            try {
                readLength = in.read(buffer);
            } catch (IOException e) {
                throw new AssertionError(null, e);
            }
            if (readLength == -1)
                return -1;
            point = 1;
            return buffer[0];
        }
        private static boolean isPrintableCharExceptSpace(int c) {
            return 33 <= c && c <= 126;
        }
        String next() {
            int c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1)
                throw new NoSuchElementException();
            StringBuilder b = new StringBuilder();
            do {
                b.appendCodePoint(c);
                c = readByte();
            } while (c != -1 && isPrintableCharExceptSpace(c));
            return b.toString();
        }
        long nextLong() {
            int c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1)
                throw new NoSuchElementException();
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            long result = 0L;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                result = result * 10L + (c - '0');
                c = readByte();
            } while (c != -1 && isPrintableCharExceptSpace(c));
            return minus ? -result : result;
        }
        int nextInt() {
            long n = nextLong();
            if (n < Integer.MIN_VALUE || n > Integer.MAX_VALUE)
                throw new InputMismatchException();
            return (int)n;
        }
        double nextDouble() {
            return Double.parseDouble(next());
        }
        int[] nextIntArray(int n) {
            int[] result = new int[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextInt();
            }
            return result;
        }
        private static boolean allSameLength(int[] a, int[] b, int[]... c) {
            if (a.length != b.length)
                return false;
            for (int[] element : c)
                if (a.length != element.length)
                    return false;
            return true;
        }
        private static boolean allSameLength(char[] a, char[] b, char[]... c) {
            if (a.length != b.length)
                return false;
            for (char[] element : c)
                if (a.length != element.length)
                    return false;
            return true;
        }
        void nextVerticalIntArrays(int[] a, int[] b, int[]... c) {
            if (!allSameLength(a, b, c))
                throw new IllegalArgumentException();
            for (int i = 0; i < a.length; i++) {
                a[i] = nextInt();
                b[i] = nextInt();
                for (int[] d : c) {
                    d[i] = nextInt();
                }
            }
        }
        long[] nextLongArray(int n) {
            long[] result = new long[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextLong();
            }
            return result;
        }
        char nextChar() {
            int c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1)
                throw new NoSuchElementException();
            return (char)c;
        }
        char[] nextCharArray(int n) {
            char[] result = new char[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextChar();
            }
            return result;
        }
        char[][] next2dCharArray(int n, int m) {
            char[][] result = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = nextChar();
                }
            }
            return result;
        }
        void nextVerticalCharArrays(char[] a, char[] b, char[]... c) {
            if (!allSameLength(a, b, c))
                throw new IllegalArgumentException();
            for (int i = 0; i < a.length; i++) {
                a[i] = nextChar();
                b[i] = nextChar();
                for (char[] d : c) {
                    d[i] = nextChar();
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    static int N;
    static Cord[] R;
    static Cord[] B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();

        R = new Cord[N];
        for (int i = 0; i < N; i++) {
            R[i] = new Cord(i, sc.nextInt(), sc.nextInt());
        }
        B = new Cord[N];
        for (int i = 0; i < N; i++) {
            B[i] = new Cord(i, sc.nextInt(), sc.nextInt());
        }

        System.out.println( solve() );
    }

    private static int solve() {
        Set<Integer>[] B2R = new Set[N];
        Set<Integer>[] R2B = new Set[N];
        for (int i = 0; i < N; i++) {
            B2R[i] = new HashSet<>();
            R2B[i] = new HashSet<>();
        }

        for (int b = 0; b < N; b++) {
            for (int r = 0; r < N; r++) {
                if( isFriendable(B[b], R[r]) ) {
                    B2R[b].add(r);
                    R2B[r].add(b);
                }
            }
        }

        // 二部グラフの最大マッチングらしいがアルゴリズムを知らないのでなんかそれっぽく頑張っている
        int pair = 0;
        while(true) {
            Pair p = findPair(B2R, R2B);
            if( p != null ) {
                B2R[p.b].clear();
                R2B[p.r].clear();

                for (Set<Integer> rs : B2R) rs.remove(p.r);
                for (Set<Integer> bs : R2B) bs.remove(p.b);
                pair++;
            } else {
                break;
            }
        }
        return pair;
    }

    static Pair findPair(Set<Integer>[] B2R, Set<Integer>[] R2B) {
        for (int b = 0; b < N; b++) {
            Set<Integer> set = B2R[b];
            if( set.size() == 1 ) {
                int r = set.iterator().next();
                return new Pair(b, r);
            }
        }

        for (int r = 0; r < N; r++) {
            Set<Integer> set = R2B[r];
            if( set.size() == 1 ) {
                int b = set.iterator().next();
                return new Pair(b, r);
            }
        }

        // なんか適当なsizeのやつから適当に取り除く
        for (int b = 0; b < N; b++) {
            Set<Integer> set = B2R[b];
            if( !set.isEmpty() ) {
                int r = set.iterator().next();
                return new Pair(b, r);
            }
        }

        for (int r = 0; r < N; r++) {
            Set<Integer> set = R2B[r];
            if( !set.isEmpty() ) {
                int b = set.iterator().next();
                return new Pair(b, r);
            }
        }

        return null;
    }

    static class Pair {
        int b;
        int r;

        public Pair(int b, int r) {
            this.b = b;
            this.r = r;
        }
    }

    private static boolean isFriendable(Cord b, Cord r) {
        return b.x > r.x && b.y > r.y;
    }

    static class Cord {
        int i;
        int x;
        int y;

        public Cord(int i, int x, int y) {
            this.i = i;
            this.x = x;
            this.y = y;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

