		for(int i=0;i<n;i++) {
			int[] ab = new int[2];
			ab[0] = in.nextInt();
			ab[1] = in.nextInt();
			listcd.add(ab);
		}
		listcd.sort((ab1,ab2)->ab1[0]-ab2[0]);

