			int[] cd = new int[2];
			cd[0] = in.nextInt();
			cd[1] = in.nextInt();
			listab.add(cd);
		}
		listab.sort((cd1,cd2)->cd1[0]-cd2[0]);

		boolean[] usedcd = new boolean[n];
		int count = 0;
		for(int i=0;i<n;i++) {
