	/*
	 * int[][]
	 * int[][0]が小さいのが先(xが小さいのが先)
	 * int[][1]が大きいのが先(yが大きいのが先)
	 */
	private static class SortComparatorC2 implements Comparator<int[]> {

		@Override
		public int compare(int[] o1, int[] o2) {
			if (o1[0] < o2[0]) {
				return -1;
			} else if (o1[0] > o2[0]) {
				return 1;
			} else {
				if (o1[1] < o2[1]) {
					return 1;
				} else if (o1[1] > o2[1]) {
					return -1;
				} else {
					return 0;
				}
			}

		}

	}

