				p2.add(new P(in.nextInt(), in.nextInt()));
			}

			q1 = copy(p1);
			q2 = copy(p2);
			s1 = copy(p1);
			s2 = copy(p2);
			t1 = copy(p1);
			t2 = copy(p2);

			Collections.sort(p1, new MyComparator());
			Collections.sort(p2, new MyComparator());

			Collections.sort(t1, new MyComparator());
			Collections.sort(t2, new MyComparator());

			int count1 = 0;
			int count2 = 0;
			int count3 = 0;
			int count4 = 0;

			for (int i = p1.size() - 1; i >= 0; i--) {
				for (int j = p2.size()-1; j >= 0; j--) {
					if (p1.get(i).x < p2.get(j).x && p1.get(i).y < p2.get(j).y) {
						count1++;
						p2.remove(j);
						break;
					}
				}
			}

			for (int i = 0; i < t1.size(); i++) {
				for (int j = 0; j < t2.size(); j++) {
					if (t1.get(i).x < t2.get(j).x && t1.get(i).y < t2.get(j).y) {
						count3++;
						t2.remove(j);
						break;
					}
				}
			}

			Collections.sort(q1, new MyComparator2());
			Collections.sort(q2, new MyComparator2());

			Collections.sort(s1, new MyComparator2());
			Collections.sort(s2, new MyComparator2());

			for (int i = q1.size() - 1; i >= 0; i--) {
				for (int j = q2.size()-1; j >= 0; j--) {
					if (q1.get(i).x < q2.get(j).x && q1.get(i).y < q2.get(j).y) {
						count2++;
						q2.remove(j);
						break;
					}
				}
			}

			for (int i = 0; i < s1.size(); i++) {
				for (int j = 0; j < s2.size(); j++) {
					if (s1.get(i).x < s2.get(j).x && s1.get(i).y < s2.get(j).y) {
						count4++;
						s2.remove(j);
						break;
					}
				}
			}

			out.println(Math.max(Math.max(count1, count2),Math.max(count3, count4)));
		}

	}

