            for (int j = red.length - 1; j >= 0; j--) {
                if (blue[i][0] > red[j][0] && blue[i][1] > red[j][1] && !used[j]) {
                    used[j] = true;
                    cnt++;
                    break;
                }
            }
        }

        out.println(cnt);
    }
}

