            List<Point> redPoint = new List<Point>();
            for(int i = 0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                redPoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }
            List<Point> bluePoint = new List<Point>();
            for(int i = 0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                bluePoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }

            Dictionary<Point, List<Point>> pairC = new Dictionary<Point, List<Point>>();
            foreach(Point bp in bluePoint)
            {
                List<Point> cList = new List<Point>();
                foreach(Point rp in redPoint)
                {
                    if(rp.X < bp.X && rp.Y < bp.Y)
                    {
                        cList.Add(rp);
                    }
                }
                pairC.Add(bp, cList);
            }
            HashSet<Point> usedPoint = new HashSet<Point>();
            int pairCnt = GetPairCount(bluePoint, pairC, 0, usedPoint);

            Console.WriteLine(pairCnt);
        }

        private static int GetPairCount(List<Point> bluePoint, Dictionary<Point, List<Point>> pairC, int bi, HashSet<Point> usedPoint)
        {
            int max = usedPoint.Count;

            for(int i = bi; i < bluePoint.Count; i++)
            {
                HashSet<Point> cList = new HashSet<Point>();
                pairC[bluePoint[i]].Sort((a, b) => b.X - a.X);
                List<Point> rPXS = new List<Point>(pairC[bluePoint[i]]);
                pairC[bluePoint[i]].Sort((a, b) => b.Y - a.Y);
                List<Point> rPYS = new List<Point>(pairC[bluePoint[i]]);
                IEnumerable<Point> xm = rPXS.Where((x) => !usedPoint.Contains(x));
                if(xm.Count() > 0)
                {
                    cList.Add(xm.First());
                }
                IEnumerable<Point> ym = rPYS.Where((x) => !usedPoint.Contains(x));
                if(ym.Count() > 0)
                {
                    cList.Add(ym.First());
                }

                foreach(Point rp in cList)
                {
                    usedPoint.Add(rp);
                    int cnt;
                    if(i >= bluePoint.Count - 1)
                    {
                        cnt = usedPoint.Count;
                    }
                    else
                    {
                        cnt = GetPairCount(bluePoint, pairC, i + 1, usedPoint);
                    }
                    usedPoint.Remove(rp);
                    max = Math.Max(max, cnt);
                }
            }

            return max;
        }
    }

    public class Point
    {
        public int X;
        public int Y;
    }
}

