        /// <summary>
        /// 指定した値以上の先頭のインデクスを返す
        /// </summary>
        /// <typeparam name="T">比較する値の型</typeparam>
        /// <param name="arr">対象の配列（※ソート済みであること）</param>
        /// <param name="start">開始インデクス [inclusive]</param>
        /// <param name="end">終了インデクス [exclusive]</param>
        /// <param name="value">検索する値</param>
        /// <param name="comparer">比較関数(インターフェイス)</param>
        /// <returns>指定した値以上の先頭のインデクス</returns>
        public static int LowerBound<T>(IReadOnlyList<T> arr, int start, int end, T value, IComparer<T> comparer)
        {
            int low = start;
            int high = end;
            int mid;
            while (low < high)
            {
                mid = ((high - low) >> 1) + low;
                if (comparer.Compare(arr[mid], value) < 0)
                    low = mid + 1;
                else
                    high = mid;
            }
            return low;
        }

        //引数省略のオーバーロード
        public static int LowerBound<T>(IReadOnlyList<T> arr, T value) where T : IComparable
        {
            return LowerBound(arr, 0, arr.Count, value, Comparer<T>.Default);
        }

        /// <summary>
        /// 指定した値より大きい先頭のインデクスを返す
        /// </summary>
        /// <typeparam name="T">比較する値の型</typeparam>
        /// <param name="arr">対象の配列（※ソート済みであること）</param>
        /// <param name="start">開始インデクス [inclusive]</param>
        /// <param name="end">終了インデクス [exclusive]</param>
        /// <param name="value">検索する値</param>
        /// <param name="comparer">比較関数(インターフェイス)</param>
        /// <returns>指定した値より大きい先頭のインデクス</returns>
        public static int UpperBound<T>(IReadOnlyList<T> arr, int start, int end, T value, IComparer<T> comparer)
        {
            int low = start;
            int high = end;
            int mid;
            while (low < high)
            {
                mid = ((high - low) >> 1) + low;
                if (comparer.Compare(arr[mid], value) <= 0)
                    low = mid + 1;
                else
                    high = mid;
            }
            return low;
        }

        //引数省略のオーバーロード
        public static int UpperBound<T>(IReadOnlyList<T> arr, T value)
        {
            return UpperBound(arr, 0, arr.Count, value, Comparer<T>.Default);
        }
        #endregion
    }
}

using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Threading.Tasks;

class Program
{
	/*
	・概要
	最大流問題の解決に使用
	計算量は、O(V^2 * E)
	（頂点の数がV、辺の数がE）

	・（最大）二部マッチング問題
	二集団の前後にノード（スタートとゴール）を付け加えることで、最大流問題に帰着可能
	（cf. 重みづけがない場合は、フローを全て1にすれば良いだけ）

	・使用法
	有向グラフの辺の数だけAddEdgeを呼び出し、辺の始点、終点、フローを与える。
	MaxFlowが最大フローを返す。

	*/

	//Main
	static void Main(string[] args)
	{
		//読み込む
		int N = int.Parse(Console.ReadLine());

		//x座標とy座標を合わせたジャグ配列
		int[][] redCoord = new int[N][];
		//ソート の都合上、{x,y}とする
		int[][] blueCoord = new int[N][];

		//読み込む
		for(int i=0; i<N; i++){
			string[] S = Console.ReadLine().Split(' ');
			int a = int.Parse(S[0]);
			int b = int.Parse(S[1]);

			redCoord[i] = new int[2]{a,b};
		}
		for(int i=0; i<N; i++){
			string[] S = Console.ReadLine().Split(' ');
			int c = int.Parse(S[0]);
			int d = int.Parse(S[1]);

			blueCoord[i] = new int[2]{c,d};
		}

		//1. Dinicクラスのインスタンスを作成
		//ノード数は、両集団の構成員数＋２（スタートとゴール）
		Dinic maxPair = new Dinic(N+N+2);

		//2. 辺を結合
		/*
		まず、スタートと赤と、青とゴールとを全て繋ぐ
		スタートはノード2N、ゴールはノード2N+1（= 2N+2 - 1）とする
		*/
		int start = 2*N;
		int goal = 2*N + 1;
		for(int i=0; i<N; i++){
			int redNode = i;
			int blueNode = i+N;
			maxPair.AddEdge(start,redNode,1);
			maxPair.AddEdge(blueNode,goal,1);
		}

		//次に、赤と青との間に辺を結合できる場合（マッチング可能な場合）、辺を追加
		/*
		cf. この段階で、O(N*N)時間かかる
		*/
		for(int i=0; i<N; i++){
			for(int j=0; j<N; j++){
				int redNode = i;
				int blueNode = j+N;
				//結合可能な場合
				if(redCoord[i][0] < blueCoord[j][0] && redCoord[i][1] < blueCoord[j][1]){
					//重みはないので、常にフローは1
					maxPair.AddEdge(redNode,blueNode,1);
				}
			}
		}

		//スタートからゴールまでの最大流を求める
		int ans = maxPair.MaxFlow(start,goal);

		Console.WriteLine(ans);
	}
}


//Dinic法用のクラス
/*
・注意
辺のフローがint型の範囲内のものでしか使用できない。

辺のフローがlong型やdouble型の問題に利用したい場合、
EdgeクラスのCapプロパティに対応する部分を書き換える必要あり。
*/


class Dinic
{
		//深さ優先探索で十分に大きい値として使用
		static int bigEnough = 100000;

		//コンストラクタ
		/*
		全体のノード数で初期化
		*/
		public Dinic(int node_size)
		{
				V = node_size;
				G = Enumerable.Repeat(0, V).Select(_=> new List<Edge>()).ToList();
				level = Enumerable.Repeat(0, V).ToList();
				iter = Enumerable.Repeat(0, V).ToList();
		}

		class Edge
		{
				public Edge(int to, int cap, int rev)
				{
						To = to; Cap = cap; Rev = rev;
				}
				public int To { get; set; }
				public int Cap { get; set; }
				public int Rev { get; set; }
		}

		List<List<Edge>> G;
		int V;
		List<int> level;
		List<int> iter;

		//辺を追加
		/*
		引数：出発点、行き先、capacity（その辺の最大流）
		（＝始点、終点、フロー）
		*/
		public void AddEdge(int from,int to,int cap)
		{
				G[from].Add(new Edge(to, cap, G[to].Count));
				G[to].Add(new Edge(from, 0, G[to].Count - 1));
		}

		//最大流を返す
		/*
		引数：出発点、行き先（スタートとゴール）
		*/
		public int MaxFlow(int s,int t)
		{
				int flow = 0;
				while (true)
				{
						BFS(s);
						if (level[t] < 0) { return flow; }
						iter = Enumerable.Repeat(0, V).ToList() ;
						var f = DFS(s, t, bigEnough);
						while (f > 0)
						{
								flow += f;
								f = DFS(s, t, bigEnough);
						}
				}
		}

		void BFS(int s)
		{
				level = Enumerable.Repeat(-1, V).ToList();
				level[s] = 0;
				var que = new Queue<int>();
				que.Enqueue(s);
				while (que.Count != 0)
				{
						var v = que.Dequeue();
						for(int i = 0; i < G[v].Count; i++)
						{
								var e = G[v][i];
								if(e.Cap>0 && level[e.To]< 0)
								{
										level[e.To] = level[v] + 1;
										que.Enqueue(e.To);
								}
						}
				}
		}

		int DFS(int v,int t,int f)
		{
				if (v == t) return f;
				for(int i = iter[v]; i < G[v].Count; i++)
				{
						iter[v] = i;
						var e = G[v][i];
						if(e.Cap>0 && level[v] < level[e.To])
						{
								var d = DFS(e.To, t, Math.Min(f, e.Cap));
								if (d > 0)
								{
										e.Cap -= d;
										G[e.To][e.Rev].Cap += d;
										return d;
								}
						}
				}
				return 0;
		}
}

