        /// <summary>
        /// 昇順ソート済みリストに対しての二分探索系
        /// </summary>
        static class Search
        {
            /// <summary>
            /// Bound系の下請け
            /// </summary>
            static int FindBound<T>(IList<T> list, T v, int begin, int end, Func<T, T, bool> judge) where T : IComparable<T>
            {
                int low = begin, high = end;

                if (low > high) { throw new ArgumentException(); }

                while (low < high)
                {
                    var mid = (high + low) / 2;

                    if (judge(v, list[mid])) { high = mid; }
                    else { low = mid + 1; }
                }

                return low;
            }

            /// <summary>
            /// v以上で最小のインデックスを返す
            /// </summary>
            public static int LowerBound<T>(IList<T> list, T v, int begin, int end) where T : IComparable<T>
                => FindBound(list, v, begin, end, (x, y) => x.CompareTo(y) <= 0);

            /// <summary>
            /// v以上で最小のインデックスを返す
            /// </summary>
            public static int LowerBound<T>(IList<T> list, T v) where T : IComparable<T>
                => LowerBound<T>(list, v, 0, list.Count());

            /// <summary>
            /// vより大きな最小のインデックスを返す
            /// </summary>
            public static int UpperBound<T>(IList<T> list, T v, int begin, int end) where T : IComparable<T>
                => FindBound(list, v, begin, end, (x, y) => x.CompareTo(y) < 0);

            /// <summary>
            /// vより大きな最小のインデックスを返す
            /// </summary>
            public static int UpperBound<T>(IList<T> list, T v) where T : IComparable<T>
                => UpperBound(list, v, 0, list.Count());

            /// <summary>
            /// 範囲中でvと等価な個数を返す
            /// </summary>
            public static int EqualRange<T>(IList<T> list, T v, int begin, int end) where T : IComparable<T>
                => UpperBound(list, v, begin, end) - LowerBound(list, v, begin, end);

            /// <summary>
            /// 範囲中でvと等価な個数を返す
            /// </summary>
            public static int EqualRange<T>(IList<T> list, T v) where T : IComparable<T>
                => UpperBound(list, v) - LowerBound(list, v);

            /// <summary>
            /// v以下で最大のインデックスを返す
            /// O(logN+N)なので注意
            /// </summary>
            public static int OrLess<T>(IList<T> list, T v, int begin, int end) where T : IComparable<T>
            {
                var i = LowerBound(list, v, begin, end);

                if (list[i].CompareTo(v) != 0)
                {
                    // v未満で最大の値とする
                    if (i > 0) i--;
                }
                else
                {
                    // vと同じ値で、一番最後へ移動させる
                    while (i < end && list[i + 1].CompareTo(v) == 0) { i++; }
                }

                return i;
            }

            /// <summary>
            /// v以下で最大のインデックスを返す
            /// O(logN+N)なので注意
            /// </summary>
            public static int OrLess<T>(IList<T> list, T v) where T : IComparable<T>
                => OrLess(list, v, 0, list.Count());

            /// <summary>
            /// v未満で最大のインデックスを返す
            /// </summary>
            public static int LessThan<T>(IList<T> list, T v, int begin, int end) where T : IComparable<T>
            {
                var i = LowerBound(list, v, begin, end);

                // v未満で最大の値とする
                return (i > 0) ? i - 1 : i;
            }

            /// <summary>
            /// v以下で最大のインデックスを返す
            /// </summary>
            public static int LessThan<T>(IList<T> list, T v) where T : IComparable<T>
                => LessThan(list, v, 0, list.Count());
        }

        /// <summary>
        /// 最大フローを求める
        /// 応用：2部最大マッチング
        /// </summary>
        class Dinic
        {
            static readonly int INF = int.MaxValue / 3;

            class Edge
            {
                public int To;
                // 逆辺
                public int Capacity;
                public int Rev;

                public Edge(int to, int cap, int r)
                {
                    this.To = to;
                    this.Capacity = cap;
                    this.Rev = r;
                }
            }

            readonly List<Edge>[] G;

            // sからの距離
            readonly int[] Level;

            // 調査済みフラグ
            readonly int[] Iter;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="n">ノード数</param>
            public Dinic(int n)
            {
                G = Enumerable.Range(0, n)
                    .Select(_ => new List<Edge>())
                    .ToArray();

                Level = new int[n];
                Iter = new int[n];
            }

            /// <summary>
            /// 流路追加
            /// </summary>
            /// <param name="from"></param>
            /// <param name="to"></param>
            /// <param name="cap"></param>
            public void Add(int from, int to, int cap)
            {
                G[from].Add(new Edge(to, cap, G[to].Count));
                G[to].Add(new Edge(from, 0, G[from].Count - 1));
            }

            void Bfs(int s)
            {
                for (int i = 0; i < Level.Length; i++)
                {
                    Level[i] = -1;
                }
                var q = new Queue<int>();

                Level[s] = 0;
                q.Enqueue(s);

                while (q.Any())
                {
                    var v = q.Dequeue();
                    for (int i = 0; i < G[v].Count(); i++)
                    {
                        var e = G[v][i];
                        if (e.Capacity > 0 && Level[e.To] < 0)
                        {
                            Level[e.To] = Level[v] + 1;
                            q.Enqueue(e.To);
                        }
                    }
                }
            }

            int Dfs(int v, int t, int f)
            {
                if (v == t) return f;
                for (int i = Iter[v]; i < G[v].Count(); Iter[v] = ++i)
                {
                    var e = G[v][i];
                    if (e.Capacity > 0 && Level[v] < Level[e.To])
                    {
                        int d = Dfs(e.To, t, Math.Min(f, e.Capacity));
                        if (d > 0)
                        {
                            e.Capacity -= d;
                            G[e.To][e.Rev].Capacity += d;
                            return d;
                        }
                    }
                }

                return 0;
            }

            /// <summary>
            /// 最大流量を調べる
            /// </summary>
            /// <param name="s">始点</param>
            /// <param name="t">終点</param>
            /// <returns></returns>
            public int Flow(int s, int t)
            {
                if (s == t)
                {
                    return 0;
                }

                int flow = 0;

                while (true)
                {
                    Bfs(s);
                    if (Level[t] < 0) return flow;
                    for (int i = 0; i < Iter.Length; i++)
                    {
                        Iter[i] = 0;
                    }

                    int f;
                    while ((f = Dfs(s, t, INF)) > 0)
                    {
                        flow += f;
                    }
                }
            }

            /// <summary>
            /// 始点と終点の探索
            /// 一意に定まると仮定して返答する
            /// </summary>
            /// <returns></returns>
            public Tuple<int, int> Find()
            {
                // 始点: 誰からも流れてきていない
                var s = Enumerable.Range(0, G.Count())
                    .Except(G.SelectMany(x => x.Select(y => y.To)))
                    .FirstOrDefault();

                // 終点: 誰へも流さない
                var t = Enumerable.Range(0, G.Count())
                    .FirstOrDefault(x => !G[x].Any(y => y.Capacity > 0));

                return new Tuple<int, int>(s, t);
            }
        }

