      if (maxv<b)maxv=b;
      ctr--;
      return;
    }

    for (int i = 0; i < list[ctr].Count; i++) {
      if (list[ctr][i] != -1 && !chk[list[ctr][i]] ) {
        sList.Add(list[ctr][i]);
        sLisCount++;
        chk[list[ctr][i]] = true;
        ctr++;
        search( b + 1);
      }else{
        sList.Add(-1);
        sLisCount++;
        ctr++;
        search( b );
      }
    }

    if (sList.Count!=0){
      if (sList[sLisCount - 1] !=-1)chk[sList[sLisCount - 1]]=false;
      sList.RemoveAt(sLisCount - 1);
      sLisCount--;
    }
    ctr--;
    return;
  }


}

