        static public void Solve()
        {
            var N = NN;
            var ab = Repeat(0, N).Select(_ => new { a = NN, b = NN }).ToArray();
            var cd = Repeat(0, N).Select(_ => new { c = NN, d = NN }).ToArray();
            var path = Repeat(0, 2 * N + 2).Select(_ => new List<int>()).ToArray();
            for (var i = 0; i < N; i++)
            {
                for (var j = 0; j < N; j++)
                {
                    if (cd[j].c > ab[i].a && cd[j].d > ab[i].b)
                    {
                        path[j + 1 + N].Add(i + 1);
                    }
                }
            }
            for (var i = 1; i <= N; i++)
            {
                path[0].Add(i + (int)N);
                path[i].Add(2 * (int)N + 1);
            }
            var s = 0;
            var t = 2 * (int)N + 1;

            var cap = Repeat(0, 2 * N + 2).Select(_ => new Dictionary<long, long>()).ToArray();
            for (var i = 0; i < path.Length; i++)
            {
                foreach (var item in path[i])
                {
                    cap[i][item] = 1;
                    cap[item][i] = 0;
                }
            }

            // maxflow
            var done = new bool[2 * N + 2];
            Func<long, long, long, long> dfs = (x, y, z) => default(long);
            dfs = (from, to, flow) =>
            {
                if (from == to) return flow;
                done[from] = true;
                foreach (var item in cap[from])
                {
                    if (done[item.Key] || item.Value == 0) continue;
                    var f = dfs(item.Key, to, Min(flow, item.Value));
                    if (f != 0)
                    {
                        cap[from][item.Key] -= f;
                        cap[item.Key][from] += f;
                        return f;
                    }
                }
                return 0;
            };
            while (dfs(s, t, long.MaxValue >> 1) != 0) done = new bool[2 * N + 2];

            Console.WriteLine(cap[s].Sum(e => 1 - e.Value));
        }

