    public static int Main()
    {
        new Solve().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        var points = new Point[2*N];
        for(int i=0; i<2*N; i++)
        {
            int color = i < N ? 0 : 1;
            points[i] = new Point(color, cin.nextInt(), cin.nextInt());
        }
        var sorted = points.OrderBy(a => a.X);
        var set = new List<Point>();
        var matchedCount = 0;
        foreach (var point in sorted)
        {
            if(point.Color == 0)//red
            {
                set.Add(point);
            }
            else//blue
            {
                if(set.Count() > 0)
                {
                    var highestIndex = 0;
                    var highestRedY = int.MinValue;
                    var indexCount = 0;
                    var isMatched = false;
                    foreach(var s in set)
                    {
                        if(s.Y < point.Y && s.Y > highestRedY)
                        {
                            highestRedY = s.Y;
                            highestIndex = indexCount;
                            isMatched = true;
                        }
                        indexCount++;
                    }
                    if(isMatched)
                    {
                        set[highestIndex].Y = int.MaxValue;
                        matchedCount++;
                    }
                }
            }
        }
        Console.WriteLine(matchedCount.ToString());

    }
}
