            IO.Printer.Out.Flush();
        }
    }

    /// <summary>
    /// get max matching between left side nodes and right side nodes
    /// </summary>
    public class BipartiteMatching
    {
        Dinic fordFulkerson;
        HashSet<int> startVertice = new HashSet<int>();
        HashSet<int> targetVertice = new HashSet<int>();

        public BipartiteMatching()
        {
            fordFulkerson = new Dinic();
        }

        public void AddPair(int leftSide, int rightSide)
        {
            fordFulkerson.AddEdge(leftSide, rightSide, 1);

            startVertice.Add(leftSide);
            targetVertice.Add(rightSide);
        }

        public double GetMaxMatchingNum()
        {
            int start = fordFulkerson.MaxIdx + 1;
            int target = start + 1;

            foreach (var s in startVertice)
            {
                fordFulkerson.AddEdge(start, s, 1);
            }
            foreach (var t in targetVertice)
            {
                fordFulkerson.AddEdge(t, target, 1);
            }

            return fordFulkerson.GetMaxFlow(start, target);
        }
    }

    /// <summary>
    /// get max flow from s to t
    /// </summary>
    public class Dinic
    {
        public class Edge
        {
            public int V;
            public double C;
            public Edge N;
            public Edge B;
        }

        Edge[] _pool = new Edge[0];
        int _topIdx;

        Edge[] _adj = new Edge[0];

        public int MaxIdx;
        int _minV;

        public Dinic()
        {
            Expand(ref _pool, 128, true);
            Expand(ref _adj, 128, false);
            Init();
        }

        public void Init()
        {
            for (int i = 0; i < _adj.Length; i++) _adj[i] = null;
            _topIdx = 0;
            MaxIdx = 0;
            _minV = Int32.MaxValue;
        }

        void Expand(ref Edge[] edges, int size, bool fillWithEmptyEdge = false)
        {
            if (edges.Length <= size)
            {
                var newEdges = new Edge[Math.Max(size, edges.Length * 2)];
                for (int i = 0; i < edges.Length; i++) newEdges[i] = edges[i];
                if (fillWithEmptyEdge)
                {
                    for (int i = edges.Length; i < newEdges.Length; i++)
                    {
                        newEdges[i] = new Edge();
                    }
                }
                edges = newEdges;
            }
        }

        public void AddEdge(int u, int v, double c, double bc = 0)
        {
            MaxIdx = Math.Max(MaxIdx, Math.Max(u + 1, v + 1));
            _minV = Math.Min(_minV, Math.Min(u, v));

            Expand(ref _pool, _topIdx + 1, true);
            Expand(ref _adj, MaxIdx);

            _pool[_topIdx].V = v;
            _pool[_topIdx].C = c;
            _pool[_topIdx].N = _adj[u];
            _adj[u] = _pool[_topIdx];
            _topIdx++;

            _pool[_topIdx].V = u;
            _pool[_topIdx].C = bc;
            _pool[_topIdx].N = _adj[v];
            _adj[v] = _pool[_topIdx];
            _topIdx++;

            _adj[u].B = _adj[v];
            _adj[v].B = _adj[u];

            if (u == v)
            {
                _adj[u].N.B = _adj[u];
                _adj[v].B = _adj[v].N;
            }
        }

        int[] _d;
        int[] _q;
        int _qh;
        int _qt;
        Edge[] _cur;

        public double GetMaxFlow(int s, int t)
        {
            MaxIdx = Math.Max(MaxIdx, Math.Max(s + 1, t + 1));
            _minV = Math.Min(_minV, Math.Min(s, t));

            _d = new int[MaxIdx];
            _q = new int[MaxIdx];
            _cur = new Edge[MaxIdx];

            double f = 0;

            while (ReLabel(s, t))
            {
                for (int i = 0; i < MaxIdx; i++) _cur[i] = _adj[i];
                f += Augument(s, t, s, double.MaxValue);
            }

            return f;
        }

        bool ReLabel(int s, int t)
        {
            for (int i = 0; i < MaxIdx; i++) _d[i] = Int32.MaxValue;
            _d[_q[_qh = _qt = 0] = t] = 0;
            while (_qh <= _qt)
            {
                var u = _q[_qh++];

                for (var i = _adj[u]; i != null; i = i.N)
                {
                    if (i.B.C != 0 && _d[i.V] > _d[u] + 1)
                    {
                        _d[i.V] = _d[u] + 1;
                        if ((_q[++_qt] = i.V) == s)
                        {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        double Augument(int s, int t, int u, double e)
        {
            if (u == t) return e;
            double f = 0;

            for (var i = _cur[u]; i != null; i = i.N)
            {
                if (i.C > 0 && _d[u] == _d[i.V] + 1)
                {
                    var df = Augument(s, t, i.V, Math.Min(e, i.C));
                    if (df > 0)
                    {
                        i.C -= df;
                        i.B.C += df;
                        e -= df;
                        f += df;
                    }
                }
                if (!(e > 0)) break;
            }

            return f;
        }

        // (S, T)
        public Tuple<List<int>, List<int>> GetStCut(int s)
        {
            var used_flg = new bool[MaxIdx];

            Dfs(s, used_flg);

            var ret_s = new List<int>();
            var ret_t = new List<int>();
            for (int i = _minV; i < MaxIdx; i++)
            {
                if (!used_flg[i])
                {
                    ret_t.Add(i);
                }
                else
                {
                    ret_s.Add(i);
                }
            }

            return new Tuple<List<int>, List<int>>(ret_s, ret_t);
        }

        void Dfs(int u, bool[] used_flg)
        {
            if (used_flg[u]) return;
            used_flg[u] = true;

            for (var i = _adj[u]; i != null; i = i.N)
            {
                if (i.C > 1e-6) Dfs(i.V, used_flg);
            }
        }
    }
}

