    {
        var w = new P[2 * n];
        for (int i = 0; i < 2 * n; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var a = int.Parse(line[0]);
            var b = int.Parse(line[1]);
            if (i < n) w[i] = new P { x = a, y = b, red = true };
            else w[i] = new P { x = a, y = b };
        }
        return w;
    }
}

using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Threading.Tasks;

/*
・概要
：FordFulkersonのアルゴリズムを使用し、（重みなし）最大二部マッチング問題を解くライブラリ。
	（最大流問題に使用するアルゴリズムを応用）

：最大流を求める計算量は、O(f * E)
	（最大フローがf、辺の数がE）
	なお、事前準備の段階でO(X + Y)かかる。
	（X,Yは二集団それぞれの要素数。）

・（最大）二部マッチング問題とは。
：最大二部マッチング
	「二集団間で最大何ペア作ることができるか」、という問題。
	（ペア作成可能）条件を満たすペアの間にだけ、有向辺を追加し、
	後は最大流問題として解くだけ。

：重み付き最大二部マッチング
	上記に加え、ペア毎に異なる利得が得られる場合に、
	「全ペアの合計利得の最大値」を求める問題。
	→「最小費用流」問題に帰着可能（本ライブラリの対象外）

：最大流問題を応用した解法
	二集団の前後にノード（スタートとゴール）を付け加えることで、最大流問題に帰着可能
	（cf. 重みづけがないので、フローを全て1にすれば良いだけ）

・使用法
1. 名前空間FordFulkerson上のクラスMatchingのインスタンスを作成
	引数は、２集団X,Yそれぞれの要素数（頂点の数）
	（e.g. FordFulkerson.Matching match = new FordFulkerson.Matching(X,Y);）

2. MatchPair関数で、マッチング可能な二者間全ての間に、辺を形成する。
	引数は、集団Xの頂点と、集団Yの頂点。
	（e.g. match.MatchPair(x,y);）
	なお、それぞれ「Xの中で何番目か」、「Yの中で何番目か」を渡せば良い。

3. MaxPair関数で、最大マッチング数を取得する。
	（e.g. int ans = match.MaxPair();）

*/

class Program
{
	//Main
	static void Main(string[] args)
	{
		//読み込む
		int N = int.Parse(Console.ReadLine());

		//それぞれの座標を読み込む
		int[][] red = new int[N][];
		int[][] blue = new int[N][];
		for(int i=0; i<N; i++){
			red[i] = Console.ReadLine().Split(' ').Select(j => int.Parse(j)).ToArray();
		}
		for(int i=0; i<N; i++){
			blue[i] = Console.ReadLine().Split(' ').Select(j => int.Parse(j)).ToArray();
		}

		//1. 名前空間FordFulkerson上のクラスMatchingのインスタンスを作成
		//引数は、２集団X,Yそれぞれの要素数（頂点の数）
		FordFulkerson.Matching match = new FordFulkerson.Matching(N,N);

		//2. マッチング可能な二者間全ての間に、辺を形成する。
		for(int i=0; i<N; i++){
			for(int j=0; j<N; j++){
				if(red[i][0] < blue[j][0] && red[i][1] < blue[j][1]){
					match.MatchPair(i,j);
				}
			}
		}

		//MaxPair関数で、最大マッチング数を取得する。
		int ans = match.MaxPair();

		Console.WriteLine(ans);
	}
}

//FordFulkerson法用の名前空間
/*
3つのクラスを内包
・（重みなし）最大二部マッチング問題を解く為のクラスMatching
・辺を意味するEdge
・グラフとして問題を解くGraph
*/

/*
全てclass Graphからアクセスのこと
（e.g.
・初期化
	FordFulkerson.Graph maxPair = new FordFulkerson.Graph(N+N+2);

・エッジの追加
	maxPair.AddEdge(start,goal,1);
