class Solve
{
    public Solve() { }
    public static int Main()
    {
        new Solve().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        int[] red = new int[N];
        int[] blue = new int[N];

        for(int i=0; i<N; i++)
        {
            int x = cin.nextInt();
            int y = cin.nextInt();
            red[i] = x * 1000 + y;
        }
        for (int i = 0; i < N; i++)
        {
            int x = cin.nextInt();
            int y = cin.nextInt();
            blue[i] = x * 1000 + y;
        }
        Array.Sort(red);
        Array.Sort(blue);
        Array.Reverse(red);

        int pairs = 0;
        for(int i=0; i<N; i++)
        {
            int blueX = blue[i] / 1000;
            int blueY = blue[i] - (blueX * 1000);
            for(int y=0; y<N; y++)
            {
                int redX = red[y] / 1000;
                int redY = red[y] - (redX * 1000);
                if (redX < blueX && redY < blueY)
                {
                    pairs++;
                    red[y] = 9999999;
                    break;
                }

            }
        }
        Console.WriteLine(pairs.ToString());

    }
}


class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextInt() + add;
        }
        return Array;
    }

    public long nextLong()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextLong() + add;
        }
        return Array;
    }

    public double nextDouble()
    {
        return double.Parse(next());
    }


    public double[] ArrayDouble(int N, double add = 0)
    {
        double[] Array = new double[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextDouble() + add;
        }
        return Array;
    }
}

