namespace AtCoder
{
    class Program
    {
        static List<Coordinate> red;
        static List<Coordinate> blue;

        static void Main(string[] args)
        {
            //[summary]C - 2D Plane 2N Points
            int N = int.Parse(Console.ReadLine());

            red = GetCoordinates(N).ToList();
            blue = GetCoordinates(N).ToList();

            foreach(var b in blue)
            {
                GetPair(b.y, b.x);
            }

            Console.WriteLine(N - red.Count);
        }

        static void GetPair(int y , int x)
        {
            for(int i = 0; i < red.Count; i++)
            {
                if (red[i].y < y && red[i].x < x)
                {
                    red.RemoveAt(i);
                    return;
                }
            }
        }

        static IEnumerable<Coordinate> GetCoordinates(int N)
        {
            var coords = new List<Coordinate>();

            for(int i = 0; i < N; i++)
            {
                var line = ReadLine();
                int y = line[0];
                int x = line[1];

                coords.Add(new Coordinate(y, x));
            }

            //y座標,x座標の昇順にソート
            return coords.OrderBy(c => c.y).ThenBy(c => c.x);
        }

        static List<int> ReadLine()
        {
            var line = Console.ReadLine();
            var arr = line.Split(' ');

            return arr.Select(x => int.Parse(x)).ToList();
        }

        struct Coordinate
        {
            public int y;
            public int x;

            public Coordinate(int y, int x)
            {
                this.y = y;
                this.x = x;
            }
        }
    }
}

