public class Hello
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        var w  = setArray(n);
        var hs = new HashSet<P>();
        var count = 0;
        foreach (var x in w.OrderBy(y =>y.x))
            if (x.red) hs.Add(x);
            else
            {
                var t = hs.Where(z => z.x < x.x && z.y < x.y).OrderByDescending(z => z.y);
                if (t.Count() > 0) { hs.Remove(t.First()); count++; }
            }
        Console.WriteLine(count);
    }
    public static P[] setArray(int n)
    {
        var w = new P[2 * n];
        for (int i = 0; i < 2 * n; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var a = int.Parse(line[0]);
            var b = int.Parse(line[1]);
            if (i < n) w[i] = new P { x = a, y = b, red = true };
            else w[i] = new P { x = a, y = b };
        }
        return w;
    }
}

