class C
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => Read()).ToArray();
		var bs = new int[n].Select(_ => Read()).ToArray();

		var dag = new List<int[]>();
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (rs[i][0] < bs[j][0] && rs[i][1] < bs[j][1])
					dag.Add(new[] { i + 1, n + j + 1, 1 });
		dag.AddRange(Enumerable.Range(1, n).Select(i => new[] { 0, i, 1 }));
		dag.AddRange(Enumerable.Range(n + 1, n).Select(i => new[] { i, 2 * n + 1, 1 }));

		Console.WriteLine(MaxFlow(2 * n + 1, 0, 2 * n + 1, dag.ToArray()));
	}

	static long MaxFlow(int n, int sv, int ev, int[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new Dictionary<int, long>());
		foreach (var r in dag)
		{
			map[r[0]][r[1]] = r[2];
			map[r[1]][r[0]] = 0;
		}

		var u = new bool[n + 1];
		long Dfs(int v, long min)
		{
			if (v == ev) return min;
			u[v] = true;
			foreach (var key in map[v].Keys)
			{
				var value = map[v][key];
				if (u[key] || value == 0) continue;
				var f = Dfs(key, Math.Min(min, value));
				if (f != -1)
				{
					map[v][key] -= f;
					map[key][v] += f;
					u[v] = false;
					return f;
				}
			}
			u[v] = false;
			return -1;
		}

		long M = 0, t;
		while ((t = Dfs(sv, long.MaxValue)) != -1) M += t;
		return M;
	}
}

