    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];

            var rPts = new Tuple<long, long>[N];
            var bPts = new Tuple<long, long>[N];
            for (var i = 0; i < N; ++i)
            {
                var ab = Sarray();
                rPts[i] = Tuple.Create(ab[0], ab[1]);
            }
            for (var i = 0; i < N; ++i)
            {
                var cd = Sarray();
                bPts[i] = Tuple.Create(cd[0], cd[1]);
            }
            var rPairs = new List<HashSet<Tuple<long, long>>>();
            var bCount = new Dictionary<Tuple<long, long>, long>();
            for (var i = 0; i < N; ++i)
            {
                rPairs.Add(bPts.Where(b => rPts[i].Item1 < b.Item1 && rPts[i].Item2 < b.Item2).ToHashSet());
                bCount[bPts[i]] = rPts.Where(r => r.Item1 < bPts[i].Item1 && r.Item2 < bPts[i].Item2).Count();
            }
            rPairs.Sort((l, r) => r.Count.CompareTo(l.Count));
            var ans = 0L;
            while (rPairs.Any())
            {
                var lst = rPairs.Count - 1;
                if (0 == rPairs[lst].Count)
                {
                    rPairs.RemoveAt(lst);
                    continue;
                }
                var min = N + 1;
                var sel = new Tuple<long, long>(0, 0);
                foreach (var rpt in rPairs[lst])
                {
                    if (bCount[rpt] < min)
                    {
                        min = bCount[rpt];
                        sel = rpt;
                    }
                }
                ++ans;
                rPairs.RemoveAt(lst);
                foreach (var rpt in rPairs)
                    rpt.Remove(sel);
            }
            WriteLine(ans);
        }
    }
}

