            var abDic = new Dictionary<long, Dictionary<long, int>>();
            for (var i = 0; i < N; i++)
            {
                if (!abDic.ContainsKey(ab[i].a)) abDic[ab[i].a] = new Dictionary<long, int>();
                abDic[ab[i].a][ab[i].b] = i;
            }

            var cbRedKouho = Repeat(0, N).Select(_ => new List<int>()).ToArray();
            for (var i = 0; i < N; i++)
            {
                foreach (var item in ab.Where(e => e.a < cd[i].c && e.b < cd[i].d))
                {
                    cbRedKouho[i].Add(abDic[item.a][item.b]);
                }
            }
            var done = new bool[N];
            var cbRedKouhoIndexed = cbRedKouho.Select((x, i) => new { x.Count, i }).OrderBy(e => e.Count).ToArray();
            var ans = 0;
            var tgtIdx = 0;
            while (cbRedKouhoIndexed.Length != tgtIdx)
            {
                var item = cbRedKouhoIndexed[tgtIdx];
                var redKouho = cbRedKouho[item.i];
                var ok = false;
                var redIdx = 0;
                foreach (var item2 in redKouho)
                {
                    if (done[item2]) continue;
                    done[item2] = true;
                    redIdx = item2;
                    ok = true;
                    break;
                }
                if (ok)
                {
                    ++ans;
                    for (var j = 0; j < cbRedKouho.Length; j++)
                    {
                        cbRedKouho[j].Remove(redIdx);
                        if (j == cbRedKouhoIndexed[tgtIdx].i)
                        {
                            cbRedKouho[j].Clear();
                        }
                    }
                    cbRedKouhoIndexed = cbRedKouho.Select((x, i) => new { x.Count, i }).OrderBy(e => e.Count).ToArray();
                    tgtIdx = 0;
                }
                else
                {
                    ++tgtIdx;
                }
            }
            Console.WriteLine(ans);

        }

