using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var red = sc.ReadTupArray(N);
        var blue = sc.ReadTupArray(N);
        red = red.OrderBy(ab => ab.Item1).ToArray();
        // red < blue

        var dic = new Dictionary<Tuple<int, int>, List<Tuple<int, int>>>();

        for (int i = 0; i < N; i++)
        {
            var bi = blue[i];
            dic[bi] = new List<Tuple<int, int>>();
            for (int j = 0; j < N; j++)
            {
                var ri = red[j];
                if (bi.Item1 - ri.Item1 > 0 && bi.Item2 - ri.Item2 > 0)
                {
                    dic[bi].Add(ri);
                }
            }
        }
        var ans = 0;
        var used = new bool[1000, 1000];
        foreach (var pair in dic.OrderBy(p => p.Value.Count))
        {
            var b = pair.Key;
            foreach (var a in pair.Value.OrderBy((t) => b.Item1 - t.Item1 + b.Item2 - t.Item2))
            {
                if (used[a.Item1, a.Item2]) continue;
                ans++;
                used[a.Item1, a.Item2] = true;
                break;
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}

class Scanner
