using System;
using System.Collections.Generic;
using System.Linq;

class C
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => Read()).ToArray();
		var bs = new int[n].Select(_ => Read()).ToArray();

		var dag = new List<long[]>();
		dag.AddRange(Enumerable.Range(1, n).Select(i => new[] { 0, i, 1L }));
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (rs[i][0] < bs[j][0] && rs[i][1] < bs[j][1])
					dag.Add(new[] { i + 1, n + j + 1, 1L });
		dag.AddRange(Enumerable.Range(n + 1, n).Select(i => new[] { i, 2 * n + 1, 1L }));

		Console.WriteLine(MaxFlow(2 * n + 1, 0, 2 * n + 1, dag.ToArray()));
	}

	static long MaxFlow(int n, int sv, int ev, long[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new List<long[]>());
		foreach (var r in dag)
		{
			map[r[0]].Add(new[] { r[1], r[2], map[r[1]].Count });
			map[r[1]].Add(new[] { r[0], 0, map[r[0]].Count - 1 });
		}

		var u = new bool[n + 1];
		long Dfs(long v, long min)
		{
			if (v == ev) return min;
			u[v] = true;
			foreach (var r in map[v])
			{
				if (u[r[0]] || r[1] == 0) continue;
				var delta = Dfs(r[0], Math.Min(min, r[1]));
				if (delta > 0)
				{
					r[1] -= delta;
					map[r[0]][(int)r[2]][1] += delta;
					u[v] = false;
					return delta;
				}
			}
			u[v] = false;
			return 0;
		}

		long M = 0, t;
		while ((t = Dfs(sv, long.MaxValue)) > 0) M += t;
		return M;
	}
}

