using System;
using System.Linq;

class C
{
	class Blue
	{
		public int[] p;
		public bool u;
	}

	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => read()).OrderBy(p => p[0]).ToArray();
		var bs = new int[n].Select(_ => new Blue { p = read() }).OrderBy(_ => _.p[1]).ToArray();

		var map = new int[n].Select(_ => bs.Take(0).ToList()).ToArray();
		for (int i = 0; i < n; i++)
		{
			var p = rs[i];
			for (int j = 0; j < n; j++)
			{
				var q = bs[j].p;
				if (p[0] < q[0] && p[1] < q[1]) map[i].Add(bs[j]);
			}
		}

		var c = 0;
		for (int i = n - 1; i >= 0; i--)
		{
			var b = map[i].FirstOrDefault(_ => !_.u);
			if (b != null)
			{
				c++;
				b.u = true;
			}
		}
		Console.WriteLine(c);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using static System.Console;

namespace arc91
{
    struct Point
    {
        public int x;
        public int y;
    }
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(ReadLine());
            var reds = new List<Point>();
            var blues = new List<Point>();

            for (int i = 0; i < n; i++)
            {
                var s = ReadLine().Split(' ');
                var red = new Point();
                red.x = int.Parse(s[0]);
                red.y = int.Parse(s[1]);
                reds.Add(red);
            }
            for (int i = 0; i < n; i++)
            {
                var s = ReadLine().Split(' ');
                var blue = new Point();
                blue.x = int.Parse(s[0]);
                blue.y = int.Parse(s[1]);
                blues.Add(blue);
            }

            int count = 0;
            var can = new List<int>();
            var removed = new List<int>();
            for (int i = 0; i < n; i++)
            {
                can.Clear();
                for (int j = 0; j < n; j++)
                {
                    if(reds[j].x < blues[i].x && reds[j].y < blues[i].y && !removed.Contains(j))
                    {
                        can.Add(j);
                    }
                }
                if (can.Count > 0)
                {
                    int max_y = reds[can[0]].y;
                    int max_yi = 0;
                    foreach (var c in can)
                    {
                        if (reds[c].y > max_y)
                        {
                            max_y = reds[c].y;
                            max_yi = c;
                        }
                    }
                    removed.Add(max_yi);
                    count++;
                }

            }
            WriteLine(count);
        }
    }
}

