using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static List<Coordinate> red;
        static List<Coordinate> blue;

        static void Main(string[] args)
        {
            //[summary]C - 2D Plane 2N Points
            int N = int.Parse(Console.ReadLine());

            red = GetCoordinates(N);
            blue = GetCoordinates(N);

            //赤い点は y座標の降順にソート
            red = red.OrderByDescending(c => c.y).ToList();

            //青い点は y座標の昇順にソート
            blue = blue.OrderBy(c => c.y).ToList();

            foreach (var b in blue)
            {
                GetPair(b.y, b.x);
            }

            Console.WriteLine(N - red.Count);
        }

        static void GetPair(int y, int x)
        {
            for (int i = 0; i < red.Count; i++)
            {
                //赤い点のy座標が初めて青い点のy座標より小さくなったとき
                //それ以降の赤い点に対して、x座標が最大の点を求める
                if (red[i].y < y)
                {
                    GetMaxX(i, x);
                    return;
                }
            }
        }

        static void GetMaxX(int start, int x)
        {
            int max = -1;
            int index = 0;

            for(int i = start; i < red.Count; i++)
            {
                if (red[i].x < x && red[i].x > max)
                {
                    max = red[i].x;
                    index = i;
                }
            }

            if (max > -1)
            {
                red.RemoveAt(index);
            }
        }

        static List<Coordinate> GetCoordinates(int N)
        {
            var coords = new List<Coordinate>();

            for (int i = 0; i < N; i++)
            {
                var line = ReadLine();
                int y = line[0];
                int x = line[1];

                coords.Add(new Coordinate(y, x));
            }

            return coords;
        }

        static List<int> ReadLine()
        {
            var line = Console.ReadLine();
            var arr = line.Split(' ');

            return arr.Select(x => int.Parse(x)).ToList();
        }

        struct Coordinate
        {
            public int y;
            public int x;

            public Coordinate(int y, int x)
            {
                this.y = y;
                this.x = x;
            }
        }
    }
}

