    class C091
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            SortedDictionary<int, int> dicR = new SortedDictionary<int, int>();
            SortedDictionary<int, int> dicB = new SortedDictionary<int, int>();

            for (int i = 0; i < N; i++)
            {
                string[] s = Console.ReadLine().Split(' ');
                dicR.Add(int.Parse(s[0]), int.Parse(s[1]));
            }
            for (int i = 0; i < N; i++)
            {
                string[] s = Console.ReadLine().Split(' ');
                dicB.Add(int.Parse(s[0]), int.Parse(s[1]));
            }

            int counter = 0;
            foreach (var pair in dicB)
            {
                int c = pair.Key, d = pair.Value;
                var reds = dicR.Where(x => x.Key < c && x.Value < d);
                if (reds.Count() > 0)
                {
                    int mx= reds.Max(x => x.Value);
                    var red = reds.Where(x => x.Value == mx).Single().Key;
                    dicR.Remove(red);
                    counter++;
                }
            }
            Console.WriteLine(counter);
        }
    }
}

