            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            var grid = new int[2 * n, 2 * n];//無し:0,赤:1,青:2
            var ab = new int[n, 2];
            var cd = new int[n, 2];
            for (int i = 0; i < n; i++)
            {
                int[] input = ReadInts();
                grid[input[0], input[1]] = 1;
                ab[i, 0] = input[0];
                ab[i, 1] = input[1];
            }
            for (int i = 0; i < n; i++)
            {
                int[] input = ReadInts();
                grid[input[0], input[1]] = 2;
                cd[i, 0] = input[0];
                cd[i, 1] = input[1];
            }
            /*for (int i = 0; i < 2 * n; i++)
            {
                string s = "";
                for (int j = 0; j < 2 * n; j++)
                {
                    s += grid[i, j].ToString() + " ";
                }
                Console.WriteLine(s);
            }*/

            int pairCnt = 0;
            for (int i = 2 * n - 2; i >= 0; i--)
            {
                for (int j = i; j >= 0; j--)
                {
                    //まず上
                    if (grid[j, i] == 1)
                    {
                        bool detect = false;
                        for (int p = j + 1; p < 2 * n; p++)//たて
                        {
                            for (int q = i + 1; q < 2 * n; q++)
                            {
                                if (grid[p, q] == 2)
                                {
                                    pairCnt++;
                                    grid[p, q] = 0;
                                    grid[j, i] = 0;
                                    detect = true;
                                    break;
                                }
                            }
                            if (detect) break;
                        }
                    }
                    //次は左
                    if (grid[i,j] == 1)
                    {
                        bool detect = false;
                        for (int p = i + 1; p < 2 * n; p++)//たて
                        {
                            for (int q = j + 1; q < 2 * n; q++)
                            {
                                if (grid[p, q] == 2)
                                {
                                    pairCnt++;
                                    grid[p, q] = 0;
                                    grid[i,j] = 0;
                                    detect = true;
                                    break;
                                }
                            }
                            if (detect) break;
                        }
                    }
                }
            }
            /*for (int i = 0; i < 2 * n; i++)
            {
                string s = "";
                for (int j = 0; j < 2 * n; j++)
                {
                    s += grid[i, j].ToString() + " ";
                }
                Console.WriteLine(s);
            }*/
            Console.WriteLine(pairCnt);
        }

