            for(int i = 0; i < red.Count; i++)
            {
                if (red[i].y < y && red[i].x < x)
                {
                    red.RemoveAt(i);
                    return;
                }
            }
        }

        static List<Coordinate> GetCoordinates(int N, bool isBlue = false)
        {
            var coords = new List<Coordinate>();

            for(int i = 0; i < N; i++)
            {
                var line = ReadLine();
                int y = line[0];
                int x = line[1];

                coords.Add(new Coordinate(y, x));
            }

            IEnumerable<Coordinate> e;

            if (isBlue)
            {
                //y座標,x座標の降順にソート
                e = coords.OrderByDescending(c => c.y).ThenByDescending(c => c.x);
            }
            else
            {
                //y座標,x座標の昇順にソート
                e = coords.OrderBy(c => c.y).ThenBy(c => c.x);
            }

            return e.ToList();
        }

        static List<int> ReadLine()
        {
            var line = Console.ReadLine();
            var arr = line.Split(' ');

            return arr.Select(x => int.Parse(x)).ToList();
        }

        struct Coordinate
        {
            public int y;
            public int x;

            public Coordinate(int y, int x)
            {
                this.y = y;
                this.x = x;
            }
        }
