        public void Solve()
        {
            int N = cin.ReadInt;

            List<Pair> R = new List<Pair>();
            List<Pair> B = new List<Pair>();

            for (int i = 0; i < N; i++)
            {
                R.Add(new Pair(cin.ReadInt, cin.ReadInt));
            }

            for (int i = 0; i < N; i++)
            {
                B.Add(new Pair(cin.ReadInt, cin.ReadInt));
            }

            var pairComparer = new PairComparer();

            R.Sort(pairComparer);
            B.Sort(pairComparer);

            int count = 0;

            for (int i = 0; i < N; i++)
            {
                Pair p = B[i];

                int foundIndex = -1;
                int maxY       = -1;

                for (int j = 0; j < R.Count; j++)
                {
                    Pair q = R[j];

                    if (p.X <= q.X)
                    {
                        break;
                    }

                    if (p.Y <= q.Y)
                    {
                        continue;
                    }

                    if (q.Y > maxY)
                    {
                        maxY       = q.Y;
                        foundIndex = j;
                    }
                }

                if (foundIndex != -1)
                {
                    count++;
                    R.RemoveAt(foundIndex);
                }
            }

            cou.WriteLine(count);
        }

        public class PairComparer : IComparer<Pair>
        {
            public int Compare(Pair x, Pair y)
            {
                if (x.X < y.X) return -1;
                if (x.X > y.X) return 1;

                if (x.Y < y.Y) return -1;
                if (x.Y > y.Y) return 1;

                return 0;
            }
        }

        public sealed class Pair : Pair<int, int>
        {
            public Pair(int x, int y) : base(x, y)
            {
            }
        }

        [DebuggerDisplay("({X}, {Y})")]
        public class Pair<T1, T2> : IComparable<Pair<T1, T2>>, IEquatable<Pair<T1, T2>>
            where T1 : IComparable<T1>
            where T2 : IComparable<T2>
        {
            public Pair(T1 x, T2 y)
            {
                X = x;
                Y = y;
            }

            public T1 X;
            public T2 Y;

            public int CompareTo(Pair<T1, T2> other)
            {
                if (ReferenceEquals(this, other)) return 0;
                if (ReferenceEquals(null, other)) return 1;
                var firstComparison = X.CompareTo(other.X);
                return firstComparison != 0 ? firstComparison : Y.CompareTo(other.Y);
            }

            public override string ToString() => $"({X}, {Y})";

            public bool Equals(Pair<T1, T2> other)
            {
                if (ReferenceEquals(null, other)) return false;
                if (ReferenceEquals(this, other)) return true;
                return EqualityComparer<T1>.Default.Equals(X, other.X) &&
                       EqualityComparer<T2>.Default.Equals(Y, other.Y);
            }

            public override bool Equals(object obj)
            {
                if (ReferenceEquals(null, obj)) return false;
                if (ReferenceEquals(this, obj)) return true;
                return obj.GetType() == this.GetType() && Equals((Pair<T1, T2>)obj);
            }

            public override int GetHashCode()
            {
                unchecked
                {
                    return (EqualityComparer<T1>.Default.GetHashCode(X) * 397) ^
                           EqualityComparer<T2>.Default.GetHashCode(Y);
                }
            }
        }
    }


