using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Text;


class Program
{
    static void Main(string[] args)
    {
        // 入力
        //var s = Console.ReadLine();
        var n = int.Parse(Console.ReadLine());

        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++)
        {
            int[] tmp = Console.ReadLine().Split().Select(int.Parse).ToArray();
            a[i] = tmp[0];
            b[i] = tmp[1];
        }

        //y座標でソート
        Array.Sort(b, a);

        int[] c = new int[n];
        int[] d = new int[n];
        for (int i = 0; i < n; i++)
        {
            int[] tmp = Console.ReadLine().Split().Select(int.Parse).ToArray();
            c[i] = tmp[0];
            d[i] = tmp[1];
        }

        //x座標でソート
        Array.Sort(c, d);

        //青い点のうち最もx 座標が小さいものに注目します。この点と仲良しペアになれる点が存在した場合，そのような点のうち最も y 座標が大きいものと仲良しペアにしてよい
        int[][] jag = new int[n][];
        for (int i = 0; i < jag.Length; i++)
        {
            jag[i] = new int[n];
        }

        //i が青い点、kが赤い点
        var hset = new HashSet<int>();
        for (int i = 0; i < n; i++)
        {
            for (int k = n - 1; k >= 0; k--)
            {
                if (hset.Contains(k)) continue;

                if (a[k] < c[i] && b[k] < d[i])
                {
                    jag[i][k] = 1;
                    hset.Add(k);
                    break;
                }
            }
        }

        var ans = 0;
        for (int i = 0; i < n; i++)
        {
            int sum = jag[i].Sum();
            if (sum != 0)
            {
                ans++;
            }
        }

        // 出力
        Console.WriteLine(ans);
    }
}

