        public object Calc()
        {
            var N = consoleReader.Int;
            var reds = new SortedSet<Point>(consoleReader.Repeat(N).Select(cr => new Point { x = cr.Int, y = cr.Int }), Comparer<Point>.Create((a, b) => b.x - a.x));
            var blues = new SortedSet<Point>(consoleReader.Repeat(N).Select(cr => new Point { x = cr.Int, y = cr.Int }), Comparer<Point>.Create((a, b) => a.y - b.y));

            var count = 0;
            foreach (var b in blues)
            {
                Point match = new Point { x = -1, y = -1 };
                foreach (var r in reds)
                {
                    if (AreFriend(r, b))
                    {
                        match = r;
                        break;
                    }
                }
                if (match.x >= 0)
                {
                    reds.Remove(match);
                    count++;
                }
            }

            return count;
        }
