using System;
using System.Linq;
using System.Collections.Generic;

namespace Algorithm
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var red = new int[N][];
            var blue = new int[N][];

            for (var i = 0; i < N; i++)
                red[i] = Console.ReadLine().Split().Select(int.Parse).ToArray();
            for (var i = 0; i < N; i++)
                blue[i] = Console.ReadLine().Split().Select(int.Parse).ToArray();

            red = red.OrderBy(z => z[0]).ThenBy(x => x[1]).ToArray();

            var useRed = new bool[N];
            var useBlue = new bool[N];
            var total = 0;
            for (var i = 0; i < N; i++)
            {
                var min = int.MaxValue;
                var minInd = int.MaxValue;
                if (useRed[i]) continue;
                for (var j = 0; j < N; j++)
                {
                    if (useBlue[j]) continue;
                    if (red[i][0] < blue[j][0] && red[i][1] < blue[j][1])
                    {
                        if (blue[j][0] - red[i][0] < min)
                        {
                            min = blue[j][0] - red[i][0];
                            minInd = j;
                        }
                        if (blue[j][1] - red[i][1] < min)
                        {
                            min = blue[j][1] - red[i][1];
                            minInd = j;
                        }
                    }
                }
                if (min != int.MaxValue)
                {
                    useRed[i] = true;
                    useBlue[minInd] = true;
                    total++;
                }
            }
            Console.WriteLine(total);
        }
    }
}

