                    if (a[j] < c[i] && b[j] < d[i] && !removed.Contains(j))
                    {
                        candidate.Add(j);
                    }
                }
                if (candidate.Count > 0)
                {
                    int max_yi = candidate[0];
                    foreach (var can in candidate)
                    {
                        if (b[can] > b[max_yi])
                        {
                            max_yi = can;
                        }
                    }
                    removed.Add(max_yi);
                    count++;
                }
            }
            WriteLine(count);

        }
    }
}

