        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int[] A = new int[N];
        int[] B = new int[N];
        int[] C = new int[N];
        int[] D = new int[N];
        bool[] used = new bool[N];
        for(int i=0;i<N;i++){
            A[i] = re.i();
            B[i] = re.i();
        }
        for(int i=0;i<N;i++){
            C[i] = re.i();
            D[i] = re.i();
        }
        int count = 0;
        Array.Sort(A,B);
        for(int i=N-1;i>=0;i--){
            int min = -1;
            for(int j=0;j<N;j++){
                if(!used[j] && A[i] < C[j] && B[i] < D[j] && (min == -1 || D[j] < D[min])){
                    min = j;
                }
            }
            if(min != -1){
                count++;
                used[min] = true;
            }
        }
        sb.Append(count+"\n");
    }
