    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    static void Main(string[] args)
    {
        var pr = new Program();
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        var ab = Input.ar2D(num);
        var cd = Input.ar2D(num);
        var f = new MaxFlow(2 * num + 2);
        for (var i = 0; i < num; i++)
            for (var j = 0; j < num; j++)
                if (ab[i][0] < cd[j][0] && ab[i][1] < cd[j][1])
                    f.AddDirectedEdge(i, j + num, 1);
        for(var i = 0; i < num; i++)
        {
            f.AddDirectedEdge(2 * num, i, 1);
            f.AddDirectedEdge(i + num, 2 * num + 1, 1);
        }
