    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());

            List<Point> R = new List<Point>();
            List<Point> B = new List<Point>();
            for (int i = 0; i < N; i++)
            {
                var line = Console.ReadLine().Split().Select(int.Parse).ToArray();
                R.Add(new Point(line[0], line[1], 0));
            }
            for (int i = 0; i < N; i++)
            {
                var line = Console.ReadLine().Split().Select(int.Parse).ToArray();
                B.Add(new Point(line[0], line[1], 1));
            }

            R.OrderBy(x => x.d).ToList();
            int ans = Solve(R, B);


            Console.WriteLine(ans);
            Console.ReadKey();
        }

        static int Solve(List<Point> R, List<Point> B)
        {
            int max = 0;
            if (R.Count == 0) return 0;
            List<Point> nextB = B.Where(X => X.x > R[0].x && X.y > R[0].y).ToList();
            if (nextB.Count == 0) return 0;
            R.RemoveAt(0);
            for (int i = 0; i < nextB.Count; i++)
            {
                Point temp = nextB[i];
                int tmp = B.IndexOf(nextB[i]);
                B.RemoveAt(tmp);
                max = Math.Max(max, Solve(R, B) + 1);
                B.Insert(tmp, temp);
            }
            return max;
        }
    }

    class Point
    {
        public int x;
        public int y;
        public int d;
        public Point(int a,int b, int rb)//rb 0r 1b
        {
            x = a;y = b;
            this.d = a + b;
        }
    }
