        {
            int N = int.Parse(Console.ReadLine());

            List<Point> redPoint = new List<Point>();
            for(int i=0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                redPoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }
            List<Point> bluePoint = new List<Point>();
            for(int i = 0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                bluePoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }

            Dictionary<Point, List<Point>> pairC = new Dictionary<Point, List<Point>>();
            foreach(Point rp in redPoint)
            {
                List<Point> cList = new List<Point>();
                foreach(Point bp in bluePoint)
                {
                    if(rp.X < bp.X && rp.Y < bp.Y)
                    {
                        cList.Add(bp);
                    }
                }
                pairC.Add(rp, cList);
            }

            int pairCnt = GetPairCount(redPoint, pairC, 0, new List<Point>());


            Console.WriteLine(pairCnt);
        }

        private static int GetPairCount(List<Point> redPoint, Dictionary<Point, List<Point>> pairC, int ri, List<Point> usedBp)
        {
            int max = usedBp.Count;

            for(int i=ri; i<redPoint.Count; i++)
            {
                foreach(Point bp in pairC[redPoint[i]])
                {
                    if(!usedBp.Contains(bp))
                    {
                        usedBp.Add(bp);
                        int cnt;
                        if(i >= redPoint.Count - 1)
                        {
                            cnt = usedBp.Count;
                        }
                        else
                        {
                            cnt = GetPairCount(redPoint, pairC, ri + 1, usedBp);
                        }
                        usedBp.Remove(bp);
                        max = Math.Max(max, cnt);
                    }
                }
            }

            return max;
        }
    }

