class C
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => Read()).ToArray();
		var bs = new int[n].Select(_ => Read()).ToArray();

		var dag = new List<int[]>();
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (rs[i][0] < bs[j][0] && rs[i][1] < bs[j][1])
					dag.Add(new[] { i + 1, n + j + 1 });
		dag.AddRange(Enumerable.Range(1, n).Select(i => new[] { 0, i }));
		dag.AddRange(Enumerable.Range(n + 1, n).Select(i => new[] { i, 2 * n + 1 }));

		Console.WriteLine(MaxMatching(2 * n + 1, 0, 2 * n + 1, dag.ToArray()));
	}

	static long MaxMatching(int n, int sv, int ev, int[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new Dictionary<int, bool>());
		foreach (var r in dag)
		{
			map[r[0]][r[1]] = true;
			map[r[1]][r[0]] = false;
		}

		var u = new bool[n + 1];
		bool Dfs(int v)
		{
			if (v == ev) return true;
			u[v] = true;
			foreach (var p in map[v])
			{
				if (!p.Value || u[p.Key]) continue;
				if (Dfs(p.Key))
				{
					map[v][p.Key] = false;
					map[p.Key][v] = true;
					u[v] = false;
					return true;
				}
			}
			u[v] = false;
			return false;
		}

		long M = 0;
		while (Dfs(sv)) M++;
		return M;
	}
}

