                var s = bLis.Where(x => target[0] < x[0] && target[1] < x[1])
                            .OrderBy(X => X[0])
                            .ThenBy(x => x[1])
                            .FirstOrDefault();

                if (s != null)
                {
                    result += 1;
                    bLis.Remove(s);
                }
            }

            WriteLine(result);

        }

    }
}

