class C
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => read()).OrderBy(p => p[0]).ToArray();
		var bs = new int[n].Select(_ => read()).OrderBy(p => p[1]).ToArray();

		var map_r = rs.Select(_ => new HashSet<int>()).ToArray();
		var map_b = bs.Select(_ => new HashSet<int>()).ToArray();
		for (int i = 0; i < n; i++)
		{
			var p = rs[i];
			for (int j = 0; j < n; j++)
			{
				var q = bs[j];
				if (p[0] < q[0] && p[1] < q[1])
				{
					map_r[i].Add(j);
					map_b[j].Add(i);
				}
			}
		}

		var c = 0;
		for (; ; c++)
		{
			var ok = false;

			for (int i = n - 1; i >= 0; i--)
			{
				if (map_r[i].Count != 1) continue;

				var j = map_r[i].First();
				foreach (var si in map_b[j])
					map_r[si].Remove(j);
				map_b[j].Clear();
				ok = true;
				break;
			}
			if (ok) continue;

			for (int j = n - 1; j >= 0; j--)
			{
				if (map_b[j].Count != 1) continue;

				var i = map_b[j].First();
				foreach (var sj in map_r[i])
					map_b[sj].Remove(i);
				map_r[i].Clear();
				ok = true;
				break;
			}
			if (ok) continue;

			for (int i = n - 1; i >= 0; i--)
			{
				if (map_r[i].Count == 0) continue;

				var j = map_r[i].Last();
				foreach (var si in map_b[j])
					map_r[si].Remove(j);
				map_b[j].Clear();
				foreach (var sj in map_r[i])
					map_b[sj].Remove(i);
				map_r[i].Clear();
				ok = true;
				break;
			}
			if (ok) continue;

			break;
		}
		Console.WriteLine(c);
	}
}

