          int tmp = bx[i - 1];
          bx[i - 1] = bx[i];
          bx[i] = tmp;
          tmp = by[i - 1];
          by[i - 1] = by[i];
          by[i] = tmp;
        }
      }
    }

    for (int i = 0; i < N; i++) { //リスト追加
      list[i] = new List<int>();
      for (int j = 0; j < N; j++) {
