    for (int i = 0; i < N; i++) {
      string[] input = Console.ReadLine().Split(' ');
      rx[i] = int.Parse(input[0]);
      ry[i] = int.Parse(input[0]);
    }
    for (int i = 0; i < N; i++) {
      string[] input = Console.ReadLine().Split(' ');
      bx[i] = int.Parse(input[0]);
      by[i] = int.Parse(input[0]);
    }

    int lastvalue = 0;

    for (int j = 0; j < N; j++) { //ソート
      for (int i = 1; i < N; i++) {
        if (bx[i] < bx[i - 1]) {
          int tmp = bx[i - 1];
          bx[i - 1] = bx[i];
          bx[i] = tmp;
          tmp = by[i - 1];
          by[i - 1] = by[i];
          by[i] = tmp;
        }
      }
    }

    for (int i = 0; i < N; i++) { //リスト追加
      list[i] = new List<int>();
      for (int j = 0; j < N; j++) {
        if (rx[j] < bx[i] && ry[j] < by[i] ) {
          list[i].Add(j);
        }
      }
      list[i].Add(-1);
    }

    lastvalue = search( 0, 0);
    Console.WriteLine(lastvalue);
  }

  public static List<int> sList = new List<int>();
  // public static int val=0;
  // public static int ctr=0;
  public static bool[] chk = new bool[110];

  public static int search( int b, int ctr ) {
    if (ctr == N) {
      if (sList[sList.Count - 1] !=-1)chk[sList[sList.Count - 1]]=false;
      sList.RemoveAt(sList.Count - 1);
      return b;
    }
    int value = 0;

    for (int i = 0; i < list[ctr].Count; i++) {
      int p = 0;
      if (list[ctr][i] != -1 && !chk[list[ctr][i]] ) {
        sList.Add(list[ctr][i]);
        chk[list[ctr][i]] = true;
        p = search( b + 1, ctr + 1);
      }else{
        sList.Add(-1);
        p = search( b , ctr + 1);
      }
      if (value < p) value = p;
    }

    if (sList.Count!=0){
      if (sList[sList.Count - 1] !=-1)chk[sList[sList.Count - 1]]=false;
      sList.RemoveAt(sList.Count - 1);
    }
    return value;
  }

