namespace AtCoder.ABC.C092
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Numerics;
    using System.IO;

    using AtCoder.ABC.IO;

    public class Quest
    {
        public object Solve(Parser parser)
        {
            int n = parser.Integer();

            var red = parser.Take(n).Select(p => new Red()
            {
                x = p.Integer(),
                y = p.Integer(),
            }).OrderByDescending(r => r.y).ToArray();

            Blue[] blue = parser.Take(n).Select(p => new Blue()
            {
                x = p.Integer(),
                y = p.Integer(),
            }).OrderBy(b => b.x).ToArray();

            var g = new Graph();

            for (int i = 0; i < red.Length; i++)
            {
                g.AddEdge(0, 1 + i, 1);
                for (int j = 0; j < blue.Length; j++)
                {
                    if (IsFriend(red[i], blue[j]))
                    {
                        g.AddEdge(1 + i, 1 + j + red.Length, 1);
                    }
                }
            }

            for (int j = 0; j < blue.Length; j++)
            {
                g.AddEdge(1 + j + red.Length, 1 + red.Length + blue.Length, 1);
            }

            return g.MaximizeFlow(0, 1 + red.Length + blue.Length);
        }
        private static bool IsFriend(Red red, Blue blue)
        {
            return red.x < blue.x && red.y < blue.y;
        }
    }

    class Edge
    {
        public int To;
        public int Capacity;
        public int Reverse;
    }

    class Graph
    {
        private Dictionary<int, List<Edge>> m_edges;

        public Graph()
        {
            m_edges = new Dictionary<int, List<Edge>>();
        }


        public int MaximizeFlow(int s, int t)
        {
            int flow = 0;

            while (true)
            {
                bool[] used = Enumerable.Range(0, m_edges.Count)
                .Select(x => false).ToArray();

                int f = Dfs(s, t, int.MaxValue, used);
                if (f == 0)
                {
                    return flow;
                }
                flow += f;
            }
        }

        public void AddEdge(int from, int to, int cap)
        {
            if (!m_edges.ContainsKey(from))
            {
                m_edges.Add(from, new List<Edge>());
            }

            if (!m_edges.ContainsKey(to))
            {
                m_edges.Add(to, new List<Edge>());
            }

            m_edges[from].Add(new Edge()
            {
                To = to,
                Capacity = cap,
                Reverse = m_edges[to].Count,
            });
            m_edges[to].Add(new Edge()
            {
                To = from,
                Capacity = 0,
                Reverse = m_edges[from].Count - 1,
            });
        }

        private int Dfs(int v, int t, int f, bool[] used)
        {
            if (v == t)
            {
                return f;
            }

            used[v] = true;
            foreach (var edge in m_edges[v])
            {
                if (!used[edge.To] && edge.Capacity > 0)
                {
                    int d = Dfs(edge.To, t, Math.Min(f, edge.Capacity), used);
                    if (d > 0)
                    {
                        edge.Capacity -= d;
                        m_edges[edge.To][edge.Reverse].Capacity += d;
                        return d;
                    }
                }
            }

            return 0;
        }
    }

    class Red
    {
        public int x;
        public int y;
    }

    class Blue
    {
        public int x;
        public int y;
    }

    static class Program
    {
        static void Main(string[] args)
        {
            var i = new Parser(Console.OpenStandardInput());
            var o = new Printer(Console.OpenStandardOutput());
            var got = new Quest().Solve(i);
            o.WriteLine(got);
            o.Flush();
        }
    }
}
