class C
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => read()).OrderBy(p => p[0]).ToArray();
		var bs = new int[n].Select(_ => read()).OrderBy(p => p[1]).ToArray();

		var map = new int[n].Select(_ => new int[0].ToList()).ToArray();
		for (int i = 0; i < n; i++)
		{
			var p = rs[i];
			for (int j = 0; j < n; j++)
			{
				var q = bs[j];
				if (p[0] < q[0] && p[1] < q[1]) map[i].Add(j + 1);
			}
		}

		var c = 0;
		var u = new bool[n + 1];
		for (int b, i = n - 1; i >= 0; i--)
			if ((b = map[i].FirstOrDefault(j => !u[j])) > 0)
			{
				c++;
				u[b] = true;
			}
		Console.WriteLine(c);
	}
}

