        }
        static void Solve()
        {
            var n = ReadAndParseInt();
            var ab = new List<Vec2>(n);
            var cd = new List<Vec2>(n);
            for(int i=0;i<n;++i)
            {
                var o = ReadAndParseIntArr();
                ab.Add(new Vec2()
                {
