            {
                var o = ReadAndParseIntArr();
                cd.Add( new Vec2()
                {
                    x = o[0],
                    y = o[1]
                });
            }
            int ans = 0;
            bool[] used = new bool[n];
            for(int i=0;i<n;++i)
            {
                Vec2 abi = ab[i];
                int min = int.MaxValue;
                int minidx = -1;
                for(int j=0;j<n;++j)
                {
                    Vec2 cdi = cd[j];
                    int dist = (abi.x - cdi.x) * (abi.x - cdi.x) + (abi.y - cdi.y) * (abi.y - cdi.y);
                    if( dist < min && !used[j] && abi.x < cdi.x && abi.y < cdi.y)
                    {
                        min = dist;
                        minidx = j;
                    }
                }
                if (minidx >= 0)
                {
                    used[minidx] = true;
                    ans++;
                }
            }
            Console.WriteLine(ans);

        }

        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
