    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        var red = setArray(n);
        var blue = setArray(n);
        var count = 0;
        foreach (var x in blue.OrderBy(y =>y.x))
        {
            var t = red.Where(z => z.x < x.x && z.y < x.y && !z.del).OrderByDescending(z => z.y);
            if (t.Count() > 0 ) { t.First().del = true; count++; }
        }
        Console.WriteLine(count);
    }
    public static P[] setArray (int  n )
    {
        var w = new P[n];
        for (int i = 0; i < n; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var c = int.Parse(line[0]);
            var d = int.Parse(line[1]);
            w[i] = new P { x = c, y = d };
        }
        return w;
    }
}

