public class Program {
  public static void Main() {
    int N = int.Parse(Console.ReadLine());
    int[][] red = new int[N][];
    int[][] blue = new int[N][];
    for (int i = 0; i < N; i++) red[i] = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
    for (int i = 0; i < N; i++) blue[i] = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
    red = red.OrderByDescending(a => a[1]).ToArray();
    blue = blue.OrderBy(a => a[0]).ToArray();

    int count = 0;
    for (int i = 0; i < N; i++) {
      int[] del = red.Where(a => a != null).Where(a => a[0] < blue[i][0]).FirstOrDefault();
      if (del == null) continue;
      red[Array.IndexOf(red, del)] = null;
      count++;
    }
    Console.WriteLine(count);
  }
}

using System;
using System.Collections.Generic;
using System.Linq;

class C
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var r = new int[n].Select(_ => Read()).ToArray();
		var b = new int[n].Select(_ => Read()).ToArray();

		int sv = 2 * n, ev = sv + 1;
		var dag = new List<long[]>();
		dag.AddRange(Enumerable.Range(0, n).Select(i => new[] { sv, i, 1L }));
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (r[i][0] < b[j][0] && r[i][1] < b[j][1])
					dag.Add(new[] { i, n + j, 1L });
		dag.AddRange(Enumerable.Range(n, n).Select(j => new[] { j, ev, 1L }));

		Console.WriteLine(MaxFlow(ev, sv, ev, dag.ToArray()));
	}

	static long MaxFlow(int n, int sv, int ev, long[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new List<long[]>());
		foreach (var e in dag)
		{
			map[e[0]].Add(new[] { e[1], e[2], map[e[1]].Count });
			map[e[1]].Add(new[] { e[0], 0, map[e[0]].Count - 1 });
		}

		long Bfs()
		{
			var from = new long[n + 1][];
			var u = new bool[n + 1];
			var minFlow = Enumerable.Repeat(long.MaxValue, n + 1).ToArray();
			var q = new Queue<long>();
			q.Enqueue(sv);

			while (q.TryDequeue(out var v))
			{
				if (v == ev) break;
				foreach (var e in map[v])
				{
					if (u[e[0]] || e[1] == 0) continue;
					from[e[0]] = e;
					u[e[0]] = true;
					minFlow[e[0]] = Math.Min(minFlow[v], e[1]);
					q.Enqueue(e[0]);
				}
			}

			if (from[ev] == null) return 0;
			long tv = ev;
			while (true)
			{
				from[tv][1] -= minFlow[ev];
				var rev = map[from[tv][0]][(int)from[tv][2]];
				rev[1] += minFlow[ev];
				if ((tv = rev[0]) == sv) break;
			}
			return minFlow[ev];
		}

		long M = 0, t;
		while ((t = Bfs()) > 0) M += t;
		return M;
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

class C
{
	static int[] Read() => Console.ReadLine().Split().Select(int.Parse).ToArray();
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => Read()).ToArray();
		var bs = new int[n].Select(_ => Read()).ToArray();

		var dag = new List<int[]>();
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				if (rs[i][0] < bs[j][0] && rs[i][1] < bs[j][1])
					dag.Add(new[] { i + 1, n + j + 1 });
		dag.AddRange(Enumerable.Range(1, n).Select(i => new[] { 0, i }));
		dag.AddRange(Enumerable.Range(n + 1, n).Select(i => new[] { i, 2 * n + 1 }));

		Console.WriteLine(MaxMatching(2 * n + 1, 0, 2 * n + 1, dag.ToArray()));
	}

	static long MaxMatching(int n, int sv, int ev, int[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new Dictionary<int, bool>());
		foreach (var r in dag)
		{
			map[r[0]][r[1]] = true;
			map[r[1]][r[0]] = false;
		}

		var u = new bool[n + 1];
		bool Dfs(int v)
		{
			if (v == ev) return true;
			u[v] = true;
			foreach (var p in map[v])
			{
				if (u[p.Key] || !p.Value) continue;
				if (Dfs(p.Key))
				{
					map[v][p.Key] = false;
					map[p.Key][v] = true;
					u[v] = false;
					return true;
				}
			}
			u[v] = false;
			return false;
		}

		long M = 0;
		while (Dfs(sv)) M++;
		return M;
	}
}

