namespace AtCoder.Beginner091
{
    public class ABC091C
    {
        public static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            List<Point> redPoint = new List<Point>();
            for(int i=0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                redPoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }
            List<Point> bluePoint = new List<Point>();
            for(int i = 0; i < N; i++)
            {
                int[] nums = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
                bluePoint.Add(new Point() { X = nums[0], Y = nums[1] });
            }

            int pairCnt = GetPairCount(redPoint, bluePoint, 0, new List<Point>());


            Console.WriteLine(pairCnt);
        }

        private static int GetPairCount(List<Point> redPoint, List<Point> bluePoint, int ri, List<Point> usedBp)
        {
            int max = usedBp.Count;

            for(int i=ri; i<redPoint.Count; i++)
            {
                foreach(Point bp in bluePoint)
                {
                    if(redPoint[i].X < bp.X && redPoint[i].Y < bp.Y && !usedBp.Contains(bp))
                    {
                        usedBp.Add(bp);
                        int cnt;
                        if(i >= redPoint.Count - 1)
                        {
                            cnt = usedBp.Count;
                        }
                        else
                        {
                            cnt = GetPairCount(redPoint, bluePoint, ri + 1, usedBp);
                        }
                        usedBp.Remove(bp);
                        max = Math.Max(max, cnt);
                    }
                }
            }

            return max;
        }
    }

    public class Point
    {
        public int X;
        public int Y;
    }
}

