using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace C
{
    public class Program
    {
        static void Main(string[] args)
        {
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            Solve();
            Console.Out.Flush();
        }

        public static void Solve()
        {
            var N = int.Parse(Console.ReadLine());
            var abi = new Pair[N];
            var cdi = new Pair[N];
            for (var i = 0; i < N; i++)
            {
                var ab = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                abi[i] = new Pair { X = ab[0], Y = ab[1] };
            }
            for (var i = 0; i < N; i++)
            {
                var cd = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                cdi[i] = new Pair { X = cd[0], Y = cd[1] };
            }
            abi = abi.OrderByDescending(x => x.X).ThenByDescending(x => x.Y).ToArray();
            cdi = cdi.OrderByDescending(x => x.X).ThenByDescending(x => x.Y).ToArray();

            var answer = 0;
            var ix = 0;
            var iy = 0;
            var hash = new HashSet<int>();
            while (ix < N)
            {
                if (abi[ix].X < cdi[iy].X && abi[ix].Y < cdi[iy].Y)
                {
                    if (!hash.Contains(iy))
                    {
                        answer++;
                        ix++;
                        hash.Add(iy);
                        iy = 0;
                    }
                    else
                    {
                        iy++;
                    }
                }
                else
                {
                    iy++;
                }
                if (iy >= N)
                {
                    ix++;
                    iy = 0;
                }
            }

            Console.WriteLine(answer);
        }

        public class Pair
        {
            public int X { get; set; }
            public int Y { get; set; }
        }
    }
}

