class C
{
	static void Main()
	{
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var n = int.Parse(Console.ReadLine());
		var rs = new int[n].Select(_ => read()).OrderBy(p => p[0]).ToArray();
		var bs = new int[n].Select(_ => read()).OrderBy(p => p[1]).ToArray();

		var map = new int[n].Select(_ => new int[0].ToList()).ToArray();
		for (int i = 0; i < n; i++)
		{
			var p = rs[i];
			for (int j = 0; j < n; j++)
			{
				var q = bs[j];
				if (p[0] < q[0] && p[1] < q[1]) map[i].Add(j + 1);
			}
		}

		var c = 0;
		var u = new bool[n + 1];
		for (int b, i = n - 1; i >= 0; i--)
			if ((b = map[i].FirstOrDefault(j => !u[j])) > 0)
			{
				c++;
				u[b] = true;
			}
		Console.WriteLine(c);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static List<Coordinate> red;
        static List<Coordinate> blue;

        static void Main(string[] args)
        {
            //[summary]C - 2D Plane 2N Points
            int N = int.Parse(Console.ReadLine());

            red = GetCoordinates(N).ToList();
            blue = GetCoordinates(N).ToList();

            foreach(var b in blue)
            {
                GetPair(b.y, b.x);
            }

            Console.WriteLine(N - red.Count);
        }

        static void GetPair(int y , int x)
        {
            for(int i = 0; i < red.Count; i++)
            {
                if (red[i].y < y && red[i].x < x)
                {
                    red.RemoveAt(i);
                    return;
                }
            }
        }

        static IEnumerable<Coordinate> GetCoordinates(int N)
        {
            var coords = new List<Coordinate>();

            for(int i = 0; i < N; i++)
            {
                var line = ReadLine();
                int y = line[0];
                int x = line[1];

                coords.Add(new Coordinate(y, x));
            }

            //y座標,x座標の降順にソート
            return coords.OrderByDescending(c => c.y).
                          ThenByDescending(c => c.x);
        }

        static List<int> ReadLine()
        {
            var line = Console.ReadLine();
            var arr = line.Split(' ');

            return arr.Select(x => int.Parse(x)).ToList();
        }

        struct Coordinate
        {
            public int y;
            public int x;

            public Coordinate(int y, int x)
            {
                this.y = y;
                this.x = x;
            }
        }
    }
}

