        Array.Sort(cd, (x, y) => x[1] == y[1] ? x[0].CompareTo(y[0]) : x[1].CompareTo(y[1]));

        var used = new bool[N];
        int ans = 0;
        for (int i = 0; i < N; i++)
        {
            int index = -1;
            int maxx = -1;
            for (int j = 0; j < N; j++)
            {
                if (!used[j])
                {
                    if (cd[i][0] > ab[j][0] && cd[i][1] > ab[j][1])
                    {
                        if (maxx < ab[j][0])
                        {
                            index = j;
                            maxx = ab[j][0];
                        }
                    }
                }
            }
            if (index != -1)
            {
                ans++;
                used[index] = true;
            }
        }

        WriteLine(ans);
    }
}

