	}

	static long MaxMatching(int n, int sv, int ev, int[][] dag)
	{
		var map = Array.ConvertAll(new int[n + 1], _ => new Dictionary<int, bool>());
		foreach (var r in dag)
		{
			map[r[0]][r[1]] = true;
			map[r[1]][r[0]] = false;
		}

		var u = new bool[n + 1];
		bool Dfs(int v)
		{
			if (v == ev) return true;
			u[v] = true;
			foreach (var p in map[v])
			{
				if (u[p.Key] || !p.Value) continue;
				if (Dfs(p.Key))
				{
					map[v][p.Key] = false;
					map[p.Key][v] = true;
					u[v] = false;
					return true;
				}
			}
			u[v] = false;
			return false;
		}

		long M = 0;
		while (Dfs(sv)) M++;
		return M;
	}
}

