    var smallest;
    blue.forEach((thisBlue) => {
      if (!smallest || thisBlue.x < smallest.x) {
	smallest = thisBlue;
      }
    })
    blue.splice(blue.indexOf(smallest), 1);
    return smallest;
  }

  function getMatchWithBiggestY(bluePoint) {
    var bestMatch;
    red.forEach((thisRed) => {
      if (isFriendly(thisRed, bluePoint)) {
	if (!bestMatch || thisRed.y > bestMatch.y) {
	  bestMatch = thisRed;
	}
      }
    })
    return bestMatch;
  }


  while (blue.length > 0) {
    var thisBlue = getBlueWithSmallestX();
    var bestMatch = getMatchWithBiggestY(thisBlue);

    if (bestMatch) {
      answer++;
      red.splice(red.indexOf(bestMatch), 1);
    }
  }



  // 出力
  console.log(answer);
}
