	thisRed.matches = [];
	blue.forEach(( thisBlue, bluei ) => {
	  if (isFriendly(thisRed, thisBlue)) {
	    matchCount++;
	    thisRed.matches.push(thisBlue)
	  }
	})
      }
    });

    return matchCount > 0;
  }

  var hadMatch;

  do {
    hadMatch = findMatches();

    red.forEach((thisRed, redi) => {
      var bestMatch;
      if (!thisRed.taken) {
	thisRed.matches.forEach((thisMatch) => {
	  if (!thisMatch.taken && (!bestMatch || thisMatch.y < bestMatch.y)) {
	    bestMatch = thisMatch;
	  }
	})
	if (bestMatch) {
	  thisRed.taken = true;
	  bestMatch.taken = true;
	  var removeIndex = blue.indexOf(bestMatch);
	  blue.splice(removeIndex, 1);
	  answer++;
	}

      }
    })

  } while (hadMatch);



  // 出力
  console.log(answer);
}
