var map = {};
function calc(ptnmap, idx, used){
    if(idx>=ptnmap.length || used.length == ptnmap.length){
        return used.length;
    }
    var key = idx + "_" + used.join(",");
    if(map[key]) return map[key];
    var ans = 0;
    ans=Math.max(ans, calc(ptnmap, idx+1, used));
    for(var i=0;i<ptnmap[idx].length;i++){
        var use = ptnmap[idx][i];
        if(used.indexOf(use) == -1){
            ans=Math.max(ans, calc(ptnmap, idx+1, used.concat(use)));
        }
    }
    return map[key] = ans;
}
