class MaximumMatching
  def initialize(vertex_num)
    @vertex_num = vertex_num
    @edges = Array.new(vertex_num) { [] }
    @matches = Array.new(vertex_num) { -1 }
    @visited = []
  end

  def add_edge(u, v)
    @edges[u] += [v]
    @edges[v] += [u]
  end

  def dfs(v)
    @visited[v] = true
    @edges[v].each do |e|
      w = @matches[e]
      next if w >= 0 && (@visited[w] || !dfs(w))

      @matches[v] = e
      @matches[e] = v
      return true
    end
    false
  end

  def maximum_matching
    count = 0
    0.upto(@vertex_num - 1) do |v|
      next if @matches[v] >= 0

      @visited.clear
      count += 1 if dfs(v)
    end
    count
  end
end

