# 二部グラフの最大マッチングを解く
class BipartiteGraph
  def initialize(n)
    @V = n                # 頂点数
    @G = Array.new(n){[]} # グラフの隣接リスト表現
    @match = Array.new(n) # マッチングのペア
    @used = Array.new(n)  # DFS で既に調べたか
  end

  # u -> v の辺をグラフに追加
  def add_edge(u, v)
    @G[u] << v
    @G[v] << u
  end

  # 増加パスを DFS で探索
  def dfs(v)
    @used[v] = true
    @G[v].each do |u|
      w = @match[u]
      if w < 0 || !@used[w] && dfs(w)
        @match[v] = u
        @match[u] = v
        return true
      end
    end
    false
  end

  # 最大マッチングを求める
  def bipartite_matching
    res = 0
    @match.fill(-1)
    @V.times do |v|
      if @match[v] < 0
        @used.fill(false)
        res += 1 if dfs(v)
      end
    end
    return res
  end
end

