type byLen [][]int

func (a byLen) Len() int           { return len(a) }
func (a byLen) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a byLen) Less(i, j int) bool { return len(a[i]) < len(a[j]) }

func solve() {
	n := getInt()
	getPoints := func() []point {
		ret := make([]point, n)
		for i := range ret {
			ret[i].x = getInt()
			ret[i].y = getInt()
		}
		return ret
	}
	reds := getPoints()
	blues := getPoints()

	// 以下の要素を含む構造体たちのスライス
	// 1. ある赤い点から見た友だちになれる青い点の数
	// 2. 既に友達として選ばれたかどうかを表すbool
	rCnts := make([]struct {
		c int
		b bool
	}, n)
	for i, r := range reds {
		for _, b := range blues {
			if b.x > r.x && b.y > r.y {
				rCnts[i].c++
			}
		}
	}

	// ある青い点から見た友達になれる赤い点たち のスライス
	bFriends := make([][]int, n)
	for i, b := range blues {
		for j, r := range reds {
			if b.x > r.x && b.y > r.y {
				bFriends[i] = append(bFriends[i], j)
			}
		}
	}

	sort.Sort(byLen(bFriends))
	ans := 0
	for _, bf := range bFriends {
		minCnt := inf
		minIdx := -1
		for _, i := range bf {
			if rCnts[i].b {
				continue
			}

			if minCnt > rCnts[i].c {
				minCnt = rCnts[i].c
				minIdx = i
			}
		}

		if minIdx == -1 {
			continue
		}
		rCnts[minIdx].b = true
		ans++
	}

	fmt.Fprintln(wr, ans)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

