import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

type NumSortA struct {
	A      int
	B      int
	IsPair bool
}

type NumAs []NumSortA

func (n NumAs) Len() int {
	return len(n)
}

func (n NumAs) Swap(i, j int) {
	n[i], n[j] = n[j], n[i]
}

func (n NumAs) Less(i, j int) bool {
	return n[i].A < n[j].B
}

type NumSortB struct {
	A      int
	B      int
	IsPair bool
}

type NumBs []NumSortB

func (n NumBs) Len() int {
	return len(n)
}

func (n NumBs) Swap(i, j int) {
	n[i], n[j] = n[j], n[i]
}

func (n NumBs) Less(i, j int) bool {
	return n[i].B < n[j].B
}

func main() {
	s := IOInitialize()
	N := Int(s)
	redAs, redBs := scanNums(s, N)
	sort.Sort(redAs)
	sort.Sort(redBs)
	blueAs, blueBs := scanNums(s, N)
	sort.Sort(blueAs)
	sort.Sort(blueBs)
	pairACnts := 0
	for _, redA := range redAs {
		for i, blueA := range blueAs {
			if redA.A < blueA.A && redA.B < blueA.B && !blueA.IsPair {
				pairACnts++
				blueAs[i].IsPair = true
				break
			}
		}
	}

	pairBCnts := 0
	for _, redB := range redBs {
		for i, blueB := range blueBs {
			if redB.A < blueB.A && redB.B < blueB.B && !blueB.IsPair {
				pairBCnts++
				blueBs[i].IsPair = true
				break
			}
		}
	}
	fmt.Println(max(pairACnts, pairBCnts))
}

func max(nums ...int) int {
	res := nums[0]
	for _, num := range nums {
		if res < num {
			res = num
		}
	}
	return res
}

func IOInitialize() *bufio.Scanner {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	return s
}

func Int(s *bufio.Scanner) int {
	if !s.Scan() {
		panic("scan error")
	}

	value, err := strconv.Atoi(s.Text())
	if err != nil {
		panic("text to int error")
	}
	return value
}

func scanNums(s *bufio.Scanner, len int) (numAs NumAs, numBs NumBs) {
	for i := 0; i < len; i++ {
		numA := Int(s)
		numB := Int(s)
		numAs = append(numAs, NumSortA{A: numA, B: numB, IsPair: false})
		numBs = append(numBs, NumSortB{A: numA, B: numB, IsPair: false})
	}
	return
}

