	fmt.Println(MaxFlow(0, 1+N+N))
}

const Inf = 1 << 60

type Edge struct {
	To, Cap, Rev int
}

var adjL [][]*Edge

// 最大流 (最小カット) Ford-Fulkerson O(F|E|)
func MaxFlow(s, t int) int {
	flow := 0
	for {
		f := flowDfs(s, t, Inf, make([]bool, len(adjL)))
		if f == 0 {
			return flow
		}
		flow += f
	}
}

func AddEdge(from, to, cap int) {
	adjL[from] = append(adjL[from], &Edge{
		To:  to,
		Cap: cap,
		Rev: len(adjL[to]),
	})
	adjL[to] = append(adjL[to], &Edge{
		To:  from,
		Cap: 0,
		Rev: len(adjL[from]) - 1,
	})
}

func flowDfs(v, t, f int, used []bool) int {
	if v == t {
		return f
	}
	used[v] = true
	for _, edge := range adjL[v] {
		if !used[edge.To] && edge.Cap > 0 {
			d := flowDfs(edge.To, t, Min(f, edge.Cap), used)
			if d > 0 {
				edge.Cap -= d
				adjL[edge.To][edge.Rev].Cap += d
				return d
			}
		}
	}
	return 0
}

func Min(xs ...int) int {
	min := xs[0]
	for _, x := range xs[1:] {
		if min > x {
			min = x
		}
	}
	return min
}

