type Point struct {
	i         int
	x, y      int
	ref       int
	isMatched bool
}

func (p Point) IsPair(x, y int) bool {
	return p.x < x && p.y < y
}

type PointList []*Point

func (p PointList) Len() int {
	return len(p)
}

func (p PointList) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p PointList) Less(i, j int) bool {
	return p[i].ref < p[j].ref
}

func nextInt(sc *bufio.Scanner) int {
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	return n
}

type MatchList map[int]bool
type MatchTable map[int]MatchList

func Run(in io.Reader, out io.Writer) error {
	sc := bufio.NewScanner(in)
	sc.Split(bufio.ScanWords)

	n := nextInt(sc)
	red := make(PointList, n)
	blue := make(PointList, n)
	isMatched := make(MatchTable, n)

	for i := 0; i < n; i++ {
		x, y := nextInt(sc), nextInt(sc)
		red[i] = &Point{i, x, y, 0, false}
	}

	for i := 0; i < n; i++ {
		x, y := nextInt(sc), nextInt(sc)
		isMatched[i] = make(MatchList, n)

		match := 0
		for j := 0; j < n; j++ {
			if red[j].IsPair(x, y) {
				isMatched[i][j] = true
				match++
				red[j].ref++
			}
		}
		blue[i] = &Point{i, x, y, match, false}
	}

	sort.Sort(red)
	sort.Sort(blue)

	cnt := 0
	for _, b := range blue {
		for _, r := range red {
			if r.isMatched {
				continue
			}
			if !isMatched[b.i][r.i] {
				continue
			}
			r.isMatched = true
			cnt += 1
			break
		}
	}

	fmt.Fprintf(out, "%d\n", cnt)

	return nil
}

func main() {
	in, out := os.Stdin, os.Stdout
	Run(in, out)
}

