		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d %d", &pt.x, &pt.y)
		cd[i] = pt
	}

	abPoints = make([]Record, N)
	cdPoints = make([]Record, N)

	for i, pt := range ab {
		abPoints[i] = Record{pt}
	}
	for i, pt := range cd {
		cdPoints[i] = Record{pt}
	}

	sort.Sort(abPoints)
	sort.Sort(cdPoints)

	doneAb := make(map[Record]struct{})
	for _, cdPoint := range cdPoints {
		opponent := Record{pt: point{-1, -1}}
		for _, abPoint := range abPoints {
			if _, e := doneAb[abPoint]; e {
				continue
			}
			if abPoint.pt.x > cdPoint.pt.x {
