			}
			if abPoint.pt.isSub(cdPoint.pt) && abPoint.pt.y > opponent.pt.y {
				opponent = abPoint
			}
		}
		if opponent.pt.x != -1 {
			doneAb[opponent] = struct{}{}
		}
	}
	fmt.Println(len(doneAb))
}

