import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
)

type Point struct {
	i         int
	x, y      int
	ref       int
	isMatched bool
}

func (p Point) IsPair(x, y int) bool {
	return p.x < x && p.y < y
}

func nextInt(sc *bufio.Scanner) int {
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	return n
}

type MatchList map[int]bool
type MatchTable map[int]MatchList

func Run(in io.Reader, out io.Writer) error {
	sc := bufio.NewScanner(in)
	sc.Split(bufio.ScanWords)

	n := nextInt(sc)
	red := make([]*Point, n)
	blue := make([]*Point, n)
	isMatched := make(MatchTable, n)

	for i := 0; i < n; i++ {
		x, y := nextInt(sc), nextInt(sc)
		red[i] = &Point{i, x, y, 0, false}
	}

	for i := 0; i < n; i++ {
		x, y := nextInt(sc), nextInt(sc)
		isMatched[i] = make(MatchList, n)

		match := 0
		for j := 0; j < n; j++ {
			if red[j].IsPair(x, y) {
				isMatched[i][j] = true
				match++
				red[j].ref++
			}
		}
		blue[i] = &Point{i, x, y, match, false}
	}

	sort.Slice(red, func(i, j int) bool {
		return red[i].ref < red[j].ref
	})
	sort.Slice(blue, func(i, j int) bool {
		return blue[i].ref > blue[j].ref
	})

	cnt := 0
	for _, b := range blue {
		for _, r := range red {
			if r.isMatched {
				continue
			}
			if !isMatched[b.i][r.i] {
				continue
			}
			r.isMatched = true
			cnt += 1
			break
		}
	}

	fmt.Fprintf(out, "%d\n", cnt)

	return nil
}

func main() {
	in, out := os.Stdin, os.Stdout
	Run(in, out)
}

