func (l Points) Less(i, j int) bool {
	return l[i].in < l[j].in || l[i].x*l[i].y < l[j].x*l[j].y
}

func (l Points) Swap(i, j int) {
	l[i], l[j] = l[j], l[i]
}

func main() {
	s := wordScanner()

	var n int
	scanInts(s, &n)

	reds := make(Points, n)
	for i := range reds {
		scanInts(s, &reds[i].x, &reds[i].y)
	}

	blues := make(Points, n)
	for i := range blues {
		scanInts(s, &blues[i].x, &blues[i].y)
	}

	sort.Sort(reds)

	for i, b := range blues {
		for _, r := range reds {
			if isInner(r, b) {
				blues[i].in++
			}
		}
	}
	sort.Sort(blues)

	c := 0
	for _, r := range reds {
		for j, b := range blues {
			if isInner(r, b) {
				blues = append(blues[:j], blues[j+1:]...)
				c++
				break
			}
		}
	}
	fmt.Println(c)
}

func isInner(inner, outer Point) bool {
	return outer.x > inner.x && outer.y > inner.y
}

func wordScanner() *bufio.Scanner {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	return s
}

func scanInts(s *bufio.Scanner, vals ...*int) {
	for i := range vals {
		s.Scan()
		n, _ := strconv.Atoi(s.Text())
		*vals[i] = n
	}
}

