type point struct {
	x, y int
}
type byx []point

func (a byx) Len() int           { return len(a) }
func (a byx) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a byx) Less(i, j int) bool { return a[i].x < a[j].x }

func solve() {
	n := getInt()
	getPoints := func() []point {
		ret := make([]point, n)
		for i := range ret {
			ret[i].x = getInt()
			ret[i].y = getInt()
		}
		return ret
	}
	reds := getPoints()
	blues := getPoints()

	sort.Sort(byx(blues))

	ans := 0
	m := make(map[int]bool)
	for _, b := range blues {
		friend := -1
		now := -1
		for i, r := range reds {
			if b.x <= r.x || b.y <= r.y {
				continue
			} else if _, exist := m[r.y]; exist {
				continue
			}

			if now < r.y {
				now = r.y
				friend = i
			}
		}
		if friend == -1 {
			continue
		}
		ans++
		m[friend] = true
	}

	fmt.Fprintln(wr, ans)
}

