import (
	"fmt"
	"sort"
)

var (
	n    int
	a, b int
	c, d int
)

func main() {
	fmt.Scan(&n)
	red := make([][]int, 0, n)
	blue := make([][]int, 0, n)

	for i := 0; i < n; i++ {
		fmt.Scan(&a, &b)
		red = append(red, []int{a, b})
	}
	for i := 0; i < n; i++ {
		fmt.Scan(&c, &d)
		blue = append(blue, []int{c, d})
	}

	sort.Slice(blue, func(i, j int) bool {
		return blue[i][0] < blue[j][0]
	})

	count := 0
	for _, v := range blue {
		candidate := filter(red, v[0])
		sort.Slice(candidate, func(i, j int) bool {
			return candidate[i][1] > candidate[j][1]
		})
		for _, w := range candidate {
			if w[1] < v[1] {
				red = del(red, w)
				count++
				break
			}
		}
	}
	fmt.Println(count)

}

func del(red [][]int, where []int) [][]int {
	ret := make([][]int, 0, len(red))
	for _, v := range red {
		if v[0] == where[0] && v[1] == where[1] {
			continue
		}

		ret = append(ret, v)
	}

	return ret
}

func filter(red [][]int, blueX int) [][]int {
	ret := make([][]int, 0, len(red))
	for _, v := range red {
		if v[0] < blueX {
			ret = append(ret, v)
		}
	}

	return ret
}

