var sc = bufio.NewScanner(os.Stdin)

func nextInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func main() {
	sc.Split(bufio.ScanWords)
	N := nextInt()

	as := make([]int, N)
	for i := range as {
		as[i] = nextInt()
	}

	bs := make([]int, N)
	for i := range bs {
		bs[i] = nextInt()
	}

	ans := 0
	tmp := make([]int, len(bs))
	for i := uint8(0); i < 31; i++ {
		for j, b := range bs {
			tmp[j] = b % (1 << i)
		}
		sort.Ints(tmp)

		count := 0
		for _, a := range as {
			n := a % (1 << i)

			x := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return (1<<i)-n <= m
			})
			y := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 2*(1<<i)-n <= m
			})

			z := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 3*(1<<i)-n <= m
			})
			w := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 4*(1<<i)-n <= m
			})

			count += y - x + w - z
		}

		if count%2 == 1 {
			ans += 1 << i
		}
	}

	fmt.Println(ans)
}

