	fmt.Fprintln(wt, a...)
}

type Point struct {
	x, y int
}

type PR []Point

func (a PR) Len() int      { return len(a) }
func (a PR) Swap(i, j int) { a[i], a[j] = a[j], a[i] }
func (a PR) Less(i, j int) bool {
	if a[i].y == a[j].y {
		return a[i].x > a[j].x
	}
	return a[i].y > a[j].y
}

type PB []Point

func (a PB) Len() int      { return len(a) }
func (a PB) Swap(i, j int) { a[i], a[j] = a[j], a[i] }
func (a PB) Less(i, j int) bool {
	if a[i].x == a[j].x {
		return a[i].y < a[j].y
	}
	return a[i].x < a[j].x
}

