	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	n := nextInt()
	pr, pb := make(PR, n), make(PB, n)
	for i := 0; i < n; i++ {
		pr[i] = Point{nextInt(), nextInt()}
	}
	for i := 0; i < n; i++ {
		pb[i] = Point{nextInt(), nextInt()}
	}
	sort.Sort(pr)
	sort.Sort(pb)

	ans := 0
	used := make([]bool, n)
	for i := 0; i < n; i++ {
		// pbを基準にする
		for j := 0; j < n; j++ {
			if used[j] {
				continue
			}
			if pb[i].x > pr[j].x && pb[i].y > pr[j].y {
				ans++
				used[j] = true
				break
			}
		}
	}

	puts(ans)
}

