		sort.Sort(byY{redPoints})
		if i == 0 {
			sort.Sort(byX{redPoints})
		}
		for j := range make([]struct{}, 2) {
			sort.Sort(byX{bluePoints})
			sort.Sort(byY{bluePoints})
			if j == 0 {
				sort.Sort(byX{bluePoints})
			}
			bluePoints = reverse(bluePoints)

			rPs := make([]point, n)
			bPs := make([]point, n)
			copy(rPs, redPoints)
			copy(bPs, bluePoints)

			cnt := 0
			for len(rPs) > 0 {
				for k := len(bPs) - 1; k >= 0; k-- {
					rPsh := rPs[len(rPs)-1]
					bPsk := bPs[k]
					if rPsh.x < bPsk.x && rPsh.y < bPsk.y {
						rPs = rPs[:len(rPs)-1]
						bPs = append(bPs[:k], bPs[k+1:]...)
						cnt++
						break
					}
					if k == 0 {
						rPs = rPs[:len(rPs)-1]
					}
				}
				ans = max(ans, cnt)
			}
		}
	}
	fmt.Println(ans)
}

