type pair struct{ a, b int }

type point struct{ x, y int }
type byXY []point

func (p byXY) Len() int      { return len(p) }
func (p byXY) Swap(i, j int) { p[i], p[j] = p[j], p[i] }
func (p byXY) Less(i, j int) bool {
	if p[i].x == p[j].x {
		return p[i].y < p[j].y
	}
	return p[i].x < p[j].x
}

func solve() {
	n := ri()
	as := make([]point, n)
	for i := 0; i < n; i++ {
		as[i] = point{x: ri(), y: ri()}
	}
	bs := make([]point, n)
	for i := 0; i < n; i++ {
		bs[i] = point{x: ri(), y: ri()}
	}
	sort.Sort(byXY(as))
	sort.Sort(byXY(bs))

	aIsUsed := make([]bool, len(as))
	ct := 0
	for _, b := range bs {
		found := false
		yMax := -inf
		yMaxIdx := -1
		for j, a := range as {
			if aIsUsed[j] {
				continue
			}
			if !(a.x < b.x && a.y < b.y) {
				continue
			}

			found = true
			if a.y > yMax {
				yMax = a.y
				yMaxIdx = j
			}
		}
		if found {
			ct++
			aIsUsed[yMaxIdx] = true
		}
	}

	pln(ct)
}

