func minLetter(f, l int) bool {
	return l < f
}

func (p *problem) solve() {
	N := p.nextInt()
	red := []point{}
	blue := []point{}
	for i := 0; i < N; i++ {
		l := p.nextInts()
		red = append(red, point{x: l[0], y: l[1]})
		log.Printf("l:%v, red:%v", l, red)
	}
	for i := 0; i < N; i++ {
		l := p.nextInts()
		blue = append(blue, point{x: l[0], y: l[1]})
		log.Printf("l:%v, blue:%v", l, blue)
	}
	var c int
	for _, rp := range red {
		log.Println(blue)
		index := 999
		lastDist := 999
		for i, bp := range blue {
			log.Printf("red:%v, blue:%v", rp, bp)
			if rp.x < bp.x && rp.y < bp.y {
				log.Printf("pair! %v", c)
				dist := bp.x - rp.x
				if minLetter(lastDist, dist) {
					log.Printf("min last: %v, current:%v, index:%v", lastDist, dist, index)
					lastDist = dist
					index = i
				}
			}
		}
		if index != 999 {
			c++
			newB := []point{}
			newB = append(newB, blue[:index]...)
			if index+1 <= len(blue)-1 {
				newB = append(newB, blue[index+1:]...)
			}
			blue = newB
		}
	}
	p.printf("%d", c)
}

func main() {
	if debug {
		log.SetOutput(os.Stdout)
	} else {
		log.SetOutput(ioutil.Discard)
	}

	p := problem{
		in:  bufio.NewReader(os.Stdin),
		out: bufio.NewWriter(os.Stdout),
	}
	p.solve()

	if err := p.out.Flush(); err != nil {
		panic(err)
	}
}

type problem struct {
	in  *bufio.Reader
	out *bufio.Writer
}

func (p *problem) printi(d int) {
	if err := p.out.WriteByte(byte(d)); err != nil {
		panic(err)
	}
}

func (p *problem) printf(format string, a ...interface{}) {
	if _, err := fmt.Fprintf(p.out, format, a...); err != nil {
		panic(err)
	}
}

func (p *problem) nextInt() int {
	return stoi(p.next())
}

func (p *problem) nextInts() []int {
	line := p.nextSSLine()
	ds := make([]int, len(line))
	for i, s := range line {
		ds[i] = stoi(s)
	}
	return ds
}

func (p *problem) nextSSLine() []string {
	return strings.Split(p.next(), " ")
}

// Next reads line and return string.
func (p *problem) next() string {
	var b []byte
	for {
		l, pre, err := p.in.ReadLine()
		if err != nil {
			panic(err)
		}
		b = append(b, l...)
		if !pre {
			break
		}
	}
	return string(b)
}

func stoi(s string) int {
	i, err := strconv.Atoi(s)
	if err != nil {
		fmt.Println(i)
		fmt.Println(err)
	}
	return i
