type blueSorter []*edge

func (a blueSorter) Len() int { return len(a) }
func (a blueSorter) Less(i, j int) bool {
	return a[i].to.fromNum < a[j].to.fromNum
}
func (a blueSorter) Swap(i, j int) { a[i], a[j] = a[j], a[i] }

func main() {
