func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	N := sc.nextInt()
	R := make([]Point, N)
	for i := 0; i < N; i++ {
		R[i] = Point{i, sc.nextInt(), sc.nextInt()}
	}
	B := make([]Point, N)
	for i := 0; i < N; i++ {
		B[i] = Point{i, sc.nextInt(), sc.nextInt()}
	}
	sort.Sort(ByX(B))
	done := make(map[int]bool)
	for _, pb := range B {
		targets := []Point{}
		for i, pr := range R {
			if pr.x < pb.x && pr.y < pb.y && !done[i] {
				targets = append(targets, pr)
			}
		}
		if len(targets) != 0 {
			sort.Sort(ByY(targets))
			done[targets[0].id] = true
		}
	}

	fmt.Fprintln(wtr, len(done))
	wtr.Flush()
}

