	}

	blues := make(pairs, N)
	for i := range blues {
		fmt.Scan(&blues[i].x, &blues[i].y)
	}

	count := 0
	used := make([]bool, len(reds))
	for _, b := range blues {
		cand := -1
		for i, r := range reds {
			if !used[i] && r.x < b.x && r.y < b.y {
				if cand == -1 {
					cand = i
					continue
				}

				if reds[cand].x < r.x && reds[cand].y < r.y {
					cand = i
				}
			}
		}

