          if (ma[1] < e[1]) {
            ma = tuple(e[0], e[1], false);
            f = true;
          }
        }
      }
      if (f) {
        s.removeKey(ma);
        ans++;
      }
    }
    else {
      s.insert(L[i]);
    }
  }

  writeln(ans);
}

