    }
    rep(i,n){
        rep(j,n){
            if(ax[i] < bx[j] && ay[i] < by[j]){
                dc.add_edge(i, j+n, 1);
            }
        }
    }
    rep(i, n){
        dc.add_edge(n + n, i, 1);
    }
    rep(i, n){
        dc.add_edge(i + n, n + n + 1, 1);
    }
    cout << dc.max_flow(n + n, n + n + 1) << endl;
    return 0;
}

