class Ford_Fulkerson:
    def __init__(self,G,N,s,t,check):
        self.G,self.N,self.s,self.t,self.check=G,N,s,t,check
        for v in range(self.N):
            if v==s or v==t:
                continue
            for nv,cap in self.G[v].items():
                self.G[nv][v]=0
            if self.check(v):
                self.G[s][v]=1
                self.G[v][s]=0
            else:
                self.G[v][t]=1
                self.G[t][v]=0
        self.max_f=self.Max_Flow(self.G,self.s,self.t)

    def dfs(self,G,v,t,f,used):
        if v==t:
            return f
        used[v]=True
        for nv,cap in G[v].items():
            if not used[nv] and cap>0:
                d=self.dfs(self.G,nv,t,min(f,cap),used)
                if d>0:
                    self.G[v][nv]-=d
                    self.G[nv][v]+=d
                    return d
        return 0

    def Max_Flow(self,G,s,t):
        flow=0
        while(True):
            used=[False]*(2*N+2)
            f=self.dfs(self.G,self.s,self.t,float('inf'),used)
            if f==0:
                return flow
            flow+=f

