    if len(bc) == 0 or len(rc) == 0:
        return pair

    bcc = bc.copy()
    e = bcc.pop()
    pairs = [pair]

    for i in rc:
        if e[0] > i[0] and e[1] > i[1]:
            rcc = rc.copy()
            rcc.remove(i)
            pairs.append(check_rec(bcc, rcc, pair+1))

