class Bipartite_Matching():
    # n : 頂点数
    def __init__(self, n):
        self.match = [-1]*n
        self.used = [0]*n
        self.n = n
        self.edges = [[] for i in range(n)]

    # u→v のedgeを張る
    def add_edge(self, u, v):
        self.edges[u].append(v)

    # 増加路の判定
    def dfs(self, v):
        self.used[v] = 1
        for u in self.edges[v]:
            w = self.match[u]
            if w < 0 or (not self.used[w] and self.dfs(w)):
                self.match[v] = u
                self.match[u] = v
                return True
        return False

    # 最大マッチングの辺数を返す
    def bipartite_matching(self):
        ret = 0
        for v in range(self.n):
            if self.match[v] < 0:
                self.used = [0]*self.n
                if self.dfs(v):
                    ret += 1
        return ret


