def ret_minimum_match(match, lower_i, matched_higher_set, matched_lower_set):
    min_i = -1
    min_len = 101
    for i, ma in enumerate(match):
        if i in matched_higher_set or lower_i not in ma:
            continue
        if min_len > len(ma - matched_lower_set) > 0:
