"""
==================================================
二部グラフの最大マッチングを求めるプログラム

# 条件
G = (U,V,E) |U| = |E|

# 入力
U --> 1 2 3 4 .... 10
V --> a b c d .... j
E -->
1 a
1 d
2 b
2 f
etc...

# 出力(最大マッチングの一例)
edges = [(1,a), (2,b), (3 h), ...]

# 定義
def get_edge(M, u, U)    枝集合Mに含まれる枝のうち、頂点uと接している枝の他方の頂点_(1)を返す関数。そのような枝
                         が複数ある場合、一番最初に見つかった頂点を返す。また、引数にUが指定されている場合、(1)
                         を満たし、かつUに含まれる頂点を返す。

def get_nodes(M)         枝集合Mに含まれる枝に関して、左接続の頂点と右接続の頂点に分け、左接続の頂点集合と右接続
                         の頂点集合の二つを返す関数。

def augpath(Si, Ti, M, E)
                         二部グラフにおいて、増大道があるかどうかを判定・処理するプログラム。

==================================================
"""

def get_edge(M, u, U=None):

    if U == None:
        for x in M[:]:
            if x[0] == u:
                return x[1]
            elif x[1] == u:
                return x[0]

    else:
        for x in M[:]:
            if x[0] == u and x[1] in U:
                return x[1]
            elif x[1] == u and x[0] in U:
                return x[0]
    return None

def get_nodes(M):
    U = set()
    V = set()
    for x in M:
        U.add(x[0])
        V.add(x[1])
    return (U, V)


def augpath(Si, Ti, M, E):
    (U, V) = get_nodes(M)
    Ti1 = set(x[1] for x in E if x[0] in Si and not x[1] in Ti)

    if Ti1 == set():
        return (M, None)

    elif Ti1.difference(V) == set():
        Si1 = set(x[0] for x in M if x[1] in Ti1)
        (M, ui1) = augpath(Si1, Ti.union(Ti1), M, E)

        if ui1 == None:
            return (M, None)

        else:
            v = get_edge(M, ui1)
            M.remove((ui1,v))

            ui = get_edge(E, v, U=Si)
            M.append((ui,v))

            return (M, ui)

    else:
        v = Ti1.difference(V).pop()
        u = get_edge(E, v, U=Si)
        M.append((u,v))

        return (M, u)

def Hungary(U0, V0, E):
    U_bef = set()
    M = []
    cnt = 0
    length = len(U0)

    # CALC
    while True:

        # INIT
        (U, V) = get_nodes(M)
        u = U0[cnt%length]
        cnt = cnt + 1
        S0 = set()
        S0.add(u)
        T0 = set()

        # 終了条件(すべての頂点から始まる増大道を調べて、マッチング数が変わっていなければ、それ以上増えることはない)
        if cnt % length == 0:
            if U.difference(U_bef) == set():
                break
            U_bef = U.copy()

        # 枝刈り(すでにマッチングしている頂点から始まる道は増大道ではない)
        if u in U:
            continue

        #CALC
        (M, u) = augpath(S0, T0, M, E)

    return M

