def solve():
    N = get_next_int()
    red_heap = []
    red_heap_rev = []
    for i in range(N):
        a, b = get_next_ints()
        heapq.heappush(red_heap, (b, a))
        heapq.heappush(red_heap_rev, (a, b))
    blue_heap = []
    blue_heap_rev = []
    for i in range(N):
        c, d = get_next_ints()
        heapq.heappush(blue_heap, (d, c))
        heapq.heappush(blue_heap_rev, (c, d))

    blue_heap = sorted(blue_heap)
    red_heap = sorted(red_heap)
    blue_heap_rev = sorted(blue_heap_rev)
    red_heap_rev = sorted(red_heap_rev)
    ans = 0
    while(len(blue_heap) > 0):
        blue_pos = heapq.heappop(blue_heap)
        for i in range(len(red_heap)):
            red_pos = red_heap[i]
            if blue_pos[0] > red_pos[0] and blue_pos[1] > red_pos[1]:
                ans += 1
                # heapq.heappop(red_heap)
                # print(blue_pos[1], blue_pos[0], red_pos[1], red_pos[0])
                del red_heap[i]
                break
            elif blue_pos[0] < red_pos[0]:
                break

    ans_rev = 0
    while(len(blue_heap_rev) > 0):
        blue_pos = heapq.heappop(blue_heap_rev)
        for i in range(len(red_heap_rev)):
            red_pos = red_heap_rev[i]
            if blue_pos[0] > red_pos[0] and blue_pos[1] > red_pos[1]:
