def able_to_be_pair(red, blue):
    return True if (blue[0] - red[0]) > 0 and (blue[1] - red[1]) > 0 else False

import itertools
def permutations(array, choose=None):
    if choose is None:
        choose = len(array)
    return list(itertools.permutations(array, choose))

if '__main__' == __name__:
    resolve()

