    ans = 0
    count = [0]*n
    abli.sort(reverse=True)

    for i in range(n):
        flag = False
        for w in range(n):
            if abli[i][0] < cdli[w][0] and abli[i][1] < cdli[w][1] and count[w] == 0:
                ans += 1
                count[w] = 1
                flag = True
            if flag == True:
                break

    return ans

