import collections, itertools, copy


class MaximumFlow:
    def ford_fulkerson(self, G, s, t):
        G = copy.deepcopy(G)

        def dfs(start, used):
            if start == t:
                return [start]
            for end, cap in G[start].items():
                if cap > 0 and end not in used:
                    used.add(end)
                    ret = dfs(end, used)
                    if ret:
                        return ret + [start]
            return []

        flow_value = 0
        flow_dict = collections.defaultdict(
            lambda: collections.defaultdict(int))
        while True:
            root = dfs(s, set([s]))
            if root:
                root = root[::-1]
                residue = min([G[a][b] for a, b in zip(root, root[1:])])
                flow_value += residue
                for a, b in zip(root, root[1:]):
                    if a in flow_dict:
                        if residue >= flow_dict[b][a]:
                            flow_dict[a][b] += residue - flow_dict[b][a]
                            del flow_dict[b][a]
                        else:
                            flow_dict[b][a] -= residue
                    else:
                        flow_dict[a][b] += residue
                    flow_dict[a][b]
                    G[a][b] -= residue
                    G[b][a] += residue
            else:
                if t in flow_dict:
                    del flow_dict[t]
                    return (flow_value, flow_dict)


