class FordFulkerson :
    # deque required
    def __init__(self, N) :
        self.N = N
        self.G = [[] for _ in range(N)]

    def add_edge(self, fr, to, cap) :
        self.G[fr].append([to, cap, len(self.G[to])])
        self.G[to].append([fr, 0, len(self.G[fr])-1])

    def bfs(self, fr, to) :
        self.pre_v = [0] * self.N
        self.pre_e = [0] * self.N
        visited = [False] * self.N
        visited[fr] = True

        q = deque([fr])
        while q :
            cur = q.popleft()

            for i, (nex, cap, _) in enumerate(self.G[cur]) :
                if visited[nex] or cap <= 0 :
                    continue

                self.pre_v[nex], self.pre_e[nex] = cur, i
                q.append(nex)
                visited[nex] = True

                if nex == to :
                    return True

        return False

    def flow(self, fr, to) :
        ret = 0
        while self.bfs(fr, to) :
            cur = to
            min_cap = float('inf')
            while cur != fr :
                min_cap = min(min_cap, self.G[self.pre_v[cur]][self.pre_e[cur]][1])
                cur = self.pre_v[cur]

            ret += min_cap
            cur = to
            while cur != fr :
                self.G[self.pre_v[cur]][self.pre_e[cur]][1] -= min_cap
                self.G[cur][self.G[self.pre_v[cur]][self.pre_e[cur]][2]][1] += min_cap
                cur = self.pre_v[cur]

        return ret

