      return f
    for i in range(self.iter[v], len(self.G[v])):
      self.iter[v] = i
      e = self.G[v][i]
      if e['cap'] > 0 and self.d[v] < self.d[e['to']]:
        r = self.dfs(e['to'], t, min(INF, e['cap']))
        if r > 0:
          e['cap'] -= r
          self.G[e['to']][e['rev']]['cap'] += r
          return r
    return 0

  def max_flow(self, s, t):
    flow = 0
    while True:
      self.bfs(s)
      if self.d[t] < 0:
        return flow
      self.iter = [0 for _ in range(self.N)]
      f = self.dfs(s,t,INF)
      while f > 0:
        flow += f
        f = self.dfs(s,t,INF)  

