fn solve() {
    input! {
        N: usize,
        AB: [(u32,u32); N],
        CD: [(u32,u32); N],
    }

    let s = 2*N;
    let t = 2*N+1;
    let mut g = Network::new(2*N+2);
    for i in 0..N {
        g.add_edge(s, i, 1);
        g.add_edge(i+N, t, 1);
    }
    for i in 0..N {
        for j in 0..N {
            let ab = AB[i];
            let cd = CD[j];
            if ab.0 < cd.0 && ab.1 < cd.1 {
                g.add_edge(i, j+N, 1);
            }
        }
    }
    println!("{}", g.max_flow(s,t));
