fn main() {
    use std::cell::Cell;

    let n: usize = parse_line();

    struct Point {
        x: i32,
        y: i32,
    }

    struct RedPoint {
        point: Point,
        used: Cell<bool>,
    }

    let red_points = {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let p = parse_vec::<i32>();
            v.push(RedPoint {
                point: Point { x: p[0], y: p[1] },
                used: Cell::new(false),
            });
        }
        v.sort_by_key(|p| p.point.x);
        v
    };

    let blue_points = {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let p = parse_vec::<i32>();
            v.push(Point { x: p[0], y: p[1] });
        }
        v.sort_by_key(|p| p.x);
        v
    };

    let mut pair_count = 0;
    for blue in blue_points {
        let r = red_points
            .iter()
            .take_while(|r| r.point.x < blue.x)
            .filter(|r| !r.used.get())
            .max_by_key(|r| r.point.y);

        if let Some(r) = r {
            r.used.set(true);
            pair_count += 1;
        }
    }

    println!("{}", pair_count);
}

