fn main() {
    let stdin = stdin();
    let mut scan = InputScanner::new(stdin.lock(),256);

    let n:usize = scan.next();

    let mut ab:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();
    let mut cd:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();

    let mut count = 0;

    while ab.len() > 0 && cd.len() > 0 {
        let (x,y) = ab.remove(0);

        let mut min = std::usize::MAX;
        let mut index = None;

        for i in 0..cd.len() {
            if cd[i].0 > x && cd[i].1 > y {
				let mut c = 0;

				for &(a,b) in &ab {
					if x <= a && a < cd[i].0 && y <= b && b < cd[i].1 {
						c += 1;
					}
				}

				if c < min {
					min = c;
					index = Some(i);
				}
            }
        }

        if let Some(i) = index {
            count += 1;
            cd.remove(i);
        }
    }

    println!("{}",count);
