    let mut map: Vec<Vec<i32>> = vec![vec![0; 2 * n]; 2 * n];

    for i in 0..n {
        let x = rpv[i][0];
        let y = rpv[i][1];
        map[x][y] = 1;
        let x = bpv[i][0];
        let y = bpv[i][1];
        map[x][y] = -1;
    }

    map[0][0] = max(0, map[0][0]);
    for x in 1..(2 * n) {
        map[x][0] = max(0, map[x][0] + map[x - 1][0]);
    }
    for y in 1..(2 * n) {
        map[0][y] = max(0, map[0][y] + map[0][y - 1]);
    }
    for y in 1..(2 * n) {
        for x in 1..(2 * n) {
            map[x][y] = max(
                0,
                map[x][y] + map[x - 1][y] + map[x][y - 1] - map[x - 1][y - 1],
            );
        }
    }

    println!("{}", n - map[2 * n - 1][2 * n - 1] as usize);
}

