    let mut scan = InputScanner::new(stdin.lock(),256);

    let n:usize = scan.next();

    let ab:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();
    let cd:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();

	let mut m:Vec<usize> = (0..n).map(|_| 0).collect::<Vec<usize>>();
	let mut t:Vec<Vec<usize>> = (0..n).map(|_| Vec::new()).collect::<Vec<Vec<usize>>>();
	let mut r:Vec<Vec<usize>> = (0..n).map(|_| Vec::new()).collect::<Vec<Vec<usize>>>();

	for (i,&(a,b)) in ab.iter().enumerate() {
        for (j,&(c,d)) in cd.iter().enumerate() {
            if c > a && d > b {
				m[j] += 1;
				r[j].push(i);
				t[i].push(j);
            }
        }
    }

	let mut count = 0;

	for i in 0..n {
		let mut min = std::usize::MAX;
		let mut index = None;

		for &j in &t[i] {
			if m[j] > 0 && m[j] < min && r[j].iter()
											.filter(|&&s| s != i)
											.filter(|&&s| {
												t[s].iter().filter(|&&c| c > 0).count() == 1
											}).count() == 0 {
				min = m[j];
				index = Some(j);
			}
		}

		if index.is_none() {
			for &j in &t[i] {
				if m[j] > 0 && m[j] < min {
					min = m[j];
					index = Some(j);
				}
			}
		}

