pub struct Edge {
	pub to: usize,
	pub capacity: i64,
	pub reverse: usize,
}

pub struct Dinic {
	edges: Vec<Vec<Edge>>,
	level: Vec<i64>,
	iter: Vec<usize>,
}

impl Dinic {
	pub fn new(v: usize) -> Self {
		Dinic { edges: vec![vec![]; v], level: vec![0; v], iter: vec![0; v] }
	}

	pub fn add_edge(&mut self, from: usize, to: usize, capacity: i64) {
		let reverse = self.edges[to].len();
		self.edges[from].push(Edge { to: to, capacity: capacity, reverse: reverse });
		let reverse = self.edges[from].len() - 1;
		self.edges[to].push(Edge { to: from, capacity: 0, reverse: reverse });
	}

	fn bfs(&mut self, from: usize) {
		for i in self.level.iter_mut() {
			*i = -1;
		}
		let mut q = std::collections::VecDeque::new();
		self.level[from] = 0;
		q.push_back(from);
		while let Some(v) = q.pop_front() {
			for e in self.edges[v].iter() {
				if e.capacity > 0 && self.level[e.to] < 0 {
					self.level[e.to] = self.level[v] + 1;
					q.push_back(e.to);
				}
			}
		}
	}

	fn dfs(&mut self, v: usize, to: usize, f: i64) -> i64 {
		if v == to {
			return f;
		}
		while self.iter[v] < self.edges[v].len() {
			let i = self.iter[v];
			let e = self.edges[v][i];
			if e.capacity > 0 && self.level[v] < self.level[e.to] {
				let d = self.dfs(e.to, to, std::cmp::min(f, e.capacity));
				if d > 0 {
					self.edges[v][i].capacity -= d;
					self.edges[e.to][e.reverse].capacity += d;
					return d;
				}
			}
			self.iter[v] += 1;
		}
		0
	}

	fn max_flow(&mut self, from: usize, to: usize) -> i64 {
		let mut flow = 0;
		loop {
			self.bfs(from);
			if self.level[to] < 0 {
				break;
			}
			for i in self.iter.iter_mut() {
				*i = 0;
			}
			loop {
				let f = self.dfs(from, to, std::i64::MAX);
				if f > 0 {
					flow += f;
				} else {
					break;
				}
			}
		}
		flow
	}
}

