	let to = 2 * n + 1;
	for i in 0..n {
		dinic.add_edge(from, i, 1);
		dinic.add_edge(n + i, to, 1);
		for j in 0..n {
			if red[i].0 < blue[j].0 && red[i].1 < blue[j].1 {
				dinic.add_edge(i, n + j, 1);
			}
		}
	}
	let ans = dinic.max_flow(from, to);
	println!("{}", ans);
}

