}
fn solve(n: usize, mut reds: Vec<(usize, usize)>, mut blues: Vec<(usize, usize)>) -> usize {
    fn can_pair(r: (usize, usize), b: (usize, usize)) -> bool {
        r.0 < b.0 && r.1 < b.1
    };

    blues.sort();
    for &b in &blues {
        if let Some(i) = reds.iter()
            .enumerate()
            .filter(|&(_, &xy)| can_pair(xy, b))
            .max_by_key(|&(_, &(_, y))| y)
            .map(|(i, _)| i)
        {
            reds.remove(i);
        }
    }
    n - reds.len()
}
fn solve_old(n: usize, reds: Vec<(usize, usize)>, blues: Vec<(usize, usize)>) -> usize {
    let can_pair = |n_red: usize, n_blue: usize| {
        let red = reds[n_red];
        let blue = blues[n_blue];
        red.0 < blue.0 && red.1 < blue.1
    };
    let mut cp_red = vec![0usize; n];
    let mut cp_blue = vec![0usize; n];

    for n_red in 0..n {
        for n_blue in 0..n {
            if can_pair(n_red, n_blue) {
                cp_red[n_red] += 1;
                cp_blue[n_blue] += 1;
            }
        }
    }
    let mut r = 0;
    loop {
        let min_red = cp_red
            .iter()
            .cloned()
            .enumerate()
            .filter(|&x| x.1 != 0)
            .min_by_key(|&x| x.1);
        let min_blue = cp_blue
            .iter()
            .cloned()
            .enumerate()
            .filter(|&x| x.1 != 0)
            .min_by_key(|&x| x.1);
        if let (Some((mut n_red, c_red)), Some((mut n_blue, c_blue))) = (min_red, min_blue) {
            if c_red < c_blue {
                n_blue = (0..n)
                    .filter(|&n_blue| can_pair(n_red, n_blue) && cp_blue[n_blue] != 0)
                    .min_by_key(|&n_blue| cp_blue[n_blue])
                    .unwrap();
            } else {
                n_red = (0..n)
                    .filter(|&n_red| can_pair(n_red, n_blue) && cp_red[n_red] != 0)
                    .min_by_key(|&n_red| cp_red[n_red])
                    .unwrap();
            }

            r += 1;
            for n_red in 0..n {
                if can_pair(n_red, n_blue) && cp_red[n_red] != 0 {
                    cp_red[n_red] -= 1;
                }
            }
            for n_blue in 0..n {
                if can_pair(n_red, n_blue) && cp_blue[n_blue] != 0 {
                    cp_blue[n_blue] -= 1;
                }
            }
            cp_red[n_red] = 0;
            cp_blue[n_blue] = 0;
        } else {
            break;
        }
    }
    r
}

