fn solve() {
    let n = get!(usize);
    let ab = get!(usize, usize; n);
    let cd = get!(usize, usize; n);

    let mut red = Vec::new();
    for i in 0..n {
        let mut indexes = BTreeSet::new();
        for j in 0..n {
            if ab[i].0 < cd[j].0 && ab[i].1 < cd[j].1 {
                indexes.insert(j);
            }
        }
        red.push(indexes);
    }

    let mut used = BTreeSet::new();
    'gorilla: while red.iter().any(|is| is.difference(&used).count() > 0) {
        red.sort_by(|a, b| (a.difference(&used).count()).cmp(&(b.difference(&used).count())));
        if let Some(i) = red.iter().position(|is| is.difference(&used).count() > 0) {
            for j in red[i].clone() {
                if !used.contains(&j) {
                    used.insert(j);
                    red.remove(i);
                    continue 'gorilla;
                }
            }
        } else {
            break;
        }
    }
    println!("{}", used.len());

}

