                if f == 0 {
                    break;
                }
                flow += f;
            }
        }
    }
    fn bfs(&self, s: usize) -> Vec<Option<usize>> {
        let mut level = vec![None; self.edges.len()];
        let mut que = std::collections::VecDeque::new();
        level[s] = Some(0);
        que.push_back(s);
        while let Some(v) = que.pop_front() {
            let l = Some(level[v].unwrap() + 1);
            for &(to, _, cap) in &self.edges[v] {
                if cap > 0 && level[to].is_none() {
                    level[to] = l;
                    que.push_back(to);
                }
            }
        }
        level
    }
    fn dfs(
        &mut self,
        v: usize,
        t: usize,
        f: u64,
        level: &[Option<usize>],
        iter: &mut [usize],
    ) -> u64 {
        if v == t {
            return f;
        }
        for i in iter[v]..self.edges[v].len() {
            iter[v] = i;
            let (to, rev, cap) = self.edges[v][i];
            if cap > 0 && level[v].unwrap() < level[to].unwrap_or(0) {
                let d = self.dfs(to, t, std::cmp::min(f, cap), level, iter);
                if d > 0 {
                    self.edges[v][i].2 -= d;
                    self.edges[to][rev].2 += d;
                    return d;
                }
            }
        }
        0
    }
}

fn main() {
    let n = read::<u32>();
    let mut red: Vec<((u32, u32), u32)> = Vec::new();
    let mut blue: Vec<((u32, u32), u32)> = Vec::new();
    for _ in 0..n {
        let (x, y) = read_tuple();
        let mut z = 0;
        if x > y {
            z = y.clone();
        } else {
            z = x.clone();
        }
        red.push(((x, y), z));
    }
    for _ in 0..n {
        let (x, y) = read_tuple();
        let mut z = 0;
        if x > y {
            z = y.clone();
        } else {
            z = x.clone();
        }
        blue.push(((x, y), z));
    }

    println!("{}", solve(red, blue));
}

fn solve(mut red: Vec<((u32, u32), u32)>, mut blue: Vec<((u32, u32), u32)>) -> u32 {
    red.sort_by(|a, b| b.1.cmp(&a.1));
    blue.sort_by(|a, b| b.1.cmp(&a.1));

    let mut cnt = 0;
    let ((mut a, mut b), _) = red.pop().unwrap();
    let ((mut c, mut d), _) = blue.pop().unwrap();

    loop {
        if a < c && b < d {
            cnt += 1;

            if red.is_empty() || blue.is_empty() {
                break
            }

            let ((e, f), _) = red.pop().unwrap();
            let ((g, h), _) = blue.pop().unwrap();
            a = e; b = f; c = g; d = h;
            continue;
        }

        if red.is_empty() || blue.is_empty() {
            break
        }

        let ((x, y), _) = blue.pop().unwrap();
        c = x; d = y;
    }

    cnt
}

