    idx: usize
}


impl Edge{
    fn new(to: usize, capacity: usize, flow: usize, is_rev: bool, idx: usize) -> Edge{
        Edge{to,
             capacity,
             flow,
             is_rev,
             idx}
    }

    fn to(&self) -> usize{
        self.to
    }

    fn idx(&self) -> usize{
        self.idx
    }

    fn is_rev(&self) -> bool{
        self.is_rev
    }

    fn mergin(&self) -> usize{
        self.capacity - self.flow
    }

    fn increase_flow(&mut self, val: usize){
        assert!(self.mergin() >= val);
        self.flow += val;
    }

    fn decrease_flow(&mut self, val: usize){
        assert!(self.flow >= val);
        self.flow -= val;
    }

    fn is_full(&self) -> bool{
        self.flow >= self.capacity
    }
}

#[derive(Debug)]
struct FordFulkerson{
    pub residual: Vec<Vec<Edge>>,
    start: usize,
    goal: usize
}

impl FordFulkerson{
    fn new(graph: Vec<Vec<(usize, usize)>>, start: usize, goal: usize) -> FordFulkerson{
        let mut residual: Vec<Vec<Edge>> = vec![vec![];graph.len()];
        for from in 0..graph.len(){
            for j in 0..graph[from].len(){
                let (to, capacity) = graph[from][j];
                let from_idx = residual[to].len();
                let to_idx = residual[from].len();
                residual[from].push(Edge::new(to, capacity, 0, false, from_idx));
                residual[to].push(Edge::new(from, capacity, capacity, true, to_idx));
            }
        }
        FordFulkerson{
            residual,
            start,
            goal
        }
    }

    fn find_augmenting_path_recur(&self, stack: &mut Vec<Edge>,
                                  visited: &mut Vec<bool>, cur_v: usize, goal: usize)
                                  -> bool{

        if cur_v == goal{
            return true;
        }

        //println!("current = {}", cur_v);
        //println!("nexts = {:?}",  self.residual[cur_v]);
        for edge in self.residual[cur_v].iter().filter(|e| !e.is_full()){
            //println!("{:?}", edge);
            if visited[edge.to()] == true{
                continue;
            }

            stack.push(edge.clone());
            visited[edge.to()] = true;
            if self.find_augmenting_path_recur(stack, visited, edge.to(), goal){
                return true;
            }
            stack.pop();
            visited[edge.to()] = false;
        }

        return false;
    }

    fn find_augmenting_path(&self) -> Option<Vec<Edge>>{
        let mut stack: Vec<Edge> = vec![];
        let mut visited: Vec<bool> = vec![false ;self.residual.len()];
        let (start, goal) = (0, self.residual.len()-1);
        visited[start] = true;
        if self.find_augmenting_path_recur(&mut stack, &mut visited, start, goal){
            return Some(stack);
        }else{
            return None;
        }
    }

    fn update_if_possible(&mut self) -> bool{
        let argumenting_path = self.find_augmenting_path();
        if argumenting_path.is_none(){
            return false;
        }

        let argumenting_path = argumenting_path.unwrap();
         let additional: usize = argumenting_path.iter().map(|e| e.mergin()).min().unwrap();
        assert!(additional > 0);
        for path in &argumenting_path{
            let (rev_i, rev_j) = (path.to(), path.idx());
            self.residual[rev_i][rev_j].decrease_flow(additional);

            let (i, j) = (self.residual[rev_i][rev_j].to(), self.residual[rev_i][rev_j].idx);
            self.residual[i][j].increase_flow(additional);
        }
        return true;
    }

    fn get_max_flow(&mut self) -> usize{
        self.residual[self.goal].iter().filter(|e| e.is_rev).map(|e| e.mergin()).sum::<usize>()
    }
}


