fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let n = i.read::<usize>();
    let mut reds = Vec::new();
    let mut blues = Vec::new();

    for _ in 0..n {
        reds.push(i.read2::<usize, usize>());
    }
    for _ in 0..n {
        blues.push(i.read2::<usize, usize>());
    }
    let mut cp_red = vec![0usize; n];
    let mut cp_blue = vec![0usize; n];

    fn can_pair(red: (usize, usize), blue: (usize, usize)) -> bool {
        red.0 < blue.0 && red.1 < blue.1
    }

    for n_red in 0..n {
        for n_blue in 0..n {
            if can_pair(reds[n_red], blues[n_blue]) {
                cp_red[n_red] += 1;
                cp_blue[n_blue] += 1;
            }
        }
    }
    println!("");
    let mut r = 0;
    loop {
        let min_red = cp_red
            .iter()
            .cloned()
            .enumerate()
            .filter(|&x| x.1 != 0)
            .min_by_key(|&x| x.1);
        let min_blue = cp_blue
            .iter()
            .cloned()
            .enumerate()
            .filter(|&x| x.1 != 0)
            .min_by_key(|&x| x.1);
        if let (Some((mut n_red, c_red)), Some((mut n_blue, c_blue))) = (min_red, min_blue) {
            println!("red {:?} {}, blue {:?} {}", n_red, c_red, n_blue, c_blue);
            if c_red < c_blue {
                n_blue = (0..n)
                    .filter(|&n_blue| can_pair(reds[n_red], blues[n_blue]) && cp_blue[n_blue] != 0)
                    .min_by_key(|&n_blue| cp_blue[n_blue])
                    .unwrap();
            } else {
                n_red = (0..n)
                    .filter(|&n_red| can_pair(reds[n_red], blues[n_blue]) && cp_red[n_red] != 0)
                    .min_by_key(|&n_red| cp_red[n_red])
                    .unwrap();
            }

            r += 1;
            for n_red in 0..n {
                if can_pair(reds[n_red], blues[n_blue]) && cp_red[n_red] != 0 {
                    cp_red[n_red] -= 1;
                }
            }
            for n_blue in 0..n {
                if can_pair(reds[n_red], blues[n_blue]) && cp_blue[n_blue] != 0 {
                    cp_blue[n_blue] -= 1;
                }
            }
            cp_red[n_red] = 0;
            cp_blue[n_blue] = 0;
        } else {
            break;
        }
    }
    writeln!(o, "{}", r).unwrap();
}
