    const MOD_BASE: usize = 1000000007;

    #[derive(Debug, Clone, Copy)]
    struct ModNum(usize);

    impl ModNum {
        fn new(n: usize) -> Self {
            ModNum(n % MOD_BASE)
        }
    }
    macro_rules! modnum_op {
        (($ot:ident, $f:ident), ($ot_a:ident, $f_a:ident), $($rhs:ty, $e:expr,)*) => {
            $(
            impl $ot<$rhs> for ModNum {
                type Output = Self;
                fn $f(self, rhs: $rhs) -> Self {
                    Self::new(($e)(self, rhs))
                }
            }
            impl $ot_a<$rhs> for ModNum {
                fn $f_a(&mut self, rhs: $rhs) {
                    *self = Self::new(($e)(*self, rhs))
                }
            }
            )*
        }
    }

    modnum_op!(
        (Add, add),
        (AddAssign, add_assign),
        ModNum,
        |l: ModNum, r: ModNum| l.0 + r.0,
        usize,
        |l: ModNum, r: usize| l.0 + r,
    );

    modnum_op!(
        (Mul, mul),
        (MulAssign, mul_assign),
        ModNum,
        |l: ModNum, r: ModNum| l.0 * r.0,
        usize,
        |l: ModNum, r: usize| l.0 * r,
    );

    modnum_op!(
        (Sub, sub),
        (SubAssign, sub_assign),
        ModNum,
        |l: ModNum, r: ModNum| MOD_BASE + l.0 - r.0,
        usize,
        |l: ModNum, r: usize| MOD_BASE + l.0 - r,
    );

}

