pub fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().parse().ok().unwrap()
}

pub fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

pub fn read_tuple<T: std::str::FromStr + Copy>() -> (T, T) {
    let v: Vec<T> = read_vec();
    (v[0], v[1])
}

fn main() {
    let N: usize = read();
    let mut red = Vec::new();
    for i in 0..N {
        red.push(read_tuple::<i32>());
    }
    red.sort();
    let mut blue = Vec::new();
    for i in 0..N {
        blue.push(read_tuple::<i32>());
    }
    blue.sort();
    let mut ans = 0;
    for (c, d) in blue {
        let mut max_b = -1;
        let mut j = 0;
        for i in 0..red.len() {
            let (a, b) = red[i];
            if a < c && b < d {
                if b > max_b {
                    max_b = b;
                    j = i;
                }
            } else if a >= c {
                break;
            }
        }
        if max_b >= 0 {
            red.remove(j);
            ans += 1;
        }
    }
    println!("{}", ans);
}

