const INF: usize = 1000;

fn solve(mut red: Vec<(usize, usize)>, mut blue: Vec<(usize, usize)>) -> usize {
    red.sort_by(|a, b| b.0.cmp(&a.0)); // desc
    blue.sort_by(|a, b| a.0.cmp(&b.0)); // asc

    let mut cnt = 0;
    for i in 0..red.len() {
        let (a, b) = (red[i].0, red[i].1);

        let mut ymin = INF;
        let mut index = INF;
        for j in 0..blue.len() {
            let (c, d) = (blue[j].0, blue[j].1);
            if a < c && b < d {
                if d < ymin {
                    ymin = d;
                    index = j;
                }
            }
        }

        if index != INF {
            cnt += 1;
            blue[index] = (INF, INF);
        }
    }
    cnt
}

