    let n:usize = scan.next();

    let mut ab:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();
    let mut cd:Vec<(usize,usize)> = (0..n).map(|_| (scan.next(),scan.next())).collect::<Vec<(usize,usize)>>();

