fn main() {
    proconio::input! {
        n: usize,
        abs: [(usize, usize); n], // red
        cds: [(usize, usize); n], // blue
    }
    let mut ok_cds_of_abs = std::collections::HashMap::<
        (usize, usize),
        std::collections::HashSet<(usize, usize)>,
    >::new();
    let mut ok_abs_of_cds = std::collections::HashMap::<
        (usize, usize),
        std::collections::HashSet<(usize, usize)>,
    >::new();
    for (a, b) in &abs {
        for (c, d) in &cds {
            if a < c && b < d {
                ok_cds_of_abs
                    .entry((*a, *b))
                    .or_insert(std::collections::HashSet::new())
                    .insert((*c, *d));
                ok_abs_of_cds
                    .entry((*c, *d))
                    .or_insert(std::collections::HashSet::new())
                    .insert((*a, *b));
            }
        }
    }
    let mut count = 0usize;
    while !ok_cds_of_abs.is_empty() {
        let min_ab = *ok_cds_of_abs
            .iter()
            .min_by(|l, r| l.1.len().cmp(&r.1.len()))
            .unwrap()
            .0;
        let min_cd = *ok_abs_of_cds
            .iter()
            .min_by(|l, r| l.1.len().cmp(&r.1.len()))
            .unwrap()
            .0;
        count += 1;
        if ok_cds_of_abs.get(&min_ab).unwrap().len() <= ok_abs_of_cds.get(&min_cd).unwrap().len() {
            let cd = *ok_cds_of_abs.get(&min_ab).unwrap().iter().next().unwrap();
            ok_cds_of_abs.remove(&min_ab);
            ok_abs_of_cds.iter_mut().for_each(|(_cd, abs)| {
                abs.remove(&min_ab);
            });
            ok_abs_of_cds.remove(&cd);
            ok_cds_of_abs.iter_mut().for_each(|(_ab, cds)| {
                cds.remove(&cd);
            });
        } else {
            let ab = *ok_abs_of_cds.get(&min_cd).unwrap().iter().next().unwrap();
            ok_abs_of_cds.remove(&min_cd);
            ok_cds_of_abs.iter_mut().for_each(|(_ab, cds)| {
                cds.remove(&min_cd);
            });
            ok_cds_of_abs.remove(&ab);
            ok_abs_of_cds.iter_mut().for_each(|(_cd, abs)| {
                abs.remove(&ab);
            });
        }
        let v = ok_cds_of_abs
            .iter()
            .filter(|(_key, value)| value.is_empty())
            .map(|(k, _)| *k)
            .collect::<Vec<(usize, usize)>>();
        for item in v {
            ok_cds_of_abs.remove(&item);
        }
        let v = ok_abs_of_cds
            .iter()
            .filter(|(_key, value)| value.is_empty())
            .map(|(k, _)| *k)
            .collect::<Vec<(usize, usize)>>();
        for item in v {
            ok_abs_of_cds.remove(&item);
        }
    }
    println!("{}", count);
}

