fn main() {
    let n: usize = read();
    let mut red_points: Vec<Point> = Vec::new();
    let mut pair = 0;
    for _ in 0..n {
        let x = read();
        let y = read();
        red_points.push(Point {
            x: x,
            y: y,
            pair: false,
        });
    }
    red_points.sort_by(|m, n| n.y.cmp(&m.y));
    let mut blue_points: Vec<Point> = Vec::new();
    for _ in 0..n {
        let x = read();
        let y = read();
        blue_points.push(Point {
            x: x,
            y: y,
            pair: false,
        });
    }
    blue_points.sort_by(|m, n| m.x.cmp(&n.x));
    for bp in blue_points.iter_mut() {
        for rp in red_points.iter_mut() {
            if rp.x < bp.x && rp.y < bp.y {
                if !(rp.pair || bp.pair) {
                    rp.pair = true;
                    bp.pair = true;
                    pair += 1;
                }
            }
        }
    }
    println!("{}", pair);
}

